/* The heavy half of the ec cards — GENERATED, never hand-edited.
 *
 * abstract / sources / why / quote / wiki / image / places, for the cards whose ids begin `ec-`. None of it is
 * read until a reader REVEALS a card in this collection, so it is fetched then (bundle
 * `cardExtra:ec`) rather than downloaded by every visitor before they can flip one.
 *
 * IT STAGES ONTO A QUEUE rather than assigning, for the reason glossary-extra.js does: app.js
 * snapshots PRISTINE_CARDS at boot, which is BEFORE this file lands, so a plain assignment would
 * leave the editor's revert baseline empty and Revert would DELETE a shipped abstract rather than
 * restore it. cardExtraIngest drains the queue and re-seeds that baseline.
 *
 * An id data.js does not carry is not resurrected — the light half decides what a card is. */
(function () {
  var CARD_EXTRA = {
    "ec-001": {"questions":["Split since the 1930s into a micro and a macro half, <span class=\"blank\">_____</span> studies how people produce, exchange and consume when their wants outrun the labour, land and time available.","Defined by one widely used course as the study of how people interact with each other and with nature in producing their livelihoods, <span class=\"blank\">_____</span> covers buying, selling, working and family life alike."],"abstract":"<b>Economics</b> is the social science that studies how people make decisions in the face of scarcity, whether as individuals, families, businesses or whole societies.<sup class=\"fn\" data-fn=\"8\"></sup> Scarcity here means that wants for goods, services and resources exceed what is available, so that limited means with alternative uses must be divided among competing ends.<sup class=\"fn\" data-fn=\"8\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> One widely used course describes the subject instead as the study of how people interact with each other and with their natural surroundings in producing their livelihoods, and how this changes over time.<sup class=\"fn\" data-fn=\"7\"></sup> That covers how people acquire food, clothing, shelter and free time, how they deal with one another as buyers, sellers, employers, employees, citizens and family members, and how they draw on the environment.<sup class=\"fn\" data-fn=\"7\"></sup> The phenomena economists chiefly study are production, consumption, distribution and exchange, above all through markets, although no list of phenomena alone marks the subject off from its neighbours.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> The economy as a distinct object of study is only about three centuries old, emerging in the 18th century with the idea that its regularities are the unintended results of many separate choices.<sup class=\"fn\" data-fn=\"6\"></sup> Its older name was political economy, which Adam Smith in 1776 treated as a branch of the science of a statesman or legislator, meant to enrich both the people and the sovereign.<sup class=\"fn\" data-fn=\"1\"></sup> In the 19th century it was defined more narrowly as the science of the social phenomena that arise from people's combined pursuit of wealth, setting their other motives aside.<sup class=\"fn\" data-fn=\"2\"></sup> The shorter word economics came into use for the same subject, defined in one standard textbook as a study of mankind in the ordinary business of life.<sup class=\"fn\" data-fn=\"3\"></sup> Since the 1930s the discipline has been split into microeconomics and macroeconomics, and economists still share no single definition of what their subject is.<sup class=\"fn\" data-fn=\"9\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan, 5th ed. (London: Methuen, 1904), bk. 4, introduction, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=25. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 1, ch. 1, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=2. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–16, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","Roger E. Backhouse and Steven G. Medema, “Retrospectives: On the Definition of Economics,” <i>Journal of Economic Perspectives</i> 23, no. 1 (2009): 221–33, https://www.aeaweb.org/articles?id=10.1257/jep.23.1.221. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","The CORE Team, <i>The Economy</i> 1.0, unit 1, “The Capitalist Revolution,” section 1.11, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/01.html. [Open access]","<i>Principles of Economics 3e</i>, “1.1 What Is Economics, and Why Is It Important?,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]","G. Chris Rodrigo, “The Big and the Small Picture,” <i>Finance & Development</i> 48, no. 3 (September 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/09/basics.htm. [Open access]"],"why":[{"q":"Why was the subject once called political economy?","a":"Because it was first treated as part of the knowledge a statesman or legislator needed.<sup class=\"fn\" data-fn=\"1\"></sup> In 1776 it was given two objects: to enable the people to provide a plentiful revenue or subsistence for themselves, and to supply the state with a revenue sufficient for the public services.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does scarcity sit at the centre of most definitions?","a":"Because wants for goods, services and resources exceed what is available, so labour, land, tools and time must be divided among competing uses.<sup class=\"fn\" data-fn=\"8\"></sup> Choosing one use means relinquishing others, the condition that an influential definition of 1932 made the unity of the whole subject.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why do economists not agree on a single definition?","a":"Because the field now studies subjects as diverse as growth, auctions, crime and religion with tools ranging from econometrics to laboratory experiments, so any short definition is likely to be inadequate.<sup class=\"fn\" data-fn=\"5\"></sup> Economists are guided more by what works than by formal definitions, though definitions have at times been used to justify or steer what they do.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Economics"},
    "ec-002": {"questions":["Modern principles textbooks offer no agreed <span class=\"blank\">_____</span>, variously calling the subject the study of the economy, of coordination, of scarcity's effects, of choice or of human behaviour.","Moving from the pursuit of wealth to material wellbeing and then to scarce means, the accepted <span class=\"blank\">_____</span> shifted the subject from a field of activity to an aspect of all choice."],"abstract":"The <b>definition of economics</b> is the account of what the subject studies, and economists have never settled on a single one.<sup class=\"fn\" data-fn=\"5\"></sup> Surveys of modern principles textbooks find five kinds of answer: the study of the economy, of the coordination process, of the effects of scarcity, the science of choice and the study of human behaviour.<sup class=\"fn\" data-fn=\"5\"></sup> Definitions by subject matter point to production, consumption, distribution and exchange, but so many causes bear on these, from geography to social norms, that a list of phenomena alone cannot mark the subject off.<sup class=\"fn\" data-fn=\"6\"></sup> Definitions of the other kind instead name a set of central causes, such as the pursuit of wealth or rational choice among limited means.<sup class=\"fn\" data-fn=\"6\"></sup> One widely used modern course takes a broader line again, defining economics as the study of how people interact with each other and with their natural surroundings in producing their livelihoods.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The early political economists defined their subject by its aims, describing it in 1776 as a way to provide a plentiful revenue or subsistence for the people and a revenue for the state.<sup class=\"fn\" data-fn=\"4\"></sup> In the 19th century the definition was narrowed to the laws of the social phenomena that arise from the combined pursuit of wealth, setting aside every other motive except aversion to labour and the wish for present enjoyment.<sup class=\"fn\" data-fn=\"3\"></sup> A standard textbook of the early 20th century spoke instead of a study of mankind in the ordinary business of life, concerned with the material requisites of wellbeing.<sup class=\"fn\" data-fn=\"2\"></sup> In 1932 a London essay replaced all of these with the definition most often quoted since, that economics studies human behaviour as a relationship between ends and scarce means which have alternative uses.<sup class=\"fn\" data-fn=\"1\"></sup> Because it names an aspect of all choice rather than a field of activity, that definition helped economists carry their methods into voting and legislation, and into territory once thought to lie outside the discipline.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–16, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 1, ch. 1, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=2. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan, 5th ed. (London: Methuen, 1904), bk. 4, introduction, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=25. [Open access]","Roger E. Backhouse and Steven G. Medema, “Retrospectives: On the Definition of Economics,” <i>Journal of Economic Perspectives</i> 23, no. 1 (2009): 221–33, https://www.aeaweb.org/articles?id=10.1257/jep.23.1.221. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","The CORE Team, <i>The Economy</i> 1.0, unit 1, “The Capitalist Revolution,” section 1.11, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/01.html. [Open access]","Edward P. Lazear, “Economic Imperialism,” NBER Working Paper 7300 (Cambridge, MA: National Bureau of Economic Research, 1999), published in <i>Quarterly Journal of Economics</i> 115, no. 1 (2000): 99–146, https://www.nber.org/papers/w7300. [Open access]"],"why":[{"q":"Why did the 1932 definition widen the subject's reach?","a":"Because it tied economics to an aspect of all human action, the disposal of scarce means among competing ends, rather than to production, exchange or consumption as such.<sup class=\"fn\" data-fn=\"6\"></sup> Any behaviour that gives up one end for another therefore has an economic side, which is how its methods came to be applied to voting and legislation.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why was the pursuit of wealth once thought enough to define the subject?","a":"Because political economy was treated as an abstraction.<sup class=\"fn\" data-fn=\"3\"></sup> It considered people solely as beings who desire wealth and can judge the means of obtaining it, setting aside every other passion except aversion to labour and the desire for present enjoyment of costly indulgences.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why does the lack of an agreed definition not cripple the discipline?","a":"Because economists are generally guided by pragmatic considerations of what works, not by formal definitions.<sup class=\"fn\" data-fn=\"5\"></sup> Definitions still matter, however, since they have been used to justify what economists do and can reflect the direction their authors want the subject to take.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Definitions of economics"},
    "ec-003": {"questions":["Before the Great Depression there was no separate study of aggregates, because economists assumed that <span class=\"blank\">_____</span>, the analysis of individual markets, would adequately explain unemployment and output too.","Built from consumer demand theory, the theory of the firm and the study of competition and imperfect information, <span class=\"blank\">_____</span> reaches at its most abstract the general equilibrium of many markets."],"abstract":"<b>Microeconomics</b> is the branch of economics that studies the choices of individual agents such as households, workers and businesses, and how those choices interact in particular markets.<sup class=\"fn\" data-fn=\"1\"></sup> It asks how households spend their budgets, whether people work full or part time and how much they save, and what a firm produces, what it charges and how many workers it hires.<sup class=\"fn\" data-fn=\"1\"></sup> Its building blocks are consumer demand theory, the theory of the firm, the study of market competition, welfare and imperfect information, and at its most abstract the general equilibrium of many markets at once.<sup class=\"fn\" data-fn=\"2\"></sup> In its standard form consumers have complete and transitive preferences, firms try to maximise profits in the face of diminishing returns, and outcomes are modelled as an equilibrium with no excess demand in any market.<sup class=\"fn\" data-fn=\"3\"></sup> A familiar example is the supply and demand model, which explains the prices and quantities traded in a competitive market by the price at which supply equals demand.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Its counterpart, macroeconomics, studies the economy as a whole, including output, unemployment, inflation, government deficits and trade, and the two are complementary views of one economy rather than separate subjects.<sup class=\"fn\" data-fn=\"1\"></sup> Macroeconomics measures aggregates such as gross domestic product, tracing how spending, production and incomes across a whole economy flow from spenders to producers to employees and back.<sup class=\"fn\" data-fn=\"8\"></sup> Until the Great Depression of the 1930s economics was not divided in this way, since economists assumed that the study of individual markets would adequately explain aggregates such as unemployment and output.<sup class=\"fn\" data-fn=\"2\"></sup> The collapse that this approach could not explain gave rise to macroeconomics as a distinct field, built on the argument that aggregate demand, the combined spending of households, businesses and government, drives the economy.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Efforts since then to give macroeconomic models microeconomic foundations have often relied on a single representative agent, a shortcut critics call unjustified and frequently misleading.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>","sources":["<i>Principles of Economics 3e</i>, “1.2 Microeconomics and Macroeconomics,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-2-microeconomics-and-macroeconomics. [Open access]","G. Chris Rodrigo, “The Big and the Small Picture,” <i>Finance & Development</i> 48, no. 3 (September 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/09/basics.htm. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","N. Gregory Mankiw, “The Macroeconomist as Scientist and Engineer,” <i>Journal of Economic Perspectives</i> 20, no. 4 (2006): 29–46, https://www.aeaweb.org/articles?id=10.1257/jep.20.4.29. [Open access]","Alan P. Kirman, “Whom or What Does the Representative Individual Represent?,” <i>Journal of Economic Perspectives</i> 6, no. 2 (1992): 117–36, https://www.aeaweb.org/articles?id=10.1257/jep.6.2.117. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","Sarwat Jahan, Ahmed Saber Mahmud and Chris Papageorgiou, “What Is Keynesian Economics?,” <i>Finance & Development</i> 51, no. 3 (September 2014), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2014/09/basics.htm. [Open access]","The CORE Team, <i>The Economy</i> 1.0, unit 13, “Economic Fluctuations and Unemployment,” section 13.3, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/13.html. [Open access]"],"why":[{"q":"Why did macroeconomics split off from the rest of economics?","a":"Because the economics of the time could not explain the Great Depression.<sup class=\"fn\" data-fn=\"2\"></sup> Economists who assumed that markets were always in equilibrium had no plausible account of so extreme a collapse, and the study of aggregate demand that answered it grew into a separate field.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why is microeconomics said to have no competing schools?","a":"Because, on one IMF account, its theory evolved steadily from the earliest explanations of how prices are set and has a common core shared by all economists.<sup class=\"fn\" data-fn=\"2\"></sup> Macroeconomics instead grew out of anomalies that existing theory could not explain and has long had rival schools, such as New Keynesian and New Classical.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the representative agent criticised?","a":"Because treating the choices of many different consumers as those of one utility-maximising individual is, critics argue, unjustified and often wrong.<sup class=\"fn\" data-fn=\"5\"></sup> Such models are ill-suited to unemployment, which is better seen as a failure of coordination, and few economists are satisfied with the attempts made so far to unify micro and macro.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Microeconomics"},
    "ec-004": {"questions":["A 1930 essay forecast that, barring major wars and any important increase in population, the <span class=\"blank\">_____</span>, the struggle for subsistence, might be solved within a century.","A 1945 essay argued that the <span class=\"blank\">_____</span> of society is less how to allocate given resources than how to use knowledge scattered among many people and given to no single mind."],"abstract":"The <b>economic problem</b> is the problem every individual and society faces because wants exceed the resources available to satisfy them, so that choices must be made about how to use what there is.<sup class=\"fn\" data-fn=\"4\"></sup> Labour, tools, land and raw materials exist in limited supply, and even time is scarce, since everyone has the same 24 hours in a day.<sup class=\"fn\" data-fn=\"4\"></sup> Scarcity alone is not enough, however, because means with only one possible use may be scarce but cannot be economised, so the problem arises when limited means could serve several ends of different importance.<sup class=\"fn\" data-fn=\"1\"></sup> Choosing one thing then means giving up others, a condition one classic statement called almost ubiquitous in human behaviour.<sup class=\"fn\" data-fn=\"1\"></sup> For a whole society the problem becomes one of coordination, of ensuring that the right goods are produced in the right numbers by the right methods across millions of interrelated lives.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> Many economists have treated it as a problem of allocating given means to given ends, and the most quoted definition of the subject makes the disposal of scarce means with alternative uses its unifying theme.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A celebrated objection of 1945 held that the economic problem of society is not merely how to allocate given resources, because the knowledge needed is dispersed among many individuals and never given to a single mind.<sup class=\"fn\" data-fn=\"3\"></sup> On that view it is a problem of using knowledge which is not given to anyone in its totality, and the price system is one of the ways a society solves it.<sup class=\"fn\" data-fn=\"3\"></sup> A famous essay of 1930 looked forward instead, predicting that without important wars or a large rise in population the economic problem, the struggle for subsistence, might be solved within a hundred years.<sup class=\"fn\" data-fn=\"2\"></sup> Its author argued that this struggle had always been the most pressing problem of the human race, so that solving it would deprive people of their traditional purpose.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–16, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","John Maynard Keynes, “Economic Possibilities for our Grandchildren” (1930), in <i>Essays in Persuasion</i> (New York: W. W. Norton, 1963), 358–73, http://www.econ.yale.edu/smith/econ116a/keynes1.pdf. [Open access]","Friedrich A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]","<i>Principles of Economics 3e</i>, “1.1 What Is Economics, and Why Is It Important?,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Roger E. Backhouse and Steven G. Medema, “Retrospectives: On the Definition of Economics,” <i>Journal of Economic Perspectives</i> 23, no. 1 (2009): 221–33, https://www.aeaweb.org/articles?id=10.1257/jep.23.1.221. [Open access]","<i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]"],"why":[{"q":"Why is scarcity alone not enough to create the economic problem?","a":"Because means that have no alternative use may be scarce but cannot be economised.<sup class=\"fn\" data-fn=\"1\"></sup> The problem appears when limited time and means could serve several ends of different importance, so that choosing one means relinquishing others.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did one critic say the problem is about knowledge, not allocation?","a":"Because the data from which an economic calculation would start are never given to a single mind.<sup class=\"fn\" data-fn=\"3\"></sup> They exist only as dispersed, incomplete and often contradictory knowledge held by separate individuals, so the task is to secure the best use of resources known to any member of society.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did a 1930 essay think the problem might be solved?","a":"Because it expected economic progress to continue, predicting that the standard of life in progressive countries a century later would be four to eight times as high.<sup class=\"fn\" data-fn=\"2\"></sup> Barring important wars and increases in population, the struggle for subsistence might then cease to be the permanent problem of the human race.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Economic problem"},
    "ec-005": {"questions":["With axiomatised theories, journals full of theorems and its own imitation Nobel prize, economics is the <span class=\"blank\">_____</span> that most closely resembles the natural sciences.","Whether a <span class=\"blank\">_____</span> should aim not only at prediction but at understanding actions from the inside, through the reasons of the people who take them, is an old methodological dispute."],"abstract":"<b>Social science</b> is, in its broadest sense, the study of society and of the ways people behave and influence the world around them.<sup class=\"fn\" data-fn=\"1\"></sup> It takes in disciplines such as demography, economics, education, human geography, linguistics, politics, psychology, social anthropology and sociology.<sup class=\"fn\" data-fn=\"2\"></sup> Its findings range from the causes of unemployment and what helps economic growth to how and why people vote and what makes them happy, and they inform governments and many other bodies.<sup class=\"fn\" data-fn=\"1\"></sup> In the 19th century this field was described as the science of human nature in the social state, standing to society as anatomy and physiology stand to the body.<sup class=\"fn\" data-fn=\"5\"></sup> One influential tradition holds that it should aim not only at prediction but at understanding from the inside, grasping why an action made sense to the person who took it.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Economics belongs to this family because it seeks to understand how individuals interact within the social structure in producing and exchanging goods and services.<sup class=\"fn\" data-fn=\"2\"></sup> Of all the social sciences it most closely resembles the natural sciences, with axiomatised theories, articles full of theorems and its own imitation of the Nobel prizes.<sup class=\"fn\" data-fn=\"3\"></sup> An early 20th-century textbook traced that exactness to money, which gives a rough but definite measure of the force of people's steadiest motives, much as a fine balance does for chemistry.<sup class=\"fn\" data-fn=\"6\"></sup> Some economists argue that rational maximising individuals, equilibrium and a focus on efficiency set the subject apart from its neighbours and have let it move into their territory.<sup class=\"fn\" data-fn=\"8\"></sup> Studies of citations and careers find economics unusually insular and hierarchical among American social sciences, and confident of its ability to fix the world's problems, which has brought it both influence and criticism.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Economic and Social Research Council, “What Is Social Science?,” UK Research and Innovation, updated 31 March 2022, https://www.ukri.org/who-we-are/esrc/what-is-social-science/. [Open access]","Economic and Social Research Council, “Social Science Disciplines,” UK Research and Innovation, https://www.ukri.org/who-we-are/esrc/what-is-social-science/social-science-disciplines/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Sung Ho Kim, “Max Weber,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2022, https://plato.stanford.edu/entries/weber/. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 1, ch. 2, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=3. [Open access]","Marion Fourcade, Etienne Ollion and Yann Algan, “The Superiority of Economists,” <i>Journal of Economic Perspectives</i> 29, no. 1 (2015): 89–114, https://www.aeaweb.org/articles?id=10.1257/jep.29.1.89. [Open access]","Edward P. Lazear, “Economic Imperialism,” NBER Working Paper 7300 (Cambridge, MA: National Bureau of Economic Research, 1999), published in <i>Quarterly Journal of Economics</i> 115, no. 1 (2000): 99–146, https://www.nber.org/papers/w7300. [Open access]"],"why":[{"q":"Why does economics look more like a natural science than its neighbours?","a":"Because its theories have been axiomatised and its articles and books are full of theorems.<sup class=\"fn\" data-fn=\"3\"></sup> Money also gives it a rough but definite measure of the force of people's steadiest motives, which an early 20th-century textbook compared with the chemist's balance.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why might a social science need more than prediction?","a":"Because, on one influential view, it should help us understand human action from the inside, seeing why an action made sense to the people who took it.<sup class=\"fn\" data-fn=\"3\"></sup> That adds an element of subjectivity not found in the natural sciences, and the question of how to handle it shaped the methods of modern social science.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why has economics' standing among the social sciences drawn criticism?","a":"Because studies of citations and careers find it unusually insular and hierarchical, better paid and more confident of fixing the world's problems than its neighbours.<sup class=\"fn\" data-fn=\"7\"></sup> That confidence has brought influence but has also exposed economists to conflicts of interest, political critique and even derision.<sup class=\"fn\" data-fn=\"7\"></sup>"}],"wiki":"Social science"},
    "ec-006": {"questions":["A treatise of 1891 split political economy three ways, setting what is now called <span class=\"blank\">_____</span>, a body of knowledge about what is, apart from a normative science and an art of practical rules.","Most economists treat the bulk of their work as <span class=\"blank\">_____</span>, helping policy makers choose means without choosing ends, though philosophers doubt that facts and values separate so cleanly."],"abstract":"<b>Positive economics</b> is the part of economics that describes and explains how the economy actually works, making claims that may be true or false and can, at least in principle, be tested.<sup class=\"fn\" data-fn=\"1\"></sup> Its counterpart, normative economics, deals in statements of how things ought to be, which rest on values and cannot be proved true or false in the same way.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> An economist who estimates the benefits and costs of a proposed subway is doing positive analysis, while one who argues that a rich country should support its less fortunate citizens is making a normative case.<sup class=\"fn\" data-fn=\"1\"></sup> Most economists and methodologists believe the line between facts and values is reasonably clear, and regard most of economics as a positive science that helps policy makers choose means without choosing their ends.<sup class=\"fn\" data-fn=\"2\"></sup> Its models are simplified descriptions of reality designed to yield hypotheses about economic behaviour that can be tested against evidence.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> A treatise of 1891 set out the modern distinction, separating a positive science of what is from a normative science of what ought to be and from an art that formulates practical rules.<sup class=\"fn\" data-fn=\"3\"></sup> Its author warned that confusing the three would cause serious problems, and a century later one economist argued that applied policy work fits neither of the first two but belongs to the third.<sup class=\"fn\" data-fn=\"6\"></sup> The division echoes an older contrast between science, which deals in facts, and art, which deals in precepts, as the indicative mood in grammar differs from the imperative.<sup class=\"fn\" data-fn=\"5\"></sup> Philosophers question how sharp the line can be, since economists interpret vague policy goals, build their theories around a normative account of rationality and are influenced by their own interests.<sup class=\"fn\" data-fn=\"2\"></sup> Positive and normative are especially entangled in economics because many economists work as advisers and commentators, and the bitter disputes over policy after 2008 show the influence of ideology.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["<i>Principles of Economics 3e</i>, “2.3 Confronting Objections to the Economic Approach,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","John Neville Keynes, <i>The Scope and Method of Political Economy</i> (London: Macmillan, 1891), ch. 2, 31–36, Internet Archive, https://archive.org/details/scopemethodofpol00keyniala. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 132–33, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]","David Colander, “Retrospectives: The Lost Art of Economics,” <i>Journal of Economic Perspectives</i> 6, no. 3 (1992): 191–98, https://www.aeaweb.org/articles?id=10.1257/jep.6.3.191. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]"],"why":[{"q":"Why does it matter whether a statement can be tested?","a":"Because a positive statement may be true or false and can, in principle, be checked against evidence, while a normative statement rests on values and cannot be proved in the same way.<sup class=\"fn\" data-fn=\"1\"></sup> Most economists argue that their subject bears on policy chiefly through the positive information it gives about the consequences of a choice.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did the 1891 treatise insist on a third category?","a":"Because it saw the investigation of uniformities, the determination of ideals and the formulation of precepts as three different tasks.<sup class=\"fn\" data-fn=\"3\"></sup> On one modern reading, applied policy work fits neither positive nor normative economics and belongs to this art of economics.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why do philosophers doubt the line is clean in economics?","a":"Because economists must interpret incomplete policy goals, their theories rest on a normative account of rationality, and judgements are clouded by interests.<sup class=\"fn\" data-fn=\"2\"></sup> Many economists also work as commentators or advisers whose pay depends on reaching particular conclusions, which entangles the positive with the normative.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Positive and normative economics"},
    "ec-007": {"questions":["Declaring a logical gulf between ascertainable facts and valuations, a 1932 essay applied the <span class=\"blank\">_____</span> to argue that economics cannot settle which ends a society ought to pursue.","Read in the 20th century as a rule of logic called Hume's Law, the <span class=\"blank\">_____</span> holds that no evaluative conclusion follows validly from purely factual premises."],"abstract":"The <b>is-ought problem</b> is the question of whether a conclusion about what ought to be can be validly drawn from premises that state only what is.<sup class=\"fn\" data-fn=\"2\"></sup> It goes back to a short passage of the 18th century in which David Hume complained that moral writers pass, without notice, from propositions joined by 'is' and 'is not' to propositions joined by 'ought' and 'ought not'.<sup class=\"fn\" data-fn=\"1\"></sup> That change, he wrote, is imperceptible but of the last consequence, because the new relation of 'ought' needs a reason that it seems altogether inconceivable to give.<sup class=\"fn\" data-fn=\"1\"></sup> The dominant 20th-century reading took this as a rule of logic, sometimes called Hume's Law, that no evaluative conclusion follows from purely factual premises.<sup class=\"fn\" data-fn=\"2\"></sup> Other interpreters read the passage more narrowly, and few passages in his work have produced more dispute over what exactly it claims.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> In economics the problem underlies the separation of positive from normative work, the first a body of knowledge about what is and the second about what ought to be.<sup class=\"fn\" data-fn=\"6\"></sup> A much-cited essay of 1932 put it bluntly: economics deals with ascertainable facts and ethics with valuations, and between them lies a logical gulf that no ingenuity can disguise.<sup class=\"fn\" data-fn=\"3\"></sup> A century earlier the same point had been made by contrasting science, which deals in facts, with art, which deals in precepts.<sup class=\"fn\" data-fn=\"7\"></sup> In social science more widely the ideal of value-freedom became both a rule of method and a virtue, asking researchers to confront openly the subjective values behind their concepts.<sup class=\"fn\" data-fn=\"5\"></sup> Critics answer that economics cannot be value-free in practice, because its theory of rationality is itself normative and economists' judgements are shaped by their interests.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["David Hume, <i>A Treatise of Human Nature</i>, bk. 3, pt. 1, sec. 1, para. 27, Hume Texts Online, https://davidhume.org/texts/t/3/1/1. [Open access]","Rachel Cohon, “Hume’s Moral Philosophy,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/hume-moral/. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 132–33, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Sung Ho Kim, “Max Weber,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2022, https://plato.stanford.edu/entries/weber/. [Open access]","John Neville Keynes, <i>The Scope and Method of Political Economy</i> (London: Macmillan, 1891), ch. 2, 31–36, Internet Archive, https://archive.org/details/scopemethodofpol00keyniala. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]"],"why":[{"q":"Why did Hume think the move from 'is' to 'ought' needed explaining?","a":"Because 'ought' expresses a new relation or affirmation, and he could see no reason how it could be deduced from relations that are entirely different from it.<sup class=\"fn\" data-fn=\"1\"></sup> Attention to the move would, he wrote, show that the distinction of vice and virtue is not perceived by reason.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does the problem matter to economists?","a":"Because it is the logical ground for separating positive economics, a body of knowledge about what is, from normative inquiry into what ought to be.<sup class=\"fn\" data-fn=\"6\"></sup> On that view economics can trace the consequences of choices but cannot itself pronounce on the validity of the valuations behind them.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do some doubt economics can stay on the 'is' side?","a":"Because economic science is itself a human activity governed by values, and much of it is built on a normative theory of rationality.<sup class=\"fn\" data-fn=\"4\"></sup> People's judgements are also clouded by their interests, and economic theories bear centrally on interests, so ideological bias is hard to exclude.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Is–ought problem"},
    "ec-008": {"questions":["Collapsing many different consumers into a single representative <span class=\"blank\">_____</span> keeps macroeconomic models simple, but critics argue that it yields conclusions that are often wrong.","National accountants give the <span class=\"blank\">_____</span> a concrete counterpart, the institutional unit, which can own assets, incur liabilities and trade with others in its own right."],"abstract":"An <b>economic agent</b> is a decision-maker in an economic model, an individual, household, firm or government whose actions can directly or indirectly affect the actions of the others.<sup class=\"fn\" data-fn=\"3\"></sup> Microeconomics is built around such agents, studying the decisions of households, workers and businesses and modelling consumers and firms that decide what to buy, sell or produce.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> In theoretical models agents are assumed to maximise specific objectives subject to constraints that are well defined, such as a budget, so that verifiable implications about their behaviour can be derived.<sup class=\"fn\" data-fn=\"3\"></sup> The standard account requires only that agents rank their alternatives consistently, with complete and transitive preferences, and choose the feasible option they most prefer.<sup class=\"fn\" data-fn=\"4\"></sup> Firms and households are frequently treated as honorary individuals, so that a family or a company counts as a single agent with one set of preferences.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> The idea descends from the 19th-century view of political economy as concerned with people solely as beings who desire wealth and can judge the means of obtaining it.<sup class=\"fn\" data-fn=\"7\"></sup> National accounts use a related but concrete notion, the institutional unit, an entity capable in its own right of owning assets, incurring liabilities and transacting with others.<sup class=\"fn\" data-fn=\"5\"></sup> Those units are either households or legal and social entities, and every one is classified to a sector such as corporations, general government or households.<sup class=\"fn\" data-fn=\"5\"></sup> Some economists see the construct of rational, maximising individuals as one of the features that set economics apart from the other social sciences and have let it move into territory once deemed outside the discipline.<sup class=\"fn\" data-fn=\"8\"></sup> Critics of macroeconomic models that collapse many different agents into one representative individual argue that the shortcut is unjustified and leads to conclusions that are often wrong.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["<i>Principles of Economics 3e</i>, “1.2 Microeconomics and Macroeconomics,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-2-microeconomics-and-macroeconomics. [Open access]","G. Chris Rodrigo, “The Big and the Small Picture,” <i>Finance & Development</i> 48, no. 3 (September 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/09/basics.htm. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","European Commission, International Monetary Fund, OECD, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), paras. 4.2–4.31 and 22.164, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","Alan P. Kirman, “Whom or What Does the Representative Individual Represent?,” <i>Journal of Economic Perspectives</i> 6, no. 2 (1992): 117–36, https://www.aeaweb.org/articles?id=10.1257/jep.6.2.117. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP5.html. [Open access]","Edward P. Lazear, “Economic Imperialism,” NBER Working Paper 7300 (Cambridge, MA: National Bureau of Economic Research, 1999), published in <i>Quarterly Journal of Economics</i> 115, no. 1 (2000): 99–146, https://www.nber.org/papers/w7300. [Open access]"],"why":[{"q":"Why can a whole household or firm count as one agent?","a":"Because microeconomics frequently treats firms and households as honorary individuals, saying little about the separate wishes of their members.<sup class=\"fn\" data-fn=\"4\"></sup> National accounts do something similar, since the members of a multiperson household are not treated as separate institutional units.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why do economists assume agents maximise something?","a":"Because a theoretical model derives verifiable implications by supposing that agents pursue specific objectives within well-defined constraints, such as a budget.<sup class=\"fn\" data-fn=\"3\"></sup> The minimum usually assumed is that agents rank their options consistently and choose the one they most prefer among those feasible.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is the representative agent controversial?","a":"Because reducing a group of different agents to one utility-maximising individual is, critics argue, not a harmless convenience.<sup class=\"fn\" data-fn=\"6\"></sup> It makes models ill-suited to problems like unemployment, which arise from failures of coordination, and in many such models no trade takes place at all.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Agent (economics)"},
    "ec-009": {"questions":["Alongside households and firms, the <span class=\"blank\">_____</span> is the third great actor of the economy, taxing, spending, borrowing and redistributing income through transfers.","Every tax moves resources from the private sector to the <span class=\"blank\">_____</span>, a compulsory and unrequited payment whose cost usually exceeds the sum collected because it discourages some mutually beneficial trade."],"abstract":"The <b>public sector</b> is the part of an economy controlled by government, made up of the general government sector together with the public corporations that government controls.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> General government consists mainly of central, state and local government units and the social security funds they impose and control.<sup class=\"fn\" data-fn=\"1\"></sup> Its units provide goods and services to the community mostly on a nonmarket basis, redistribute income and wealth through transfers, and pay for this mainly out of taxes and other compulsory levies.<sup class=\"fn\" data-fn=\"2\"></sup> A tax is a compulsory, unrequited payment to government, and most taxes cost the private sector more than the revenue they raise because they drive a wedge between what buyers pay and sellers receive.<sup class=\"fn\" data-fn=\"8\"></sup> Most real economies are mixed, and even the most market-oriented rely on government to safeguard property, protect people from violence, enforce contracts, prevent fraud and collect taxes.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Economic models usually reduce an economy to three kinds of agents, individuals, firms and governments, and national accounts likewise sort every unit into sectors that include households, corporations and general government.<sup class=\"fn\" data-fn=\"9\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Government influences the other two by changing the level and type of taxes, the size and composition of its spending and the extent of its borrowing.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Its own purchases enter national spending directly, while taxes and transfers work indirectly on the consumption, investment and net exports of the private sector.<sup class=\"fn\" data-fn=\"5\"></sup> An 18th-century case for limited government allowed the sovereign only three duties: defence, justice and certain public works that no private individual could profit from building.<sup class=\"fn\" data-fn=\"6\"></sup> The assumption that public officials simply serve the public interest is challenged by the study of public choice, which supposes they pursue their own interests just as people do in private markets.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["European Commission, International Monetary Fund, OECD, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), paras. 4.2–4.31 and 22.164, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","International Monetary Fund, <i>Government Finance Statistics Manual 2014</i> (Washington, DC: International Monetary Fund, 2014), paras. 2.38, 2.58 and 2.63, https://www.imf.org/external/Pubs/FT/GFS/Manual/2014/gfsfinal.pdf. [Open access]","<i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]","<i>Principles of Economics 3e</i>, “1.2 Microeconomics and Macroeconomics,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-2-microeconomics-and-macroeconomics. [Open access]","Mark Horton and Asmaa El-Ganainy, “What Is Fiscal Policy?,” <i>Finance & Development</i> 46, no. 2 (June 2009), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2009/06/basics.htm. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan, 5th ed. (London: Methuen, 1904), bk. 4, ch. 9, para. 51, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=34. [Open access]","William F. Shughart II, “Public Choice,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/PublicChoice.html. [Open access]","Ruud De Mooij and Michael Keen, “Taxing Principles,” <i>Finance & Development</i> 51, no. 4 (December 2014), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2014/12/basics.htm. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]"],"why":[{"q":"Why does a public corporation count as public sector but not general government?","a":"Because general government is defined by its functions: units with political authority that provide mostly nonmarket goods and services and finance them from compulsory transfers.<sup class=\"fn\" data-fn=\"2\"></sup> A corporation that government controls but that sells at economically significant prices sits outside general government, yet inside the wider public sector of every resident unit government controls.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do even market economies need a public sector?","a":"Because there is no such thing as an absolutely free market: regulations always define the rules of the game.<sup class=\"fn\" data-fn=\"3\"></sup> Even the most market-oriented economies rely on government to safeguard private property, protect people from violence, enforce contracts, prevent fraud and collect taxes.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why does public choice doubt that officials serve the public interest?","a":"Because it models voters, politicians and policymakers with the same self-interest that economists assume of people in markets.<sup class=\"fn\" data-fn=\"7\"></sup> They are the same human beings, it argues, so it calls its approach politics without romance and expects voters to vote their pocketbooks.<sup class=\"fn\" data-fn=\"7\"></sup>"}],"wiki":"Public sector"},
    "ec-010": {"questions":["Eighteenth-century French writers likened the economy to blood moving through the body, anticipating the <span class=\"blank\">_____</span> that lets statisticians measure gross domestic product by production, spending or incomes.","Because new spending becomes income for producers who then spend part of it again, the <span class=\"blank\">_____</span> underlies the multiplier, by which output can rise by more than the first outlay."],"abstract":"The <b>circular flow of income</b> is a model of the economy in which money passes from spenders to producers, from producers to their employees or shareholders, and back into spending on further output.<sup class=\"fn\" data-fn=\"2\"></sup> Its simplest form shows two groups, households and firms, meeting in two markets: firms sell goods and services to households, and households sell their labour to firms.<sup class=\"fn\" data-fn=\"1\"></sup> Goods and labour move one way round the circle while payments, the revenues firms receive and the wages, salaries and benefits households earn, move the other.<sup class=\"fn\" data-fn=\"1\"></sup> This version is stripped down to essentials, and it can be extended to include financial markets, governments and trade with the rest of the world, as national accounts do when they record flows among all the sectors of an economy.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Because every payment for output is also someone's income, total spending, production and incomes in an economy over a year are, in principle, the same.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> That equality is why gross domestic product can be measured in three ways: by the value added in production, by the purchases of final users or by the incomes that production generates.<sup class=\"fn\" data-fn=\"4\"></sup> The expenditure approach adds consumption by households, investment by companies and purchases by government and foreigners, summed up in the identity that output equals consumption, investment, government purchases and net exports.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> The image goes back to 18th-century France, where a group of economists called the Physiocrats compared the way the economy worked to the circulation of blood in the body.<sup class=\"fn\" data-fn=\"2\"></sup> Their leading figure drew a zigzag table showing who produced and who spent what among landowners, farmers and a so-called sterile class.<sup class=\"fn\" data-fn=\"3\"></sup> The circle also underlies the multiplier, the process by which new spending raises the incomes of the people producing the extra output, part of which is spent again in turn.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["<i>Principles of Economics 3e</i>, “1.3 How Economists Use Theories and Models to Understand Economic Issues,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/1-3-how-economists-use-theories-and-models-to-understand-economic-issues. [Open access]","The CORE Team, <i>The Economy</i> 1.0, unit 13, “Economic Fluctuations and Unemployment,” section 13.3, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/13.html. [Open access]","“François Quesnay,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/bios/Quesnay.html. [Open access]","Tim Callen, “What Is Gross Domestic Product?,” <i>Finance & Development</i> 45, no. 4 (December 2008), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2008/12/basics.htm. [Open access]","European Commission, International Monetary Fund, OECD, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), paras. 4.2–4.31 and 22.164, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","The CORE Team, <i>The Economy</i> 1.0, unit 14, “Unemployment and Fiscal Policy,” CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/14.html. [Open access]","Mark Horton and Asmaa El-Ganainy, “What Is Fiscal Policy?,” <i>Finance & Development</i> 46, no. 2 (June 2009), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2009/06/basics.htm. [Open access]"],"why":[{"q":"Why must spending, output and income add up to the same total?","a":"Because every payment for output is income for someone: money flows from the spender to the producer, and from the producer to its employees or shareholders.<sup class=\"fn\" data-fn=\"2\"></sup> In principle, therefore, a year's expenditure, output and incomes are equal, which is why gross domestic product can be measured by any of the three.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does the simple model leave out government and trade?","a":"Because it is stripped down to the essentials needed to explain how the product and labour markets work.<sup class=\"fn\" data-fn=\"1\"></sup> Financial markets, governments, imports and exports can all be added, and national accounts record the full set of flows among the sectors of an economy.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why did the earliest circular diagram treat manufacturing as sterile?","a":"Because its author believed that only agriculture could produce a surplus to fund further production.<sup class=\"fn\" data-fn=\"3\"></sup> He did not reach that conclusion from the table; he built the table to fit his belief, and even had to make it inconsistent to do so.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Circular flow of income"},
    "ec-011": {"questions":["Because a scarcity of one raw material raises its price, a <span class=\"blank\">_____</span> can make thousands of users economise on it without any order being issued, since the price carries information no planner holds.","How far workers can specialise is limited by the extent of the <span class=\"blank\">_____</span>, so a porter finds work only in a great town while a Highland farmer must be his own baker."],"abstract":"A <b>market</b> is an institution that brings together buyers and sellers of goods or services, whether they meet on a trading floor, in a village square or on a website.<sup class=\"fn\" data-fn=\"1\"></sup> Markets usually use money, which leads to the formation of prices, and they differ in what is traded, how far they reach and how competitive they are.<sup class=\"fn\" data-fn=\"7\"></sup> One textbook definition picks out three features: the transfer is directly reciprocated, unlike a gift; it is entered into voluntarily for mutual benefit, unlike theft or taxation; and it is often impersonal, unlike a transfer among friends or family.<sup class=\"fn\" data-fn=\"2\"></sup> In the simplest model, the market-clearing price is the one at which buyers want to purchase exactly what sellers want to supply, and a higher price draws in more supply while discouraging purchases.<sup class=\"fn\" data-fn=\"5\"></sup> A classic argument of 1776 held that it is the power of exchanging that makes the division of labour possible, so that how far people can specialise is limited by the extent of the market.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Much of the interest economists take in markets lies in what prices do, because a price summarises information that is scattered among many people and held by none of them in full.<sup class=\"fn\" data-fn=\"4\"></sup> A well-known essay of 1945 calls the price system a kind of machinery for registering change, by which a scarcity of one raw material makes thousands of people use it more sparingly with no order issued.<sup class=\"fn\" data-fn=\"4\"></sup> Markets are nonetheless made rather than found: they rest on formal rules such as property rights and contracts and on informal ones such as customs, and no economy has an absolutely free market.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Most societies also refuse to allow some exchanges, such as the sale of organs for transplant or of babies, because they are felt to be repugnant, even when both parties would willingly agree.<sup class=\"fn\" data-fn=\"8\"></sup><sup class=\"fn\" data-fn=\"9\"></sup> Even in economies that rely on markets, a great deal of resource allocation happens outside them, inside firms, families and governments.<sup class=\"fn\" data-fn=\"9\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “1.8 Capitalist Institutions,” https://www.core-econ.org/the-economy/microeconomics/01-prosperity-inequality-08-capitalist-institutions.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), book 1, chapters 2–3, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","F. A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]","Irena Asmundson, “Back to Basics: Supply and Demand,” <i>Finance &amp; Development</i> 47, no. 2 (June 2010), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2010/06/basics.htm. [Open access]","Douglass C. North, “Institutions,” <i>Journal of Economic Perspectives</i> 5, no. 1 (1991): 97–112, https://www.aeaweb.org/articles?id=10.1257/jep.5.1.97. [Open access]","Lisa Herzog, “Markets,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2025), https://plato.stanford.edu/entries/markets/. [Open access]","Alvin E. Roth, “Repugnance as a Constraint on Markets,” <i>Journal of Economic Perspectives</i> 21, no. 3 (2007): 37–58, https://www.aeaweb.org/articles?id=10.1257/jep.21.3.37. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “10.11 The Limits of Markets,” https://www.core-econ.org/the-economy/microeconomics/10-market-successes-failures-11-market-limits.html. [Open access]"],"why":[{"q":"Why does a market need rules before it can work?","a":"Because exchange depends on institutions that people have devised: formal rules such as property rights and contracts, and informal ones such as customs and codes of conduct.<sup class=\"fn\" data-fn=\"6\"></sup> Even market-oriented economies have laws that protect property, enforce contracts and prevent fraud, which is why no economy has an absolutely free market.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do prices matter so much in a market?","a":"Because a price summarises information that is scattered among many people.<sup class=\"fn\" data-fn=\"4\"></sup> When a raw material grows scarce its price rises, users economise on it without needing to know why, and the higher price also draws in more supply.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why are some exchanges banned even when both sides agree?","a":"Because many people feel that selling certain things, such as organs or babies, violates human dignity, or doubt that a poor seller's consent is truly free.<sup class=\"fn\" data-fn=\"9\"></sup> Distaste of this kind constrains which markets exist as firmly as technology does, though it can change over time, as the history of lending at interest shows.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Market (economics)"},
    "ec-012": {"questions":["Goods in a <span class=\"blank\">_____</span> move as presents that bind people to give, to receive and to repay, so a return is expected but is never bargained over at the moment the thing changes hands.","A market sale is directly reciprocated, but a transfer in a <span class=\"blank\">_____</span> builds or marks a relationship, which is why handling one like barter was a recognised insult among the islanders who practised it."],"abstract":"A <b>gift economy</b> is a way of moving goods and services between people in which things are given rather than sold, and the return, if it comes, is not bargained over when the transfer is made.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Commercial exchange runs on the opposite principle, as an 18th-century classic put it, expecting a dinner not from the benevolence of the butcher but from his regard to his own interest.<sup class=\"fn\" data-fn=\"7\"></sup> Gifts are rarely free, however: a comparative study of the 1920s described transfers that were in theory voluntary, disinterested and spontaneous but in fact obligatory and interested.<sup class=\"fn\" data-fn=\"4\"></sup> It found three linked obligations, to give, to receive and to repay, and showed that failing to make a return could cost a person his honour, prestige and authority.<sup class=\"fn\" data-fn=\"4\"></sup> The best-known case is the kula of the islands east of New Guinea, where necklaces of red shell travelled one way round a closed ring of islands and bracelets of white shell the other.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> Each kula gift had to be repaid by an equivalent counter-gift after a lapse of time, and a disappointed partner had no direct means of forcing a better return.<sup class=\"fn\" data-fn=\"5\"></sup> The islanders sharply distinguished the kula from barter, which they also practised and called gimwali, and to say that a man conducted his kula as if it were gimwali was a criticism.<sup class=\"fn\" data-fn=\"5\"></sup> That contrast is the point of the term: a market transfer is directly reciprocated, voluntary and often impersonal, while a gift is exchanged to build a relationship.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Even in market economies much allocation is not done by markets at all, since families do not buy and sell among parents and children and governments decide by politics where schools are built.<sup class=\"fn\" data-fn=\"2\"></sup> Gift-like exchange also survives inside markets, as in the argument that firms may pay more than the market-clearing wage to shape workers' sense of a fair day's work, treating a labour contract as partly a gift exchange.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “1.8 Capitalist Institutions,” https://www.core-econ.org/the-economy/microeconomics/01-prosperity-inequality-08-capitalist-institutions.html. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “10.11 The Limits of Markets,” https://www.core-econ.org/the-economy/microeconomics/10-market-successes-failures-11-market-limits.html. [Open access]","Lisa Herzog, “Markets,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2025), https://plato.stanford.edu/entries/markets/. [Open access]","Marcel Mauss, <i>The Gift: Forms and Functions of Exchange in Archaic Societies</i>, trans. Ian Cunnison (London: Cohen &amp; West, 1966), https://archive.org/details/giftformsfunctio00maus. [Open access]","Bronislaw Malinowski, <i>Argonauts of the Western Pacific</i> (London: George Routledge &amp; Sons, 1922), Project Gutenberg, https://www.gutenberg.org/ebooks/55822. [Open access]","George A. Akerlof, “Labor Contracts as Partial Gift Exchange,” <i>Quarterly Journal of Economics</i> 97, no. 4 (1982): 543–69, EconPapers, https://econpapers.repec.org/RePEc:oup:qjecon:v:97:y:1982:i:4:p:543-569. [Paywalled]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), book 1, chapters 2–3, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]"],"why":[{"q":"Why is a gift not really free?","a":"Because gifts create obligations.<sup class=\"fn\" data-fn=\"4\"></sup> Transfers that look voluntary, disinterested and spontaneous turn out to be obligatory and interested, binding people to give, to receive and to repay, and a failure to repay can cost honour and standing.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why did kula partners refuse to haggle?","a":"Because the islanders sharply separated the kula from barter, which they called gimwali.<sup class=\"fn\" data-fn=\"5\"></sup> Haggling and bargaining were ruled out of the kula, each gift was answered later by an equivalent counter-gift, and conducting kula as if it were barter was a criticism.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why does the gift help explain what a market is?","a":"Because it shows by contrast what a market transfer is: directly reciprocated, voluntary and often impersonal.<sup class=\"fn\" data-fn=\"1\"></sup> It is also a reminder that families, firms and governments allocate a great deal without buying and selling, even in market economies.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Gift economy"},
    "ec-013": {"questions":["A team made of excellent researchers need not be an excellent team, and reasoning that it must commits the <span class=\"blank\">_____</span>, the error of carrying a property from the parts to the whole.","Each depositor who rushes to withdraw protects his own savings, yet together they can sink the bank, so assuming that what is safe for each is safe for all is the <span class=\"blank\">_____</span> at work."],"abstract":"The <b>fallacy of composition</b> is the mistake of assuming that a property of the parts of a whole must also belong to the whole.<sup class=\"fn\" data-fn=\"1\"></sup> Logicians illustrate it with a group of excellent researchers, which need not be an excellent team if its members cannot work together, and pair it with the reverse error, the fallacy of division.<sup class=\"fn\" data-fn=\"1\"></sup> Economics meets it constantly, because a modern economy is a complex system in which the economic life of every individual is interrelated with the lives of thousands or even millions of others.<sup class=\"fn\" data-fn=\"3\"></sup> The subject is divided partly for that reason into microeconomics, which studies households, workers and businesses, and macroeconomics, which looks at the economy as a whole.<sup class=\"fn\" data-fn=\"2\"></sup> The two are complementary views of one economy, rather like studying a lake plant by plant or as an ecosystem, and the macroeconomy's performance depends in the end on millions of individual decisions.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The standard example is saving: one household that saves more grows richer, but if everyone tries to save more at once, spending falls and so do the incomes out of which saving comes.<sup class=\"fn\" data-fn=\"4\"></sup> A classic statement of 1936 put it that the effect of each person's consumption on the incomes of others makes it impossible for all individuals simultaneously to save any given sums.<sup class=\"fn\" data-fn=\"4\"></sup> The argument rests on the view that aggregate demand, the sum of spending by households, businesses and government, drives output in the short run, although over the long run saving is how an economy keeps its stock of capital growing.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A bank run shows the same gap, since each depositor who hurries to withdraw is protecting his own money, but together they force the bank to recall loans early and may cause it to collapse.<sup class=\"fn\" data-fn=\"5\"></sup> The lesson is not that a whole always behaves differently from its parts, only that a conclusion about one household, firm or depositor cannot be carried over to the economy without asking how their actions affect one another.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>","sources":["Hans Hansen, “Fallacies,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2024), https://plato.stanford.edu/entries/fallacies/. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.2 Microeconomics and Macroeconomics” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-2-microeconomics-and-macroeconomics. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]","John Maynard Keynes, <i>The General Theory of Employment, Interest and Money</i> (London: Macmillan, 1936), chapters 7 and 24, Project Gutenberg Australia, https://gutenberg.net.au/ebooks03/0300071h/printall.html. [Open access]","Royal Swedish Academy of Sciences, “The Laureates Explained the Central Role of Banks in Financial Crises,” popular science background to the Prize in Economic Sciences 2022, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/2022/popular-information/. [Open access]","Laurence J. Kotlikoff, “Saving,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Saving.html. [Open access]","Sarwat Jahan, Ahmed Saber Mahmud and Chris Papageorgiou, “What Is Keynesian Economics?,” <i>Finance &amp; Development</i> 51, no. 3 (September 2014), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2014/09/basics.htm. [Open access]"],"why":[{"q":"Why can't everyone save more at the same time?","a":"Because one person's spending is another person's income.<sup class=\"fn\" data-fn=\"4\"></sup> If all households cut their consumption at once in order to save, incomes fall, so the attempt to save more defeats itself in the short run.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is a bank run an example of the fallacy?","a":"Because withdrawing is sensible for any one depositor, but a rush of withdrawals forces the bank to recall long-term loans early and sell assets in fire sales.<sup class=\"fn\" data-fn=\"5\"></sup> The resulting losses may bring down the bank that each depositor was trying to escape.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why does economics separate micro from macro?","a":"Because microeconomics studies individual households, workers and firms while macroeconomics looks at the economy as a whole.<sup class=\"fn\" data-fn=\"2\"></sup> They are complementary, since firms hire more when the whole economy grows and the whole depends on individual decisions.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Fallacy of composition"},
    "ec-014": {"questions":["Custom settles them in a traditional economy, a government in a command economy and buyers and sellers in a market economy, but every society must answer <span class=\"blank\">_____</span> somehow, because its resources are limited.","The third of the questions summed up as <span class=\"blank\">_____</span> concerns distribution, and an early-19th-century treatise called the laws dividing produce among rent, profit and wages the principal problem of the subject."],"abstract":"<b>What, how and for whom</b> are the three basic questions every economy is said to answer: which goods and services it will produce, how it will produce them, and who will receive them.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> They arise from scarcity, because human wants exceed what limited labour, land, tools and raw materials can produce, so making more of one thing means making less of another.<sup class=\"fn\" data-fn=\"8\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The first is a choice among uses, since better education may require less health care and a preserved wilderness is land given up for other purposes.<sup class=\"fn\" data-fn=\"1\"></sup> The second concerns methods, such as whether a firm employs a few skilled workers or many unskilled ones, produces at home or abroad, and uses new or recycled materials.<sup class=\"fn\" data-fn=\"1\"></sup> The third is about distribution, because a good or service that goes to one person or group is usually not available to someone else.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The answers a society gives depend on its economic system, the way it organises the production and distribution of goods and services through its basic institutions.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> In a traditional economy custom and inheritance settle them, in a command economy a ruler or government decides, and in a market economy they are the combined result of many decisions by buyers and sellers.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Economists have long given the third question special weight, and an early-19th-century treatise called the laws regulating the division of the produce among rent, profit and wages the principal problem in political economy.<sup class=\"fn\" data-fn=\"6\"></sup> A definition of 1932 recast the whole subject as the study of human behaviour as a relationship between ends and scarce means which have alternative uses.<sup class=\"fn\" data-fn=\"5\"></sup> A later objection held that the problem is not merely allocating given resources, because the knowledge needed to answer what and how is dispersed among many people and never held complete by any one planner.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["<i>Principles of Macroeconomics</i>, version 2.0, “1.1 Defining Economics” (Saylor Academy), https://saylordotorg.github.io/text_principles-of-macroeconomics-v2.0/s04-01-defining-economics.html. [Open access]","“Three Economic Questions: What, How, For Whom?,” in <i>Everyday Finance: Economics, Personal Money Management, and Entrepreneurship</i> (Gale), Encyclopedia.com, https://www.encyclopedia.com/finance/encyclopedias-almanacs-transcripts-and-maps/three-economic-questions-what-how-whom. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “1.8 Capitalist Institutions,” https://www.core-econ.org/the-economy/microeconomics/01-prosperity-inequality-08-capitalist-institutions.html. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), chapter 1, Mises Institute, https://mises.org/library/book/essay-nature-and-significance-economic-science. [Open access]","David Ricardo, <i>On the Principles of Political Economy and Taxation</i>, 3rd ed. (1821), preface, Library of Economics and Liberty, https://www.econlib.org/library/Ricardo/ricP.html. [Open access]","F. A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.1 What Is Economics, and Why Is It Important?” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]"],"why":[{"q":"Why must every society answer these questions?","a":"Because resources are limited while human wants exceed them.<sup class=\"fn\" data-fn=\"8\"></sup> Producing one thing with scarce resources means giving up another, so every economy must decide what to produce, how and for whom.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do different economies answer them differently?","a":"Because the answers depend on the economic system.<sup class=\"fn\" data-fn=\"2\"></sup> Custom and inheritance settle them in a traditional economy, a government in a command economy, and the decentralised choices of private owners, buyers and sellers in a market economy.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the for-whom question more than a technical one?","a":"Because a good that goes to one person is usually unavailable to another, so it is a question of distribution, as complaints about the gap in energy use between rich and poor countries show.<sup class=\"fn\" data-fn=\"1\"></sup> An early-19th-century treatise made the division of produce among rent, profit and wages the principal problem in political economy.<sup class=\"fn\" data-fn=\"6\"></sup>"}]},
    "ec-015": {"questions":["Because even command economies use markets and even market economies regulate them, nearly every real economy is a <span class=\"blank\">_____</span>, and the argument is over the proportions rather than the principle.","Government spending rising from about a tenth of output in late-19th-century Europe to nearly half in many European countries today measures how far each <span class=\"blank\">_____</span> has moved toward the state."],"abstract":"A <b>mixed economy</b> combines the institutions of command and market systems, and sometimes of traditional ones, within a single economy.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> At one pole stands the command economy, in which a government decides what is produced, sets prices and wages and owns resources and businesses, as Soviet planners did through a pyramid of command.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> At the other is the market economy, in which private owners run businesses and decisions are decentralised among buyers and sellers, a system that in its purest form would need no government intervention.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> In practice most countries mix the two, and even the United States, which calls itself a market economy, runs public schools and the postal service and imposes a minimum wage and emissions standards.<sup class=\"fn\" data-fn=\"2\"></sup> Conversely, even the most command-oriented economies use markets, and heavy regulation tends to breed underground markets in which buyers and sellers trade without the government's approval.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The useful question is therefore not whether an economy is mixed but in what proportions, a balancing act between market freedom and government rules.<sup class=\"fn\" data-fn=\"1\"></sup> One rough measure is public spending: at the end of the 19th century European governments spent around 10% of their GDP, and in the 21st century the figure is closer to 50% in many European countries.<sup class=\"fn\" data-fn=\"5\"></sup> Much of that growth came between 1945 and 1980 and was driven by social spending on health care, education and social protection.<sup class=\"fn\" data-fn=\"5\"></sup> A famous argument of 1936 for the mix held that the state should take on a somewhat comprehensive socialisation of investment to secure full employment, while the traditional advantages of individualism held good elsewhere.<sup class=\"fn\" data-fn=\"4\"></sup> The label is also contested, since one free-market critic uses it for a system in which government bestows favours and imposes restrictions without consistent principles, and defenders of free prices stress the knowledge that no central authority holds.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]","“Three Economic Questions: What, How, For Whom?,” in <i>Everyday Finance: Economics, Personal Money Management, and Entrepreneurship</i> (Gale), Encyclopedia.com, https://www.encyclopedia.com/finance/encyclopedias-almanacs-transcripts-and-maps/three-economic-questions-what-how-whom. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “1.8 Capitalist Institutions,” https://www.core-econ.org/the-economy/microeconomics/01-prosperity-inequality-08-capitalist-institutions.html. [Open access]","John Maynard Keynes, <i>The General Theory of Employment, Interest and Money</i> (London: Macmillan, 1936), chapters 7 and 24, Project Gutenberg Australia, https://gutenberg.net.au/ebooks03/0300071h/printall.html. [Open access]","Esteban Ortiz-Ospina, Bertha Rohenkohl, Pablo Arriagada and Max Roser, “Government Spending,” Our World in Data, 2016, consulted November 2026, https://ourworldindata.org/government-spending. [Open access]","Robert Hessen, “Capitalism,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Capitalism.html. [Open access]","Robert Heilbroner, “Socialism,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Socialism.html. [Open access]","F. A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]"],"why":[{"q":"Why are almost all real economies called mixed?","a":"Because even economies that call themselves market economies rely on government to run services such as schools and to set rules such as a minimum wage.<sup class=\"fn\" data-fn=\"2\"></sup> Even the most command-oriented economies still use markets for buying and selling.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did government spending grow so much in the 20th century?","a":"Because social spending grew, especially between 1945 and 1980, as governments paid for more health care, education and social protection.<sup class=\"fn\" data-fn=\"5\"></sup> Rising government revenues over the same period made that growth possible.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why do some economists dislike the term?","a":"Because to one free-market critic it describes a system in which government bestows favours and imposes restrictions with no clear or consistent principles.<sup class=\"fn\" data-fn=\"6\"></sup> Defenders of free prices add that prices carry dispersed knowledge which no planner can gather.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Mixed economy"},
    "ec-016": {"questions":["Asking why Soviet planning stalled, and why leaving it cost more output than the Second World War, is the work of <span class=\"blank\">_____</span>, a field that now compares capitalist economies too.","A regionally decentralised authoritarian state, in which the centre controls personnel while provinces run most of the economy, is the kind of Chinese puzzle that <span class=\"blank\">_____</span> tries to explain and classify."],"abstract":"<b>Comparative economic systems</b> is the field of economics that compares how different societies organise production and distribution in practice, and what happens when one system is exchanged for another.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> For most of the 20th century its central comparison was between Soviet-type central planning and capitalism, a rivalry in which, one economist later admitted, many expected socialism to be the organising force of the 21st century.<sup class=\"fn\" data-fn=\"1\"></sup> Under Soviet planning a state planning agency set general directives that were broken down into targets for particular factories and farms, so that the final plan resembled an immense order book.<sup class=\"fn\" data-fn=\"1\"></sup> Because the plan specified outputs in physical terms, managers maximised tonnages rather than quality, and a satirical cartoon showed a manager proudly displaying a single gigantic nail.<sup class=\"fn\" data-fn=\"1\"></sup> Planning nonetheless produced steady growth for nearly fifty years, before the Soviet Union acknowledged in the 1980s a near end to growth that was in reality a decline.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Explanations of the failure differ: one stresses that planners lacked the information that rising and falling prices carry, another that they lacked the motivation to act on the information they had.<sup class=\"fn\" data-fn=\"1\"></sup> A capitalist firm that ignores prices loses money, whereas officials in a planning ministry learned that doing something was more likely to get them into trouble than doing nothing.<sup class=\"fn\" data-fn=\"1\"></sup> Leaving planning was itself very costly, since building market institutions in the former Soviet Union brought a deeper and longer fall in output per head than the Second World War or the global financial crisis.<sup class=\"fn\" data-fn=\"2\"></sup> The field has since turned to comparing capitalist economies, asking how institutions trade off the costs of disorder against those of dictatorship, and it uses ideas such as the soft budget constraint across socialist, transitional and market economies alike.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> China fits neither old category neatly, since one analysis describes a regionally decentralised authoritarian system whose centre controls personnel while subnational governments run most of the economy, and it is still placed nearer the command end of the spectrum.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Robert Heilbroner, “Socialism,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Socialism.html. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “1.12 Varieties of Capitalism: Institutions, Government, and Politics,” https://www.core-econ.org/the-economy/microeconomics/01-prosperity-inequality-12-capitalism-varieties.html. [Open access]","Simeon Djankov, Edward Glaeser, Rafael La Porta, Florencio Lopez-de-Silanes and Andrei Shleifer, “The New Comparative Economics,” NBER Working Paper 9608 (2003), published in <i>Journal of Comparative Economics</i> 31, no. 4 (2003): 595–619, https://www.nber.org/papers/w9608. [Open access]","János Kornai, Eric Maskin and Gérard Roland, “Understanding the Soft Budget Constraint,” <i>Journal of Economic Literature</i> 41, no. 4 (2003): 1095–1136, EconPapers, https://econpapers.repec.org/RePEc:aea:jeclit:v:41:y:2003:i:4:p:1095-1136. [Paywalled]","Chenggang Xu, “The Fundamental Institutions of China’s Reforms and Development,” <i>Journal of Economic Literature</i> 49, no. 4 (2011): 1076–1151, EconPapers, https://econpapers.repec.org/RePEc:aea:jeclit:v:49:y:2011:i:4:p:1076-1151. [Paywalled]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.4 How To Organize Economies: An Overview of Economic Systems” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-4-how-to-organize-economies-an-overview-of-economic-systems. [Open access]"],"why":[{"q":"Why did Soviet planning produce a giant nail?","a":"Because the plan set targets in physical terms, so managers maximised the tonnage or yardage of output rather than its quality.<sup class=\"fn\" data-fn=\"1\"></sup> The cartoon of a manager showing off one enormous nail made the point, and shortages of unplanned inputs grew alongside it.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why was leaving central planning so costly?","a":"Because dismantling the planned economy meant building market institutions, including the rule of law, almost from nothing.<sup class=\"fn\" data-fn=\"2\"></sup> The fall in output per head in the former Soviet Union was deeper and longer than in the Second World War, the global financial crisis or the COVID-19 pandemic.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is China hard to fit into the old categories?","a":"Because it combined spectacular growth with institutions that look ill-suited to it: a regionally decentralised authoritarian system in which the centre controls personnel and subnational governments run the bulk of the economy.<sup class=\"fn\" data-fn=\"5\"></sup> Textbooks still place it closer to the command end of the spectrum than most economies.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Comparative economic systems"},
    "ec-017": {"questions":["Values about redistribution, efficiency against equity and individual against social responsibility make up an <span class=\"blank\">_____</span>, which surveys suggest predicts economists' policy positions better than their estimates of the evidence do.","Bitter quarrels over the policy response to the recession of 2008 are often cited as proof that <span class=\"blank\">_____</span> shapes economics, a discipline whose theories bear directly on people's interests."],"abstract":"An <b>economic ideology</b> is a set of values and beliefs about how an economy should be run, such as views on redistribution, on efficiency against equity and on individual against social responsibility.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Most economists hold that facts and values can be reasonably clearly separated, so that economics is largely a positive science helping policy makers choose means rather than ends.<sup class=\"fn\" data-fn=\"1\"></sup> Critics reply that economics is itself a human activity governed by values, and that because its theories bear so centrally on people's interests ideological biases are bound to be at work.<sup class=\"fn\" data-fn=\"1\"></sup> The bitter arguments over macroeconomic policy after the recession of 2008 are often cited as evidence, and earlier disputes between schools turned on questions such as how quickly wages and prices adjust.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Economists disagree in public so often that they are easy targets for comedians, though one account holds that most of the disagreement is over details rather than broad theory.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Surveys allow the question to be tested, and one of labour and public economists at 40 leading American universities, published in 1998, found considerable disagreement about policy proposals.<sup class=\"fn\" data-fn=\"2\"></sup> Their positions on policy were more closely related to their values than to their estimates of the relevant economic parameters or to their political party.<sup class=\"fn\" data-fn=\"2\"></sup> A study of a panel of distinguished economists found broad consensus, especially where the research literature was large, with the remaining differences idiosyncratic rather than split into liberal and conservative camps.<sup class=\"fn\" data-fn=\"3\"></sup> In an experiment with 2,425 economists in 19 countries, crediting a statement to a less mainstream author rather than a mainstream one, or to no one, significantly reduced agreement with it.<sup class=\"fn\" data-fn=\"4\"></sup> Economists also differ from the public, since on one set of policy questions the gap between experts and a representative sample of Americans was 35 percentage points, only partly explained by ideology.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","Victor R. Fuchs, Alan B. Krueger and James M. Poterba, “Why Do Economists Disagree About Policy?,” NBER Working Paper 6151 (1997), published in <i>Journal of Economic Literature</i> 36, no. 3 (1998): 1387–1425, https://www.nber.org/papers/w6151. [Open access]","Roger Gordon and Gordon B. Dahl, “Views among Economists: Professional Consensus or Point-Counterpoint?,” <i>American Economic Review</i> 103, no. 3 (2013): 629–35, https://www.aeaweb.org/articles?id=10.1257/aer.103.3.629. [Paywalled]","Mohsen Javdani and Ha-Joon Chang, “Who Said or What Said? Estimating Ideological Bias in Views among Economists,” IZA Discussion Paper 12738 (2019), published in <i>Cambridge Journal of Economics</i> 47, no. 2 (2023): 309–39, EconPapers, https://econpapers.repec.org/RePEc:iza:izadps:dp12738. [Open access]","Paola Sapienza and Luigi Zingales, “Economic Experts versus Average Americans,” <i>American Economic Review</i> 103, no. 3 (2013): 636–42, https://www.aeaweb.org/articles?id=10.1257/aer.103.3.636. [Paywalled]","E. Roy Weintraub, “Neoclassical Economics,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/NeoclassicalEconomics.html. [Open access]","Alan S. Blinder, “Keynesian Economics,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/KeynesianEconomics.html. [Open access]"],"why":[{"q":"Why might values matter more than evidence in policy disputes?","a":"Because surveyed economists' policy positions were more closely related to their values than to their estimates of the relevant parameters or their party identification.<sup class=\"fn\" data-fn=\"2\"></sup> Their individual estimates were also widely dispersed, and more confident than that spread warranted.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why do some say economists agree more than they appear to?","a":"Because a panel of distinguished economists showed broad consensus, particularly where the literature was large, with no liberal and conservative camps.<sup class=\"fn\" data-fn=\"3\"></sup> On one account, most public disagreement is over details rather than broad theory.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why is a value-free economics hard to achieve?","a":"Because although most economists think facts and values can be separated, economics is a human activity governed by values.<sup class=\"fn\" data-fn=\"1\"></sup> An experiment found that changing who a statement was attributed to changed how far economists agreed with it, though 82% said only content should count.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Economic ideology"},
    "ec-018": {"questions":["Heterodox schools such as the Austrian, institutionalist and post-Keynesian are usually defined negatively, by what sets them apart from <span class=\"blank\">_____</span>, the dominant tradition marked out by prestige and influence.","Student groups complain that courses present <span class=\"blank\">_____</span> as the whole subject, leaving out classical, feminist, Marxist, ecological and Austrian traditions that start from different assumptions about the economy."],"abstract":"<b>Mainstream economics</b> is the economics associated with the most prestigious university departments and the greatest influence, the dominant school that demands most of the discipline's attention.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Its core is usually called neoclassical: households and firms optimise subject to constraints, and the interaction of their choices in markets, signalled by prices, leads towards an equilibrium.<sup class=\"fn\" data-fn=\"2\"></sup> Its fundamental assumptions, such as that people have rational preferences and maximise utility, are the shared understandings of those who call themselves economists without any adjective.<sup class=\"fn\" data-fn=\"2\"></sup> It is far from uniform: some of it is highly theoretical, though most is applied and relies on rudimentary theory, and it divides into microeconomics, macroeconomics and econometrics, which estimates and tests their models.<sup class=\"fn\" data-fn=\"1\"></sup> Its boundary also moves, and one account argued in 2004 that it was shifting away from neoclassical economics towards dynamics, recursive methods and complexity.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Beside it stand other schools of thought, which differ from it and from one another less in their answers to particular questions than in their starting assumptions about how an economy works.<sup class=\"fn\" data-fn=\"1\"></sup> Austrian economists stress uncertainty and doubt the value of mathematical modelling, institutionalists question abstract general theory, and post-Keynesians build on Keynes's emphasis on demand.<sup class=\"fn\" data-fn=\"1\"></sup> Within macroeconomics the long contest between Keynesians, monetarists and new classical economists turned on questions such as whether markets adjust quickly enough to cure a recession by themselves.<sup class=\"fn\" data-fn=\"7\"></sup> Schools outside the mainstream are grouped as heterodox, a term usually defined negatively, and one argument finds their common ground in questions of ontology, about what social reality is made of, rather than in shared policies.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> A student campaign has complained that classical, post-Keynesian, institutional, ecological, feminist, Marxist and Austrian traditions are largely excluded from teaching, which presents economics as a unified body of knowledge.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","E. Roy Weintraub, “Neoclassical Economics,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/NeoclassicalEconomics.html. [Open access]","David Dequech, “Neoclassical, Mainstream, Orthodox, and Heterodox Economics,” <i>Journal of Post Keynesian Economics</i> 30, no. 2 (2007): 279–302, EconPapers, https://econpapers.repec.org/RePEc:mes:postke:v:30:y:2007:i:2:p:279-302. [Paywalled]","David Colander, Richard Holt and J. Barkley Rosser, “The Changing Face of Mainstream Economics,” <i>Review of Political Economy</i> 16, no. 4 (2004): 485–99, EconPapers, https://econpapers.repec.org/RePEc:taf:revpoe:v:16:y:2004:i:4:p:485-499. [Paywalled]","Tony Lawson, “The Nature of Heterodox Economics,” <i>Cambridge Journal of Economics</i> 30, no. 4 (2006): 483–505, EconPapers, https://econpapers.repec.org/RePEc:oup:cambje:v:30:y:2006:i:4:p:483-505. [Paywalled]","International Student Initiative for Pluralism in Economics, “An International Student Call for Pluralism in Economics,” open letter, 5 May 2014, https://www.isipe.net/open-letter. [Open access]","Alan S. Blinder, “Keynesian Economics,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/KeynesianEconomics.html. [Open access]"],"why":[{"q":"Why is mainstream economics hard to define?","a":"Because it is marked out by prestige and influence, as the ideas taught in prestigious schools, rather than by one theory.<sup class=\"fn\" data-fn=\"3\"></sup> It is clearly diverse, and whether it shares a common core is controversial.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do schools of economic thought disagree so deeply?","a":"Because they start from different assumptions.<sup class=\"fn\" data-fn=\"1\"></sup> Austrians emphasise uncertainty and distrust mathematical models, institutionalists doubt abstract general theory, and post-Keynesians build on Keynes's emphasis on demand.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does the mainstream change over time?","a":"Because influential work at its edge pulls it along, and one account argued in 2004 that it was moving towards dynamics and complexity.<sup class=\"fn\" data-fn=\"4\"></sup> Earlier, the Keynesian challenge was absorbed so fully that one writer says what is taught today is neoclassical, Keynesians included.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Mainstream economics"},
    "ec-019": {"questions":["Where economists applied utility maximisation to crime and marriage, <span class=\"blank\">_____</span> moved the other way, arguing that economic action is embedded in social relations rather than standing apart from them.","The older claim that a market society reverses the usual order, embedding social relations in the economy, was taken up by <span class=\"blank\">_____</span> as a challenge to the isolated, maximising individual of economic models."],"abstract":"<b>Economic sociology</b> is the study of economic life, markets included, from the side of sociology, one of several disciplines, alongside history and economics itself, in which markets are analysed.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Its best-known idea is embeddedness, the claim that market relations are often embedded in personal relationships, such as the ties between technical experts in different companies.<sup class=\"fn\" data-fn=\"1\"></sup> It draws on an older argument that in most societies the economy was embedded in social relations, whereas a market society reverses the order so that social relations are embedded in the economy.<sup class=\"fn\" data-fn=\"1\"></sup> Economics starts from different assumptions, since its theories rest on particular assumptions about human behaviour that tend to differ from those an anthropologist or a psychologist would use.<sup class=\"fn\" data-fn=\"6\"></sup> One statement of the difference lists three things economists insist on: rational individuals who maximise, equilibrium as part of any theory, and a focus on efficiency.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> The same statement argued that those ingredients had carried economics into intellectual territory once thought to lie outside it, and named the movement economic imperialism.<sup class=\"fn\" data-fn=\"5\"></sup> Its most famous examples apply utility maximisation to discrimination, crime and the family, interpreting marriage, divorce and fertility as forward-looking choices.<sup class=\"fn\" data-fn=\"4\"></sup> That approach does not assume that people are selfish, only that they maximise welfare as they conceive it, whether they are selfish, altruistic, loyal or spiteful.<sup class=\"fn\" data-fn=\"4\"></sup> Bibliometric evidence suggests the traffic has run mostly one way, with economics relatively insular, tightly managed from the top down and dominant within the network of the American social sciences.<sup class=\"fn\" data-fn=\"3\"></sup> Philosophers of economics have noted efforts to fuse economics and sociology, and sociological studies of economics itself, which have long looked for ideological distortions in its theory and its policy advice.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Lisa Herzog, “Markets,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2025), https://plato.stanford.edu/entries/markets/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","Marion Fourcade, Etienne Ollion and Yann Algan, “The Superiority of Economists,” <i>Journal of Economic Perspectives</i> 29, no. 1 (2015): 89–114, https://www.aeaweb.org/articles?id=10.1257/jep.29.1.89. [Open access]","Gary S. Becker, “The Economic Way of Looking at Life,” Nobel Prize lecture, 9 December 1992, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1992/becker/lecture/. [Open access]","Edward P. Lazear, “Economic Imperialism,” <i>Quarterly Journal of Economics</i> 115, no. 1 (2000): 99–146, EconPapers, https://econpapers.repec.org/RePEc:oup:qjecon:v:115:y:2000:i:1:p:99-146. [Paywalled]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.3 How Economists Use Theories and Models to Understand Economic Issues” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-3-how-economists-use-theories-and-models-to-understand-economic-issues. [Open access]"],"why":[{"q":"Why do economics and sociology often clash?","a":"Because economists analyse issues with theories built on particular assumptions about behaviour that differ from those of other social scientists.<sup class=\"fn\" data-fn=\"6\"></sup> Economists insist on rational maximising individuals, on equilibrium and on efficiency.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why did economists start studying crime and marriage?","a":"Because the economic approach is a method rather than an assumption of selfishness: people maximise welfare as they conceive it.<sup class=\"fn\" data-fn=\"4\"></sup> Applied that way it can analyse discrimination, crime and family decisions such as marriage, divorce and fertility.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is economics called insular among the social sciences?","a":"Because bibliometric data show economics to be relatively insular while it holds a dominant position among the social sciences.<sup class=\"fn\" data-fn=\"3\"></sup> The field is also tightly managed from the top down, giving it a characteristically hierarchical structure.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Economic sociology"},
    "ec-020": {"questions":["Nobody would take seriously a psychology degree built solely on Freudianism, argued the student campaign for <span class=\"blank\">_____</span>, which also wanted economic history and qualitative methods restored to courses.","Critics judged one reformed open textbook's changes minor because it still offered little <span class=\"blank\">_____</span>, leaving power and politics aside and most heterodox schools of thought outside the first course."],"abstract":"<b>Pluralism in economics</b> is the demand that the subject be taught and practised through a range of theories, methods and disciplines rather than one dominant approach.<sup class=\"fn\" data-fn=\"1\"></sup> Its best-known statement is an open letter of May 2014 from over 65 associations of economics students in more than 30 countries.<sup class=\"fn\" data-fn=\"1\"></sup> The letter called for three forms of pluralism, theoretical, methodological and interdisciplinary, and complained of a dramatic narrowing of the curriculum over the previous decades.<sup class=\"fn\" data-fn=\"1\"></sup> Where other disciplines teach competing theories, it argued, economics is presented as a unified body of knowledge, and nobody would take seriously a psychology degree confined to Freudianism.<sup class=\"fn\" data-fn=\"1\"></sup> What counts as the dominant approach is itself disputed, since even mainstream economics has many variants, and the discipline is unusually hierarchical, managed tightly from the top down.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> <br><br> A second complaint is that first courses leave out what students care about, and introductory students asked in 2023 and 2024 to name the most pressing problem for economists repeatedly named inequality and the environment.<sup class=\"fn\" data-fn=\"3\"></sup> One influential review argued in 2020 that leading textbooks were written in the calm of the two decades before 2007 and neglected mounting inequality, climate change, the future of work and financial instability.<sup class=\"fn\" data-fn=\"2\"></sup> It held that the tools for those problems, such as strategic interaction, limited information and principal-agent models, already exist in doctoral teaching and can be taught to first-year students.<sup class=\"fn\" data-fn=\"2\"></sup> The open textbook built on that view, first published in 2017, describes its mission as introducing students to what economists do now and what they know.<sup class=\"fn\" data-fn=\"3\"></sup> Its critics reply that such reforms are relatively minor, still showing limited pluralism and ignoring power and politics, so whether a reformed first course meets the student demand remains contested.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["International Student Initiative for Pluralism in Economics, “An International Student Call for Pluralism in Economics,” open letter, 5 May 2014, https://www.isipe.net/open-letter. [Open access]","Samuel Bowles and Wendy Carlin, “What Students Learn in Economics 101: Time for a Change,” <i>Journal of Economic Literature</i> 58, no. 1 (2020): 176–214, EconPapers, https://econpapers.repec.org/RePEc:aea:jeclit:v:58:y:2020:i:1:p:176-214. [Paywalled]","CORE Econ, <i>The Economy 2.0: Microeconomics</i>, “Preface,” https://www.core-econ.org/the-economy/microeconomics/0-4-preface.html. [Open access]","Andrew Mearman, Danielle Guizzo and Sebastian Berger, “Whither Political Economy? Evaluating the CORE Project as a Response to Calls for Change in Economics Teaching,” <i>Review of Political Economy</i> 30, no. 2 (2018): 241–59, EconPapers, https://econpapers.repec.org/RePEc:taf:revpoe:v:30:y:2018:i:2:p:241-259. [Paywalled]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i> (substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","Marion Fourcade, Etienne Ollion and Yann Algan, “The Superiority of Economists,” <i>Journal of Economic Perspectives</i> 29, no. 1 (2015): 89–114, https://www.aeaweb.org/articles?id=10.1257/jep.29.1.89. [Open access]"],"why":[{"q":"Why did students demand pluralism after the financial crisis?","a":"Because, their letter said, the teaching of economics was in crisis as well as the world economy, and a narrowed curriculum limited the ability to deal with financial stability, food security and climate change.<sup class=\"fn\" data-fn=\"1\"></sup> It wanted competing theories, varied methods and other social sciences brought into courses.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do some reformers think the first course can change?","a":"Because the tools needed for inequality, climate and financial instability, such as strategic interaction and principal-agent models, are already taught in doctoral programmes.<sup class=\"fn\" data-fn=\"2\"></sup> They argue a course built around them can be taught successfully to first-year students.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the reform of the first course still disputed?","a":"Because critics find the best-known reformed textbook's changes relatively minor and superficial.<sup class=\"fn\" data-fn=\"4\"></sup> In their view it still shows limited pluralism, ignores power and politics and leaves little room for political economy.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Pluralism in economics"},
    "ec-021": {"questions":["Counting the pineapples in Hawaii cannot reveal their <span class=\"blank\">_____</span>, since economists measure it against what people want, asking whether there would be enough for everyone at a price of zero.","Air is usually a free good because at a price of zero there is enough for everyone, so it escapes the <span class=\"blank\">_____</span> that governs nearly every other resource people value."],"abstract":"<b>Scarcity</b> is the condition in which human wants for goods, services and resources exceed what is available, so that not everything people want can be had at once.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Labour, land, tools and raw materials all exist in limited supply, and time is perhaps the scarcest resource of all, since rich and poor alike have the same 24 hours in a day.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A good counts as scarce when it is valued and acquiring more of it has an opportunity cost, so scarcity is a relation between wants and means rather than a matter of small quantities.<sup class=\"fn\" data-fn=\"2\"></sup> One test is to ask whether, at a price of zero, there would be enough of a good to satisfy everyone, and by that test air is usually a free good while salt-free water on the open ocean is not.<sup class=\"fn\" data-fn=\"4\"></sup> Because the vast majority of goods fail that test, getting more of one thing almost always means having less of another.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Scarcity is relative rather than absolute, so counting the pineapples in Hawaii or the steel in South Korea cannot by itself show whether either is scarce.<sup class=\"fn\" data-fn=\"4\"></sup> In a classic formulation, different degrees of scarcity of different goods give rise to different ratios of valuation between them, and changes in scarcity from either the demand side or the supply side alter those ratios.<sup class=\"fn\" data-fn=\"3\"></sup> Scarcity is not the same as poverty, since a billionaire who spends a billion dollars on one cause cannot spend it on another and has no more hours in the day than anyone else.<sup class=\"fn\" data-fn=\"4\"></sup> Nor is it a passing condition, because growth and new technology push the limits outward without removing them, and scarcity remains, only at a different level.<sup class=\"fn\" data-fn=\"6\"></sup> Whether scarcity should define the whole subject is debated: one much-quoted definition makes the disposal of scarce means its unifying theme, while a survey of textbooks finds it only one of five competing definitions.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 1.1, “What Is Economics, and Why Is It Important?,” https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.2, “A Problem of Choice and Scarcity,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-02-choice-and-scarcity.html. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–17, Mises Institute scan, https://mises-media.s3.amazonaws.com/Essay%20on%20the%20Nature%20and%20Significance%20of%20Economic%20Science_2.pdf. [Open access]","David R. Henderson, “TANSTAAFL: There Ain’t No Such Thing as a Free Lunch,” Econlib, March 3, 2014, https://www.econlib.org/library/Columns/y2014/Hendersontanstaafl.html. [Open access]","Eric Nielsen, “Jargon Alert: Opportunity Cost,” <i>Region Focus</i>, Federal Reserve Bank of Richmond, Fall 2004, 6, https://www.richmondfed.org/publications/research/econ_focus/2004/fall/~/media/1FB6F7F1004E4879ABAC1E0C1C27C17A.ashx. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.3, “Confronting Objections to the Economic Approach,” https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, ed. Edward N. Zalta (Stanford University, substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","Roger E. Backhouse and Steven G. Medema, “Retrospectives: On the Definition of Economics,” <i>Journal of Economic Perspectives</i> 23, no. 1 (2009): 221–33, https://www.aeaweb.org/articles?id=10.1257/jep.23.1.221. [Open access]"],"why":[{"q":"Why does scarcity not simply mean that something is rare?","a":"Because it is a relation between wants and means. A good is scarce when it is valued and getting more of it has an opportunity cost,<sup class=\"fn\" data-fn=\"2\"></sup> and the test is whether there would be enough to satisfy everyone at a price of zero. By that test most goods are scarce, however plentiful they look.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is scarcity not the same as poverty?","a":"Because it binds the rich as well. Even the richest person has only 24 hours in a day and must choose how to spend them, and money spent on one cause is money that cannot be spent on another.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does scarcity remain even when an economy grows?","a":"Because growth and better technology move the limits outward without removing them. The frontier of what can be had shifts, but it is still not feasible to have unlimited amounts of every good, so scarcity remains at a different level.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Scarcity"},
    "ec-022": {"questions":["In a worker's choice of hours, the solution to the problem of <span class=\"blank\">_____</span> lies where an indifference curve just touches the feasible frontier, the accepted and the imposed trade-offs equal.","Critics say nobody really solves a problem of <span class=\"blank\">_____</span> before going shopping, and economists reply that people act as if they maximise, much as a ball player never calculates the physics."],"abstract":"<b>Constrained optimisation</b> is the way economics models a choice under scarcity: a decision-maker pursues an objective, such as the greatest utility or profit, subject to a constraint that fixes which options are feasible.<sup class=\"fn\" data-fn=\"1\"></sup> The constraint marks out a feasible set, every combination the chooser could pick, and its upper edge is a feasible frontier beyond which nothing more can be had.<sup class=\"fn\" data-fn=\"2\"></sup> A consumer's budget constraint is the simplest case, since spending on each good, its price times its quantity, must add up to no more than the money available.<sup class=\"fn\" data-fn=\"5\"></sup> The objective is ranked by preferences, and the barest theory of rationality asks only that they be complete and transitive and that the chooser prefer no feasible alternative to the one chosen.<sup class=\"fn\" data-fn=\"4\"></sup> Behind the formal problem lies an older description in which ends are various while time and means are limited and capable of alternative application, so that behaviour takes the form of choice.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> In the textbook case of a worker choosing hours, the best point is where the trade-off the worker is willing to make between free time and consumption equals the trade-off the wage forces on them.<sup class=\"fn\" data-fn=\"1\"></sup> On the diagram this is where an indifference curve just touches the feasible frontier, and every other feasible point lies on a lower curve.<sup class=\"fn\" data-fn=\"1\"></sup> The same structure, an objective maximised within a feasible set, underlies most mainstream theory, which explains outcomes as equilibria of constrained rational individual choice.<sup class=\"fn\" data-fn=\"4\"></sup> The obvious objection is that nobody performs these calculations, and economists reply that people may act as if they maximise, as a ball player throws accurately without solving the physics.<sup class=\"fn\" data-fn=\"6\"></sup> Experiments find that real preferences are sometimes intransitive, which leaves open whether people are occasionally irrational or whether the standard of rationality has been set too high.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.5, “Decision-Making and Scarcity,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-05-decision-making-scarcity.html. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.4, “The Feasible Set,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-04-feasible-set.html. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–17, Mises Institute scan, https://mises-media.s3.amazonaws.com/Essay%20on%20the%20Nature%20and%20Significance%20of%20Economic%20Science_2.pdf. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, ed. Edward N. Zalta (Stanford University, substantive revision 2018), https://plato.stanford.edu/entries/economics/. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 1.3, “Economic Reasoning and Analysis,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]"],"why":[{"q":"Why is the best choice where an indifference curve touches the frontier?","a":"Because at any other feasible point the chooser could still reach a higher indifference curve. Only where the curve is tangent to the frontier do the trade-off the chooser is willing to make and the trade-off the constraint imposes balance.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does the model not require people to do the arithmetic?","a":"Because economists treat people as acting as if they maximise, much as someone throws a baseball without doing the physics, and some firms really do run elaborate programs to minimise costs or maximise profits.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why does intransitive preference trouble the theory?","a":"Because the barest theory of rational choice requires preferences that are complete and transitive. Experimental evidence that real preferences are sometimes intransitive leaves open whether people are irrational at times or whether the standard is too demanding.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Constrained optimization"},
    "ec-023": {"questions":["Economists define the value of the next best alternative forgone as the <span class=\"blank\">_____</span> of a choice, so that even a free concert ticket can still cost something.","When about 200 economists and graduate students were asked to value the <span class=\"blank\">_____</span> of using a free concert ticket, the intended answer was chosen least often of the four offered."],"abstract":"<b>Opportunity cost</b> is the value of the next best alternative given up when a choice is made, the lost chance to do or consume something else.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Because doing one thing means not doing another, every choice has an opportunity cost, whether the resource spent is money, time or effort.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Economists therefore count costs differently from accountants, adding the value of the forgone alternative to the direct out-of-pocket outlay to give what they call economic cost.<sup class=\"fn\" data-fn=\"2\"></sup> A student's year at college is the classic case, since its true cost includes the earnings given up by studying instead of working, while room and board is not a cost of college at all, because it must be paid either way.<sup class=\"fn\" data-fn=\"3\"></sup> Money prices usually reflect opportunity costs, but not always, and the time spent waiting in airport security queues is a large cost that involves no spending.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Opportunity costs are often unseen, which is the point of the parable of the broken window: the six francs paid to the glazier are seen, while the shoes or book they would otherwise have bought are not.<sup class=\"fn\" data-fn=\"6\"></sup> Cost in this sense belongs to the chooser at the moment of choice, since the alternative given up can never be enjoyed and its value cannot be directly observed by anyone else.<sup class=\"fn\" data-fn=\"5\"></sup> At a meeting of the Allied Social Science Associations in the United States, about 200 economists and economics graduate students answered a textbook question on the opportunity cost of seeing a concert with a free ticket.<sup class=\"fn\" data-fn=\"7\"></sup> Only 21.6 per cent chose the intended answer, the least popular of the four, which the survey's authors read as a dismal performance for the profession.<sup class=\"fn\" data-fn=\"7\"></sup> A reply argued that every one of the four answers can be defended under some accounting method, so the result may show that the concept is ambiguous in use rather than misunderstood.<sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 2.2, “Economic Decisions: Opportunity Costs, Economic Rents, and Incentives,” https://books.core-econ.org/the-economy/microeconomics/02-technology-incentives-02-economic-decisions.html. [Open access]","David R. Henderson, “Opportunity Cost,” <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/OpportunityCost.html. [Open access]","Eric Nielsen, “Jargon Alert: Opportunity Cost,” <i>Region Focus</i>, Federal Reserve Bank of Richmond, Fall 2004, 6, https://www.richmondfed.org/publications/research/econ_focus/2004/fall/~/media/1FB6F7F1004E4879ABAC1E0C1C27C17A.ashx. [Open access]","James M. Buchanan, <i>Cost and Choice: An Inquiry in Economic Theory</i> (Chicago: Markham, 1969; Indianapolis: Liberty Fund, 1999), ch. 3, Econlib, https://www.econlib.org/library/Buchanan/buchCv6.html?chapter_num=4. [Open access]","Frédéric Bastiat, “What Is Seen and What Is Not Seen,” in <i>Selected Essays on Political Economy</i>, trans. Seymour Cain, ed. George B. de Huszar (Irvington-on-Hudson, NY: Foundation for Economic Education, 1995), Econlib, https://www.econlib.org/library/Bastiat/basEss1.html. [Open access]","Paul J. Ferraro and Laura O. Taylor, “Do Economists Recognize an Opportunity Cost When They See One? A Dismal Performance from the Dismal Science,” <i>Contributions in Economic Analysis &amp; Policy</i> 4, no. 1 (2005): 1–12, https://econpapers.repec.org/RePEc:bpj:bejeap:v:contributions.4:y:2005:i:1:n:7. [Paywalled]","Joel Potter and Shane Sanders, “Do Economists Recognize an Opportunity Cost When They See One? A Dismal Performance or an Arbitrary Concept?,” <i>Southern Economic Journal</i> 79, no. 2 (2012): 248–56, https://ideas.repec.org/a/wly/soecon/v79y2012i2p248-256.html. [Paywalled]"],"why":[{"q":"Why is room and board not part of the cost of college?","a":"Because a student has to pay for food and housing whether or not they attend, so choosing college does not give that spending up. What college does give up is the earnings from working instead, which is why forgone income counts and living costs do not.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did the broken window not help industry as a whole?","a":"Because the six francs paid to the glazier would otherwise have been spent on something else, such as shoes or a book. The repair is seen while the purchase given up is not, so counting only the first ignores the opportunity cost.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why did so few economists choose the intended answer?","a":"Perhaps because they applied the concept poorly, as the survey's authors concluded when only 21.6 per cent chose it,<sup class=\"fn\" data-fn=\"7\"></sup> or perhaps because the question was ambiguous, since a reply showed that every answer can be defended under some accounting method.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Opportunity cost"},
    "ec-024": {"questions":["Points inside the <span class=\"blank\">_____</span> are wasteful and points beyond it unattainable, while growth in labour, capital and technology can push the whole curve outward over time.","Because resources suited to healthcare are ill suited to schooling, a society's <span class=\"blank\">_____</span> usually bows outward, each extra unit of one good costing more of the other than the last."],"abstract":"The <b>production possibility frontier</b> is a model showing the combinations of two goods that a society can produce with its limited resources and technology at a given time.<sup class=\"fn\" data-fn=\"1\"></sup> Points on the frontier are attainable, points outside it are not, and points inside it are wasteful, because more of one good could be had without giving up any of the other.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Because the frontier slopes downward, more of one good can only be had by giving up some of the other, which is what makes both scarce in the economist's sense, and its slope measures that opportunity cost.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> The frontier is usually bowed outward, since resources suited to one good are increasingly ill suited to the other, so each extra unit costs more than the last, a pattern called the law of increasing opportunity cost.<sup class=\"fn\" data-fn=\"1\"></sup> It is the same diagram as an individual's budget constraint, except that a budget constraint is a straight line, its slope fixed by the prices the consumer faces.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The model became famous through the debates of the Second World War about guns and butter, the trade-off between military production and civilian goods.<sup class=\"fn\" data-fn=\"5\"></sup> Butter seems to have little to do with weapons, but making it uses steel containers, tractors, transport and labour that could all be turned to producing arms.<sup class=\"fn\" data-fn=\"5\"></sup> Any war therefore withdraws scarce goods and services from other uses, and a government that spends more on war has less to spend on health care or anything else.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> The frontier can shift outward over time as labour and capital grow and technology improves, letting a society have more of both goods.<sup class=\"fn\" data-fn=\"1\"></sup> Even then scarcity remains, only at a different level, and the diagram cannot say which point on the frontier a society should choose, which depends on what that society desires.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.2, “The Production Possibilities Frontier and Social Choices,” https://openstax.org/books/principles-economics-3e/pages/2-2-the-production-possibilities-frontier-and-social-choices. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.3, “Confronting Objections to the Economic Approach,” https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.4, “The Feasible Set,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-04-feasible-set.html. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.2, “A Problem of Choice and Scarcity,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-02-choice-and-scarcity.html. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 6.1, “Production Possibilities Frontier,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/06%3A_Trade/6.01%3A_Production_Possibilities_Frontier. [Open access]","David R. Henderson, “TANSTAAFL: There Ain’t No Such Thing as a Free Lunch,” Econlib, March 3, 2014, https://www.econlib.org/library/Columns/y2014/Hendersontanstaafl.html. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–17, Mises Institute scan, https://mises-media.s3.amazonaws.com/Essay%20on%20the%20Nature%20and%20Significance%20of%20Economic%20Science_2.pdf. [Open access]"],"why":[{"q":"Why is the frontier usually bowed outward rather than straight?","a":"Because some resources are better suited to one good than the other. Shifting the first few costs little, but the last ones moved are poorly suited to their new use, so the opportunity cost rises; a budget constraint is straight because prices fix its slope.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does butter compete with guns at all?","a":"Because butter needs more than cows. Its manufacture uses steel containers, tractors, transport and labour, all of which could be turned to making guns, so from a production standpoint more guns entail less butter.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why can the model not say which point a society should choose?","a":"Because economics does not presume to tell a society where to produce on its frontier. It can show that points inside are wasteful, but which of the efficient mixes is best depends on what a society desires, a question that is often controversial.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Production-possibility frontier"},
    "ec-025": {"questions":["The slogan that there is no such thing as a free lunch sums up the <span class=\"blank\">_____</span> that binds everyone, since even the richest person has only 24 hours in a day.","A 1975 book called the conflict between reducing inequality and preserving efficiency the big <span class=\"blank\">_____</span>, picturing transfers to the poor as money carried in a leaky bucket."],"abstract":"A <b>trade-off</b> is a choice in which getting more of one desired thing requires giving up some of another, the everyday consequence of scarcity.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A shopper with a fixed budget faces one at every comparison, and in a standard textbook example buying one more burger means giving up four bus tickets.<sup class=\"fn\" data-fn=\"1\"></sup> The terms of a trade-off can be read from the slope of a feasible frontier, which shows how much of one good must be sacrificed for an extra unit of the other.<sup class=\"fn\" data-fn=\"3\"></sup> That trade-off, the one a person is constrained to make, is distinct from the trade-off they are willing to make, which reflects their own preferences.<sup class=\"fn\" data-fn=\"3\"></sup> The rule is summed up in the slogan that there is no such thing as a free lunch, and it binds the richest people too, since even they have only 24 hours in a day.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Governments face trade-offs as households do, since waging war withdraws scarce goods and services from other uses and more spending on war means less on health care or something else.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Economists have given some trade-offs between whole social goals names of their own, and one of the most debated is between equality and efficiency.<sup class=\"fn\" data-fn=\"6\"></sup> Arthur Okun's book of 1975 called it the big trade-off, arguing that a society's wish to reduce inequality could impair economic efficiency.<sup class=\"fn\" data-fn=\"6\"></sup> His image was a leaky bucket carrying money from rich to poor, with some lost on the way to the costs of administration and to weaker incentives to work.<sup class=\"fn\" data-fn=\"7\"></sup> Later work argued that the leak is small in some cases and that equity and efficiency can even complement each other, so how steep such a trade-off is remains an empirical question.<sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.3, “Confronting Objections to the Economic Approach,” https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.4, “The Feasible Set,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-04-feasible-set.html. [Open access]","David R. Henderson, “TANSTAAFL: There Ain’t No Such Thing as a Free Lunch,” Econlib, March 3, 2014, https://www.econlib.org/library/Columns/y2014/Hendersontanstaafl.html. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 12–17, Mises Institute scan, https://mises-media.s3.amazonaws.com/Essay%20on%20the%20Nature%20and%20Significance%20of%20Economic%20Science_2.pdf. [Open access]","Arthur M. Okun, <i>Equality and Efficiency: The Big Tradeoff</i> (Washington, DC: Brookings Institution Press, 1975), publisher’s description, https://www.brookings.edu/book/equality-and-efficiency/. [Paywalled]","“Arthur M. Okun,” <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/bios/Okun.html. [Open access]","Rebecca M. Blank, “Can Equity and Efficiency Complement Each Other?,” NBER Working Paper 8820 (2002), published in <i>Labour Economics</i> 9, no. 4 (2002): 451–68, https://www.nber.org/papers/w8820. [Open access]"],"why":[{"q":"Why is the trade-off a person faces different from the one they accept?","a":"Because one comes from the constraint and the other from preferences. The slope of the feasible frontier shows the trade-off a person is forced to make, while their willingness to swap one good for another reflects what they value.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why does a leaky bucket describe redistribution?","a":"Because some of the money taken from the rich never reaches the poor. Okun attributed the loss to the administrative costs of taxing and transferring and to incentive effects, such as weaker incentives to work for people receiving transfers.<sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why might the trade-off between equity and efficiency be small?","a":"Because the leak depends on how people respond. Transfers to people with no capacity to change their behaviour, programmes with behavioural requirements and subsidies that work as long-term investments may all lose little efficiency.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Trade-off"},
    "ec-026": {"questions":["Water is vital yet cheap because its value is judged at the <span class=\"blank\">_____</span>, by the last cupful available rather than the whole supply, which is why a diamond buys far more.","A housewife sharing yarn between socks and vests chooses well when the last bundle does equal good in each use, an early lesson in reasoning at the <span class=\"blank\">_____</span> in economics."],"abstract":"The <b>margin</b> in economics is the point of the next small change, and to think at the margin is to weigh the extra benefit and the extra cost of a little more or a little less of something.<sup class=\"fn\" data-fn=\"1\"></sup> Most real choices are of this kind, about a little more or less rather than all of one thing or all of another.<sup class=\"fn\" data-fn=\"1\"></sup> In economists' jargon marginal means the change in a total from one more unit, so marginal cost is the cost of the next unit and marginal value the value of the next unit bought.<sup class=\"fn\" data-fn=\"3\"></sup> The usual pattern is that the extra satisfaction from each further unit of a good declines, which is why people rarely make all-or-nothing choices even about their favourite things.<sup class=\"fn\" data-fn=\"1\"></sup> Societies face the same logic, since the last resources put into healthcare add little health, while the same resources moved into education, where few are used, can add much more.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Thinking at the margin resolves an old puzzle, set out in 1776, of why water, which is so useful, will buy scarcely anything, while a diamond, of little use, will buy a great deal.<sup class=\"fn\" data-fn=\"4\"></sup> A theory of value published in 1871 turned on what it called the final degree of utility, the usefulness of the last addition to a stock rather than of the stock as a whole.<sup class=\"fn\" data-fn=\"5\"></sup> We cannot live without water, it observed, yet we usually have so much that its final degree of utility is reduced nearly to zero, and only a shortage such as a drought makes more of it precious.<sup class=\"fn\" data-fn=\"5\"></sup> A later textbook put the general rule through a housewife sharing yarn between socks and vests, who has chosen well when the last bundle given to each does equal good.<sup class=\"fn\" data-fn=\"6\"></sup> Modern models state the same idea as a balance at the margin, with the best choice where the rate at which a person is willing to swap two goods equals the rate at which they are able to.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.2, “The Production Possibilities Frontier and Social Choices,” https://openstax.org/books/principles-economics-3e/pages/2-2-the-production-possibilities-frontier-and-social-choices. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 1.3, “Economic Reasoning and Analysis,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, book 1, ch. 4, ed. Edwin Cannan (London: Methuen, 1904), Econlib, https://www.econlib.org/library/Smith/smWN.html?chapter_num=7. [Open access]","W. Stanley Jevons, <i>The Theory of Political Economy</i>, 3rd ed. (London: Macmillan, 1888), ch. 3, Econlib, https://www.econlib.org/library/YPDBooks/Jevons/jvnPE.html?chapter_num=7. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), book 3, ch. 5, Econlib, https://www.econlib.org/library/Marshall/marP.html?chapter_num=14. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.5, “Decision-Making and Scarcity,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-05-decision-making-scarcity.html. [Open access]"],"why":[{"q":"Why are most choices not all-or-nothing?","a":"Because the extra satisfaction from each further unit usually falls. Even a favourite food eaten exclusively would bring little from the last servings, so people compare a little more with a little less and stop somewhere in between.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does water cost so little when it is so useful?","a":"Because value is set by the usefulness of the last addition, not the whole stock. We usually have so much water that its final degree of utility is reduced nearly to zero, while a diamond commands a great deal in exchange.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does the yarn example illustrate a general rule?","a":"Because if a thing has a greater marginal utility in one use than in another, moving some of it to the first use is a gain. The best division therefore leaves the same marginal utility in every use.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Margin (economics)"},
    "ec-027": {"questions":["Cutting pollution to zero is rarely sensible, because the last reductions cost a great deal while their <span class=\"blank\">_____</span> to health and comfort keeps falling as the air gets cleaner.","Economists judge one more hour of study or one more unit of output by its <span class=\"blank\">_____</span>, the extra gain it brings, set against the extra cost of producing or doing it."],"abstract":"<b>Marginal benefit</b> is the extra benefit gained from one more unit of a good or activity, and it is weighed against marginal cost, the extra cost of that same unit.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> The rule that follows is to keep expanding an activity while its marginal benefit exceeds its marginal cost and to stop where the two are equal, since going further would cost more than it adds.<sup class=\"fn\" data-fn=\"1\"></sup> Marginal benefit usually falls as quantity rises, because the first units meet the most pressing wants, a pattern that in consumption is called diminishing marginal utility.<sup class=\"fn\" data-fn=\"1\"></sup> Marginal cost often rises, because the cheapest and easiest ways of doing more are used first and costlier ones later.<sup class=\"fn\" data-fn=\"2\"></sup> Applied to one resource with several uses, the rule says to divide it so that the last unit does equal good in each, since otherwise moving some from one use to another would be a gain.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> What counts is the change rather than the total, much as a wealthy person may not know their whole fortune yet keep exact accounts of its additions and subtractions.<sup class=\"fn\" data-fn=\"7\"></sup> A firm raises output while marginal revenue exceeds marginal cost and cuts it when the reverse holds, and a worker choosing hours stops where the trade-off they accept equals the one the wage imposes.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Pollution control shows why the answer is rarely all or nothing, since the first reductions are cheap and valuable while the last are costly and add less.<sup class=\"fn\" data-fn=\"2\"></sup> Pushing protection past the point where marginal cost exceeds marginal benefit would use up too many resources in cutting pollution, so on this reckoning the best level of pollution is usually not zero.<sup class=\"fn\" data-fn=\"2\"></sup> For the same reason, finding that a whole programme's benefits exceed its costs is very different from showing that every additional rule within it passes the marginal test.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 12.4, “The Benefits and Costs of U.S. Environmental Laws,” https://openstax.org/books/principles-economics-3e/pages/12-4-the-benefits-and-costs-of-u-s-environmental-laws. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 7.6, “Setting Price and Quantity to Maximize Profit,” https://books.core-econ.org/the-economy/microeconomics/07-firm-and-customers-06-maximize-profit.html. [Open access]","CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 3.5, “Decision-Making and Scarcity,” https://books.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-05-decision-making-scarcity.html. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 1.3, “Economic Reasoning and Analysis,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), book 3, ch. 5, Econlib, https://www.econlib.org/library/Marshall/marP.html?chapter_num=14. [Open access]","W. Stanley Jevons, <i>The Theory of Political Economy</i>, 3rd ed. (London: Macmillan, 1888), ch. 3, Econlib, https://www.econlib.org/library/YPDBooks/Jevons/jvnPE.html?chapter_num=7. [Open access]"],"why":[{"q":"Why should an activity stop where marginal benefit equals marginal cost?","a":"Because before that point each extra unit adds more than it costs, so expanding pays, and beyond it each unit costs more than it adds.<sup class=\"fn\" data-fn=\"1\"></sup> A firm's version is to raise output while marginal revenue exceeds marginal cost and to cut it when the reverse holds.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why does marginal benefit usually fall?","a":"Because the first units meet the most pressing wants. The first slice of pizza brings more satisfaction than the sixth, and the first steps against pollution are the ones that provide the greatest benefit.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why can a programme pass a cost-benefit test while one of its rules fails?","a":"Because the test of the whole compares totals while the test of a rule compares changes. Overall benefits of environmental regulation exceeding its costs is very different from every environmental regulation making sense.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Marginal utility"},
    "ec-028": {"questions":["A firm making losses may keep producing in the short run because its fixed costs are a <span class=\"blank\">_____</span> already paid, so it stays open while revenue covers its variable costs.","The maxim that in commerce bygones are for ever bygones describes the <span class=\"blank\">_____</span>, an outlay no present action can change, which theory says should not weigh on a current decision."],"abstract":"A <b>sunk cost</b> is a cost that has already been incurred and cannot be recovered, such as a non-refundable ticket or money spent advertising a product nobody wants.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Because no present action can change it, economic theory holds that a sunk cost should not affect a current decision, which ought to weigh only the costs and benefits still to come.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Economists contrast sunk costs with incremental costs, which change with the course of action chosen and are incurred only if a decision is taken.<sup class=\"fn\" data-fn=\"2\"></sup> A classic treatise put the principle in a phrase that stuck: labour once spent has no influence on the future value of anything, and in commerce bygones are for ever bygones.<sup class=\"fn\" data-fn=\"3\"></sup> Cost on this view is forward-looking by nature, reckoned at the moment of choice from the alternatives that are still open, and based on anticipations of the future rather than on outlays already made.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Sunk costs explain why a firm making losses may keep producing, since its fixed costs are already paid and shutting down would not recover them.<sup class=\"fn\" data-fn=\"4\"></sup> It should stay open in the short run as long as the price covers its average variable cost, the part of its costs it can still avoid by stopping.<sup class=\"fn\" data-fn=\"4\"></sup> When investment cannot be reversed, firms also wait until prices rise well above long-run average cost before investing, and stay in business through long periods of losses before leaving.<sup class=\"fn\" data-fn=\"5\"></sup> One explanation treats an irreversible investment like a financial option, since waiting has value when time brings information about a project's prospects.<sup class=\"fn\" data-fn=\"5\"></sup> Some economists go further and argue that reacting to sunk costs is often rational once information, reputation and financial or time constraints are taken into account.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]","Eric Nielsen, “Jargon Alert: Sunk Cost,” <i>Region Focus</i>, Federal Reserve Bank of Richmond, Winter 2005, 6, FRASER, https://fraser.stlouisfed.org/files/docs/historical/frbrich/focus/frbrich_focus_200501.pdf. [Open access]","W. Stanley Jevons, <i>The Theory of Political Economy</i>, 3rd ed. (London: Macmillan, 1888), ch. 4, Econlib, https://www.econlib.org/library/YPDBooks/Jevons/jvnPE.html?chapter_num=8. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 8.2, “How Perfectly Competitive Firms Make Output Decisions,” https://openstax.org/books/principles-economics-3e/pages/8-2-how-perfectly-competitive-firms-make-output-decisions. [Open access]","Avinash Dixit, “Investment and Hysteresis,” <i>Journal of Economic Perspectives</i> 6, no. 1 (1992): 107–32, https://www.aeaweb.org/articles?id=10.1257/jep.6.1.107. [Open access]","James M. Buchanan, <i>Cost and Choice: An Inquiry in Economic Theory</i> (Chicago: Markham, 1969; Indianapolis: Liberty Fund, 1999), ch. 3, Econlib, https://www.econlib.org/library/Buchanan/buchCv6.html?chapter_num=4. [Open access]","R. Preston McAfee, Hugo M. Mialon and Sue H. Mialon, “Do Sunk Costs Matter?,” <i>Economic Inquiry</i> 48, no. 2 (2010): 323–36, https://ideas.repec.org/a/bla/ecinqu/v48y2010i2p323-336.html. [Paywalled]"],"why":[{"q":"Why should a sunk cost not affect a decision?","a":"Because it has already been paid and nothing done now can change it. Whatever is chosen the cost remains, so only the costs and benefits that still depend on the choice, the incremental ones, can make one option better than another.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do loss-making firms sometimes keep producing?","a":"Because their fixed costs are already paid and would not be recovered by stopping. A firm that shuts down still bears those costs, so it keeps going in the short run while the price covers the variable costs it could avoid.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why might firms wait before investing even when prices look high?","a":"Because an investment that cannot be undone is like an option, and waiting has value when time brings more information about a project's prospects. Firms therefore wait until prices rise substantially above long-run average cost.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Sunk cost"},
    "ec-029": {"questions":["France and Britain kept funding the Concorde long after its poor returns were clear, the textbook case of the <span class=\"blank\">_____</span> that the phrase about good money after bad describes.","Singapore drivers who paid more to buy a new car then drove it more, field evidence for the <span class=\"blank\">_____</span> that a laboratory treasure hunt had found surprisingly weak."],"abstract":"The <b>sunk cost fallacy</b> is the error of letting an unrecoverable past outlay sway a present decision, as when someone sits through a play they already know is awful because the ticket cannot be refunded.<sup class=\"fn\" data-fn=\"1\"></sup> It breaks a basic principle of microeconomic theory, that decisions should rest only on current and future costs and benefits.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Its popular name is throwing good money after bad, and the standard example is the Concorde, the supersonic airliner in which France and Britain kept investing long after its poor prospects were clear.<sup class=\"fn\" data-fn=\"2\"></sup> Businesses and governments are often reluctant to admit a mistake and cut their losses, and the habit of keeping failing programmes alive may be strongest in the public sector, where the profit incentive is weak.<sup class=\"fn\" data-fn=\"1\"></sup> Casinos profit from the same pattern when gamblers play on in the hope of winning back what they have already lost, although on average the house wins.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> How strong the effect is in real decisions, outside the classroom examples, is less settled than its fame might suggest.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A meta-analysis of 98 effect sizes found clear evidence for it, stronger among the young and among students, and no sign that training in economics reduced it.<sup class=\"fn\" data-fn=\"3\"></sup> A laboratory treasure-hunt game, by contrast, found a surprisingly small sunk cost effect that hardly responded to the psychological factors thought to drive it.<sup class=\"fn\" data-fn=\"4\"></sup> Field evidence from Singapore, where policy changed the sunk cost of buying a car, linked the policy of 2009 to 2013 with about 5.6 per cent more driving.<sup class=\"fn\" data-fn=\"5\"></sup> Some economists argue that many apparent cases are not errors at all, because past outlays can carry information, affect a reputation or reflect financial and time constraints.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Eric Nielsen, “Jargon Alert: Sunk Cost,” <i>Region Focus</i>, Federal Reserve Bank of Richmond, Winter 2005, 6, FRASER, https://fraser.stlouisfed.org/files/docs/historical/frbrich/focus/frbrich_focus_200501.pdf. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 1.3, “Economic Reasoning and Analysis,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]","Stefan Roth, Thomas Robbert and Lennart Straus, “On the Sunk-Cost Effect in Economic Decision-Making: A Meta-Analytic Review,” <i>Business Research</i> 8, no. 1 (2015): 99–138, https://doi.org/10.1007/s40685-014-0014-8. [Open access]","Daniel Friedman, Kai Pommerenke, Rajan Lukose, Garrett Milam and Bernardo A. Huberman, “Searching for the Sunk Cost Fallacy,” <i>Experimental Economics</i> 10, no. 1 (2007): 79–104, https://doi.org/10.1007/s10683-006-9134-0. [Paywalled]","Teck-Hua Ho, Ivan Png and Sadat Reza, “Sunk Cost Fallacy in Driving the World’s Costliest Cars,” MPRA Paper 82139 (2017), published in <i>Management Science</i> 64, no. 4 (2018): 1761–78, https://econpapers.repec.org/RePEc:pra:mprapa:82139. [Open access]","R. Preston McAfee, Hugo M. Mialon and Sue H. Mialon, “Do Sunk Costs Matter?,” <i>Economic Inquiry</i> 48, no. 2 (2010): 323–36, https://ideas.repec.org/a/bla/ecinqu/v48y2010i2p323-336.html. [Paywalled]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), section 2.1, “How Individuals Make Choices Based on Their Budget Constraint,” https://openstax.org/books/principles-economics-3e/pages/2-1-how-individuals-make-choices-based-on-their-budget-constraint. [Open access]"],"why":[{"q":"Why does economic theory call this behaviour a fallacy?","a":"Because a sunk cost cannot be changed by anything done now, so it should not affect a decision that ought to rest on current and future costs and benefits.<sup class=\"fn\" data-fn=\"3\"></sup> The ticket is paid whether or not one goes to the play, so only the evening ahead should count.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why might training in economics not protect against it?","a":"Because a meta-analysis of 98 effect sizes found no evidence that familiarity with economic decision-making, such as economic education, reduced the sunk cost effect, although older adults were less prone to it than younger ones.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do some economists doubt it is always irrational?","a":"Because reacting to a past outlay can make sense once the whole situation is considered. Sunk costs can carry information, affect a reputation or reflect financial and time constraints, so conditioning behaviour on them is often rational.<sup class=\"fn\" data-fn=\"6\"></sup>"}]},
    "ec-030": {"questions":["When one glass company switched to piece rates, output per worker rose by about 44 per cent, a clear case of pay acting as an <span class=\"blank\">_____</span> to raise effort at work.","A fine meant to stop parents collecting children late from day care raised lateness instead, showing that an <span class=\"blank\">_____</span> can change how people see a task as well as its cost."],"abstract":"An <b>incentive</b> is an economic reward or punishment that changes the benefits and costs of the alternatives open to a person, and so influences what they choose.<sup class=\"fn\" data-fn=\"1\"></sup> Prices are the most familiar incentives, since when something becomes dearer people find ways to buy less of it, though not necessarily none, and when it becomes cheaper they buy more.<sup class=\"fn\" data-fn=\"3\"></sup> What matters is the price of one option relative to another, so a general rise in all prices may change little while a change in one price shifts choices.<sup class=\"fn\" data-fn=\"1\"></sup> Incentives need not be monetary, and time is one of the most important non-monetary costs, as anyone who must queue for days to get a free concert ticket discovers.<sup class=\"fn\" data-fn=\"3\"></sup> The reliance on them goes back to the claim of 1776 that we expect our dinner not from the benevolence of the butcher, the brewer or the baker but from their regard to their own interest.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Economists' models often assume entirely self-interested people for simplicity, while acknowledging that real people are more altruistic and are moved by love, duty and the wish for approval as well.<sup class=\"fn\" data-fn=\"8\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The evidence that people respond to pay for performance is strong, and when one glass company switched to piece rates, output per worker rose by about 44 per cent.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Yet a long review of incentives in firms found less evidence that contracts are designed as theory predicts, and little known about rewarding work whose output is hard to measure.<sup class=\"fn\" data-fn=\"5\"></sup> Monetary incentives can also clash with other motives, changing how a task is seen and sometimes weakening intrinsic motivation even when they work in the short run.<sup class=\"fn\" data-fn=\"6\"></sup> In one field study a fine introduced for parents who collected their children late from day-care centres increased lateness, and lateness stayed high after the fine was removed.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["CORE Econ, <i>The Economy 2.0: Microeconomics</i> (London: CORE Economics Education, 2023), section 2.2, “Economic Decisions: Opportunity Costs, Economic Rents, and Incentives,” https://books.core-econ.org/the-economy/microeconomics/02-technology-incentives-02-economic-decisions.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, book 1, ch. 2, ed. Edwin Cannan (London: Methuen, 1904), Econlib, https://www.econlib.org/library/Smith/smWN.html?chapter_num=5. [Open access]","Russell Roberts, “Incentives Matter,” Econlib, June 5, 2006, https://www.econlib.org/library/Columns/y2006/Robertsincentives.html. [Open access]","Edward P. Lazear, “Performance Pay and Productivity,” <i>American Economic Review</i> 90, no. 5 (2000): 1346–61, https://www.aeaweb.org/articles?id=10.1257/aer.90.5.1346. [Paywalled]","Canice Prendergast, “The Provision of Incentives in Firms,” <i>Journal of Economic Literature</i> 37, no. 1 (1999): 7–63, https://www.aeaweb.org/articles?id=10.1257/jel.37.1.7. [Paywalled]","Uri Gneezy, Stephan Meier and Pedro Rey-Biel, “When and Why Incentives (Don’t) Work to Modify Behavior,” <i>Journal of Economic Perspectives</i> 25, no. 4 (2011): 191–210, https://www.aeaweb.org/articles?id=10.1257/jep.25.4.191. [Open access]","Uri Gneezy and Aldo Rustichini, “A Fine Is a Price,” <i>Journal of Legal Studies</i> 29, no. 1 (2000): 1–17, https://rady.ucsd.edu/_files/faculty-research/uri-gneezy/fine.pdf. [Open access]","<i>Introduction to Economic Analysis</i>, LibreTexts Social Sciences, section 1.3, “Economic Reasoning and Analysis,” https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]"],"why":[{"q":"Why do relative prices matter more than the general price level?","a":"Because a choice compares options. If every price rose by 5 per cent a decision such as where to shop would probably not change, but a change in the price of one option relative to another shifts the balance of costs and benefits.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did a fine make parents arrive later?","a":"Because penalties are introduced into incomplete contracts and can change the information people have about a situation.<sup class=\"fn\" data-fn=\"7\"></sup> Monetary incentives may alter how a task is perceived, so a fine can turn an obligation into something closer to a price.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why is rewarding some kinds of work so hard?","a":"Because pay for performance needs performance to be measured. A review of incentives in firms concluded that little is known about how incentives are provided to workers whose output is difficult to measure.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Incentive"},
    "ec-031": {"questions":["When a new fine for collecting children late from day care was followed by more late arrivals, the penalty had become a <span class=\"blank\">_____</span> working against its own purpose.","A weekday driving ban in Mexico City that left the air no cleaner, as more and dirtier cars took to the roads, is a <span class=\"blank\">_____</span> studied in environmental policy."],"abstract":"A <b>perverse incentive</b> is a reward or penalty that produces the opposite of what its designers wanted, because the people it targets find a cheaper way to collect the reward than doing what was intended.<sup class=\"fn\" data-fn=\"2\"></sup> It is a sharp case of the broader law of unintended consequences, which holds that the actions of people, and especially of governments, have effects that nobody anticipated.<sup class=\"fn\" data-fn=\"1\"></sup> In the middle of the 19th century the French writer Frédéric Bastiat separated what is seen, the immediate effect of a law, from what is not seen, the later effects that a good economist must try to foresee.<sup class=\"fn\" data-fn=\"3\"></sup> In 1936 the sociologist Robert K. Merton gave the first systematic analysis of the idea, naming ignorance and error as the commonest sources of consequences that no one intended.<sup class=\"fn\" data-fn=\"1\"></sup> The usual mistake is to assume that behaviour will stay fixed when its costs and rewards change, or to reward a measurable stand-in instead of the outcome that is actually wanted.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The best-documented case began in April 1902, when the French colonial authorities in Hanoi, fighting bubonic plague, paid a few cents for every rat tail delivered to the police.<sup class=\"fn\" data-fn=\"6\"></sup> Within about three months officials found that residents were farming rats, cutting off the tails and letting the animals go to breed, while smugglers brought rodents into the city from all over Tonkin.<sup class=\"fn\" data-fn=\"6\"></sup> A modern study found the same pattern in Mexico City, where a 1989 rule keeping most cars off the roads one weekday a week did not improve air quality, because vehicle numbers rose and the fleet shifted towards high-emissions cars.<sup class=\"fn\" data-fn=\"4\"></sup> A field study of day-care centres found that introducing a fine for parents who collected their children late increased the number of late arrivals, and removing the fine later brought no reduction.<sup class=\"fn\" data-fn=\"5\"></sup> Welfare schemes can carry the same flaw when each extra unit of earnings is withdrawn in lost support, leaving a low-paid worker no better off for working, a situation economists call the poverty trap.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Rob Norton, “Unintended Consequences,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/UnintendedConsequences.html. [Open access]","Glen Whitman, “Slavery, Snakes, and Switching: The Role of Incentives in Creating Unintended Consequences,” Library of Economics and Liberty, 7 May 2007, https://www.econlib.org/library/Columns/y2007/Whitmanincentives.html. [Open access]","Frédéric Bastiat, “What Is Seen and What Is Not Seen,” in <i>Selected Essays on Political Economy</i>, trans. Seymour Cain, ed. George B. de Huszar (Irvington-on-Hudson, NY: Foundation for Economic Education, 1995), Library of Economics and Liberty, https://www.econlib.org/library/Bastiat/basEss1.html. [Open access]","Lucas W. Davis, “The Effect of Driving Restrictions on Air Quality in Mexico City,” <i>Journal of Political Economy</i> 116, no. 1 (2008): 38–81, abstract at EconPapers, https://econpapers.repec.org/article/ucpjpolec/v_3a116_3ay_3a2008_3ai_3a1_3ap_3a38-81.htm. [Paywalled]","Uri Gneezy and Aldo Rustichini, “A Fine Is a Price,” <i>Journal of Legal Studies</i> 29, no. 1 (2000): 1–17, abstract at EconPapers, https://econpapers.repec.org/article/ucpjlstud/v_3a29_3ay_3a2000_3ai_3a1_3ap_3a1-17.htm. [Paywalled]","Ivan Franceschini and Michael G. Vann, “The Great Hanoi Rat Hunt: A Conversation with Michael G. Vann,” <i>Made in China Journal</i>, 20 August 2020, https://madeinchinajournal.com/2020/08/20/the-great-hanoi-rat-hunt. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “15.2 The Poverty Trap” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/15-2-the-poverty-trap. [Open access]"],"why":[{"q":"Why did the Hanoi bounty fail to reduce the number of rats?","a":"Because the city paid for tails rather than for fewer rats, so residents could earn the bounty without shrinking the population at all. Within about three months officials found people farming rats, cutting off the tails and releasing the animals to breed, and a network smuggling rodents in from across Tonkin.<sup class=\"fn\" data-fn=\"6\"></sup> It is a case of rewarding the wrong thing: what the authorities wanted was fewer rats, but what they paid for was a stand-in that could be produced more cheaply.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why are some famous stories of perverse incentives treated with caution?","a":"Because several of the best-known ones are told without firm evidence. The tale of an Italian town whose bounty on dead vipers led people to breed vipers in their basements may be apocryphal, as one account that retells it concedes, even though the mistake it describes is real.<sup class=\"fn\" data-fn=\"2\"></sup> The Hanoi rat hunt is different, since it rests on documents in the French colonial archives that a historian found while researching the city.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why can a fine make a behaviour more common instead of less?","a":"Because a penalty is usually introduced into an agreement that never spelled out every term, and it can change what people believe about the situation they are in. In the day-care study, the fine for lateness was followed by more late parents, not fewer, and the higher rate persisted after the fine was removed.<sup class=\"fn\" data-fn=\"5\"></sup> The result undercuts the simple deterrence prediction that a penalty, with everything else unchanged, must reduce the behaviour it targets.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Perverse incentive"},
    "ec-032": {"questions":["Cambodia exporting mostly gold and knitwear while Singapore concentrates on integrated circuits shows national <span class=\"blank\">_____</span> at work, a pattern that can also leave narrow economies exposed to shocks.","Learning by doing, differences in ability and economies of scale are the three usual sources of the gains from <span class=\"blank\">_____</span>, which pays only when workers can trade their output for everything else."],"abstract":"<b>Specialisation</b> is the concentration of a person, a firm, a region or a country on a narrow range of tasks or products, with everything else obtained from others.<sup class=\"fn\" data-fn=\"2\"></sup> Its advantages are usually traced to three sources: skills learned by doing the same work repeatedly, natural or acquired differences in ability, and the lower average cost of producing on a large scale.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It only makes sense if what a worker earns can be exchanged for the other things she needs, so it depends on markets or on some other way of getting goods from producers to users.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Firms specialise in particular goods or in one stage of a product, and countries do too, as when Cambodia's largest exports are gold and knitwear while Singapore specialises in integrated circuits.<sup class=\"fn\" data-fn=\"2\"></sup> Because skill can be acquired by practice alone, specialisation would reward exchange even among people who started out identical, though differences in relative cost give a further reason to specialise.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The idea is far older than modern economics, and Plato's <i>Republic</i> already held that more is produced, better and more easily, when each person does one task suited to them.<sup class=\"fn\" data-fn=\"5\"></sup> Xenophon observed that in small towns one workman made chairs, doors, ploughs and tables, while in large cities a man could live by stitching shoes alone, because each narrow trade had enough customers.<sup class=\"fn\" data-fn=\"4\"></sup> Adam Smith turned the same observation into a principle in 1776, arguing that specialisation is limited by the extent of the market, which is why a country carpenter must also be joiner, cabinet-maker and wheelwright.<sup class=\"fn\" data-fn=\"3\"></sup> Concentration also has a cost, since an economy that depends on a few products is more exposed to shocks, and among low-income countries greater diversification has gone together with lower volatility and higher growth.<sup class=\"fn\" data-fn=\"8\"></sup> The pattern is an association rather than a proven cause, and little is known about how diversification is linked to growth, so it supports caution about extreme concentration rather than a settled rule.<sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.1 What Is Economics, and Why Is It Important?” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §2.3 “Comparative Advantage, Specialization, and Markets,” https://www.core-econ.org/the-economy/microeconomics/02-technology-incentives-03-comparative-advantage.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), bk. 1, chaps. 1–3, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","Xenophon, <i>Cyropaedia</i> 8.2.5, trans. Walter Miller, Loeb Classical Library (Cambridge, MA: Harvard University Press, 1914), Perseus Digital Library, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0204%3Abook%3D8%3Achapter%3D2%3Asection%3D5. [Open access]","Plato, <i>Republic</i> 2.370c, trans. Paul Shorey (Cambridge, MA: Harvard University Press, 1969), Perseus Digital Library, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0168%3Abook%3D2%3Asection%3D370c. [Open access]","Michael Munger, “Division of Labor,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/DivisionofLabor.html. [Open access]","Donald J. Boudreaux, “Comparative Advantage,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/ComparativeAdvantage.html. [Open access]","Chris Papageorgiou and Nikola Spatafora, <i>Economic Diversification in LICs: Stylized Facts and Macroeconomic Implications</i>, IMF Staff Discussion Note SDN/12/13 (Washington, DC: International Monetary Fund, 2012), https://www.imf.org/external/pubs/ft/sdn/2012/sdn1213.pdf. [Open access]"],"why":[{"q":"Why does specialisation depend on trade?","a":"Because a worker who makes only one thing must swap it, or the pay for it, for everything else. Specialisation makes sense only if the pay for a job can buy the other goods and services a worker needs.<sup class=\"fn\" data-fn=\"1\"></sup> Societies have solved the problem of moving goods from producer to user in different ways, from government requisitioning to sharing within families, but markets greatly widened the scope for it.<sup class=\"fn\" data-fn=\"2\"></sup> Where the market is very small, nobody has any encouragement to dedicate himself entirely to one employment.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did large cities allow narrower trades than small towns?","a":"Because more people meant more demand for each branch of work. Xenophon noted that in large cities one trade, or even part of one, was enough to support a man, so that one made men's shoes and another women's.<sup class=\"fn\" data-fn=\"4\"></sup> Smith made the same point with a nailer, who could make hundreds of thousands of nails a year but could never sell them in the remote and inland Highlands of Scotland.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why might a country not want to specialise completely?","a":"Because concentrating on a few products can raise exposure to shocks. Many low-income countries have depended on a narrow range of primary products, sectors with limited scope for productivity growth, and lack of diversification may increase their vulnerability to external shocks and macroeconomic instability.<sup class=\"fn\" data-fn=\"8\"></sup> Greater diversification has been associated with lower volatility and higher growth, though the evidence is a correlation that its authors said needed further work.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Division of labour"},
    "ec-033": {"questions":["Splitting a skilled tailor's work into more than 300 simple operations, each done by someone without tailoring skills, is the <span class=\"blank\">_____</span> applied inside a modern garment firm.","Paying for exactly the skill each step requires, rather than the skill of the hardest step throughout, is one reason the <span class=\"blank\">_____</span> lowers the cost of manufactured goods."],"abstract":"The <b>division of labour</b> is the splitting of a production process into separate tasks, each carried out by a different worker, instead of having one person make the whole product.<sup class=\"fn\" data-fn=\"4\"></sup> It combines specialisation with the partition of a complex job into many sub-tasks, and its importance is that a given number of workers can produce far more than the same number working alone, even skilled artisans.<sup class=\"fn\" data-fn=\"6\"></sup> The standard explanation lists three gains: workers become more dexterous at a narrow task, no time is lost moving between kinds of work, and narrowly defined steps invite tools and machines that save labour.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A further gain is that an employer who divides the work can buy exactly the skill or strength each step needs, instead of paying for the most difficult step throughout.<sup class=\"fn\" data-fn=\"3\"></sup> The division happens inside firms, across a whole society and even across the world, and it raises the problem of how goods are to get from the producer to the final user.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> The best-known illustration is a pin workshop described in 1776, where about eighteen operations, a figure that was really a quick estimate, were shared out so that ten men made upwards of 48,000 pins a day.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Working separately and without training, Adam Smith wrote, each of them could certainly not have made twenty pins in a day, and perhaps not one.<sup class=\"fn\" data-fn=\"1\"></sup> Modern firms push the logic further, as when a Chinese garment maker split the work of a skilled tailor into more than 300 operations performed by workers without tailoring skills.<sup class=\"fn\" data-fn=\"5\"></sup> Its limits are debated: the classic view is that the division is limited by the extent of the market, while a later argument holds that the costs of coordinating specialised workers more often set the limit.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> There is also a human cost, for the same book warned that a worker confined to a few simple operations loses the habit of exerting his understanding and becomes as stupid and ignorant as a human creature can become.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), bk. 1, chaps. 1–3, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), bk. 5, chap. 1, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","Charles Babbage, <i>On the Economy of Machinery and Manufactures</i> (London: Knight, 1832), chap. 19, “On the Division of Labour,” Project Gutenberg, https://www.gutenberg.org/ebooks/4238. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “1.1 What Is Economics, and Why Is It Important?” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/1-1-what-is-economics-and-why-is-it-important. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §2.3 “Comparative Advantage, Specialization, and Markets,” https://www.core-econ.org/the-economy/microeconomics/02-technology-incentives-03-comparative-advantage.html. [Open access]","Michael Munger, “Division of Labor,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/DivisionofLabor.html. [Open access]","Michael Munger, “I’ll Stick With These: Some Sharp Observations on the Division of Labor,” Library of Economics and Liberty, 2 April 2007, https://www.econlib.org/library/Columns/y2007/Mungerpins.html. [Open access]","Gary S. Becker and Kevin M. Murphy, “The Division of Labor, Coordination Costs, and Knowledge,” <i>Quarterly Journal of Economics</i> 107, no. 4 (1992): 1137–60, abstract at EconPapers, https://econpapers.repec.org/article/oupqjecon/v_3a107_3ay_3a1992_3ai_3a4_3ap_3a1137-1160..htm. [Paywalled]"],"why":[{"q":"Why does dividing work raise output per worker?","a":"Because each worker grows more dexterous at a narrow task, no time is lost switching from one kind of work to another, and simple, well-defined steps invite machines that abridge labour.<sup class=\"fn\" data-fn=\"1\"></sup> The gain holds even when the people working alone would be expert artisans.<sup class=\"fn\" data-fn=\"6\"></sup> An employer can also buy exactly the skill or force each step needs, instead of paying a worker skilled enough for the hardest step to do the easy ones too.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did the author of the pin example also worry about it?","a":"Because he thought a life spent on a few simple operations dulled the mind. Such a worker, he wrote, has no occasion to exert his understanding, loses the habit, and becomes incapable of judging the great interests of his country unless very particular pains are taken to prevent it.<sup class=\"fn\" data-fn=\"2\"></sup> The worry sits in the fifth book of the same work whose first chapter praises the pin workshop.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"What limits how far labour can be divided?","a":"The classic answer is the size of the market: the number of steps into which pin-making is split depends on how many pins can be sold, so a small market supports few steps and a world market many.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> A later argument holds that the limit is more often set by the costs of coordinating specialised workers who perform complementary tasks, and by the amount of general knowledge available.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Division of labour"},
    "ec-034": {"questions":["Expecting dinner from the butcher's regard for his own interest rather than from his benevolence describes the <span class=\"blank\">_____</span> by which both parties gain without either aiming at the other's good.","Against the mercantilist belief that every trade has a winner and a loser, a <span class=\"blank\">_____</span> is described as positive-sum, since neither party would agree to it without expecting to gain."],"abstract":"A <b>voluntary exchange</b> is a trade that both parties enter freely, and the central claim made for it is that each side expects to end up better off than if the trade had not happened.<sup class=\"fn\" data-fn=\"2\"></sup> The two parties value the goods differently, each giving up something it values less for something it values more, which is why exchange can create gains instead of merely moving wealth around.<sup class=\"fn\" data-fn=\"2\"></sup> The benefit each party receives compared with going without the trade is its surplus, and the sum of the buyer's and the seller's surplus measures the gains from trade.<sup class=\"fn\" data-fn=\"5\"></sup> On a single sale the possible gain is the gap between the most the buyer would pay and the cost to the seller of supplying the good, and any price inside that gap leaves both better off.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> The price decides how the gain is divided, so bargaining power affects who receives more of it without changing whether the trade benefits both.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> The idea answers the older mercantilist view that in every transaction one party gains only at the other's expense, a view contradicted by the willingness of both sides to trade.<sup class=\"fn\" data-fn=\"2\"></sup> Adam Smith put the point in 1776, observing that we expect our dinner not from the benevolence of the butcher, the brewer or the baker but from their regard to their own interest.<sup class=\"fn\" data-fn=\"1\"></sup> The claim concerns what each party expects at the moment of the deal, so a trade can still disappoint, and the result that a competitive market exhausts the gains from trade holds only when no outsider is affected and contracts are complete.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Mutual benefit is also not the same as fairness, since a seller who charges a hiker lost in the desert an enormous price for a bottle of water makes a trade both gain from while taking unfair advantage of her.<sup class=\"fn\" data-fn=\"7\"></sup> Consumer and producer surplus, the measures economists use for these gains, record how much each side gains in money, not whether the outcome is just.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), bk. 1, chap. 2, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","Murray N. Rothbard, “Free Market,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/FreeMarket.html. [Open access]","Donald J. Boudreaux, “Comparative Advantage,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/ComparativeAdvantage.html. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §8.5 “Gains from Trade in Competitive Equilibrium: Allocation and Distribution,” https://www.core-econ.org/the-economy/microeconomics/08-supply-demand-05-gains-from-trade.html. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §7.7 “Gains from Trade: The Surplus and How It Is Divided,” https://www.core-econ.org/the-economy/microeconomics/07-firm-and-customers-07-divided-surplus.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “3.5 Demand, Supply, and Efficiency” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/3-5-demand-supply-and-efficiency. [Open access]","Matt Zwolinski, Benjamin Ferguson and Alan Wertheimer, “Exploitation,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 3 October 2022, https://plato.stanford.edu/entries/exploitation/. [Open access]"],"why":[{"q":"Why can both sides gain from the same trade?","a":"Because they value the goods differently: each gives up something it values less for something it values more, so the exchange is positive-sum rather than zero-sum.<sup class=\"fn\" data-fn=\"2\"></sup> On any one sale, every price between the most the buyer would pay and the cost to the seller leaves both with a surplus, and such a range exists whenever their valuations differ.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why does a voluntary trade not guarantee a fair outcome?","a":"Because a trade can benefit both parties and still take unfair advantage of one of them, as when a lost hiker pays a huge price for water.<sup class=\"fn\" data-fn=\"7\"></sup> The measures of gains from trade say nothing about fairness, and the price, which depends on bargaining power, decides how the gains are shared.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why might a voluntary trade still leave someone worse off?","a":"Because each party acts on expectations, and an expectation can prove wrong, which is why people repeat some trades and refuse others.<sup class=\"fn\" data-fn=\"2\"></sup> People outside the trade can also be harmed, as when production causes noise or pollution nearby, and contracts may fail to cover what matters, as for the buyer of a second-hand car who cannot tell whether it is roadworthy.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Voluntary exchange"},
    "ec-035": {"questions":["Portugal needed less labour than England for both cloth and wine yet still exported wine, because that was where it had the <span class=\"blank\">_____</span> measured in cloth forgone.","An island fisher who sacrifices half a banana per fish, while her neighbour sacrifices a whole banana, has the <span class=\"blank\">_____</span> in fishing and should leave banana gathering to him."],"abstract":"A <b>lower opportunity cost</b> in making a good, meaning that less of other goods is given up for each unit produced, is what gives a person, firm or country a comparative advantage in it.<sup class=\"fn\" data-fn=\"5\"></sup> The idea is that what matters for trade is not who is absolutely best at producing something but who sacrifices least to produce it.<sup class=\"fn\" data-fn=\"1\"></sup> In a simple island example, a woman who gives up half a banana for each fish she catches should fish, while her neighbour, who gives up a whole banana per fish, should gather bananas, and both then consume more.<sup class=\"fn\" data-fn=\"1\"></sup> Any rate of exchange lying between their two costs leaves both better off, and such a rate exists whenever their relative costs differ.<sup class=\"fn\" data-fn=\"1\"></sup> The surprising consequence is that a producer who is better at everything still gains by buying a good from someone less productive, as long as that someone gives up less to make it.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> The principle was set out in 1817 with England and Portugal, cloth and wine, where Portugal needed less labour for both goods yet still gained by importing English cloth and exporting wine.<sup class=\"fn\" data-fn=\"2\"></sup> Because it holds between two people with no border between them, it is often described as the root reason for all specialisation and trade, not only trade between nations.<sup class=\"fn\" data-fn=\"1\"></sup> A common misreading takes it as a promise that nobody loses, yet the argument is that trade raises a nation's total income, which can still shift in ways that hurt large groups within it.<sup class=\"fn\" data-fn=\"3\"></sup> Its logic is mathematically sound, which is different from showing that it explains real trade, but a study of Japan's sudden opening to trade in the 1860s found the pattern of trade the theory predicts.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> A later test using the productivity of 1.6 million parcels of land in 55 countries across 17 crops found that the theory, despite all it leaves out, has significant explanatory power.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Donald J. Boudreaux, “Comparative Advantage,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/ComparativeAdvantage.html. [Open access]","David Ricardo, <i>On the Principles of Political Economy and Taxation</i> (London: John Murray, 1817), chap. 6, “On Foreign Trade,” Project Gutenberg, https://www.gutenberg.org/ebooks/33310. [Open access]","Paul Krugman, “Ricardo’s Difficult Idea,” Massachusetts Institute of Technology, https://web.mit.edu/krugman/www/ricardo.htm. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §2.3 “Comparative Advantage, Specialization, and Markets,” https://www.core-econ.org/the-economy/microeconomics/02-technology-incentives-03-comparative-advantage.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “2.2 The Production Possibilities Frontier and Social Choices” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/2-2-the-production-possibilities-frontier-and-social-choices. [Open access]","Arnaud Costinot and Dave Donaldson, “Ricardo’s Theory of Comparative Advantage: Old Idea, New Evidence,” NBER Working Paper 17969 (Cambridge, MA: National Bureau of Economic Research, 2012), https://www.nber.org/papers/w17969. [Open access]","Daniel Bernhofen and John C. Brown, “A Direct Test of the Theory of Comparative Advantage: The Case of Japan,” <i>Journal of Political Economy</i> 112, no. 1 (2004): 48–67, abstract at EconPapers, https://econpapers.repec.org/RePEc:ucp:jpolec:v:112:y:2004:i:1:p:48-67. [Paywalled]"],"why":[{"q":"Why does an absolutely better producer still gain from trade?","a":"Because what decides who should make what is the relative cost, not the absolute one. A farmer who grows both apples and wheat better than her neighbour still gains by buying his apples, since he gives up less wheat to grow them than she would.<sup class=\"fn\" data-fn=\"4\"></sup> Any price between their two costs leaves both of them better off.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why is the principle so often misunderstood?","a":"Because it looks simple but rests on a dense web of linked ideas about how competitive markets work, what determines wages and how the balance of payments adds up.<sup class=\"fn\" data-fn=\"3\"></sup> It is also a mathematical argument, even when stated without equations, and some readers who value ideas resist reasoning of that kind.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"How has the idea been tested against real data?","a":"Japan's sudden and complete opening to trade in the 1860s gave one test, and the prices it had faced before trade predicted the direction of its exports and imports, as the theory says they should.<sup class=\"fn\" data-fn=\"7\"></sup> A later study used crop data covering 1.6 million parcels of land, including crops not actually grown there, and found that the theory has significant explanatory power.<sup class=\"fn\" data-fn=\"6\"></sup>"}]},
    "ec-036": {"questions":["Raising grapes under glass in Scotland at about thirty times the cost of foreign wine illustrated in 1776 why an <span class=\"blank\">_____</span> abroad makes buying better than making at home.","A rich country with an <span class=\"blank\">_____</span> in every product, thanks to educated workers and advanced equipment, still gains by trading with poorer countries according to its relative costs."],"abstract":"An <b>absolute advantage</b> is the ability of a person or country to produce more of a good than another can from the same inputs, or the same amount with fewer.<sup class=\"fn\" data-fn=\"5\"></sup> It can come from more resources, more productive ones or a natural endowment, as with oil in Saudi Arabia, which is largely a matter of drilling a hole, or the rich copper mines of Chile and Zambia.<sup class=\"fn\" data-fn=\"3\"></sup> When each of two countries is absolutely better at a different good, the gains from each specialising in its own good and trading are easy to see.<sup class=\"fn\" data-fn=\"3\"></sup> The case for free trade made in 1776 rested on this idea, holding that if a foreign country can supply a commodity cheaper than we can make it, it is better to buy it with the produce of our own industry.<sup class=\"fn\" data-fn=\"1\"></sup> Its model was the household: the tailor buys his shoes from the shoemaker, and what is prudence in the conduct of every private family can scarcely be folly in that of a great kingdom.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The same argument pointed out that very good grapes could be raised in Scotland under glass and on hot-beds, but at about thirty times the expense of equally good wine from abroad.<sup class=\"fn\" data-fn=\"1\"></sup> Absolute advantage alone is an incomplete account of trade, as was shown in 1817 with the case of Portugal importing English cloth even though Portugal could make cloth with less labour than England.<sup class=\"fn\" data-fn=\"2\"></sup> What decides the pattern is the comparison of costs measured in other goods forgone, so a country with an absolute advantage in every product still gains by specialising and trading.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> High-income countries often hold such an advantage across the board, through educated workers, advanced equipment and up-to-date production processes, yet trade with poorer countries can still benefit both sides.<sup class=\"fn\" data-fn=\"4\"></sup> For the same reason the simple model of trade holds that competition from low-wage countries is not necessarily harmful, because trade can be mutually beneficial whatever the difference in wages.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i> (1776), bk. 4, chap. 2, Project Gutenberg, https://www.gutenberg.org/ebooks/3300. [Open access]","David Ricardo, <i>On the Principles of Political Economy and Taxation</i> (London: John Murray, 1817), chap. 6, “On Foreign Trade,” Project Gutenberg, https://www.gutenberg.org/ebooks/33310. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “33.1 Absolute and Comparative Advantage” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/33-1-absolute-and-comparative-advantage. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “33.2 What Happens When a Country Has an Absolute Advantage in All Goods” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/33-2-what-happens-when-a-country-has-an-absolute-advantage-in-all-goods. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §2.3 “Comparative Advantage, Specialization, and Markets,” https://www.core-econ.org/the-economy/microeconomics/02-technology-incentives-03-comparative-advantage.html. [Open access]","Donald J. Boudreaux, “Comparative Advantage,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/ComparativeAdvantage.html. [Open access]","Paul Krugman, “Ricardo’s Difficult Idea,” Massachusetts Institute of Technology, https://web.mit.edu/krugman/www/ricardo.htm. [Open access]"],"why":[{"q":"Why is absolute advantage an incomplete explanation of trade?","a":"Because a country can be better at making everything and still gain from trade. Portugal could make both cloth and wine with less labour than England, yet it paid to import English cloth and put its own effort into wine.<sup class=\"fn\" data-fn=\"2\"></sup> What matters is where a producer's advantage is relatively largest, or its disadvantage relatively smallest, not who is best in absolute terms.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why did the 1776 case for free trade appeal to households?","a":"Because every prudent head of a family already avoided making at home what would cost more to make than to buy. The tailor buys shoes and the shoemaker employs a tailor, each putting his whole industry where he has some advantage, and the argument held that what is prudence in a family can scarcely be folly in a great kingdom.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"What gives a country an absolute advantage?","a":"More resources, more productive resources or a natural endowment. Saudi oil, rich American farmland, climates suited to coffee in Guatemala and Colombia, and the copper mines of Chile and Zambia are examples.<sup class=\"fn\" data-fn=\"3\"></sup> Skill can create one too, as can the quality of the soil and the other characteristics of the natural surroundings.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Absolute advantage"},
    "ec-037": {"questions":["A situation falls short of <span class=\"blank\">_____</span> when someone could be made better off without anyone being made worse off, an unexploited gain that economists treat as a kind of waste.","Because <span class=\"blank\">_____</span> counts only the valuations of people able to back them with money, an outcome that meets it can still fail the separate test of fairness."],"abstract":"<b>Economic efficiency</b> is the use of resources so that no more of what people value could be had from the same means, or the same ends reached with fewer.<sup class=\"fn\" data-fn=\"1\"></sup> In everyday speech efficiency means a lack of waste, and economists keep that sense while measuring ends and means by value, not physical quantity.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The formal test most often used is that no one could be made better off without someone else being made worse off, so an inefficient situation is one in which some party could gain at no cost to anyone.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Economists distinguish productive efficiency, in which no more of one good can be made without making less of another, from allocative efficiency, in which the mix of goods produced is the one society most wants.<sup class=\"fn\" data-fn=\"2\"></sup> In a market this means that every trade for which a buyer would pay more than the cost of supplying the good takes place, so that the combined surplus of buyers and sellers is as large as possible.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Economists have long tried to keep statements about efficiency apart from judgements of value, though the subject's closeness to policy makes it virtually impossible to avoid mixing the two.<sup class=\"fn\" data-fn=\"7\"></sup> Efficiency is measured by the valuations of those willing and able to back their preferences with money, which raises the question of whose valuations count and how they are weighted.<sup class=\"fn\" data-fn=\"1\"></sup> For that reason the economist's objection to monopoly is not that it transfers wealth from customers to the seller, since economics has no way of knowing which party is more worthy, but that it cuts output and leaves society as a whole poorer.<sup class=\"fn\" data-fn=\"8\"></sup> The result that competitive markets are efficient holds only under stringent conditions, including many buyers and sellers, no effects on outsiders and complete contracts, and even then an efficient allocation need not be desirable.<sup class=\"fn\" data-fn=\"4\"></sup> Efficiency and fairness are therefore treated as two separate criteria for judging an outcome, and an allocation can satisfy the first while failing the second.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Paul Heyne, “Efficiency,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Efficiency.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “2.2 The Production Possibilities Frontier and Social Choices” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/2-2-the-production-possibilities-frontier-and-social-choices. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “3.5 Demand, Supply, and Efficiency” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/3-5-demand-supply-and-efficiency. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §8.5 “Gains from Trade in Competitive Equilibrium: Allocation and Distribution,” https://www.core-econ.org/the-economy/microeconomics/08-supply-demand-05-gains-from-trade.html. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §5.3 “Evaluating Institutions and Outcomes: Fairness,” https://www.core-econ.org/the-economy/microeconomics/05-the-rules-of-the-game-03-evaluating-institutions-outcomes.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Marc Fleurbaey, “Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","George J. Stigler, “Monopoly,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Monopoly.html. [Open access]"],"why":[{"q":"Why do economists measure efficiency in value rather than physical terms?","a":"Because in purely physical terms every process turns all of its inputs into outputs, so calling a machine efficient already means counting only the useful work it does, and useful is a judgement of value.<sup class=\"fn\" data-fn=\"1\"></sup> The everyday sense of efficiency as a lack of waste survives, but waste is judged by what people value.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the economic case against monopoly about efficiency, not the transfer?","a":"Because economics has no way of saying whether the customer or the monopolist is more worthy of the money that passes between them. The objection is that a price raised above the competitive level makes customers buy less, so less is produced and society as a whole is worse off.<sup class=\"fn\" data-fn=\"8\"></sup>"},{"q":"Why does an efficient outcome not settle whether it is desirable?","a":"Because efficiency in markets holds only under stringent conditions, and even then the sum of monetary gains says nothing about fairness.<sup class=\"fn\" data-fn=\"4\"></sup> Fairness is a separate criterion, judged by how unequal an allocation is or by how it came about.<sup class=\"fn\" data-fn=\"5\"></sup> The money valuations behind efficiency also count only the preferences of people able to pay.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Economic efficiency"},
    "ec-038": {"questions":["Of all the productively efficient points on a production possibilities frontier, only one achieves <span class=\"blank\">_____</span> for society, the particular mix of goods its members most desire.","A seller who prices above marginal cost, shutting out buyers willing to pay more than the cost of supplying them, sacrifices <span class=\"blank\">_____</span> and creates what economists call deadweight loss."],"abstract":"<b>Allocative efficiency</b> is achieved when the particular mix of goods and services an economy produces is the one its members most desire, so that resources go to the uses they value most.<sup class=\"fn\" data-fn=\"1\"></sup> It is distinguished from productive efficiency, which only requires that no more of one good could be made without making less of another, a condition met anywhere on the frontier of what an economy can produce.<sup class=\"fn\" data-fn=\"1\"></sup> Many combinations of goods are productively efficient, but only one of them is allocatively efficient for a society as a whole.<sup class=\"fn\" data-fn=\"1\"></sup> In a single market the condition is that output expands until the value of the last unit to the buyer who gets it equals the marginal cost of producing it, so that no trade worth more than its cost is left undone.<sup class=\"fn\" data-fn=\"3\"></sup> At that point the combined surplus of buyers and sellers is as large as it can be, and any other quantity, larger or smaller, reduces it.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> <br><br> A firm with market power that sets its price above marginal cost sells less than this, leaving out buyers who would pay more than the cost of supplying them, and the surplus lost is called deadweight loss.<sup class=\"fn\" data-fn=\"4\"></sup> This, rather than the transfer of money from customers to the seller, is the economist's main objection to monopoly, because the higher price means less is produced and society as a whole is worse off.<sup class=\"fn\" data-fn=\"6\"></sup> Price ceilings and price floors cause a similar loss, since they block some transactions that buyers and sellers would both have been willing to make.<sup class=\"fn\" data-fn=\"2\"></sup> The standard is defined through willingness to pay, so the valuations that count are those of people able to back their preferences with money, which raises the question of whose valuations are used and how they are weighted.<sup class=\"fn\" data-fn=\"5\"></sup> Real markets also have several imperfections at once, and the theory of the second best shows that removing only some of them can move an economy further from efficiency rather than closer to it.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “2.2 The Production Possibilities Frontier and Social Choices” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/2-2-the-production-possibilities-frontier-and-social-choices. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “3.5 Demand, Supply, and Efficiency” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/3-5-demand-supply-and-efficiency. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §8.5 “Gains from Trade in Competitive Equilibrium: Allocation and Distribution,” https://www.core-econ.org/the-economy/microeconomics/08-supply-demand-05-gains-from-trade.html. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §7.7 “Gains from Trade: The Surplus and How It Is Divided,” https://www.core-econ.org/the-economy/microeconomics/07-firm-and-customers-07-divided-surplus.html. [Open access]","Paul Heyne, “Efficiency,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Efficiency.html. [Open access]","George J. Stigler, “Monopoly,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Monopoly.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]"],"why":[{"q":"Why is a point on the production frontier not automatically the best one?","a":"Because every point on the frontier is productively efficient, meaning more of one good can be had only by giving up some of another, but only one of those points is the mix society most desires.<sup class=\"fn\" data-fn=\"1\"></sup> Which mix that is can be a controversial question, discussed in political science and philosophy as well as economics.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does pricing above marginal cost cause inefficiency?","a":"Because some buyers would pay more than it costs to make another unit, yet are priced out. In one textbook example a carmaker sells 32 cars when there are potential gains from trade on 64, so selling one more car to the next buyer at a lower price would leave someone better off and nobody worse off.<sup class=\"fn\" data-fn=\"4\"></sup> Less is produced, and society as a whole is poorer.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why might removing one market distortion fail to improve efficiency?","a":"Because real markets have many imperfections at once, and the theory of the second best shows that fixing some of them can lead away from the competitive ideal and reduce efficiency.<sup class=\"fn\" data-fn=\"7\"></sup> The efficiency of competitive markets itself holds only under stringent conditions, such as no effects on outsiders and complete contracts.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Allocative efficiency"},
    "ec-039": {"questions":["Free public schooling, which redistributes towards poorer families while building a skilled workforce, is cited as evidence that the <span class=\"blank\">_____</span> is not always as steep as assumed.","A West Bengal tenancy reform that raised both sharecroppers' incomes and output per unit of land cut against the assumed <span class=\"blank\">_____</span> between a fairer distribution and a larger total."],"abstract":"The <b>equity-efficiency trade-off</b> is the proposition that policies which make the distribution of income more equal tend to reduce the total output an economy produces, so that a society must give up some of one to gain more of the other.<sup class=\"fn\" data-fn=\"1\"></sup> The usual reasons are that high taxes on the rich weaken their incentive to work and invest, while benefits withdrawn as earnings rise weaken the incentive of the poor to work.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The idea is associated with a 1975 book that called the conflict between equality and efficiency the big tradeoff, an expanded version of lectures given at Harvard University in 1974.<sup class=\"fn\" data-fn=\"3\"></sup> Its best-known image is the leaky bucket, in which money carried from the rich to the poor loses some of its contents in transit through administrative costs and weakened incentives.<sup class=\"fn\" data-fn=\"2\"></sup> Its author nonetheless believed that transfers from the relatively rich to the relatively poor were appropriate policy, while recognising the efficiency lost along the way.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Whether the trade-off is steep is an empirical question, and the evidence on it is contested.<sup class=\"fn\" data-fn=\"5\"></sup> Some policies may raise both equality and output, such as free public schooling, which redistributes towards poorer families while building the skills on which an economy grows.<sup class=\"fn\" data-fn=\"1\"></sup> The efficiency loss may also be small when transfers go to people who cannot change their behaviour, or when they pay for things that work as investments and raise future incomes.<sup class=\"fn\" data-fn=\"4\"></sup> A tenancy reform in West Bengal from 1978, which let sharecroppers keep up to three-quarters of their crop and protected them from eviction, was followed by higher output per unit of land and higher farm incomes.<sup class=\"fn\" data-fn=\"6\"></sup> Cross-country work by International Monetary Fund staff found redistribution generally benign for growth except in extreme cases, while warning of the limits of such data, so the size of the trade-off remains disputed.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “15.5 Government Policies to Reduce Income Inequality” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/15-5-government-policies-to-reduce-income-inequality. [Open access]","“Arthur M. Okun,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/bios/Okun.html. [Open access]","Arthur M. Okun, <i>Equality and Efficiency: The Big Tradeoff</i> (Washington, DC: Brookings Institution Press, 1975), publisher’s description, https://www.brookings.edu/book/equality-and-efficiency. [Paywalled]","Rebecca M. Blank, “Can Equity and Efficiency Complement Each Other?,” NBER Working Paper 8820 (Cambridge, MA: National Bureau of Economic Research, 2002), published in <i>Labour Economics</i> 9, no. 4 (2002): 451–68, https://www.nber.org/papers/w8820. [Open access]","Jonathan D. Ostry, Andrew Berg and Charalambos G. Tsangarides, <i>Redistribution, Inequality, and Growth</i>, IMF Staff Discussion Note SDN/14/02 (Washington, DC: International Monetary Fund, 2014), https://www.imf.org/external/pubs/ft/sdn/2014/sdn1402.pdf. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §5.13 “Application: A Policy to Redistribute the Surplus and Raise Efficiency,” https://www.core-econ.org/the-economy/microeconomics/05-the-rules-of-the-game-13-redistribute-surplus-raise-efficiency.html. [Open access]"],"why":[{"q":"Why might redistribution reduce total output?","a":"Because a guaranteed income can reduce the incentive to work, and very high taxes on the rich are likely to discourage work and enterprise.<sup class=\"fn\" data-fn=\"1\"></sup> Some of the money is also lost to the administrative costs of taxing and transferring, which is the leak in the bucket.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why do some economists doubt that the trade-off is large?","a":"Because the best available cross-country data do not support a big trade-off between redistribution and growth: lower inequality goes with faster and more durable growth, and only extreme redistribution shows signs of direct harm, though such regressions have clear limits.<sup class=\"fn\" data-fn=\"5\"></sup> The loss is also likely to be small where transfers go to people who cannot change their behaviour or fund investments that raise future incomes.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"How did the West Bengal reform raise both equality and output?","a":"Because sharecroppers who kept a larger share had a greater reward for working hard and, protected from eviction, a reason to invest in their land. One study credited the reform with around 28 per cent of the region's growth in agricultural productivity from 1979 to 1993, but it was not a gain for everyone, since some landowners' incomes fell.<sup class=\"fn\" data-fn=\"6\"></sup>"}]},
    "ec-040": {"questions":["Cost-benefit analysis measures a policy's benefits by people's <span class=\"blank\">_____</span> for its effects, a method long criticised for weighting the preferences of the rich above those of the poor.","A wealthy woman outbidding a hungry infant's mother for milk counts as efficient when value is measured by <span class=\"blank\">_____</span>, which is why efficiency alone cannot show that an outcome is good."],"abstract":"<b>Willingness to pay</b> is the largest amount a person would give for a good or an outcome, and it is the yardstick economists use to measure how much people value what an efficiency judgement weighs.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> A demand curve traces buyers' willingness to pay, and the gap between what a buyer would have paid and the price actually paid is the consumer surplus that efficiency calculations add up.<sup class=\"fn\" data-fn=\"5\"></sup> In cost-benefit analysis the benefits of a policy are likewise measured by people's willingness to pay for its effects, and its costs by the compensation needed to offset the harms.<sup class=\"fn\" data-fn=\"2\"></sup> Economic efficiency is defined through such money valuations, so the preferences that count are those of people willing and able to back them with money.<sup class=\"fn\" data-fn=\"1\"></sup> For that reason an efficient allocation need not be a desirable one, since the sum of money gains is a poor measure of overall benefit and says nothing about fairness.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Willingness to pay depends on income as well as on how much a person cares, so a billionaire would be able, and therefore willing, to pay more than a pauper for the same improvement even if both cared about it equally.<sup class=\"fn\" data-fn=\"2\"></sup> Adding it up across people therefore weights the preferences of the rich more heavily than those of the poor, a criticism long made of cost-benefit analysis.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A classic example has a wealthy dowager bid scarce milk away from the mother of an undernourished infant in order to wash her diamonds, an outcome efficient in the economist's sense, though defenders of the standard call the example strained.<sup class=\"fn\" data-fn=\"1\"></sup> Some methods answer the objection by weighting willingness to pay, and British government appraisal guidance allows a higher social value for gains to lower-income households, on the principle that extra income is worth more to those who have less.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Economics can clarify such choices, but neither economics nor any other science can eliminate disagreements about questions of value, so whether and how far to weight remains a value judgement.<sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Paul Heyne, “Efficiency,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Efficiency.html. [Open access]","Paul R. Portney, “Benefit-Cost Analysis,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/BenefitCostAnalysis.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Marc Fleurbaey, “Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “3.5 Demand, Supply, and Efficiency” (Houston: OpenStax, 2022), https://openstax.org/books/principles-economics-3e/pages/3-5-demand-supply-and-efficiency. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §8.5 “Gains from Trade in Competitive Equilibrium: Allocation and Distribution,” https://www.core-econ.org/the-economy/microeconomics/08-supply-demand-05-gains-from-trade.html. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), “Distributional weighting,” https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i> (CORE Econ, 2023), §5.3 “Evaluating Institutions and Outcomes: Fairness,” https://www.core-econ.org/the-economy/microeconomics/05-the-rules-of-the-game-03-evaluating-institutions-outcomes.html. [Open access]"],"why":[{"q":"Why does measuring value by willingness to pay favour the rich?","a":"Because what someone is willing to pay depends on what they are able to pay. A billionaire can offer more than a pauper for the same cleaner air even if both care about it equally.<sup class=\"fn\" data-fn=\"2\"></sup> Summed across a population, willingness to pay therefore weights the preferences of the rich more than the preferences of the poor.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do economists use money valuations at all?","a":"Because every idea of efficiency needs some measure of value, and money lets the evaluations of many different people be compared and responded to.<sup class=\"fn\" data-fn=\"1\"></sup> In cost-benefit analysis the money figures are meant to capture far more than income, such as better visibility or lower health risks, and count only values held by individual members of society.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"How can an appraisal correct for differences in income?","a":"By weighting each person's willingness to pay, or by using a social welfare function instead of a simple sum, as more sophisticated variants of cost-benefit analysis do.<sup class=\"fn\" data-fn=\"4\"></sup> British government guidance calculates a welfare weight for a group from its median income compared with the national median, giving more value to monetisable gains for lower-income households.<sup class=\"fn\" data-fn=\"7\"></sup>"}],"wiki":"Willingness to pay"},
    "ec-041": {"questions":["A machine of tanks, levers and floating cisterns built for a doctoral thesis in 1891 to show how prices settle was a physical <span class=\"blank\">_____</span> rather than one written in equations.","Because a narrower <span class=\"blank\">_____</span> can be handled more exactly but matches real life less closely, choosing what to hold fixed and what to let vary is the central decision in building one."],"abstract":"An <b>economic model</b> is a simplified description of how some part of an economy works, built to yield conclusions about economic behaviour that can be checked against evidence.<sup class=\"fn\" data-fn=\"1\"></sup> Most models are written as sets of equations or drawn as graphs, but they also come as diagrams and even machines, such as the hydraulic apparatus of tanks and levers that Irving Fisher built for his doctoral thesis in 1891 to show how prices settle.<sup class=\"fn\" data-fn=\"2\"></sup> A model keeps the features that matter for the question being asked and leaves out the rest, which is why its lack of realism is usually described as a feature rather than a fault.<sup class=\"fn\" data-fn=\"2\"></sup> Textbooks distinguish a theory, the more abstract representation, from a model, the more applied one, although in practice the two words are used almost interchangeably.<sup class=\"fn\" data-fn=\"3\"></sup> A century ago economists spoke mainly of principles, laws and theories, whereas today the model has become the standard intellectual tool of the discipline.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Building a model means choosing what to hold fixed and what to let vary, and a narrower model can be handled more exactly but corresponds less closely to real life.<sup class=\"fn\" data-fn=\"7\"></sup> The method is old, since political economy was described in the 19th century as reasoning from an arbitrary definition of man, just as geometry reasons from an arbitrary definition of a line.<sup class=\"fn\" data-fn=\"8\"></sup> Modern theorists go further by stating every assumption explicitly, so that conclusions follow by mathematical reasoning and a reader can judge how far they apply to a particular case.<sup class=\"fn\" data-fn=\"6\"></sup> Philosophers note that such models often distort their targets on purpose, assuming omniscient agents or markets in perfect equilibrium, in order to make a complicated system tractable.<sup class=\"fn\" data-fn=\"5\"></sup> Whether a model built on false assumptions can still explain anything remains debated, and its predictions are always limited by the randomness of the data and the validity of the theory behind it.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>","sources":["Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","CORE Team, <i>The Economy 1.0</i>, “Unit 2: Technology, Population, and Growth,” §2.2–2.3, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/02.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), §1.3, “How Economists Use Theories and Models to Understand Economic Issues,” https://openstax.org/books/principles-economics-3e/pages/1-3-how-economists-use-theories-and-models-to-understand-economic-issues. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Roman Frigg and Stephan Hartmann, “Models in Science,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2006, substantive revision 2025, https://plato.stanford.edu/entries/models-science/. [Open access]","Gerard Debreu, “Economic Theory in the Mathematical Mode,” Nobel Memorial Lecture, 8 December 1983, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/debreu-lecture.pdf. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, chap. 5, §2, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=33. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP.html?chapter_num=6. [Open access]"],"why":[{"q":"Why is leaving out detail called a feature of a model rather than a fault?","a":"Because a model is built to answer a particular question, so it keeps the features that matter for that question and ignores unimportant details.<sup class=\"fn\" data-fn=\"2\"></sup> A model that tried to describe every detail of millions of decisions would be impossible to use, and seeing more by looking at less is the point of building one.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does stating every assumption explicitly help someone using a model?","a":"Because once the assumptions are fully explicit, the conclusions follow from them by mathematical reasoning, and a reader can judge more soundly how far the model applies to a particular situation.<sup class=\"fn\" data-fn=\"6\"></sup> It also lets the same structure answer new questions when its basic concepts are given a new interpretation.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why can a carefully built model still make wrong predictions?","a":"Because every model is a subjective approximation of reality, so its predictions are limited both by the randomness of the data it tries to explain and by the validity of the theory used to derive its equations.<sup class=\"fn\" data-fn=\"1\"></sup> The failure of existing models to predict the global financial crisis is one example that is still debated.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Economic model"},
    "ec-042": {"questions":["Sustained growth in labour productivity alongside a stable return on capital was listed in 1961 as a <span class=\"blank\">_____</span> about growth, and later moved from research papers into textbooks.","A model of share-price movements is expected to reproduce each <span class=\"blank\">_____</span> about returns, such as heavy tails in their distribution, before it is trusted to represent a market."],"abstract":"A <b>stylised fact</b> is a broad empirical regularity that holds roughly across many times, places or markets, stated simply enough for a model to be asked to explain it.<sup class=\"fn\" data-fn=\"1\"></sup> The term covers patterns such as the way the annual output of advanced economies oscillates around an upward trend, or the stubborn unpredictability of share prices.<sup class=\"fn\" data-fn=\"1\"></sup> Because the economy is so complex, each such regularity is treated as a pleasant surprise that invites a formal explanation of the process generating it.<sup class=\"fn\" data-fn=\"1\"></sup> In finance, one widely used list sets out properties of price changes common to many markets and instruments, including how heavy the tails of their distribution are and how returns depend on one another over time.<sup class=\"fn\" data-fn=\"5\"></sup> These properties are treated as constraints that a model of returns should reproduce, and a recent test on intraday data for 30 large American stocks found support for eight of the original 11.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Stylised facts tell a modeller what a model is for, because a model is judged partly by whether it can reproduce the regularities it was built to explain.<sup class=\"fn\" data-fn=\"1\"></sup> In 1961 six such facts about growth were stated, among them that labour productivity and capital per worker had grown at sustained rates while the return on capital and the ratio of capital to output had stayed stable.<sup class=\"fn\" data-fn=\"2\"></sup> They were used both to summarise what national income accounts showed and to shape the growth models built to explain them, and the first five later passed from research papers into textbooks.<sup class=\"fn\" data-fn=\"2\"></sup> A stylised fact remains an empirical claim, and a re-examination of postwar American and British data found that the list broadly held but that several items had drifted, including a fall in the American labour share since 1990.<sup class=\"fn\" data-fn=\"3\"></sup> Even that drift depends on measurement, since a working paper correcting for the period chosen, self-employment and housing income found no general decline in the labour share across a sample of advanced economies.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","Charles I. Jones and Paul M. Romer, “The New Kaldor Facts: Ideas, Institutions, Population, and Human Capital,” NBER Working Paper 15094 (2009), published in <i>American Economic Journal: Macroeconomics</i> 2, no. 1 (2010): 224–45, https://www.nber.org/papers/w15094. [Open access]","Berthold Herrendorf, Richard Rogerson and Akos Valentinyi, “Growth and the Kaldor Facts,” <i>Federal Reserve Bank of St. Louis Review</i> 101, no. 4 (2019): 259–76, https://doi.org/10.20955/r.101.259-76. [Open access]","Gilbert Cette, Lorraine Koehl and Thomas Philippon, “Labor Shares in Some Advanced Economies,” NBER Working Paper 26136 (2019), https://www.nber.org/papers/w26136. [Open access]","Rama Cont, “Empirical Properties of Asset Returns: Stylized Facts and Statistical Issues,” <i>Quantitative Finance</i> 1, no. 2 (2001): 223–36, abstract at IDEAS/RePEc, https://ideas.repec.org/a/taf/quantf/v1y2001i2p223-236.html. [Paywalled]","Ethan Ratliff-Crain, Colin M. Van Oort, James Bagrow, Matthew T. K. Koehler and Brian F. Tivnan, “Revisiting Cont's Stylized Facts for Modern Stock Markets,” arXiv preprint 2311.07738, version 2 (2024), https://arxiv.org/abs/2311.07738. [Open access]"],"why":[{"q":"Why is a stylised fact treated as a test for a model?","a":"Because a good model must yield precise and verifiable implications, and formal evaluation includes assessing whether it can reproduce the stylised facts it was meant to explain.<sup class=\"fn\" data-fn=\"1\"></sup> In finance the regularities of price changes are used in exactly this way, as constraints that any model of returns should be able to reproduce.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why did the growth facts of 1961 stop being argued over?","a":"Because, on one account, the first five moved from research papers into textbooks once the neoclassical growth model showed which features a model needs in order to explain them.<sup class=\"fn\" data-fn=\"2\"></sup> Researchers then turned to the sixth fact, the wide variation in growth rates between countries, and to newer regularities.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why can a stylised fact itself be disputed?","a":"Because it is still an empirical claim that depends on data and measurement. A re-examination found that several of the original growth facts had drifted, including the American labour share since 1990.<sup class=\"fn\" data-fn=\"3\"></sup> Yet a working paper that corrected for the period chosen, self-employment and housing income found no general decline in the labour share across advanced economies.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Stylized fact"},
    "ec-043": {"questions":["Coined in a German economics book of 1908, the term <span class=\"blank\">_____</span> names the demand that every social phenomenon be explained through the actions of individuals and what motivates them.","Critics of the representative agent argue that <span class=\"blank\">_____</span> has never actually been carried out with individuals alone, since relations between people keep entering the explanation."],"abstract":"<b>Methodological individualism</b> is the principle that social phenomena must be explained by showing how they result from the actions of individuals, which are in turn explained by the beliefs and aims that motivate them.<sup class=\"fn\" data-fn=\"1\"></sup> It is sometimes put as the demand that explanations of large-scale, or macro, phenomena be given micro foundations that specify the mechanism of individual action behind them.<sup class=\"fn\" data-fn=\"1\"></sup> The term was coined by an economist, since a German book of 1908 has a chapter with that title and its author introduced the phrase into English in a journal article of 1909.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Insofar as economists state their philosophical assumptions at all, a claim to follow methodological individualism is the most common, although the term is rarely defined precisely.<sup class=\"fn\" data-fn=\"2\"></sup> The discipline that satisfies it most clearly is microeconomics, and the self-interested, calculating agent of economic theory is the most fully worked-out model of rational action built on it.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The assumption shapes how economics explains markets, since economic regularities are traced to the choices of individuals facing social and natural constraints and to the unintended consequences of those choices.<sup class=\"fn\" data-fn=\"3\"></sup> In the pure model of a market economy each individual is the source both of tastes and of information, and prices are what coordinate their separate plans.<sup class=\"fn\" data-fn=\"5\"></sup> Macroeconomics often meets the principle through a representative agent, a single utility-maximising individual whose choices stand in for those of a whole sector, and critics argue that this shortcut is unjustified and frequently misleading.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Critics of general equilibrium theory likewise trace some of its failures to the difficulty of aggregating the behaviour of many different individuals into market totals.<sup class=\"fn\" data-fn=\"6\"></sup> A further objection is that explanations in terms of individuals alone have never actually been achieved, and that the workable version brings relations between individuals, and so social structure, into the explanation.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Joseph Heath, “Methodological Individualism,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2005, substantive revision 2024, https://plato.stanford.edu/entries/methodological-individualism/. [Open access]","Geoffrey M. Hodgson, “Meanings of Methodological Individualism,” <i>Journal of Economic Methodology</i> 14, no. 2 (2007): 211–26, https://uhra.herts.ac.uk/id/eprint/77/1/900694.pdf. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Alan P. Kirman, “Whom or What Does the Representative Individual Represent?,” <i>Journal of Economic Perspectives</i> 6, no. 2 (1992): 117–36, https://www.aeaweb.org/articles?id=10.1257/jep.6.2.117. [Open access]","Kenneth J. Arrow, “General Economic Equilibrium: Purpose, Analytic Techniques, Collective Choice,” Nobel Memorial Lecture, 12 December 1972, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/arrow-lecture.pdf. [Open access]","Frank Ackerman, “Still Dead After All These Years: Interpreting the Failure of General Equilibrium Theory,” Global Development and Environment Institute Working Paper 00-01, Tufts University, 1999, published in <i>Journal of Economic Methodology</i> 9, no. 2 (2002): 119–39, https://ageconsearch.umn.edu/record/15587/files/wp000001.pdf. [Open access]"],"why":[{"q":"Why is microeconomics said to satisfy this principle most clearly?","a":"Because it explains outcomes from the choices of individual agents, and its self-interested, calculating agent is the most clearly articulated model of rational action.<sup class=\"fn\" data-fn=\"1\"></sup> Its regularities are traced to the choices of individuals facing constraints and to the unintended consequences of those choices.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do critics object to the representative agent?","a":"Because reducing a group of different agents to one standard utility-maximising individual is, they argue, not simply an analytical convenience but unjustified.<sup class=\"fn\" data-fn=\"4\"></sup> It leads to conclusions that are usually misleading and often wrong, especially about problems such as unemployment, which are better seen as failures of coordination between many agents.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is the term said to be ambiguous?","a":"Because it is rarely defined precisely and wavers between explanations in terms of individuals alone and explanations in terms of individuals plus the relations between them.<sup class=\"fn\" data-fn=\"2\"></sup> The first has never been achieved, and the second, more workable version brings social structure into the explanation alongside individuals.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Methodological individualism"},
    "ec-044": {"questions":["A textbook first published in 1890 pictured disturbing causes shut for a time in a pound called <span class=\"blank\">_____</span>, so that one group of economic tendencies could be studied on its own.","Because it is often unclear exactly what is being held constant, the clause <span class=\"blank\">_____</span> has been said to have a history of studied ambiguity despite its everyday use."],"abstract":"<b>Ceteris paribus</b> is a Latin phrase meaning ‘other things being equal’, and in economics it marks an analysis that holds constant every influence except the ones being studied.<sup class=\"fn\" data-fn=\"2\"></sup> A demand curve or a supply curve relates only two variables, price and quantity, and it is drawn on the assumption that no other relevant factor, such as income, changes.<sup class=\"fn\" data-fn=\"1\"></sup> When several things change at once, economists analyse the effect of each factor separately with the others held equal and then combine the results.<sup class=\"fn\" data-fn=\"1\"></sup> Used well, such assumptions clarify a picture without distorting its key facts, by setting aside what matters less to the question in hand.<sup class=\"fn\" data-fn=\"2\"></sup> Without the qualification the laws of supply and demand would not necessarily hold, because in the real world demand and supply depend on far more than price.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> A leading textbook first published in 1890 pictured disturbing causes being shut for a time in a pound called ceteris paribus, so that one group of tendencies could be studied alone.<sup class=\"fn\" data-fn=\"3\"></sup> The narrower the issue is made, it added, the more exactly it can be handled but the less closely it corresponds to real life, and with each step more things are let out of the pound.<sup class=\"fn\" data-fn=\"3\"></sup> An earlier account had already held that economic laws are true only in the absence of disturbing causes, much as a theory of the tides holds despite the many minor forces acting on the sea.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Philosophers ask what such a qualified law actually claims, since laws in the special sciences, economics among them, seem to have exceptions, and whether they have any testable content at all.<sup class=\"fn\" data-fn=\"5\"></sup> The clause can also hide weak reasoning, and one survey of its history warns that it is often unclear what is being held constant and by what authority, calling that history one of studied ambiguity.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), §3.2, “Shifts in Demand and Supply for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-2-shifts-in-demand-and-supply-for-goods-and-services. [Open access]","CORE Team, <i>The Economy 1.0</i>, “Unit 2: Technology, Population, and Growth,” §2.2–2.3, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/02.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, chap. 5, §2, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=33. [Open access]","Joseph Persky, “Retrospectives: Ceteris Paribus,” <i>Journal of Economic Perspectives</i> 4, no. 2 (1990): 187–93, https://www.aeaweb.org/articles?id=10.1257/jep.4.2.187. [Open access]","Alexander Reutlinger, Gerhard Schurz, Andreas Hüttemann and Siegfried Jaag, “Ceteris Paribus Laws,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2011, substantive revision 2024, https://plato.stanford.edu/entries/ceteris-paribus/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP.html?chapter_num=6. [Open access]"],"why":[{"q":"Why does a demand curve need the assumption at all?","a":"Because the curve shows a relationship between only two variables, price and quantity, while real demand also depends on income and many other factors.<sup class=\"fn\" data-fn=\"1\"></sup> Holding those constant is what lets the curve show the effect of price alone, and the effects of the other factors can be analysed separately and then combined.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does narrowing a question carry a cost?","a":"Because the more an issue is narrowed, the more exactly it can be handled but the less closely it corresponds to real life.<sup class=\"fn\" data-fn=\"3\"></sup> The narrow results are meant to be widened step by step, letting more causes out of the pound, so that exact discussions become less abstract.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do philosophers find the clause puzzling?","a":"Because laws in the special sciences such as economics seem to have exceptions, so it is unclear what a generalisation that holds only when other things are equal actually claims, or whether it can be tested.<sup class=\"fn\" data-fn=\"5\"></sup> Economists themselves have warned that it is often unclear what is being held constant.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Ceteris paribus"},
    "ec-045": {"questions":["The 1953 collection <span class=\"blank\">_____</span> opened by separating knowledge of what is from discussion of what ought to be, then applied that outlook to demand curves and exchange rates.","Whether firms truly try to maximise profits does not matter, argued the essay that opens <span class=\"blank\">_____</span>, so long as theories built on that assumption predict market prices and quantities well."],"abstract":"<b>Essays in Positive Economics</b> is a collection published by the University of Chicago Press whose opening essay of 1953, 'The Methodology of Positive Economics', became the most cited, most influential and most controversial piece of writing on method in 20th-century economics.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Its author, Milton Friedman, began by separating a positive science, a body of knowledge about what is, from a normative one, which discusses what ought to be.<sup class=\"fn\" data-fn=\"2\"></sup> He held that confusion between the two was a real hindrance, and he conjectured that policy disputes are mostly disputes about the consequences of alternatives, which progress in positive economics could settle.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The rest of the book applies that outlook to price theory and monetary policy, with essays on the demand curve, the effects of taxes and the case for flexible exchange rates.<sup class=\"fn\" data-fn=\"4\"></sup> It helped shape many economists' ideas of how to do good economics, and its popular legacy survives in textbook chapters explaining why the assumptions of models need not be realistic, while its critics call its view of science deeply flawed.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Its central and most controversial claim is about simplification: the realism of a theory's assumptions, it argued, is irrelevant, and a theory is to be judged only by the accuracy of its predictions.<sup class=\"fn\" data-fn=\"1\"></sup> On this view it does not matter whether firms really try to maximise profits, so long as a theory built on that assumption predicts prices and quantities in markets well.<sup class=\"fn\" data-fn=\"1\"></sup> Complete realism was declared unattainable, and whether a theory is realistic enough was to be settled only by whether its predictions are good enough for the purpose in hand.<sup class=\"fn\" data-fn=\"5\"></sup> Critics replied that the essay uses 'assumption' and 'unrealistic' in several different senses, and one argued that a simple law is useful only under conditions that have nothing to do with how unrealistic it is.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Philosophers of science now discuss the same question as idealisation, the deliberate distortion of a system, such as assuming that agents are omniscient, to make it tractable.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Milton Friedman, “The Methodology of Positive Economics (1953),” in <i>The Methodology of Positive Economics: Reflections on the Milton Friedman Legacy</i>, ed. Uskali Mäki (Cambridge: Cambridge University Press, 2009), 3–44, https://www.cambridge.org/core/books/abs/methodology-of-positive-economics/methodology-of-positive-economics-1953/CFF7143A05C9A667D3E54E9AD747A98A. [Paywalled]","Uskali Mäki, “Reading the Methodological Essay in Twentieth-Century Economics: Map of Multiple Perspectives,” author's preprint of a chapter in <i>The Methodology of Positive Economics: Reflections on the Milton Friedman Legacy</i>, ed. Uskali Mäki (Cambridge: Cambridge University Press, 2009), University of Helsinki, https://tint.helsinki.fi/maki/materials/maki,%20readingF53.pdf. [Open access]","Milton Friedman, <i>Essays in Positive Economics</i> (Chicago: University of Chicago Press, 1953; paperback 1966), publisher's page with table of contents, https://press.uchicago.edu/ucp/books/book/chicago/E/bo25773835.html.","Herbert A. Simon, “Rational Decision-Making in Business Organizations,” Nobel Memorial Lecture, 8 December 1978, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/simon-lecture.pdf. [Open access]","Roman Frigg and Stephan Hartmann, “Models in Science,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2006, substantive revision 2025, https://plato.stanford.edu/entries/models-science/. [Open access]"],"why":[{"q":"Why did the essay begin by separating positive from normative economics?","a":"Because it held that confusion between the two hindered the recognition that economics can be a positive science.<sup class=\"fn\" data-fn=\"2\"></sup> It also conjectured that most policy disputes are really about the consequences of alternatives, which progress in positive economics could in principle resolve.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did critics say the argument against realistic assumptions proves too much?","a":"Because it lets economists ignore any evidence that does not concern market prices and quantities, such as surveys of managers, so that fundamental theory is almost never exposed to disconfirming evidence.<sup class=\"fn\" data-fn=\"1\"></sup> A method that looks eclectic and pragmatic was in this way used in the service of a rigid theoretical orthodoxy.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does a falling-body law that ignores air resistance not prove the essay's point?","a":"Because, as one critic replied, the conditions under which such a simple law gives a good enough approximation are not at all the conditions under which it is unrealistic.<sup class=\"fn\" data-fn=\"5\"></sup> Using a simplification where it happens to work is different from praising lack of realism as such.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Essays in Positive Economics"},
    "ec-046": {"questions":["Experiments in which people share real money find altruism, reciprocity and a dislike of inequality, so that the purely selfish <span class=\"blank\">_____</span> of the textbooks is often in the minority.","A prediction made in 2000 held that <span class=\"blank\">_____</span> would lose some of his calculating power and learn more slowly as economics paid closer attention to human cognition and emotion."],"abstract":"<b>Homo economicus</b>, Latin for ‘economic man’, is the nickname given to the selfish and calculating character who appears in economics textbooks.<sup class=\"fn\" data-fn=\"1\"></sup> In its classic form he is concerned only with acquiring wealth and with judging which means will best obtain it, while every other human motive is set aside.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> The figure was built as a deliberate abstraction, and its 19th-century formulation stressed that no economist ever supposed that people really are constituted that way.<sup class=\"fn\" data-fn=\"2\"></sup> Early critics nonetheless attacked the construct as a monomaniac concerned only with money, although its original psychology also included desires for leisure and luxury.<sup class=\"fn\" data-fn=\"3\"></sup> The figure fits the principle of explaining social outcomes through individual choices so well that it is often called the most clearly worked-out model of rational action.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Whether real people resemble the model has been argued over for centuries, and since the 1990s economists have run hundreds of experiments in which people make real choices about sharing money.<sup class=\"fn\" data-fn=\"1\"></sup> Those experiments almost always find some self-interested behaviour but also altruism, reciprocity and a dislike of unequal outcomes, so that in many of them the purely selfish player is in the minority.<sup class=\"fn\" data-fn=\"1\"></sup> One response keeps the method while dropping the selfishness, assuming only that people maximise their welfare as they conceive it, whether they are selfish, altruistic, loyal or spiteful.<sup class=\"fn\" data-fn=\"5\"></sup> Another, from behavioural economics, predicted in 2000 that the model would come to look more like real human beings, with less calculating power, slower learning and more room for emotion.<sup class=\"fn\" data-fn=\"4\"></sup> Many economists now treat self-interest as a good assumption for settings such as shopping but a poor one for others, such as paying taxes or working hard for an employer.<sup class=\"fn\" data-fn=\"1\"></sup>","sources":["CORE Team, <i>The Economy 1.0</i>, “Unit 4: Social Interactions,” §4.2, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/04.html. [Open access]","John Stuart Mill, “On the Definition of Political Economy; and on the Method of Investigation Proper to It,” in <i>Essays on Some Unsettled Questions of Political Economy</i>, 2nd ed. (London: Longmans, Green, Reader, and Dyer, 1874), essay 5, Library of Economics and Liberty, https://www.econlib.org/library/Mill/mlUQP.html?chapter_num=6. [Open access]","Joseph Persky, “The Ethology of Homo Economicus,” <i>Journal of Economic Perspectives</i> 9, no. 2 (1995): 221–31, https://www.aeaweb.org/articles?id=10.1257/jep.9.2.221. [Open access]","Richard H. Thaler, “From Homo Economicus to Homo Sapiens,” <i>Journal of Economic Perspectives</i> 14, no. 1 (2000): 133–41, https://www.aeaweb.org/articles?id=10.1257/jep.14.1.133. [Open access]","Gary S. Becker, “The Economic Way of Looking at Life,” Nobel Lecture, 9 December 1992, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/becker-lecture.pdf. [Open access]","Joseph Heath, “Methodological Individualism,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2005, substantive revision 2024, https://plato.stanford.edu/entries/methodological-individualism/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]"],"why":[{"q":"Why did economists build a figure they knew to be unrealistic?","a":"Because the method of political economy reasoned from a simplified premise, considering people solely as beings who desire wealth, much as geometry starts from an arbitrary definition of a line.<sup class=\"fn\" data-fn=\"2\"></sup> Its classic statement insisted that no economist was ever so absurd as to suppose people really are like that.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the selfish figure often in the minority in experiments?","a":"Because when people make real choices about sharing money, they show altruism, reciprocity and aversion to inequality alongside self-interest.<sup class=\"fn\" data-fn=\"1\"></sup> This holds even when the amounts being shared are worth many days' wages, which makes it hard to dismiss the generosity as cheap.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why can the economic approach survive without assuming selfishness?","a":"Because it can assume only that people maximise welfare as they themselves conceive it, whether they are selfish, altruistic, loyal, spiteful or masochistic.<sup class=\"fn\" data-fn=\"5\"></sup> On that view self-interest is one possible content of a person's preferences rather than part of the method itself.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Homo economicus"},
    "ec-047": {"questions":["Someone whose circular preferences let them be drained of money through repeated swaps fails the consistency demanded by <span class=\"blank\">_____</span>, which treats such a pattern as a mark of irrationality.","Applied far beyond markets to crime, discrimination and the family, <span class=\"blank\">_____</span> assumes that each person maximises welfare as they conceive it within limits of income and time."],"abstract":"<b>Rational choice theory</b> is the framework in which an agent is modelled as having consistent preferences over the options available and choosing whichever feasible option it most prefers.<sup class=\"fn\" data-fn=\"1\"></sup> Preferences count as consistent when they are complete, so that any two options can be ranked, and transitive, so that preferring one thing to a second and the second to a third means preferring the first to the third.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Preferences of this kind, together with a technical condition of continuity, can be represented by a utility function, a number that merely records the agent's ranking.<sup class=\"fn\" data-fn=\"1\"></sup> The theory permeates modern economics and other formalised social sciences, and textbook models of the consumer apply it by having people choose the combination of goods that maximises their utility.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Economic models built on it assume that agents maximise specific objectives subject to well-defined constraints, such as a budget.<sup class=\"fn\" data-fn=\"6\"></sup> <br><br> Rationality in this sense is a minimal standard about how preferences and choices cohere, and it sets aside questions about whether a person's desires are appropriate or beliefs reasonable.<sup class=\"fn\" data-fn=\"3\"></sup> Its defenders point to the money pump, which shows that someone with circular preferences who will pay a little for each preferred swap can be drained of money indefinitely.<sup class=\"fn\" data-fn=\"3\"></sup> Its reach has been extended far beyond markets, to crime, discrimination and the family, on the assumption that people maximise welfare as they conceive it.<sup class=\"fn\" data-fn=\"4\"></sup> Critics reply that there is considerable experimental evidence that people's preferences are not in fact transitive, which may show either that the standard is too demanding or that people are sometimes irrational.<sup class=\"fn\" data-fn=\"1\"></sup> A rival tradition argues that real decision-makers, with limited information and computing power, look for options that are good enough, and that theories of this bounded kind fit the evidence at least as well.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Sven Ove Hansson and Till Grüne-Yanoff, “Preferences,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2006, substantive revision 2022, https://plato.stanford.edu/entries/preferences/. [Open access]","Katie Steele and H. Orri Stefánsson, “Decision Theory,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2015, substantive revision 2025, https://plato.stanford.edu/entries/decision-theory/. [Open access]","Gary S. Becker, “The Economic Way of Looking at Life,” Nobel Lecture, 9 December 1992, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/becker-lecture.pdf. [Open access]","Herbert A. Simon, “Rational Decision-Making in Business Organizations,” Nobel Memorial Lecture, 8 December 1978, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/simon-lecture.pdf. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), §6.1, “Consumption Choices,” https://openstax.org/books/principles-economics-3e/pages/6-1-consumption-choices. [Open access]"],"why":[{"q":"Why does a utility function carry no information beyond a ranking?","a":"Because it merely represents the agent's preference ordering: one option gets a higher number than another exactly when it is preferred.<sup class=\"fn\" data-fn=\"1\"></sup> Any transformation of the function that preserves the order would represent the same preferences equally well, so the size of the numbers means nothing on its own.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why is transitivity defended as a requirement of rationality?","a":"Because of the money pump argument: someone with circular preferences who will pay a small amount for each preferred exchange can be led round the cycle repeatedly, ending worse off by their own lights.<sup class=\"fn\" data-fn=\"3\"></sup> Real agents, the argument runs, would refuse to trade or adjust their preferences instead.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do some economists prefer theories of bounded rationality?","a":"Because real decision-makers have limited computing power and incomplete information, so they look for satisfactory choices rather than optimal ones.<sup class=\"fn\" data-fn=\"5\"></sup> One leading critic argued that phenomena requiring utility maximisation, rather than a bounded theory, for their explanation simply had not been observed in aggregate data.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Rational choice model"},
    "ec-048": {"questions":["A passage of 1739–40 denying that it is contrary to reason to prefer the world's destruction to a scratched finger is often read as making <span class=\"blank\">_____</span> the whole of practical reason.","Because economics was defined in 1932 as entirely neutral between ends, the rationality it attributes to people is <span class=\"blank\">_____</span>, compatible with selfish, altruistic, loyal or spiteful aims alike."],"abstract":"<b>Instrumental rationality</b> is the kind of rationality a person shows insofar as she adopts suitable means to her ends, whatever those ends happen to be.<sup class=\"fn\" data-fn=\"1\"></sup> It is generally treated as an important and presumably indispensable part of practical rationality, and some have argued that it is the whole of it.<sup class=\"fn\" data-fn=\"1\"></sup> That stronger thesis is often called Humean, after a passage of 1739–40 holding that it is not contrary to reason to prefer the destruction of the world to the scratching of one's finger, though whether Hume held it is doubted.<sup class=\"fn\" data-fn=\"1\"></sup> On such a view reason can fault a choice of means that cannot reach an end, but cannot condemn the end itself unless it rests on a false belief.<sup class=\"fn\" data-fn=\"1\"></sup> Decision theory is sometimes read as containing, or simply being, a theory of instrumental rationality, saying which means to take given beliefs about how likely each is to succeed.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> <br><br> This is close to what an economist means by rational, since an agent counts as rational if their preferences are consistent and they choose the feasible option they most prefer, with nothing said about what they ought to prefer.<sup class=\"fn\" data-fn=\"2\"></sup> A definition of 1932 made economics the study of the relation between given ends and scarce means, and concluded that the subject is entirely neutral between ends.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Rational behaviour in the economist's sense can therefore be selfish, altruistic, loyal or spiteful, provided people pursue their own aims as well as they can.<sup class=\"fn\" data-fn=\"4\"></sup> In practice economists have nevertheless narrowed the content again, supposing that the motives that matter most are a desire for wealth and for larger bundles of goods and services.<sup class=\"fn\" data-fn=\"2\"></sup> One critic of the standard theory argued that because real decision-makers have limited computing power and incomplete information, the study of decisions should be concerned mainly with procedural rather than substantive rationality.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Niko Kolodny and John Brunero, “Instrumental Rationality,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2013, substantive revision 2023, https://plato.stanford.edu/entries/rationality-instrumental/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i>, 2nd ed. (London: Macmillan, 1935), chap. 2, “Ends and Means,” Mises Institute, https://mises.org/online-book/essay-nature-and-significance-economic-science/ii-ends-and-means. [Open access]","Gary S. Becker, “The Economic Way of Looking at Life,” Nobel Lecture, 9 December 1992, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/becker-lecture.pdf. [Open access]","Herbert A. Simon, “Rational Decision-Making in Business Organizations,” Nobel Memorial Lecture, 8 December 1978, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/simon-lecture.pdf. [Open access]","Katie Steele and H. Orri Stefánsson, “Decision Theory,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2015, substantive revision 2025, https://plato.stanford.edu/entries/decision-theory/. [Open access]"],"why":[{"q":"Why does the economist's rationality say nothing about what people want?","a":"Because economics was defined as the study of the relation between given ends and scarce means, which makes it entirely neutral between ends.<sup class=\"fn\" data-fn=\"3\"></sup> Rationality then means only having consistent preferences and choosing the most preferred feasible option, whatever those preferences are.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why can a spiteful person count as rational in this sense?","a":"Because the economic approach assumes only that people maximise welfare as they conceive it, whether they are selfish, altruistic, loyal, spiteful or masochistic.<sup class=\"fn\" data-fn=\"4\"></sup> The aims are taken as given, and what is assessed is how well and how consistently they are pursued.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the Humean thesis thought to threaten the authority of morality?","a":"Because if instrumental rationality were the whole of practical rationality, then on an occasion when acting morally was not a suitable means to a person's ends, it would not be irrational for her to refuse to act morally.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Instrumental and value rationality"},
    "ec-049": {"questions":["Because a displaced level of output is pushed back towards it, as gravity pulls back a stone on a string, a stable <span class=\"blank\">_____</span> was pictured as self-correcting in a classic textbook.","Explaining why millions of separate buying and selling decisions usually fit together, the idea of an <span class=\"blank\">_____</span> rests on everyone facing the same prices, which move whenever supply and demand differ."],"abstract":"An <b>economic equilibrium</b> is a situation in a model that perpetuates itself, so that the thing of interest does not change unless some outside force alters the conditions the model describes.<sup class=\"fn\" data-fn=\"1\"></sup> It does not require that nothing changes, because output or prices rising at a constant rate can also be an equilibrium.<sup class=\"fn\" data-fn=\"1\"></sup> In a single market the equilibrium price is the only price at which the quantity buyers want equals the quantity sellers offer, and at any higher price there is excess supply.<sup class=\"fn\" data-fn=\"3\"></sup> In the standard model of supply and demand, demand falls and supply rises with price, giving a system that moves towards the market-clearing price without anyone intervening.<sup class=\"fn\" data-fn=\"4\"></sup> When demand and supply are in stable equilibrium, a classic textbook explained, any accident that moves output away from it brings forces into play that push it back, as gravity pulls back a displaced stone hanging on a string.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The concept answers an old puzzle, which is why millions of separate decisions about buying and selling usually fit together so well that buyers can count on buying and sellers on selling.<sup class=\"fn\" data-fn=\"5\"></sup> Since the 1870s the answer has been that all agents face the same set of prices, that some price changes wherever supply and demand are unequal, and that none changes once they match.<sup class=\"fn\" data-fn=\"5\"></sup> In the economy-wide version, firms maximise profit and consumers satisfy their preferences, and the outcome is an equilibrium with no excess demand in any market.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Showing that such a balance can exist is not showing that a real economy reaches it, and critics point out that equilibrium in these models need be neither unique nor stable.<sup class=\"fn\" data-fn=\"8\"></sup> Economists also stress that the balance of supply and demand is far from perfect, as long spells of unemployed labour and idle equipment, notably in the 1930s, have shown.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["CORE Team, <i>The Economy 1.0</i>, “Unit 2: Technology, Population, and Growth,” §2.2–2.3, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/02.html. [Open access]","CORE Team, <i>The Economy 1.0</i>, “Unit 8: Supply and Demand: Price-Taking and Competitive Markets,” §8.8, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/08.html. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i> (Houston: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","Sam Ouliaris, “What Are Economic Models?,” <i>Finance & Development</i> 48, no. 2 (June 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/06/basics.htm. [Open access]","Kenneth J. Arrow, “General Economic Equilibrium: Purpose, Analytic Techniques, Collective Choice,” Nobel Memorial Lecture, 12 December 1972, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/arrow-lecture.pdf. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2003, substantive revision 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, chap. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=31. [Open access]","Frank Ackerman, “Still Dead After All These Years: Interpreting the Failure of General Equilibrium Theory,” Global Development and Environment Institute Working Paper 00-01, Tufts University, 1999, published in <i>Journal of Economic Methodology</i> 9, no. 2 (2002): 119–39, https://ageconsearch.umn.edu/record/15587/files/wp000001.pdf. [Open access]"],"why":[{"q":"Why can a growing economy still be in equilibrium?","a":"Because equilibrium means that one or more things in the model are constant, not that nothing at all changes.<sup class=\"fn\" data-fn=\"1\"></sup> Output or prices increasing at a constant rate can therefore be an equilibrium, so long as nothing disturbs the conditions that keep that rate steady.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does a market tend to move towards its equilibrium price?","a":"Because at a price above it the quantity supplied exceeds the quantity demanded, and at a price below it the reverse.<sup class=\"fn\" data-fn=\"3\"></sup> With demand falling and supply rising as the price rises, the system moves towards the market-clearing price without any intervention.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is proving that an equilibrium exists not the end of the matter?","a":"Because, critics point out, the equilibrium of a general equilibrium model need be neither unique nor stable, and there seem to be no grounds for dismissing such ill-behaved outcomes as special cases.<sup class=\"fn\" data-fn=\"8\"></sup> The balance of supply and demand in real economies has also been far from perfect, as the 1930s showed.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Economic equilibrium"},
    "ec-050": {"questions":["Studying one market at a time with other things held equal is partial analysis, whereas <span class=\"blank\">_____</span> treats a whole economy of interlinked markets as one system of equations.","Rigorous proofs in the 1930s and the 1950s finally showed that a <span class=\"blank\">_____</span> can exist, but critics note that it need be neither unique nor stable once it does."],"abstract":"<b>General equilibrium</b> is a state of a whole economy in which supply equals demand in every market at once, analysed with models in which all buyers and sellers take prices as given.<sup class=\"fn\" data-fn=\"3\"></sup> The word 'general' marks the claim that equilibrium cannot properly be spoken of for one commodity alone, because supply and demand in any market depend on the prices of other goods.<sup class=\"fn\" data-fn=\"1\"></sup> In such an equilibrium every producer maximises profit at the going prices, every consumer satisfies their preferences within a budget, and total demand equals total supply for each commodity.<sup class=\"fn\" data-fn=\"2\"></sup> The mathematical theory was founded in 1874–77, when economic relationships were written as a system of equations describing an entire economy of interlinked markets.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> For six decades its followers could only note that the number of equations equalled the number of unknowns, and a rigorous proof that an equilibrium exists came in 1935–36 and again in the early 1950s.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The contrast is with partial equilibrium analysis, which studies one market at a time, as most economists had done before, for instance the price of cloth on the cloth market alone.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Its leading advocate in the late 19th century defended it as breaking a complex question into pieces, studying one bit at a time with other things held equal and then combining the partial solutions.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> The general approach matters wherever a change in one market feeds back on others, and it underlies the proof of the conditions under which a competitive equilibrium is Pareto efficient.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> General equilibrium models of markets are counted among the central models of modern science, and their influence spreads in policy through computable versions and in macroeconomics through the demand for microfoundations.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Critics argue that the theory has nonetheless failed on its own terms, since its equilibrium need be neither unique nor stable, and they trace this to the difficulty of aggregating many different individuals.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Kenneth J. Arrow, “General Economic Equilibrium: Purpose, Analytic Techniques, Collective Choice,” Nobel Memorial Lecture, 12 December 1972, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/arrow-lecture.pdf. [Open access]","Gerard Debreu, “Economic Theory in the Mathematical Mode,” Nobel Memorial Lecture, 8 December 1983, Nobel Foundation, https://www.nobelprize.org/uploads/2018/06/debreu-lecture.pdf. [Open access]","CORE Team, <i>The Economy 1.0</i>, “Unit 8: Supply and Demand: Price-Taking and Competitive Markets,” §8.8, CORE Econ, https://www.core-econ.org/the-economy/v1/book/text/08.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, chap. 5, §2, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=33. [Open access]","Frank Ackerman, “Still Dead After All These Years: Interpreting the Failure of General Equilibrium Theory,” Global Development and Environment Institute Working Paper 00-01, Tufts University, 1999, published in <i>Journal of Economic Methodology</i> 9, no. 2 (2002): 119–39, https://ageconsearch.umn.edu/record/15587/files/wp000001.pdf. [Open access]","Alexander Reutlinger, Gerhard Schurz, Andreas Hüttemann and Siegfried Jaag, “Ceteris Paribus Laws,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2011, substantive revision 2024, https://plato.stanford.edu/entries/ceteris-paribus/. [Open access]","Roman Frigg and Stephan Hartmann, “Models in Science,” in <i>The Stanford Encyclopedia of Philosophy</i>, first published 2006, substantive revision 2025, https://plato.stanford.edu/entries/models-science/. [Open access]"],"why":[{"q":"Why can equilibrium not be found one commodity at a time?","a":"Because supply and demand in any one market depend on the prices of other commodities.<sup class=\"fn\" data-fn=\"1\"></sup> The overall equilibrium of an economy therefore cannot be broken down into separate equilibria for individual goods, and all prices have to be considered together.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did counting equations and unknowns not settle whether an equilibrium exists?","a":"Because matching the number of equations to the number of unknowns is an argument that cannot convince a mathematician that a solution exists.<sup class=\"fn\" data-fn=\"2\"></sup> The tools that later solved the problem, generalisations of fixed point theorems, did not exist when the theory was founded.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do critics say the theory failed on its own terms?","a":"Because the equilibrium of a general equilibrium model need be neither unique nor stable, and there seem to be no grounds for dismissing such outcomes as implausible special cases.<sup class=\"fn\" data-fn=\"5\"></sup> Critics trace the problem to the difficulty of aggregation and to the unpredictable nature of individual preferences.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"General equilibrium theory"},
    "ec-051": {"questions":["A prediction of the form 'when A increases, B falls', read off by setting two equilibria side by side, is the typical product of <span class=\"blank\">_____</span> applied to an economic model.","Because <span class=\"blank\">_____</span> sets only the starting point and the resting point of a market side by side, it is silent on how long the adjustment takes or whether it ever arrives."],"abstract":"<b>Comparative statics</b> is the method of comparing the equilibrium of an economic model before and after one of its conditions changes, and reading off which way the outcome moves.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The textbook version has four steps: draw the market before the change, decide whether the event affects demand or supply, shift the right curve, and compare the new equilibrium price and quantity with the old.<sup class=\"fn\" data-fn=\"1\"></sup> When unusually good weather enlarges a salmon catch, for example, the supply curve moves right, the equilibrium price falls and the quantity sold rises, even though the demand curve has not moved.<sup class=\"fn\" data-fn=\"1\"></sup> The typical result has the form 'when A increases, B falls', a prediction about how one variable affects another that holds within the setting the model describes.<sup class=\"fn\" data-fn=\"2\"></sup> Everything else is held fixed for the comparison, so that other disturbing causes are set aside for a time rather than denied.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> What the comparison leaves out is the journey, since it states where a market will settle but not how it gets there.<sup class=\"fn\" data-fn=\"3\"></sup> The answer is only meaningful if the new equilibrium is stable, and whether it is stable is a dynamic question that the comparison itself has to assume.<sup class=\"fn\" data-fn=\"6\"></sup> Marshall called this the statical method and treated it as a temporary aid, warning that the element of time is a chief cause of the difficulties of economic investigation.<sup class=\"fn\" data-fn=\"3\"></sup> Samuelson's Nobel lecture of 1970 shows the kind of answer it gives: raise the price of an input and a profit-maximising firm must buy less of it, a qualitative result reached without knowing any numbers.<sup class=\"fn\" data-fn=\"4\"></sup> Before the 1930s economists used causal language freely, but some already worried that comparing two equilibrium states was not quite the same thing as tracing cause and effect.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["<i>Principles of Economics 3e</i>, “3.3 Changes in Equilibrium Price and Quantity: The Four-Step Process,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/3-3-changes-in-equilibrium-price-and-quantity-the-four-step-process. [Open access]","<i>Introduction to Economic Analysis</i>, “1.3 Economic Reasoning and Analysis,” LibreTexts Social Sciences, https://socialsci.libretexts.org/Bookshelves/Economics/Applied_Economics/Introduction_to_Economic_Analysis_(LibreTexts)/01%3A_What_Is_Economics/1.03%3A_Economic_Reasoning_and_Analysis. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), book 5, chap. 5, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=33. [Open access]","Paul A. Samuelson, “Maximum Principles in Analytical Economics,” Nobel Memorial Lecture, 11 December 1970, in <i>Nobel Lectures, Economics 1969–1980</i> (Singapore: World Scientific, 1992), https://www.nobelprize.org/uploads/2018/06/samuelson-lecture.pdf. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, rev. 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Geoffrey Poitras, “Cobweb Theory, Market Stability, and Price Expectations,” <i>Journal of the History of Economic Thought</i> 45, no. 1 (2023): 137–61, https://doi.org/10.1017/S1053837222000116. [Open access]"],"why":[{"q":"Why does the method say nothing about how a market adjusts?","a":"Because it compares two resting points and leaves out the time between them.<sup class=\"fn\" data-fn=\"3\"></sup> Marshall treated this statical method as a temporary simplification,<sup class=\"fn\" data-fn=\"3\"></sup> and whether the new position is ever reached depends on dynamic stability conditions that the comparison has to take for granted.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why can a comparison give a definite answer without any numbers?","a":"Because the structure of the model fixes the direction of the response. A profit-maximising firm facing a dearer input can only answer by buying less of it,<sup class=\"fn\" data-fn=\"4\"></sup> and the textbook method asks only which curve shifts and which way before comparing the two equilibria.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does it matter what the comparison holds fixed?","a":"Because the answer changes with it. A firm free to adjust its other inputs responds more elastically to a price rise than one whose other inputs are fixed,<sup class=\"fn\" data-fn=\"4\"></sup> and every such prediction holds only in the setting the model describes.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Comparative statics"},
    "ec-052": {"questions":["Swings in farm prices lasting twice the production lag, damped or explosive according to the elasticities of supply and demand, are what the <span class=\"blank\">_____</span> was first built to explain in 1930.","Following price from one period to the next instead of only finding where supply and demand cross, the <span class=\"blank\">_____</span> is the textbook example of a dynamic rather than a static market model."],"abstract":"The <b>cobweb model</b> is a dynamic model of a market in which producers decide how much to supply from the price they have just seen, so that output answers to last period's price while the price clears this period's demand.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It was built for farm products, where the delay between deciding to produce and bringing goods to market can be one season for corn, a few seasons for livestock and some years for fruit trees.<sup class=\"fn\" data-fn=\"2\"></sup> A large harvest drives the price down, the low price persuades farmers to produce less, the small crop that follows drives the price up, and the path traced on a supply-and-demand diagram looks like a cobweb.<sup class=\"fn\" data-fn=\"2\"></sup> Such cycles last twice the production lag, and their swings shrink, persist or grow according to the relative elasticities of supply and demand.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The first formal treatments appeared in 1930, in independent work published in German that built on the finding that German hog production followed past hog prices.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The model is the standard illustration of a dynamic model, one that follows the movement of prices and quantities over time instead of seeking a single static equilibrium.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Static theory of the 1920s and 1930s assumed that a disturbed market would gravitate back to equilibrium, so lasting fluctuations had to be blamed on outside shocks, and the cobweb showed that a lag alone could keep a market from settling.<sup class=\"fn\" data-fn=\"2\"></sup> In a dynamic system the same equilibrium may be stable or unstable, depending on whether its movements are damped and die away or are explosive.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Its weak point is the assumption that producers expect the latest price to last, so that they are wrong in the same predictable way year after year.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Later versions let expectations adapt to past errors or be rational, which tames or removes the cycle, and work on the British pig market in the 1930s found a cycle of about four years where the simple model predicted two.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>","sources":["Geoffrey Poitras, “Cobweb Theory, Market Stability, and Price Expectations,” <i>Journal of the History of Economic Thought</i> 45, no. 1 (2023): 137–61, https://doi.org/10.1017/S1053837222000116. [Open access]","Daniele Besomi, “Cobweb Cycles,” in <i>International Encyclopedia of the Social Sciences</i>, 2nd ed., Encyclopedia.com, https://www.encyclopedia.com/social-sciences/applied-and-social-sciences-magazines/cobweb-cycles. [Open access]","Matthias Ruth, L. Martin Cloutier and Philip Garcia, “A Nonlinear Model of Information and Coordination in Hog Production: Testing the Coasian-Fowlerian Dynamic Hypotheses,” paper presented at the annual meeting of the American Agricultural Economics Association, 1998, AgEcon Search, https://ageconsearch.umn.edu/record/20971/files/spruth01.pdf. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), preface to the eighth edition, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=1. [Open access]","Paul A. Samuelson, “Maximum Principles in Analytical Economics,” Nobel Memorial Lecture, 11 December 1970, in <i>Nobel Lectures, Economics 1969–1980</i> (Singapore: World Scientific, 1992), https://www.nobelprize.org/uploads/2018/06/samuelson-lecture.pdf. [Open access]","Robert W. Dimand, “Macroeconomic Dynamics at the Cowles Commission from the 1930s to the 1950s,” Cowles Foundation Discussion Paper 2195 (New Haven: Yale University, 2019), https://cowles.yale.edu/sites/default/files/2022-08/d2195.pdf. [Open access]"],"why":[{"q":"Why can a market described by the model fail to settle?","a":"Because output answers to last period's price while the price clears this period's demand, so a glut is followed by a shortage and a shortage by a glut.<sup class=\"fn\" data-fn=\"1\"></sup> Whether the swings shrink or grow depends on the relative elasticities of supply and demand.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did the model matter to economists of the 1930s?","a":"Because static theory said a disturbed market would gravitate back to equilibrium, leaving lasting fluctuations to be explained by shocks from outside. The cobweb showed that a production lag on its own could keep prices cycling.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is its assumption about farmers' expectations criticised?","a":"Because it has producers expect the latest price to last, so they repeat the same mistake every period.<sup class=\"fn\" data-fn=\"2\"></sup> Versions with adaptive or rational expectations tame or remove the cycle,<sup class=\"fn\" data-fn=\"1\"></sup> and a study of British pigs found a four-year cycle where the simple model predicted two.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Cobweb model"},
    "ec-053": {"questions":["Defining capital as wealth existing at an instant and income as services received over a period, a book of 1906 drew the line between <span class=\"blank\">_____</span> that national accounts still follow.","Whether a figure is measured at a moment, like wealth or the number of people out of work, or per period, like income, is the difference between <span class=\"blank\">_____</span> in economic statistics."],"abstract":"<b>Stock and flow</b> are the two kinds of quantity in economics: a stock is measured at a point in time, while a flow is measured per period of time.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Wealth is a stock and income a flow, which is why a bathtub is the usual picture, with the water in the tub as the stock, the tap as the inflow and the drain as the outflow.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A stock changes only through flows, rising when inflows exceed outflows and falling when they fall short.<sup class=\"fn\" data-fn=\"4\"></sup> National accounts are built on the same rule, recording stocks in balance sheets at the start and end of a period and requiring every change in value between them to be captured as a flow.<sup class=\"fn\" data-fn=\"2\"></sup> The distinction was set out in 1906 by Fisher, who defined capital as a stock of wealth existing at an instant and income as a flow of services through a period of time.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Confusing the two is a common error, and the clearest case in public finance is the difference between a government's deficit and its debt.<sup class=\"fn\" data-fn=\"5\"></sup> The deficit is how much the government borrows in one year, a flow, while the debt is the sum of all past deficits and surpluses, a stock.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A large stock can feed its own inflow, since interest on the debt is part of government spending, so a long run of deficits makes the debt harder to stop growing.<sup class=\"fn\" data-fn=\"4\"></sup> Unemployment works the same way, because the number of people out of work at any moment is a stock that is fed by people losing jobs and drained by people finding them.<sup class=\"fn\" data-fn=\"4\"></sup> The logic is harder than it looks: students at an elite business school, given simple accumulation tasks, showed a poor grasp of how stocks and flows are related.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Irving Fisher, <i>The Nature of Capital and Income</i> (New York: Macmillan, 1906), 51–59, https://archive.org/details/natureofcapitali00fishuoft. [Open access]","European Commission, International Monetary Fund, Organisation for Economic Co-operation and Development, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), 39, paras. 3.4–3.10, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","The CORE Team, <i>The Economy 2.0: Microeconomics</i>, “9.2 Income and Wealth,” CORE Econ, https://books.core-econ.org/the-economy/microeconomics/09-lenders-borrowers-02-income-and-wealth.html. [Open access]","Galina Hale, “Stocks and Flows,” in <i>International Encyclopedia of the Social Sciences</i>, 2nd ed., Encyclopedia.com, https://www.encyclopedia.com/social-sciences/applied-and-social-sciences-magazines/stocks-and-flows. [Open access]","<i>Principles of Economics 3e</i>, “30.1 Government Spending,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/30-1-government-spending. [Open access]","<i>Principles of Economics 3e</i>, “30.3 Federal Deficits and the National Debt,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/30-3-federal-deficits-and-the-national-debt. [Open access]","Linda Booth Sweeney and John D. Sterman, “Bathtub Dynamics: Initial Results of a Systems Thinking Inventory,” <i>System Dynamics Review</i> 16 (2000): 249–94, abstract at https://mitmgmtfaculty.mit.edu/jsterman/bathtubdynamics/. [Paywalled]"],"why":[{"q":"Why does a large government debt make deficits harder to end?","a":"Because the stock feeds its own inflow: interest on the debt is part of government spending, so the bigger the debt, the larger the interest bill that adds to it.<sup class=\"fn\" data-fn=\"4\"></sup> The deficit is the yearly flow and the debt the running total of past deficits and surpluses.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why must national accounts record flows as well as balance sheets?","a":"Because stocks are recorded only at the beginning and end of each period, and every change in value between those two dates has to appear as a flow for the accounts to be complete and consistent.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did Fisher think the distinction mattered so much?","a":"Because he held that overlooking it had caused real confusion in economics, the old wage fund theory among it.<sup class=\"fn\" data-fn=\"1\"></sup> A stock is fully described by one magnitude, while a flow needs two, an amount and a duration, from which its rate follows.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Stock and flow"},
    "ec-054": {"questions":["A value above one is called elastic and a value below one inelastic, so estimating the <span class=\"blank\">_____</span> of petrol demand shows how far consumption falls when its price rises.","Short-run estimates for American petrol demand run from about −0.02 to −0.37, a disagreement over the size of <span class=\"blank\">_____</span> that turns on how the price changes were isolated."],"abstract":"<b>Elasticity</b> is the economist's measure of responsiveness: the percentage change in one quantity divided by the percentage change in another that brings it about.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It is a ratio of one percentage change to another and nothing more, which lets the responses of quite different markets, such as air travel and petrol, be set side by side.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> A value above one is called elastic and a value below one inelastic, meaning that the quantity moves proportionally more or less than whatever moved it.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Elasticity is not the slope of a curve, since along a straight demand line the slope stays the same while the elasticity changes from point to point.<sup class=\"fn\" data-fn=\"4\"></sup> The idea was first named as the elasticity of wants, demand being called elastic or inelastic according as the amount bought rises much or little for a given fall in price.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The same ratio works for any pair of variables, which is why economists also speak of income elasticity, cross-price elasticity between two goods, and the elasticity of labour supply with respect to wages.<sup class=\"fn\" data-fn=\"2\"></sup> Elasticities are estimated rather than observed, and in 2014 the U.S. Energy Information Administration put the short-run price elasticity of petrol demand at about −0.02 to −0.04.<sup class=\"fn\" data-fn=\"5\"></sup> Studies that isolated price changes not driven by demand, such as differences in state fuel taxes, found a short-run elasticity of about −0.37, many times larger.<sup class=\"fn\" data-fn=\"6\"></sup> Responses also grow with time, because over several years drivers can buy more efficient cars or move closer to work.<sup class=\"fn\" data-fn=\"6\"></sup> Policy models depend on such numbers too, and the U.S. Congressional Budget Office drew a range of 0.27 to 0.53 from the research literature for one measure of how labour supply responds to a temporary change in pay.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["<i>Principles of Economics 3e</i>, “5.1 Price Elasticity of Demand and Price Elasticity of Supply,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/5-1-price-elasticity-of-demand-and-price-elasticity-of-supply. [Open access]","<i>Principles of Economics 3e</i>, “5.4 Elasticity in Areas Other Than Price,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/5-4-elasticity-in-areas-other-than-price. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), book 3, chap. 4, “The Elasticity of Wants,” Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=13. [Open access]","The CORE Team, <i>The Economy 2.0: Microeconomics</i>, “7.5 Demand, Elasticity, and Revenue,” CORE Econ, https://books.core-econ.org/the-economy/microeconomics/07-firm-and-customers-05-demand-elasticity-revenue.html. [Open access]","U.S. Energy Information Administration, “Gasoline Prices Tend to Have Little Effect on Demand for Car Travel,” <i>Today in Energy</i>, 15 December 2014, https://www.eia.gov/todayinenergy/detail.php?id=19191. [Open access]","Lutz Kilian and Xiaoqing Zhou, “Gasoline Demand More Responsive to Price Changes than Economists Once Thought,” <i>Dallas Fed Economics</i>, Federal Reserve Bank of Dallas, 16 June 2020, https://www.dallasfed.org/research/economics/2020/0616.aspx. [Open access]","Felix Reichling and Charles Whalen, “Review of Estimates of the Frisch Elasticity of Labor Supply,” Congressional Budget Office Working Paper 2012-13, 25 October 2012, EconPapers, https://econpapers.repec.org/RePEc:cbo:wpaper:43676. [Open access]","Geoffrey Poitras, “Cobweb Theory, Market Stability, and Price Expectations,” <i>Journal of the History of Economic Thought</i> 45, no. 1 (2023): 137–61, https://doi.org/10.1017/S1053837222000116. [Open access]"],"why":[{"q":"Why is elasticity not simply the slope of the demand curve?","a":"Because slope compares absolute changes while elasticity compares percentage changes.<sup class=\"fn\" data-fn=\"1\"></sup> Along a straight demand line the slope is constant, yet the elasticity changes from point to point, so a steep curve and a low elasticity are related but are not the same thing.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why do estimates for petrol demand differ so widely?","a":"Because an estimate depends on isolating price changes that are not themselves caused by demand. The Energy Information Administration used figures of about −0.02 to −0.04,<sup class=\"fn\" data-fn=\"5\"></sup> while studies that exploited differences in state fuel taxes found about −0.37.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why does comparing two elasticities matter in a market with a production lag?","a":"Because in the cobweb model the swings in price grow ever wider when supply responds more strongly to price than demand does, and die away when it responds less strongly.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Elasticity (economics)"},
    "ec-055": {"questions":["Stating every assumption explicitly and deriving conclusions by proof, the axiomatic style that transformed <span class=\"blank\">_____</span> after 1944 was defended for showing exactly where a theory applies.","Warnings against 'mathiness', a slippery blend of words and symbols, are among the criticisms of <span class=\"blank\">_____</span> as a style of theory that can run ahead of the evidence it describes."],"abstract":"<b>Mathematical economics</b> is the use of mathematical methods, from algebra and graphs to calculus and fixed-point theorems, to state economic theories and work out what follows from them.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Its symbolic birth is usually dated to 1838, when Cournot published a mathematical theory of wealth, and in 1871 Jevons argued that economics, if it was to be a science at all, must be a mathematical science.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The case rests on the subject matter, since prices, quantities and costs present themselves as numbers and economic reasoning already deals in quantities and the relations between them.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> A further advantage is discipline, because fuzzy thinking that survives in words is exposed once a model is reduced to equations.<sup class=\"fn\" data-fn=\"1\"></sup> The cost is that mathematical models rest on simplifying assumptions and lose the nuance that a narrative account can keep.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> After 1944 the field was transformed by game theory, input-output analysis and new methods of optimisation, and theory moved towards an axiomatic style in which assumptions are stated and conclusions proved.<sup class=\"fn\" data-fn=\"3\"></sup> Defenders argue that making every assumption explicit allows a sounder judgement of where a theory applies, and that rigour has repeatedly given economists a deeper understanding of their problems.<sup class=\"fn\" data-fn=\"3\"></sup> Critics reply that the machinery can outrun the evidence, warning of complex theories that are valuable only as applied mathematics and of 'mathiness', a blend of words and symbols that leaves room for slippage between theoretical and empirical claims.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> The traffic has run both ways, since economic problems have also shaped mathematics, as when a lemma from a paper on growth theory was reformulated as a fixed-point theorem in 1941.<sup class=\"fn\" data-fn=\"3\"></sup> The balance of the discipline's leading journals has meanwhile shifted, with far fewer papers of pure theory and many more empirical studies than in earlier decades.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["<i>Principles of Economics 3e</i>, “A: The Use of Mathematics in Principles of Economics,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/a-the-use-of-mathematics-in-principles-of-economics. [Open access]","W. Stanley Jevons, <i>The Theory of Political Economy</i>, 3rd ed. (London: Macmillan, 1888), chap. 1, Library of Economics and Liberty, https://www.econlib.org/library/YPDBooks/Jevons/jvnPE.html?chapter_num=5. [Open access]","Gerard Debreu, “Economic Theory in the Mathematical Mode,” Nobel Memorial Lecture, 8 December 1983, https://www.nobelprize.org/uploads/2018/06/debreu-lecture.pdf. [Open access]","Paul A. Samuelson, “Maximum Principles in Analytical Economics,” Nobel Memorial Lecture, 11 December 1970, in <i>Nobel Lectures, Economics 1969–1980</i> (Singapore: World Scientific, 1992), https://www.nobelprize.org/uploads/2018/06/samuelson-lecture.pdf. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, rev. 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Paul M. Romer, “Mathiness in the Theory of Economic Growth,” <i>American Economic Review</i> 105, no. 5 (2015): 89–93, https://www.aeaweb.org/articles?id=10.1257/aer.p20151066. [Paywalled]","Daniel S. Hamermesh, “Six Decades of Top Economics Publishing: Who and How?,” <i>Journal of Economic Literature</i> 51, no. 1 (2013): 162–72, https://www.aeaweb.org/articles?id=10.1257/jel.51.1.162. [Paywalled]"],"why":[{"q":"Why did early advocates think economics had to be mathematical?","a":"Because its subject matter is quantitative. All economic writers must be mathematical so far as they are scientific at all, the argument ran, since they treat of quantities and the relations of quantities,<sup class=\"fn\" data-fn=\"2\"></sup> and with the numbers of prices and exchange taken away there would be nothing left to study.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why do defenders value the axiomatic method?","a":"Because stating every assumption explicitly permits a sounder judgement of how far a theory applies to a particular case, and insisting on rigour has repeatedly led economists to understand their problems better and to find techniques that fit them.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do introductory textbooks manage with little more than algebra?","a":"Because no important introductory idea needs advanced mathematics. Equations and graphs are one tool among several, useful for exposing fuzzy thinking but bought at the price of simplifying assumptions and lost nuance.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Mathematical economics"},
    "ec-056": {"questions":["Born of a study showing that stock market forecasters did no better than chance, the <span class=\"blank\">_____</span> went on to lead the joining of economic theory to mathematics and statistics.","Methods for estimating systems of simultaneous equations, and for deciding when their coefficients can be identified, were worked out in the 1940s at the <span class=\"blank\">_____</span> in Chicago."],"abstract":"The <b>Cowles Commission</b> for Research in Economics was a research institute founded in 1932 by Alfred Cowles at Colorado Springs, which moved to Chicago in 1939 and to Yale in 1955, where it continues as the Cowles Foundation.<sup class=\"fn\" data-fn=\"1\"></sup> The commission, and the journal <i>Econometrica</i> that Cowles also funded, grew out of his own study finding that stock market forecasters did no better than chance.<sup class=\"fn\" data-fn=\"3\"></sup> It worked in close partnership with the Econometric Society, founded in 1930, whose headquarters moved with it to New Haven in 1955.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Its first motto was 'Science is Measurement', replaced in 1952 by 'Theory and Measurement' to reflect the importance of theory.<sup class=\"fn\" data-fn=\"1\"></sup> The move from Colorado was made partly because it was hard to attract leading economists to so remote a place.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> By the 1950s it had led the movement to relate economic theories to mathematical and statistical studies, and Yale's announcement of the move in 1954 presented it in exactly those terms.<sup class=\"fn\" data-fn=\"2\"></sup> Its econometricians worked out how to estimate systems of simultaneous equations with random errors, including the conditions under which the structural coefficients of such systems can be identified.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> A monograph of 1950 estimated a model of the American economy with twelve interlocking variables as a single system, a forerunner of the large macroeconomic models used for decades afterwards.<sup class=\"fn\" data-fn=\"3\"></sup> Its theorists worked on general equilibrium too, and a Nobel lecture of 1983 remembered it in 1950 as a strongly interactive group where game theory, input-output analysis and the simplex algorithm were constant topics.<sup class=\"fn\" data-fn=\"4\"></sup> Its structural approach to cause and effect dominated econometrics until at least the 1980s, before critics and design-based methods built on natural experiments challenged it.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>","sources":["Cowles Foundation for Research in Economics, “About Us,” Yale University, https://cowles.yale.edu/about-cowles. [Open access]","Cowles Foundation for Research in Economics, “The Cowles Foundation Moves from Chicago to Yale's Department of Economics,” Yale University news release of 15 December 1954, https://cowles.yale.edu/about-us/move-yale. [Open access]","Robert W. Dimand, “Macroeconomic Dynamics at the Cowles Commission from the 1930s to the 1950s,” Cowles Foundation Discussion Paper 2195 (New Haven: Yale University, 2019), https://cowles.yale.edu/sites/default/files/2022-08/d2195.pdf. [Open access]","Gerard Debreu, “Economic Theory in the Mathematical Mode,” Nobel Memorial Lecture, 8 December 1983, https://www.nobelprize.org/uploads/2018/06/debreu-lecture.pdf. [Open access]","Olav Bjerkholt, “Trygve Haavelmo at the Cowles Commission,” <i>Econometric Theory</i> 31, no. 1 (2015): 1–84, https://doi.org/10.1017/S026646661400019X. [Paywalled]","Committee for the Prize in Economic Sciences in Memory of Alfred Nobel, <i>Answering Causal Questions Using Observational Data</i>, Scientific Background (Stockholm: Royal Swedish Academy of Sciences, 2021), https://www.nobelprize.org/uploads/2021/10/advanced-economicsciencesprize2021.pdf. [Open access]"],"why":[{"q":"Why did a businessman found an economics research institute?","a":"Because his own study of stock market forecasting had found that the forecasters did no better than chance, and that interest led him to pay for both the commission and the journal <i>Econometrica</i>.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did the commission leave Colorado for Chicago?","a":"Because it was difficult to attract leading economists to a place as remote as Colorado Springs. When its founder moved to Chicago in 1939 the headquarters went too, and a link with the University of Chicago was set up.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did its approach to estimation later lose ground?","a":"Because its structural models drew criticism, from Lucas in 1976 and Sims in 1980 among others,<sup class=\"fn\" data-fn=\"3\"></sup> and design-based studies using natural experiments later offered a different route to answering causal questions.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Cowles Foundation"},
    "ec-057": {"questions":["Following one country's output across fifty years or the same 12,686 Americans since 1979, collections of <span class=\"blank\">_____</span> let economists see how quantities and lives change over time.","With no official measure of American national income before 1934, the first years of the Depression passed without the <span class=\"blank\">_____</span> that could describe its toll consistently and in detail."],"abstract":"<b>Economic data</b> are the recorded observations of prices, output, jobs, trade, incomes and other quantities that economists use to describe economies and to test their ideas against the world.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Some follow quantities through time, as the World Bank's World Development Indicators do, listing about 1,400 series for 217 economies in 2026, many going back more than 50 years.<sup class=\"fn\" data-fn=\"1\"></sup> Others follow the same people over many years, as the American NLSY79 survey has done since 1979 with a sample of young people born between 1957 and 1964.<sup class=\"fn\" data-fn=\"2\"></sup> They come from two broad kinds of source, statistical surveys and administrative records, and statistical agencies are expected to choose between them by quality, timeliness, cost and the burden on respondents.<sup class=\"fn\" data-fn=\"4\"></sup> Even one headline figure is assembled from many of them, and American GDP estimates are pieced together from business censuses, monthly retail surveys, trade documents, payroll records and much else.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Much of this machinery is recent, and in the early 1930s the United States had thousands of market, commodity and industry indexes but no official measure of national income.<sup class=\"fn\" data-fn=\"5\"></sup> The first official estimates, for 1929 to 1932, were requested by a Senate resolution and delivered in January 1934 to describe the toll of the Depression.<sup class=\"fn\" data-fn=\"5\"></sup> Economics itself has grown steadily more empirical, and its leading journals now publish far fewer papers of pure theory and many more studies built on data the authors collected or on experiments.<sup class=\"fn\" data-fn=\"7\"></sup> Empirical papers reached citation parity with theoretical ones around 2000, and within fields and journals they are now cited more.<sup class=\"fn\" data-fn=\"8\"></sup> Computers now capture data from vast numbers of transactions, and datasets of that size can call for tools beyond conventional regression, such as machine learning.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["World Bank, “World Development Indicators,” https://datatopics.worldbank.org/world-development-indicators/. [Open access]","U.S. Bureau of Labor Statistics, National Longitudinal Surveys, “NLSY79 Cohort,” https://www.nlsinfo.org/content/cohorts/nlsy79. [Open access]","<i>Principles of Economics 3e</i>, “19.1 Measuring the Size of the Economy: Gross Domestic Product,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/19-1-measuring-the-size-of-the-economy-gross-domestic-product. [Open access]","United Nations Statistics Division, “Fundamental Principles of Official Statistics,” endorsed by General Assembly resolution 68/261, 29 January 2014, https://unstats.un.org/fpos/. [Open access]","Rosemary D. Marcuss and Richard E. Kane, “U.S. National Income and Product Statistics: Born of the Great Depression and World War II,” <i>Survey of Current Business</i> 87 (February 2007): 32–46, https://apps.bea.gov/scb/pdf/2007/02%20February/0207_history_article.pdf. [Open access]","Hal R. Varian, “Big Data: New Tricks for Econometrics,” <i>Journal of Economic Perspectives</i> 28, no. 2 (2014): 3–28, https://www.aeaweb.org/articles?id=10.1257/jep.28.2.3. [Open access]","Daniel S. Hamermesh, “Six Decades of Top Economics Publishing: Who and How?,” <i>Journal of Economic Literature</i> 51, no. 1 (2013): 162–72, https://www.aeaweb.org/articles?id=10.1257/jel.51.1.162. [Paywalled]","Joshua Angrist, Pierre Azoulay, Glenn Ellison, Ryan Hill and Susan Feng Lu, “Economic Research Evolves: Fields and Styles,” <i>American Economic Review</i> 107, no. 5 (2017): 293–97, https://www.aeaweb.org/articles?id=10.1257/aer.p20171117. [Paywalled]"],"why":[{"q":"Why do statistical agencies use both surveys and administrative records?","a":"Because data for statistical purposes may come from either, and agencies are meant to choose by quality, timeliness, cost and the burden on the people and firms who respond.<sup class=\"fn\" data-fn=\"4\"></sup> A figure like GDP draws on both, from business censuses to payroll records.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why were the first American national income figures produced in the 1930s?","a":"Because a Senate resolution of 1932 asked the Department of Commerce for them, and when they arrived in January 1934 they met the need to describe the economic toll of the Depression consistently and in detail.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why can very large datasets need new tools?","a":"Because they can offer more possible predictors than conventional estimation can handle and allow more flexible relationships than simple linear models, problems that machine learning techniques such as decision trees and neural nets are designed to meet.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Economic data"},
    "ec-058": {"questions":["Endorsed by the UN General Assembly in 2014, ten principles of impartiality, transparency and confidentiality govern the <span class=\"blank\">_____</span> that national agencies publish on economy and society.","When Greece's deficit for 2008 was revised from 5.0 to 7.7 per cent of GDP, a European report blamed political pressure for weakening the country's <span class=\"blank\">_____</span> on public finance."],"abstract":"<b>Official statistics</b> are the figures that government statistical agencies compile and publish on the economic, demographic, social and environmental condition of a country.<sup class=\"fn\" data-fn=\"1\"></sup> The United Nations' Fundamental Principles of Official Statistics, first adopted by European statisticians in 1991 and endorsed by the General Assembly in 2014, call them an indispensable element of the information system of a democratic society.<sup class=\"fn\" data-fn=\"1\"></sup> They require agencies to choose their methods on strictly professional grounds, to explain their sources and methods, and to keep individual returns strictly confidential and use them only for statistics.<sup class=\"fn\" data-fn=\"1\"></sup> Shared international standards keep the figures comparable, and the System of National Accounts, issued jointly by the United Nations, the European Commission, the OECD, the IMF and the World Bank, is the common framework for national accounts.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> National codes add their own tests, and Britain's Code of Practice asks that published statistics have public value, be of high quality and come from trustworthy producers.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The figures come from surveys, censuses and administrative records, and the American unemployment rate rests on the Current Population Survey, run every month since 1940 and covering about 60,000 households.<sup class=\"fn\" data-fn=\"2\"></sup> American GDP is pieced together by the Bureau of Economic Analysis from business censuses, retail surveys, trade documents and payroll records, and the estimates are revised as more information arrives.<sup class=\"fn\" data-fn=\"3\"></sup> Many such series are younger than they seem, since the first official American estimates of national income were delivered to the Senate in January 1934 under the direction of Simon Kuznets.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Their worth depends on independence from politics, and in October 2009 Greece revised its government deficit for 2008 from 5.0 to 7.7 per cent of GDP.<sup class=\"fn\" data-fn=\"6\"></sup> A European Commission report of 2010 blamed weak governance that left fiscal statistics open to political pressure and electoral cycles, and warned that the Greek figures would stay in question until checks and balances were in place.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["United Nations Statistics Division, “Fundamental Principles of Official Statistics,” endorsed by General Assembly resolution 68/261, 29 January 2014, https://unstats.un.org/fpos/. [Open access]","<i>Principles of Economics 3e</i>, “21.1 How Economists Define and Compute Unemployment Rate,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/21-1-how-economists-define-and-compute-unemployment-rate. [Open access]","<i>Principles of Economics 3e</i>, “19.1 Measuring the Size of the Economy: Gross Domestic Product,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/19-1-measuring-the-size-of-the-economy-gross-domestic-product. [Open access]","Rosemary D. Marcuss and Richard E. Kane, “U.S. National Income and Product Statistics: Born of the Great Depression and World War II,” <i>Survey of Current Business</i> 87 (February 2007): 32–46, https://apps.bea.gov/scb/pdf/2007/02%20February/0207_history_article.pdf. [Open access]","Mary-Lynne Neil, “Simon Kuznets: The Founder of National Income Measurement,” <i>Survey of Current Business</i> 100, no. 8 (18 August 2020), https://apps.bea.gov/scb/issues/2020/08-august/0820-influencer-kuznets.htm. [Open access]","European Commission, <i>Report on Greek Government Deficit and Debt Statistics</i>, COM(2010) 1 final (Brussels, 8 January 2010), https://ec.europa.eu/eurostat/documents/4187653/6404656/COM_2010_report_greek.pdf/c8523cfa-d3c1-4954-8ea1-64bb11e59b3a. [Open access]","Office for Statistics Regulation, “The Code of Practice for Statistics,” UK Statistics Authority, https://code.statisticsauthority.gov.uk/. [Open access]","European Commission, International Monetary Fund, Organisation for Economic Co-operation and Development, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), 39, paras. 3.4–3.10, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]"],"why":[{"q":"What do the United Nations principles require of statistical agencies?","a":"They require methods chosen on strictly professional grounds, information on sources and methods so that the data can be interpreted correctly, and individual returns kept strictly confidential and used only for statistics.<sup class=\"fn\" data-fn=\"1\"></sup> They also call for international concepts and methods, which is the role of the System of National Accounts.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup>"},{"q":"Why are official figures revised after they are first published?","a":"Because early estimates are built from incomplete sources. As more information comes in, the Bureau of Economic Analysis updates its GDP estimates, and every five years, after the census of businesses, it revises the whole series back to 1929.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did the European Commission doubt the Greek figures?","a":"Because the 2008 deficit had been revised from 5.0 to 7.7 per cent of GDP, and the report found poor cooperation between institutions, diffuse responsibilities and missing documentation, which left fiscal statistics subject to political pressure and electoral cycles.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Official statistics"},
    "ec-059": {"questions":["Because price and quantity are set together by supply and demand, fitting one to the other runs into <span class=\"blank\">_____</span>, the problem that instrumental variables were devised in the 1920s to solve.","Ability and ambition push people both to study longer and to earn more, a source of <span class=\"blank\">_____</span> that makes the raw link between schooling and wages a poor guide to the return on education."],"abstract":"<b>Endogeneity</b> is the econometric name for the problem that arises when a variable used to explain an outcome is itself shaped by that outcome, or by something else that also drives it, so that the correlation between them cannot be read as cause and effect.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Its classic sources are omitted variables, errors of measurement, reverse causation and simultaneity, in which two quantities are settled together, as price and quantity are by supply and demand.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> People with more education earn more, but those who choose long schooling may differ in talent and would probably have earned more anyway, so the correlation mixes the effect of schooling with the effect of who chooses it.<sup class=\"fn\" data-fn=\"2\"></sup> Among American men born in the 1930s, earnings were about seven per cent higher for each extra year of education, a figure that cannot by itself say how much of the gap the schooling caused.<sup class=\"fn\" data-fn=\"2\"></sup> Reverse causation can mislead as well, because rising unemployment lets employers set lower wages, which may prompt demands for a higher minimum wage.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The problem first arose in estimating supply and demand, since each observed price and quantity is set by both at once, and the method of instrumental variables was devised in the 1920s to separate them.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> An early alternative was to let supply answer to the previous period's price, a device seen at the time as an ingenious solution to this identification problem.<sup class=\"fn\" data-fn=\"6\"></sup> Petrol shows the stakes, because studies that isolated price changes not driven by demand, using differences in state fuel taxes, found short-run elasticities many times larger than older estimates.<sup class=\"fn\" data-fn=\"5\"></sup> The standard remedies look for variation that is as good as random, such as season of birth, which shifts schooling through school-leaving laws but is unlikely to be linked to other causes of earnings.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> The turn towards dealing with endogeneity through better research design has been called a credibility revolution in empirical economics, although critics worry that it favours clean answers over important questions.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Committee for the Prize in Economic Sciences in Memory of Alfred Nobel, <i>Answering Causal Questions Using Observational Data</i>, Scientific Background (Stockholm: Royal Swedish Academy of Sciences, 2021), https://www.nobelprize.org/uploads/2021/10/advanced-economicsciencesprize2021.pdf. [Open access]","Royal Swedish Academy of Sciences, <i>Natural Experiments Help Answer Important Questions</i>, Popular Science Background to the Prize in Economic Sciences 2021 (Stockholm, 2021), https://www.nobelprize.org/uploads/2021/10/popular-economicsciencesprize2021-3.pdf. [Open access]","Joshua D. Angrist and Alan B. Krueger, “Instrumental Variables and the Search for Identification: From Supply and Demand to Natural Experiments,” NBER Working Paper 8456 (2001), published in <i>Journal of Economic Perspectives</i> 15, no. 4 (2001): 69–85, https://www.nber.org/papers/w8456. [Open access]","Joshua D. Angrist and Jörn-Steffen Pischke, “The Credibility Revolution in Empirical Economics: How Better Research Design Is Taking the Con out of Econometrics,” NBER Working Paper 15794 (2010), published in <i>Journal of Economic Perspectives</i> 24, no. 2 (2010): 3–30, https://www.nber.org/papers/w15794. [Open access]","Lutz Kilian and Xiaoqing Zhou, “Gasoline Demand More Responsive to Price Changes than Economists Once Thought,” <i>Dallas Fed Economics</i>, Federal Reserve Bank of Dallas, 16 June 2020, https://www.dallasfed.org/research/economics/2020/0616.aspx. [Open access]","Geoffrey Poitras, “Cobweb Theory, Market Stability, and Price Expectations,” <i>Journal of the History of Economic Thought</i> 45, no. 1 (2023): 137–61, https://doi.org/10.1017/S1053837222000116. [Open access]"],"why":[{"q":"Why can't the raw link between schooling and earnings be trusted?","a":"Because people who choose long schooling differ from those who do not, in talent among other things, and might have earned more anyway.<sup class=\"fn\" data-fn=\"2\"></sup> The difference this creates, between the simple comparison of averages and the true causal effect, is what econometricians call selection bias.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"How does an instrumental variable get around the problem?","a":"It uses only the part of the variation in the explanatory variable that comes from the instrument, and if the instrument is valid that part is unrelated to the omitted variables.<sup class=\"fn\" data-fn=\"3\"></sup> Quarter of birth was used in this way because it shifts schooling through school-leaving laws while chance decides when a person is born.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does the problem matter for estimates of petrol demand?","a":"Because prices respond to demand as well as driving it. Isolating price changes that demand did not cause, such as those from state fuel taxes, gave a short-run elasticity of about −0.37, far above older estimates of a few hundredths.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Endogeneity (econometrics)"},
    "ec-060": {"questions":["Situations in real life that resemble randomised trials, created by chance, institutional rules or policy changes, are what economists exploit as a <span class=\"blank\">_____</span> when a true experiment is impossible.","The sudden arrival of about 125,000 Cubans in 1980, which swelled Miami's labour force by about 7 per cent, served as a <span class=\"blank\">_____</span> for measuring how immigration affects local wages."],"abstract":"A <b>natural experiment</b> is an event or situation, outside the control of the people studied, that exposes some of them to a change and not others in a way that is as if it had been randomly assigned.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Such situations arise from natural random variation, institutional rules or policy changes, and research over the last thirty years has shown that they are far from rare.<sup class=\"fn\" data-fn=\"1\"></sup> They differ from a controlled trial because the researcher does not choose who is treated, and the people affected may decide for themselves whether to take part, which makes the results harder to interpret.<sup class=\"fn\" data-fn=\"1\"></sup> The idea is old, and as early as 1944 an econometrician wrote of “the stream of experiments that Nature is steadily turning out of her own enormous laboratory”.<sup class=\"fn\" data-fn=\"2\"></sup> Since the 1990s natural experiments have become a central tool in the economics of development, education, labour, health and public finance.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> <br><br> When New Jersey raised its minimum wage from $4.25 to $5.05 an hour on 1 April 1992, a survey of 410 fast-food restaurants compared employment there with neighbouring Pennsylvania, where the minimum stayed at $4.25.<sup class=\"fn\" data-fn=\"3\"></sup> Against the standard prediction, employment in the New Jersey restaurants rose relative to Pennsylvania, and the Swedish Academy's summary in 2021 read the follow-up studies as showing smaller negative effects than economists had believed thirty years earlier.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> The Mariel boatlift of 1980, which brought about 125,000 Cubans to the United States and raised Miami's labour force by about 7 per cent, showed virtually no effect on the wages or unemployment of less-skilled workers already there.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Season of birth supplied another case, since school-leaving laws keep children born late in the year at school longer, and their extra schooling showed up in higher earnings.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Critics have argued that such studies often leave unstated the economic assumptions needed to interpret their estimates, and that the findings can change when those assumptions are relaxed.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Royal Swedish Academy of Sciences, <i>Natural Experiments Help Answer Important Questions</i>, Popular Science Background to the Prize in Economic Sciences 2021 (Stockholm, 2021), https://www.nobelprize.org/uploads/2021/10/popular-economicsciencesprize2021-3.pdf. [Open access]","Committee for the Prize in Economic Sciences in Memory of Alfred Nobel, <i>Answering Causal Questions Using Observational Data</i>, Scientific Background (Stockholm: Royal Swedish Academy of Sciences, 2021), https://www.nobelprize.org/uploads/2021/10/advanced-economicsciencesprize2021.pdf. [Open access]","David Card and Alan B. Krueger, “Minimum Wages and Employment: A Case Study of the Fast Food Industry in New Jersey and Pennsylvania,” NBER Working Paper 4509 (1993), published in <i>American Economic Review</i> 84, no. 4 (1994): 772–93, https://www.nber.org/papers/w4509. [Open access]","David Card, “The Impact of the Mariel Boatlift on the Miami Labor Market,” NBER Working Paper 3069 (1989), published in <i>Industrial and Labor Relations Review</i> 43, no. 2 (1990): 245–57, https://www.nber.org/papers/w3069. [Open access]","Joshua D. Angrist and Alan B. Krueger, “Does Compulsory School Attendance Affect Schooling and Earnings?,” NBER Working Paper 3572 (1990), published in <i>Quarterly Journal of Economics</i> 106, no. 4 (1991): 979–1014, https://www.nber.org/papers/w3572. [Open access]","Mark R. Rosenzweig and Kenneth I. Wolpin, “Natural ‘Natural Experiments’ in Economics,” <i>Journal of Economic Literature</i> 38, no. 4 (2000): 827–74, https://www.aeaweb.org/articles?id=10.1257/jel.38.4.827. [Paywalled]","Joshua D. Angrist and Jörn-Steffen Pischke, “The Credibility Revolution in Empirical Economics: How Better Research Design Is Taking the Con out of Econometrics,” NBER Working Paper 15794 (2010), published in <i>Journal of Economic Perspectives</i> 24, no. 2 (2010): 3–30, https://www.nber.org/papers/w15794. [Open access]"],"why":[{"q":"Why is a natural experiment harder to interpret than a clinical trial?","a":"Because in a trial the researcher controls who is offered the treatment, while in a natural experiment the people affected may choose for themselves whether to take part.<sup class=\"fn\" data-fn=\"1\"></sup> Later work set out exactly which conclusions about cause and effect such data can support.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why was Pennsylvania used in the minimum wage study?","a":"Because a comparison group was needed in which the minimum did not change but other conditions were similar. Labour markets on either side of the border were likely to move together, so a different employment trend in New Jersey could be read as an effect of the higher minimum.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why have critics questioned some natural experiment studies?","a":"Because the behavioural, market and technological assumptions needed to interpret their estimates are often left unstated, and simple economic models show that the interpretation can shift when those assumptions are relaxed.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Natural experiment"},
    "ec-061": {"questions":["Because economists can seldom run controlled experiments, <span class=\"blank\">_____</span> has to estimate each relationship from data produced by a whole system in which every variable may be moving at once.","Since a critique of 1983 shook trust in fragile results, applied <span class=\"blank\">_____</span> has leaned on research designs that resemble random assignment, such as chance events that treat similar groups differently."],"abstract":"<b>Econometrics</b> is the branch of economics that uses economic theory, mathematics and statistical inference to put numbers on economic relationships.<sup class=\"fn\" data-fn=\"1\"></sup> Its aim is to turn a qualitative statement, such as that spending rises with income, into a quantitative one, such as that consumer spending rises by 95 cents for every extra dollar of disposable income.<sup class=\"fn\" data-fn=\"1\"></sup> An econometric model begins with a theory of how households, firms and the rest of the economy interact, and then fills that theory with parameters measured from historical data.<sup class=\"fn\" data-fn=\"2\"></sup> Its main tool is the multiple regression, which estimates how a change in one variable affects another while taking account of the other things that affect it.<sup class=\"fn\" data-fn=\"1\"></sup> The field was organised in December 1930, when a society for advancing economic theory in its relation to statistics and mathematics was founded in Cleveland, and its journal <i>Econometrica</i> followed in 1933.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The central difficulty is that economists can seldom or never carry out controlled experiments, so their data are the outcome of many interacting relationships at once.<sup class=\"fn\" data-fn=\"5\"></sup> That makes it hard to tell from the data alone which relationship is being measured, and the answer worked out in the 1940s was to state economic theories in terms of probability so that the methods of mathematical statistics could be applied.<sup class=\"fn\" data-fn=\"5\"></sup> The first prize in economics, in 1969, went to two founders of the field for building dynamic models of economic processes, one of them an econometric model used to forecast and plan policy in the Netherlands.<sup class=\"fn\" data-fn=\"4\"></sup> After a famous critique of 1983 questioned how far applied results could be trusted, much empirical work answered by putting research design at the centre, above all designs that imitate random assignment.<sup class=\"fn\" data-fn=\"6\"></sup> Natural experiments, in which chance events or policy changes treat similar groups of people differently, now let econometricians draw conclusions about cause and effect in a way that resembles a clinical trial in medicine.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Sam Ouliaris, “What Is Econometrics?,” <i>Finance &amp; Development</i> 48, no. 4 (December 2011), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2011/12/basics.htm. [Open access]","Saul H. Hymans, “Forecasting and Econometric Models,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson, Econlib, https://www.econlib.org/library/Enc/ForecastingandEconometricModels.html. [Open access]","The Econometric Society, “About,” https://www.econometricsociety.org/society/about. [Open access]","Erik Lundberg, “Award Ceremony Speech,” Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1969, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1969/ceremony-speech/. [Open access]","Royal Swedish Academy of Sciences, “Press Release: The Prize in Economics 1989,” 11 October 1989, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1989/press-release/. [Open access]","Joshua D. Angrist and Jörn-Steffen Pischke, “The Credibility Revolution in Empirical Economics: How Better Research Design Is Taking the Con out of Econometrics,” <i>Journal of Economic Perspectives</i> 24, no. 2 (2010): 3–30, https://www.aeaweb.org/articles?id=10.1257/jep.24.2.3. [Open access]","Royal Swedish Academy of Sciences, “Press Release: The Prize in Economic Sciences 2021,” 11 October 2021, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/2021/press-release/. [Open access]"],"why":[{"q":"Why can economists not simply run experiments to measure an economic relationship?","a":"Because they can seldom or never carry out controlled experiments in the way natural scientists do.<sup class=\"fn\" data-fn=\"5\"></sup> The market outcomes they observe are produced by many behaviours and relationships acting on one another at once, so all the variables may change together and it is hard to be sure which relationship the data reveal.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does a policymaker need the size of a relationship and not just its direction?","a":"Because a central bank setting interest rates must know roughly how much a change will move inflation and growth.<sup class=\"fn\" data-fn=\"1\"></sup> Several competing models can often explain the same regularity, but few say anything about the magnitude, and putting a number on it is exactly the job econometrics does.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why did natural experiments become so important in applied work?","a":"Because questions of cause and effect lack an obvious comparison: nobody knows what would have happened without the policy or the event.<sup class=\"fn\" data-fn=\"7\"></sup> Chance events that treat similar groups differently supply that comparison, much as a clinical trial does, and research design of this kind became the main engine of more credible empirical work.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Econometrics"},
    "ec-062": {"questions":["From February 1996 one central bank published its inflation outlook as a fan of probabilities, a way of presenting <span class=\"blank\">_____</span> meant to stop readers fixing on a falsely precise central line.","Estimating the current quarter’s growth before the official figure appears, a task called nowcasting, is the near end of <span class=\"blank\">_____</span>, whose accuracy falls away as the horizon stretches further ahead."],"abstract":"<b>Economic forecasting</b> is the attempt to say in advance how an economy will move, and the measure most often used to judge a forecast is how well it predicted the growth of real output.<sup class=\"fn\" data-fn=\"1\"></sup> Structural forecasts come from econometric models that embody economic theory, while nonstructural forecasts project a series forward from its own past and from statistical correlations with little theory behind them.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Any model forecast needs assumptions about things the model does not explain, such as future tax rates and the policy the central bank will follow, so every forecast is conditional on those assumptions.<sup class=\"fn\" data-fn=\"1\"></sup> Forecasters also add their own judgement to the equations, a practice once dismissed as unscientific and now widely treated as unavoidable.<sup class=\"fn\" data-fn=\"1\"></sup> Forecasts are collected and compared as well as made, and the oldest quarterly survey of macroeconomic forecasts in the United States began in 1968.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Every forecast is surrounded by uncertainty, and that uncertainty grows quickly the further ahead it looks and during periods of large shocks or rapid structural change.<sup class=\"fn\" data-fn=\"3\"></sup> That is why the Bank of England began in February 1996 to publish its inflation forecast as a probability distribution, the fan chart, meant to convey its judgement without suggesting a precision that would be spurious.<sup class=\"fn\" data-fn=\"5\"></sup> A review of the Bank’s forecasting in 2024 judged that the fan charts had weak conceptual foundations and had outlived their usefulness, and urged it to publish alternative scenarios alongside the central forecast instead.<sup class=\"fn\" data-fn=\"3\"></sup> At the near end, nowcasting estimates the current quarter’s growth before the official figure is released, using methods similar to those of the statistical agency that will publish it.<sup class=\"fn\" data-fn=\"7\"></sup> Further out the record is weaker, and a study of growth forecasts for 63 countries from 1992 to 2014 found that forecasters missed the size of recessions by a wide margin until the year was almost over, with private and official forecasts performing about the same.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Saul H. Hymans, “Forecasting and Econometric Models,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson, Econlib, https://www.econlib.org/library/Enc/ForecastingandEconometricModels.html. [Open access]","Francis X. Diebold, “The Past, Present, and Future of Macroeconomic Forecasting,” <i>Journal of Economic Perspectives</i> 12, no. 2 (1998): 175–92, https://www.aeaweb.org/articles?id=10.1257/jep.12.2.175. [Open access]","Ben S. Bernanke, <i>Forecasting for Monetary Policy Making and Communication at the Bank of England: A Review</i> (London: Bank of England, April 2024), https://www.bankofengland.co.uk/independent-evaluation-office/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review. [Open access]","Federal Reserve Bank of Philadelphia, “Survey of Professional Forecasters,” https://www.philadelphiafed.org/surveys-and-data/real-time-data-research/survey-of-professional-forecasters. [Open access]","Erik Britton, Paul Fisher and John Whitley, “The Inflation Report Projections: Understanding the Fan Chart,” <i>Bank of England Quarterly Bulletin</i>, 1998 Q1, https://www.bankofengland.co.uk/-/media/boe/files/quarterly-bulletin/1998/the-inflation-report-projections-understanding-the-fan-chart. [Open access]","Zidong An, João Tovar Jalles and Prakash Loungani, “How Well Do Economists Forecast Recessions?,” IMF Working Paper 18/39 (Washington, DC: International Monetary Fund, March 2018), https://www.imf.org/en/publications/wp/issues/2018/03/05/how-well-do-economists-forecast-recessions-45672. [Open access]","Federal Reserve Bank of Atlanta, “GDPNow,” https://www.atlantafed.org/cqer/research/gdpnow. [Open access]"],"why":[{"q":"Why is an economic forecast always conditional on assumptions?","a":"Because a model can only forecast the variables it explains once values have been fixed for the ones it does not, such as tax rates and central-bank policy.<sup class=\"fn\" data-fn=\"1\"></sup> A wrong guess about those outside variables produces an input error, quite apart from any error in the equations themselves, and a review of the Bank of England’s forecasting in 2024 urged it to stress that conditionality more and to publish alternative scenarios.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did a central bank turn to a fan of probabilities instead of a single line?","a":"Because a single path encouraged readers to concentrate on an apparently precise central projection and to read the shaded band around it as fixed limits rather than probabilities.<sup class=\"fn\" data-fn=\"5\"></sup> The fan chart was meant to show the Bank’s own assessment of the range of outcomes without claiming a precision that would be spurious.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why forecast at all when the errors are so large?","a":"Because forecasts made in real time do contain useful information about the future course of key economic variables, even though they are subject to a high degree of uncertainty.<sup class=\"fn\" data-fn=\"3\"></sup> Inflation targeting, adopted in Britain in 1992, put more weight on taking a forward view of inflationary pressure, and that view is best described by an explicit forecast.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Economic forecasting"},
    "ec-063": {"questions":["The calmer American output growth after 1984, when the standard deviation of annual growth fell from 2.7 to 1.6 per cent, is a widely studied <span class=\"blank\">_____</span> in a macroeconomic time series.","Tests that can find a <span class=\"blank\">_____</span> without knowing its date in advance let econometricians ask when an old relationship stopped holding, instead of assuming that the past still describes the future."],"abstract":"A <b>structural break</b> is a lasting change in the relationships that generate an economic time series, so that patterns which held in the past are a poor guide to what comes next.<sup class=\"fn\" data-fn=\"1\"></sup> Tests that detect a break whose date is not known in advance, and methods that estimate when it happened, changed applied time-series econometrics in the late 20th century.<sup class=\"fn\" data-fn=\"2\"></sup> A closely studied example is the calming of output in the United States, where the standard deviation of annual real GDP growth was 2.7 per cent from 1960 to 1983 and 1.6 per cent from 1984 to 2001.<sup class=\"fn\" data-fn=\"5\"></sup> Its causes are disputed, and one estimate credits improved policy with 20 to 30 per cent of it, identifiable good luck with as much again and unknown good luck with the rest.<sup class=\"fn\" data-fn=\"5\"></sup> A model fitted to data from before a break has no way of knowing that the economy it describes has changed.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> One line of research argues that breaks are the main reason economic forecasts fail, and that other suspects such as a model’s simplifications do relatively little harm when no break occurs.<sup class=\"fn\" data-fn=\"1\"></sup> The most damaging kind is a location shift, a change in the long-run average of a variable, which leaves a model’s forecasts biased in the same direction period after period until the model is adjusted.<sup class=\"fn\" data-fn=\"1\"></sup> Forecasters have long pushed models back on track with adjustments called add factors, and such devices give up some accuracy in calm times as insurance against an unforeseen break.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Forecast failure was common across rich economies during the Great Recession of 2008 to 2012, the latest of many such episodes, and recessions are typically missed by a wide margin until the year is nearly over.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A review of the Bank of England in 2024 found that its large recent errors came mainly from hard-to-forecast shocks such as the pandemic and dearer energy, and stressed that uncertainty rises sharply during rapid structural change.<sup class=\"fn\" data-fn=\"3\"></sup>","sources":["Jennifer L. Castle, Michael P. Clements and David F. Hendry, “An Overview of Forecasting Facing Breaks,” <i>Journal of Business Cycle Research</i> 12 (2016): 3–23, https://doi.org/10.1007/s41549-016-0005-2. [Open access]","Bruce E. Hansen, “The New Econometrics of Structural Change: Dating Breaks in U.S. Labor Productivity,” <i>Journal of Economic Perspectives</i> 15, no. 4 (2001): 117–28, https://www.aeaweb.org/articles?id=10.1257/jep.15.4.117. [Open access]","Ben S. Bernanke, <i>Forecasting for Monetary Policy Making and Communication at the Bank of England: A Review</i> (London: Bank of England, April 2024), https://www.bankofengland.co.uk/independent-evaluation-office/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review. [Open access]","Zidong An, João Tovar Jalles and Prakash Loungani, “How Well Do Economists Forecast Recessions?,” IMF Working Paper 18/39 (Washington, DC: International Monetary Fund, March 2018), https://www.imf.org/en/publications/wp/issues/2018/03/05/how-well-do-economists-forecast-recessions-45672. [Open access]","James H. Stock and Mark W. Watson, “Has the Business Cycle Changed and Why?,” NBER Working Paper 9127 (Cambridge, MA: National Bureau of Economic Research, 2002), https://www.nber.org/papers/w9127. [Open access]","Saul H. Hymans, “Forecasting and Econometric Models,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson, Econlib, https://www.econlib.org/library/Enc/ForecastingandEconometricModels.html. [Open access]"],"why":[{"q":"Why does a structural break do more damage than a simplified model?","a":"Because in a world that does not change, a model’s forecasts perform about as well out of sample as its fit to the past suggested, even if the model leaves things out.<sup class=\"fn\" data-fn=\"1\"></sup> A break, above all a shift in a variable’s long-run average, breaks that link, and the forecasts stay biased in one direction until the forecaster changes the model.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do forecasters add their own adjustments to a model’s output?","a":"Because outside information can show that the model’s past parameters no longer fit, and the pragmatic aim is the most informative forecast rather than a test of the model.<sup class=\"fn\" data-fn=\"6\"></sup> Such adjustments, long called add factors, are one way to put forecasts back on track after a shift, at the cost of a wider spread of errors in normal times.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why are recessions so often missed until they are under way?","a":"Because forecasts for ordinary years are revised slowly, and even when revisions speed up in a recession year they are not large enough to avoid big errors.<sup class=\"fn\" data-fn=\"4\"></sup> Shocks such as a pandemic or a sudden jump in energy prices are by their nature difficult to forecast, and they were generally not predicted by financial markets or outside experts either.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Structural break"},
    "ec-064": {"questions":["Invoking the <span class=\"blank\">_____</span>, a central-bank research bulletin in 2022 argued that in principle macroprudential tools should guard the financial system while interest rates stay devoted to keeping inflation on target.","Writing the economy as a determinate system of equations and solving for the settings of policy led to the <span class=\"blank\">_____</span>, which says a state needs as many means of policy as it has aims."],"abstract":"The <b>Tinbergen rule</b> holds that a government aiming to reach a number of independent policy targets needs at least as many independent policy instruments to do it.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> A target is an outcome the policymaker wants, such as a given rate of unemployment or of inflation, and an instrument is a lever it controls directly, such as taxes or monetary policy.<sup class=\"fn\" data-fn=\"3\"></sup> Counting the levers is not enough, because instruments can be sufficient in number and still unable to produce separate effects, and two that move the economy in the same way act as one.<sup class=\"fn\" data-fn=\"4\"></sup> Jan Tinbergen stated the condition in the early 1950s, after building some of the first multi-equation models of whole economies, among them a 27-equation model of the Netherlands.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> The logic is that of a determinate system of equations, in which the state, as the presentation speech for the first economics prize put it in 1969, must as a rule have as many means of economic policy as it has aims.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The rule shows plainly how a model becomes policy advice: write the economy as equations, fix the values wanted for the targets and solve for the settings of the instruments.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> For Tinbergen a model meant listing the variables, listing the relations they must obey and testing those relations against observation, and it could then be put to work on practical problems.<sup class=\"fn\" data-fn=\"2\"></sup> The approach assumed that the economy would not change its behaviour in response to policy, and the case made from 1976 that people’s expectations adjust to what policymakers do undermined that assumption.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> The rule is still invoked, as when a research bulletin of the European Central Bank in 2022 used it to argue that macroprudential policy should handle risks to the financial system while monetary policy keeps inflation on target.<sup class=\"fn\" data-fn=\"5\"></sup> Model-based advice remains built into Dutch government, where the planning bureau that Tinbergen first directed from 1945 produces the projections that form the official basis of the budget.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Erik Lundberg, “Award Ceremony Speech,” Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1969, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1969/ceremony-speech/. [Open access]","Jan Tinbergen, “The Use of Models: Experience and Prospects,” Prize Lecture, 12 December 1969, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1969/tinbergen/lecture/. [Open access]","David R. Henderson, “Jan Tinbergen,” in <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/bios/Tinbergen.html. [Open access]","Nicola Acocella, Giovanni Di Bartolomeo and Andrew Hughes Hallett, “The Theory of Economic Policy: From a Theory of Control to a Theory of Conflict (Resolutions),” Working Paper 91, Sapienza University of Rome, December 2011, https://memotef.web.uniroma1.it/sites/default/files/allegati/2024-07/FullTextWP91.pdf. [Open access]","Alberto Martin, Caterina Mendicino and Alejandro Van der Ghote, “Systemic Risk and Policy Interventions: Monetary and Macroprudential Policy,” <i>ECB Research Bulletin</i> 97 (European Central Bank, 2022), https://www.ecb.europa.eu/pub/economic-research/resbull/2022/html/ecb.rb220621~f8769cf5a8.en.html. [Open access]","CPB Netherlands Bureau for Economic Policy Analysis, “About CPB,” https://www.cpb.nl/en/about-cpb. [Open access]","Thomas J. Sargent, “Rational Expectations,” in <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/RationalExpectations.html. [Open access]"],"why":[{"q":"Why must the instruments be independent and not just numerous?","a":"Because instruments can be enough in number and still unable to produce separate effects on the targets.<sup class=\"fn\" data-fn=\"4\"></sup> At least as many instruments as targets is only the necessary condition; the full condition is that the instruments are linearly independent, meaning that no lever merely repeats what another already does.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why did the idea of rational expectations weaken this way of advising governments?","a":"Because the classical theory treated the private sector as a fixed system that does not react to policy.<sup class=\"fn\" data-fn=\"4\"></sup> If people form expectations rationally, the government cannot manipulate their forecast errors in a predictable and reliable way, and the policymaker loses the stable, parametric system the rule takes for granted.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why might monetary policy still be asked to watch financial risks?","a":"Because in practice macroprudential policy is not fully effective, not least since a large part of the financial system operates beyond the reach of regulation.<sup class=\"fn\" data-fn=\"5\"></sup> Interest rates reach every corner of the economy, so they can help contain systemic risk, but the same research bulletin warned that this may mean sacrificing some price stability.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Tinbergen Rule"},
    "ec-065": {"questions":["When a large price jump from twelve months before drops out of the comparison, annual inflation can fall in a month of quite normal prices, the kind of <span class=\"blank\">_____</span> a careful reader checks first.","Because its denominator keeps growing, an index rising twenty points a year from 100 reports ever smaller inflation rates, a <span class=\"blank\">_____</span> that comes from arithmetic and not from weaker price pressure."],"abstract":"A <b>base effect</b> is the part of a change in a growth rate that comes from what happened in the base period it is measured against, usually the same month a year earlier, not from anything happening now.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Annual inflation compares a price index with its value 12 months before, so each month’s change in that rate reflects both the latest price movement and the one that has just dropped out of the comparison.<sup class=\"fn\" data-fn=\"2\"></sup> If prices jumped a year ago, the annual rate falls as that jump drops out, and if they slumped it rises, even when the latest month is quite normal.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A steady absolute rise also gives a shrinking percentage as the base grows, so an index climbing 20 points a year from 100 shows inflation of 20 per cent, then 16.67, then 14.29.<sup class=\"fn\" data-fn=\"5\"></sup> Measuring a base effect takes judgement, because deciding whether a price movement a year earlier was unusual or extreme is not a purely technical question.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Statisticians warn users to watch for it whenever a claim rests on a 12-month growth rate, where the usual preference for annual over monthly figures can mislead.<sup class=\"fn\" data-fn=\"1\"></sup> After the collapse of spring 2020, the UK’s statistical office pointed out that even if monthly GDP stayed flat, its 12-month growth would jump to nearly 25 per cent in April 2021 while the economy remained below its pre-pandemic level.<sup class=\"fn\" data-fn=\"1\"></sup> Fuel showed the same thing in prices, for in April 2020 fuels and lubricants subtracted 0.30 percentage points from the annual CPIH rate and a year later they added 0.28, a swing of 0.58 points.<sup class=\"fn\" data-fn=\"1\"></sup> In the euro area, base effects linked to the collapse in oil prices early in 2020 contributed around 5 percentage points to the rise in energy inflation between December 2020 and March 2021.<sup class=\"fn\" data-fn=\"3\"></sup> One remedy is to measure from a fixed point, and economists at the Federal Reserve Bank of Dallas proposed averaging inflation since the start of the pandemic to avoid distortions from spring 2020.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Grant Fitzner, “Beware Base Effects,” <i>National Statistical</i>, Office for National Statistics blog, 19 May 2021, https://blog.ons.gov.uk/2021/05/19/beware-base-effects/. [Open access]","European Central Bank, “Base Effects and Their Impact on HICP Inflation in Early 2005,” Box 3, <i>Monthly Bulletin</i>, January 2005, https://www.ecb.europa.eu/pub/pdf/other/mb200501_focus03.en.pdf. [Open access]","Ieva Rubene and Gerrit Koester, “Recent Dynamics in Energy Inflation: The Role of Base Effects and Taxes,” <i>ECB Economic Bulletin</i>, no. 3 (2021), https://www.ecb.europa.eu/pub/economic-bulletin/focus/2021/html/ecb.ebbox202103_04~0a0c8f0814.en.html. [Open access]","Tyler Atkinson, Jim Dolmas and Marc P. Giannoni, “Average Inflation over the Pandemic Avoids ‘Base-Effect’ Distortions,” <i>Dallas Fed Economics</i>, Federal Reserve Bank of Dallas, 13 May 2021, https://www.dallasfed.org/research/economics/2021/0513. [Open access]","Sweta Satya, “Base Effect,” <i>Arthapedia</i>, Indian Economic Service, Government of India, https://ies.gov.in/arthapedia/concept/base-effect. [Open access]","European Central Bank, “Base Effects and Their Impact on HICP Inflation in 2013,” Box 5, <i>Monthly Bulletin</i>, February 2013, https://www.ecb.europa.eu/pub/pdf/other/mb201302_focus05.en.pdf. [Open access]"],"why":[{"q":"Why can annual inflation fall in a month when prices rise normally?","a":"Because the change in the annual rate is roughly this month’s price change minus the change in the same month a year earlier.<sup class=\"fn\" data-fn=\"2\"></sup> In January 2004 annual euro-area energy inflation fell from 1.8 to −0.4 per cent despite a monthly rise of 0.9 per cent, because a 3.1 per cent jump from January 2003 had dropped out of the comparison.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did statisticians in 2021 warn against trusting 12-month growth rates?","a":"Because the dramatic falls of April 2020, when monthly GDP dropped a record 18.7 per cent, had become the base for the comparison.<sup class=\"fn\" data-fn=\"1\"></sup> Double-digit growth would reflect that low base rather than a boom, so the advice was to compare activity with February 2020 or to set the latest three months against the previous quarter.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why is the size of a base effect hard to pin down?","a":"Because treating a base effect as the result of an unusual movement a year earlier requires a judgement about what counts as unusual.<sup class=\"fn\" data-fn=\"2\"></sup> Analysts therefore separate the dropping-out of old changes from the latest month’s news, or sidestep the problem by averaging over a longer period from a fixed starting point.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Base effect"},
    "ec-066": {"questions":["Universities judged on what auditors count soon reshape their work around the counting, an extension of <span class=\"blank\">_____</span> far beyond the British monetary policy it was first stated about in 1975.","Because the people being measured can react to the measuring, <span class=\"blank\">_____</span> marks a limit on economic method, since a relationship seen while nobody steered by it may vanish once somebody does."],"abstract":"<b>Goodhart’s law</b> is the principle that any observed statistical regularity will tend to collapse once pressure is placed upon it for control purposes.<sup class=\"fn\" data-fn=\"1\"></sup> Its point is that the people and firms behind a statistic respond to how they are steered, so a pattern that held while it was merely observed can break as soon as policy begins to lean on it.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> It was set out in 1975 in a paper on British monetary management, whose new approach adopted in 1971 had proved troublesome and at times unhappy to operate.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> Over the following decade Britain set targets for the growth of a broad money aggregate from July 1976, made them the centrepiece of its medium-term strategy in March 1980 and abandoned them in October 1985.<sup class=\"fn\" data-fn=\"3\"></sup> The United States ran its own experiment with money-growth targets from October 1979 to September 1982, an episode some economists took as evidence against such targets.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> The law names a limit that economics shares with the other social sciences, because the things being studied can change their behaviour once they are measured and steered.<sup class=\"fn\" data-fn=\"1\"></sup> A close relative from social research holds that the more a quantitative indicator is used for social decision-making, the more it is exposed to corruption and the more it distorts the processes it was meant to monitor.<sup class=\"fn\" data-fn=\"1\"></sup> The argument that people’s expectations adapt to policy makes a related point about economic models, since a government cannot reliably exploit forecasting errors that rational people will not keep making.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> The idea now reaches far beyond money, to the audit of universities and public services, where measuring performance for national scrutiny can take on a life of its own that jeopardises the work it audits.<sup class=\"fn\" data-fn=\"7\"></sup> Its wide popular use has stretched it to the point of ambiguity, and recent work separates at least four ways in which optimising a measure can break its link with the goal it stood for.<sup class=\"fn\" data-fn=\"1\"></sup>","sources":["David Manheim and Scott Garrabrant, “Categorizing Variants of Goodhart’s Law,” arXiv:1803.04585, version 4 (2019), https://arxiv.org/abs/1803.04585. [Open access]","C. A. E. Goodhart, “Problems of Monetary Management: The UK Experience,” in <i>Monetary Theory and Practice</i> (London: Palgrave, 1984), 91–121, https://doi.org/10.1007/978-1-349-17295-5_4. [Paywalled]","Edward Nelson, “UK Monetary Policy 1972–97: A Guide Using Taylor Rules,” Bank of England working paper (London: Bank of England, 2000), https://www.bankofengland.co.uk/-/media/boe/files/working-paper/2000/uk-monetary-policy-1972-1997-a-guide-using-taylor-rules.pdf. [Open access]","Bennett T. McCallum, “Monetarism,” in <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/Monetarism.html. [Open access]","Thomas J. Sargent, “Rational Expectations,” in <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/RationalExpectations.html. [Open access]","Nicola Acocella, Giovanni Di Bartolomeo and Andrew Hughes Hallett, “The Theory of Economic Policy: From a Theory of Control to a Theory of Conflict (Resolutions),” Working Paper 91, Sapienza University of Rome, December 2011, https://memotef.web.uniroma1.it/sites/default/files/allegati/2024-07/FullTextWP91.pdf. [Open access]","Marilyn Strathern, “‘Improving Ratings’: Audit in the British University System,” <i>European Review</i> 5, no. 3 (1997): 305–21, https://doi.org/10.1002/(SICI)1234-981X(199707)5:3%3C305::AID-EURO184%3E3.0.CO;2-4. [Paywalled]"],"why":[{"q":"Why might a relationship collapse once policy starts to rely on it?","a":"Because the classical way of advising governments treated the economy as a fixed system that does not react to policy, while real people and firms have objectives of their own and respond to what the policymaker does.<sup class=\"fn\" data-fn=\"6\"></sup> If they form expectations rationally, a government cannot manipulate their forecasting errors in a predictable and reliable way.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why is the law tied to British monetary policy?","a":"Because it was first stated about the United Kingdom’s monetary management after 1971, whose new approach had proved troublesome to operate.<sup class=\"fn\" data-fn=\"2\"></sup> Britain then targeted the growth of a broad money aggregate from 1976, made it the centrepiece of its medium-term financial strategy in 1980 and abandoned it in October 1985.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why has the meaning of the law become harder to pin down?","a":"Because it has been interpreted ever more widely, as have its relatives Campbell’s law and the Lucas critique, which were also stated narrowly at first.<sup class=\"fn\" data-fn=\"1\"></sup> One classification separates regressional, extremal, causal and adversarial failures, depending on whether the break comes from noise, from pushing into new territory, from the regulator’s own action or from an agent with different goals.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Goodhart's law"},
    "ec-067": {"questions":["A coin game whose prize doubles with every toss before the first head has an infinite <span class=\"blank\">_____</span>, yet few would pay much to play, which is why outcomes came to be weighed by usefulness.","Where the odds are known, as with dice or the statistics insurers keep, a gamble can be summarised by its <span class=\"blank\">_____</span>, the long-term average its outcomes would produce over many repetitions."],"abstract":"The <b>expected value</b> of an uncertain prospect is the average of its possible outcomes, each weighted by its probability, and it is often described as the long-term average that many repetitions would produce.<sup class=\"fn\" data-fn=\"1\"></sup> It is the natural tool for uncertainty that takes the form of risk in the narrow sense, a quantity susceptible of measurement because the possible outcomes and their chances can be known.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Risk analysis often summarises a hazard the same way, as the probability of an unwanted event multiplied by a measure of its severity, a use of the word that is relatively new although such calculations go back to the 17th century.<sup class=\"fn\" data-fn=\"2\"></sup> A measurable risk can be pooled, and insurance spreads it across a large number of people so that each person’s contingency becomes a fixed cost.<sup class=\"fn\" data-fn=\"4\"></sup> An insurer that can sort customers into risk groups can charge each group its expected losses, and a premium equal to what the average member of the group collects is called actuarially fair.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> Expected value alone is a poor guide to choice, as a coin-tossing game with an infinite expected payout shows, since hardly anyone would pay a large sum to play it.<sup class=\"fn\" data-fn=\"7\"></sup> The answer published in 1738 was to weigh outcomes by their usefulness to the person, the root of expected utility theory, whose slogan is to choose the act with the highest expected utility.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A risky alternative is also often described by two numbers, its expectation value and its standard deviation, which measures how widely the outcomes are spread around that average.<sup class=\"fn\" data-fn=\"2\"></sup> All of this needs the probabilities to be available, and decision theorists call a choice in which the options come with a probability distribution over outcomes a choice under risk.<sup class=\"fn\" data-fn=\"8\"></sup> Knight separated probabilities known in advance, as with dice, from statistical ones read off grouped cases, as in fire insurance, and from mere estimates, which he treated as different in kind.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Barbara Illowsky and Susan Dean, <i>Introductory Statistics 2e</i>, “4.2 Mean or Expected Value and Standard Deviation” (Houston: OpenStax, Rice University, 2023), https://openstax.org/books/introductory-statistics-2e/pages/4-2-mean-or-expected-value-and-standard-deviation. [Open access]","Sven Ove Hansson, “Risk,” in <i>The Stanford Encyclopedia of Philosophy</i>, ed. Edward N. Zalta and Uri Nodelman, https://plato.stanford.edu/entries/risk/. [Open access]","Frank H. Knight, <i>Risk, Uncertainty and Profit</i> (Boston: Houghton Mifflin, 1921), pt. 1, ch. 1, Econlib, https://www.econlib.org/library/Knight/knRUP.html?chapter_num=3#book-reader. [Open access]","Frank H. Knight, <i>Risk, Uncertainty and Profit</i> (Boston: Houghton Mifflin, 1921), pt. 3, ch. 7, “The Meaning of Risk and Uncertainty,” Econlib, https://www.econlib.org/library/Knight/knRUP.html?chapter_num=9#book-reader. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “16.2 Insurance and Imperfect Information” (Houston: OpenStax, Rice University, 2022), https://openstax.org/books/principles-economics-3e/pages/16-2-insurance-and-imperfect-information. [Open access]","R. A. Briggs, “Normative Theories of Rational Choice: Expected Utility,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/rationality-normative-utility/. [Open access]","Martin Peterson, “The St. Petersburg Paradox,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/paradox-stpetersburg/. [Open access]","Katie Steele and H. Orri Stefánsson, “Decision Theory,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/decision-theory/. [Open access]"],"why":[{"q":"Why can an insurer price a policy when no one knows who will crash?","a":"Because it does not need to know which individual will have an accident, only how much a whole risk group costs on average.<sup class=\"fn\" data-fn=\"5\"></sup> Insurance extends the base of a risk across many people and turns each person’s uncertain loss into a fixed cost, which works because the chances can be measured from grouped cases.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why is the highest expected value not always the best choice?","a":"Because a game can have an infinite expected payout and still be worth very little to the person playing it, which is the St Petersburg paradox.<sup class=\"fn\" data-fn=\"7\"></sup> Expected utility theory responds by weighting outcomes by what they are worth to the chooser, and it is a theory of how people should decide that often predicts badly how they actually do.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why does the expected value depend on knowing the probabilities?","a":"Because it is built by multiplying each outcome by its probability, so it can only be computed when a probability distribution over outcomes exists.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> Where people must instead consult their own beliefs about what will happen, decision theorists speak of choice under uncertainty rather than choice under risk.<sup class=\"fn\" data-fn=\"8\"></sup>"}],"wiki":"Expected value"},
    "ec-068": {"questions":["A fire insurer can turn a measurable risk into a fixed cost, but an outcome whose probability nobody can estimate involves <span class=\"blank\">_____</span>, for which no premium can be calculated at all.","Preferring a bet on an urn of known proportions to one on an urn of unknown proportions shows how people treat <span class=\"blank\">_____</span>, odds that cannot be measured, differently from ordinary risk."],"abstract":"<b>Knightian uncertainty</b> is uncertainty about outcomes whose probability cannot be known, as distinct from risk, where the probability can be determined and the outcome insured against.<sup class=\"fn\" data-fn=\"3\"></sup> The idea comes from a book of 1921 which argued that the word ‘risk’ means in some cases a quantity susceptible of measurement and at other times something distinctly not of that character.<sup class=\"fn\" data-fn=\"1\"></sup> A measurable uncertainty, or risk proper, was in its author’s view so different from an unmeasurable one that it was not in effect an uncertainty at all.<sup class=\"fn\" data-fn=\"1\"></sup> The difference turns on classification, since some probabilities are known in advance, as with dice, and others are read off a large group of similar cases, as with fire, but some situations are too unique to group.<sup class=\"fn\" data-fn=\"2\"></sup> Business decisions, the book argued, generally deal with situations far too unique for any statistical tabulation to guide them, so they rest on estimates, judgement or intuition rather than calculated chances.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> That gave the idea its economic work, for true uncertainty explained why perfect competition need not eliminate profit, which entrepreneurs would earn even in long-run equilibrium as a return for bearing it.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Insurance can turn a measurable risk into a fixed cost by spreading it over many people, but no one can pool an outcome that has no group of like cases, and judging such outcomes is the entrepreneur’s role.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> The book received only two reviews when it appeared, yet it went on to change how economic theory was taught, becoming central to the principles course at the London School of Economics by 1935.<sup class=\"fn\" data-fn=\"4\"></sup> Decision theorists still separate choice under risk, where the options come with a probability distribution over outcomes, from choice under uncertainty, where people must consult their own beliefs about what will happen.<sup class=\"fn\" data-fn=\"5\"></sup> A famous example with an urn holding balls of unknown proportions shows that the difference can matter, since preferences that seem reasonable there cannot be represented by an expected utility function.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Frank H. Knight, <i>Risk, Uncertainty and Profit</i> (Boston: Houghton Mifflin, 1921), pt. 1, ch. 1, Econlib, https://www.econlib.org/library/Knight/knRUP.html?chapter_num=3#book-reader. [Open access]","Frank H. Knight, <i>Risk, Uncertainty and Profit</i> (Boston: Houghton Mifflin, 1921), pt. 3, ch. 7, “The Meaning of Risk and Uncertainty,” Econlib, https://www.econlib.org/library/Knight/knRUP.html?chapter_num=9#book-reader. [Open access]","David R. Henderson, “Frank Hyneman Knight,” in <i>The Concise Encyclopedia of Economics</i>, Econlib, https://www.econlib.org/library/Enc/bios/Knight.html. [Open access]","Ross Emmett, “A Century of Risk, Uncertainty, and Profit,” Econlib, 3 December 2018, https://www.econlib.org/library/Columns/y2018/Emmettriskuncertaintyprofit.html. [Open access]","Katie Steele and H. Orri Stefánsson, “Decision Theory,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/decision-theory/. [Open access]","R. A. Briggs, “Normative Theories of Rational Choice: Expected Utility,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/rationality-normative-utility/. [Open access]"],"why":[{"q":"Why can insurance not remove this kind of uncertainty?","a":"Because insurance works by spreading a contingency over a large number of people and turning it into a fixed cost, and that depends on grouping enough like cases to measure the chance.<sup class=\"fn\" data-fn=\"2\"></sup> A truly unique situation has no others, or too few, to tabulate, so no probability of any value can be inferred for it.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does true uncertainty explain the existence of profit?","a":"Because the question was why perfect competition would not wipe profits out, and the answer was that entrepreneurs earn them, even in long-run equilibrium, as a return for putting up with uncertainty.<sup class=\"fn\" data-fn=\"3\"></sup> True uncertainty prevents competition from working itself out perfectly and so accounts for the peculiar income of the entrepreneur.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does the distinction still matter in the theory of choice?","a":"Because the standard representation theorem applies only to options that come with a probability distribution over outcomes, which is choice under risk.<sup class=\"fn\" data-fn=\"5\"></sup> Where probabilities are unknown, as with an urn of unknown proportions, reasonable-seeming preferences violate the independence axiom and cannot be described by expected utility at all.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Knightian uncertainty"},
    "ec-069": {"questions":["Rather than invent probabilities for futures nobody can even list, people facing <span class=\"blank\">_____</span> are urged to ask what is going on here and to act on a reference narrative that may prove wrong.","Treating every possible future as if it carried a subjective probability produces spurious precision, the charge at the heart of the argument about <span class=\"blank\">_____</span> that two British economists revived in 2020."],"abstract":"<b>Radical uncertainty</b> is uncertainty so deep that people do not know what is going to happen and have only a very limited ability even to describe the things that might happen.<sup class=\"fn\" data-fn=\"2\"></sup> It is not the uncertainty of a rare event in the long tail of a distribution, whose low probability can still be estimated, but the wide range of uncertain futures that lies between such events and the unimaginable.<sup class=\"fn\" data-fn=\"2\"></sup> Two British economists made the term the title of a book in 2020, arguing that the distinction between risk and uncertainty had been buried by economists for over half a century and needed to be restored.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Their target was the habit of treating people as if they attached subjective probabilities to every possible future event, which in their view is tempting but misguided because it leads to spurious precision.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> The contrast they revived goes back to 1921, when risk was described as a quantity susceptible of measurement and uncertainty as something distinctly not of that character.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> The pandemic was their classic example, since pandemics were known to be likely but nobody knew enough to attach a probability to a virus emerging in Wuhan in December 2019.<sup class=\"fn\" data-fn=\"1\"></sup> A review of the Bank of England’s forecasting in 2024 made a related point about economies in general, calling them complex, ever-changing and subject to unpredictable shocks such as pandemics or wars.<sup class=\"fn\" data-fn=\"6\"></sup> Instead of filling gaps in knowledge with probability calculations, the book advises robust and resilient strategies and action organised around a ‘reference narrative’ that its users accept may be wrong.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Its first question for any decision is ‘what is going on here’, a habit the authors illustrate from the discussions of the Bank of England’s Monetary Policy Committee.<sup class=\"fn\" data-fn=\"3\"></sup> One reviewer found the book impressive but often repetitious, and noted how closely it echoes an older Austrian distinction between probability that applies to a class of events and probability for a single case.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["NYU Stern Department of Economics, “Radical Uncertainty: Decision-Making Beyond the Numbers, by Mervyn King and John Kay,” 17 July 2020, https://www.stern.nyu.edu/experience-stern/about/departments-centers-initiatives/academic-departments/economics/news/radical-uncertainty-decision-making-beyond-the-numbers. [Open access]","Mikko Arevuo, “Radical Uncertainty: Decision-Making for an Unknowable Future,” book review, Institute of Economic Affairs, 1 April 2020, https://iea.org.uk/?p=32872. [Open access]","Vicky Pryce, review of <i>Radical Uncertainty</i>, by John Kay and Mervyn King, Society of Professional Economists, 24 April 2020, https://www.spe.org.uk/reading-room/book-reviews/radical-uncertainty. [Open access]","Frank H. Knight, <i>Risk, Uncertainty and Profit</i> (Boston: Houghton Mifflin, 1921), pt. 1, ch. 1, Econlib, https://www.econlib.org/library/Knight/knRUP.html?chapter_num=3#book-reader. [Open access]","David Gordon, review of <i>Radical Uncertainty: Decision-Making Beyond the Numbers</i>, by John Kay and Mervyn King, <i>Quarterly Journal of Austrian Economics</i> 24, no. 1 (2021), Mises Institute, https://mises.org/quarterly-journal-austrian-economics/review-radical-uncertainty-decision-making-beyond-numbers. [Open access]","Ben S. Bernanke, <i>Forecasting for Monetary Policy Making and Communication at the Bank of England: A Review</i> (London: Bank of England, April 2024), https://www.bankofengland.co.uk/independent-evaluation-office/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review. [Open access]"],"why":[{"q":"Why is radical uncertainty not the same as a very unlikely event?","a":"Because an event in the long tail of a distribution is imaginable and well defined, so its low probability can still be estimated.<sup class=\"fn\" data-fn=\"2\"></sup> Radical uncertainty covers the far larger territory between such events and the unimaginable, a world of uncertain futures about which speculation is necessary and disagreement may never be resolved.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why do its advocates object to giving every future a probability?","a":"Because believing that we attach subjective probabilities to all possible future events is, on their account, misguided and leads to spurious precision: we crave certainties that cannot exist and invent knowledge we cannot have.<sup class=\"fn\" data-fn=\"1\"></sup> A sympathetic reviewer puts the same point bluntly, saying that a figure for such a case only expresses how confident someone feels.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why might a narrative help where probabilities cannot?","a":"Because a reference narrative, built from whatever evidence can be gathered, gives action a shape without pretending to a full list of outcomes, and its users are meant to accept that it may be wrong and that evidence may favour another story.<sup class=\"fn\" data-fn=\"3\"></sup> The aim is strategies that are robust and resilient across alternative futures rather than optimal for one forecast.<sup class=\"fn\" data-fn=\"2\"></sup>"}]},
    "ec-070": {"questions":["A survey of American economists in the 1990s found that their policy positions tracked each person’s <span class=\"blank\">_____</span> about redistribution and equity more closely than their estimates of how the economy responds.","Saying that one person’s gain outweighs another’s loss needs a <span class=\"blank\">_____</span> comparing their satisfactions, a step held in 1932 to rest on no ascertainable fact and so to lie outside economic science."],"abstract":"A <b>value judgement</b> is a claim about what is good or bad or what ought to be done, as distinct from a claim about how the world is that evidence could in principle test.<sup class=\"fn\" data-fn=\"1\"></sup> Economists borrow from philosophy the distinction between positive statements, which describe the world as it is and can be tested, and normative statements, which describe how it should be and rest on values.<sup class=\"fn\" data-fn=\"1\"></sup> In the usual division of labour, economics as a positive science helps policy makers choose the means to their ends without bearing on the choice of the ends themselves.<sup class=\"fn\" data-fn=\"2\"></sup> A classic statement of that view, published in 1932, held that economics deals with ascertainable facts and ethics with valuations and obligations, with a logical gulf fixed between the two.<sup class=\"fn\" data-fn=\"3\"></sup> On the same view, comparing the satisfaction different people draw from equal incomes rests on no ascertainable fact, which is why judging that one person’s gain outweighs another’s loss has been treated as a value judgement.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> <br><br> The separation is questioned on several grounds, because economists must interpret the goals they are given, their science is a human activity governed by values, and much of it rests on a normative theory of rationality.<sup class=\"fn\" data-fn=\"2\"></sup> Values can enter research at four points, in the choice of a problem, the gathering of evidence, the acceptance of a hypothesis and the use made of the results.<sup class=\"fn\" data-fn=\"4\"></sup> Value-freedom as Max Weber understood it was a discipline of the researcher that went with openly confessing one’s own values, not a claim that values could be removed.<sup class=\"fn\" data-fn=\"7\"></sup> A survey of American labour and public economists in the 1990s found that their positions on policy were more closely related to their values than to their estimates of the relevant economic parameters.<sup class=\"fn\" data-fn=\"8\"></sup> An economist can therefore legitimately work out what policies follow from stated value premises, but the premises themselves, such as treating growth as a goal, need to be scrutinised rather than taken for granted.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics 3e</i>, “2.3 Confronting Objections to the Economic Approach” (Houston: OpenStax, Rice University, 2022), https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/economics/. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), ch. 6, Internet Archive, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","Julian Reiss and Jan Sprenger, “Scientific Objectivity,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/scientific-objectivity/. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Gunnar Myrdal, “The Equality Issue in World Development,” Prize Lecture, 17 March 1975, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1974/myrdal/lecture/. [Open access]","Sung Ho Kim, “Max Weber,” in <i>The Stanford Encyclopedia of Philosophy</i>, https://plato.stanford.edu/entries/weber/. [Open access]","Victor R. Fuchs, Alan B. Krueger and James M. Poterba, “Why Do Economists Disagree About Policy?,” NBER Working Paper 6151 (1997), published in <i>Journal of Economic Literature</i> 36, no. 3 (1998): 1387–1425, https://doi.org/10.3386/w6151. [Open access]"],"why":[{"q":"Why can evidence not settle a value judgement?","a":"Because a positive statement may be true or false and can be tested at least in principle, while a normative statement is an opinion based on values that cannot be proved true or false.<sup class=\"fn\" data-fn=\"1\"></sup> An influential essay of 1932 put it as a logical gulf: economics deals with ascertainable facts, ethics with valuations and obligations.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do economists who share the evidence still disagree about policy?","a":"Because their positions on policy turn out to be more closely related to their values, such as their views on redistribution and on efficiency against equity, than to their estimates of the economic parameters involved.<sup class=\"fn\" data-fn=\"8\"></sup> The same estimate of a policy’s effects can support opposite recommendations once different judgements about what matters are added.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup>"},{"q":"Why is the line between fact and value in economics disputed?","a":"Because economists have to interpret the incomplete goals that policy makers give them, and economics, like any human activity, is itself governed by values.<sup class=\"fn\" data-fn=\"2\"></sup> Its theory of rational choice is normative, people’s views of right and wrong are shaped by beliefs about how people behave, and interests can cloud judgement on questions that touch them directly.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Value judgment"},
    "ec-071": {"questions":["The two fundamental theorems of <span class=\"blank\">_____</span> link perfectly competitive markets to Pareto efficiency, and the second says any such allocation is reachable once endowments are suitably redistributed.","An older version of <span class=\"blank\">_____</span> confined itself to the part of social welfare measurable with money and argued that transfers from rich to poor raise the total of satisfaction."],"abstract":"<b>Welfare economics</b> is the branch of economics that asks whether one economic outcome, institution or policy is better for a society than another.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It is the traditional name for normative economics, and in the first half of the 20th century most leading economists worked on it, above all on criteria for judging public policies.<sup class=\"fn\" data-fn=\"1\"></sup> Arthur Pigou's <i>The Economics of Welfare</i> limited the subject to economic welfare, the part of social welfare that can be brought “directly or indirectly into relation with the measuring-rod of money”.<sup class=\"fn\" data-fn=\"3\"></sup> The same book reasoned that moving income from a relatively rich person to a relatively poor one of similar temperament must raise the aggregate sum of satisfaction, because it meets more intense wants at the expense of less intense ones.<sup class=\"fn\" data-fn=\"4\"></sup> Most economists now identify a person's welfare with the satisfaction of their preferences, a choice that keeps questions about paternalism from arising but makes it doubtful whether welfare can be compared between people.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The field's best-known results are its two fundamental theorems, both about markets that are perfectly competitive.<sup class=\"fn\" data-fn=\"2\"></sup> The first says that such an equilibrium is Pareto efficient, so no one could be made better off without someone being made worse off, and the second that any Pareto-efficient allocation can be reached through competitive markets once endowments are suitably redistributed.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Neither describes a real economy, since no economy has ever been in perfectly competitive equilibrium, and the second has been read as licensing a division of labour in which economists study efficiency and others study justice.<sup class=\"fn\" data-fn=\"2\"></sup> The 1972 Nobel prize in economics was shared for work that included welfare theory, among it criteria for comparing different economic situations and a theorem that a social welfare function cannot be built out of individual preferences.<sup class=\"fn\" data-fn=\"5\"></sup> Around 2000 it was no longer a subject every student was expected to learn, partly because it had repeatedly failed to reach conclusive results, though the 1998 prize went to welfare economics itself and interest has since revived.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Arthur C. Pigou, <i>The Economics of Welfare</i>, 4th ed. (London: Macmillan, 1932), part I, chap. 1, Econlib, https://www.econlib.org/library/NPDBooks/Pigou/pgEW1.html. [Open access]","Arthur C. Pigou, <i>The Economics of Welfare</i>, 4th ed. (London: Macmillan, 1932), part I, chap. 8, Econlib, https://www.econlib.org/library/NPDBooks/Pigou/pgEW8.html. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1972,” press release, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1972/press-release/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1998,” press release, 14 October 1998, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1998/press-release/. [Open access]","“Kenneth Arrow,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Arrow.html. [Open access]"],"why":[{"q":"Why did the older approach favour transfers from rich to poor?","a":"Because it assumed that the satisfaction a person gets from extra income falls as income rises, so a transfer from a relatively rich person to a relatively poor one of similar temperament meets more intense wants at the expense of less intense ones.<sup class=\"fn\" data-fn=\"4\"></sup> The argument depends on comparing satisfactions between people, which most later economists, who equate welfare with the satisfaction of preferences, have treated as questionable.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why do the fundamental theorems not show that real markets are best?","a":"Because they describe perfectly competitive equilibria, and no economy has ever been or will ever be in one.<sup class=\"fn\" data-fn=\"2\"></sup> Real markets have several imperfections at once, and the theory of the second best shows that fixing some of them can move a society further from the ideal rather than closer.<sup class=\"fn\" data-fn=\"2\"></sup> The second theorem also leaves the choice of distribution to others.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did welfare economics fall out of fashion late in the 20th century?","a":"Partly because of its repeated failure to provide conclusive results and its long focus on impossibility theorems, and partly because of a persistent ambiguity about whether value judgements belong in economics at all.<sup class=\"fn\" data-fn=\"1\"></sup> Interest has since revived, linked to work on inequality and redistribution and to the search for measures of social well-being beyond national income.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Welfare economics"},
    "ec-072": {"questions":["Because it needs no comparison of one person's welfare with another's, <span class=\"blank\">_____</span> became a central test in economics, though it says nothing about most policies that create losers.","Equilibrium in perfectly competitive markets achieves <span class=\"blank\">_____</span>, the first fundamental theorem of welfare economics shows, yet several such allocations usually exist and the criterion cannot rank them."],"abstract":"<b>Pareto efficiency</b> describes an allocation in which no one can be made better off without making at least one other person worse off.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> One allocation Pareto dominates another if at least one person is better off under it and nobody is worse off, and an allocation that nothing dominates in this way is called Pareto efficient or Pareto optimal.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The idea is named after Vilfredo Pareto, a railway engineer turned economist who succeeded Léon Walras at Lausanne in 1893 and published his <i>Manual of Political Economy</i> in 1906.<sup class=\"fn\" data-fn=\"3\"></sup> Its appeal is that it needs no comparison of one person's welfare with another's, since it relies only on whether each person prefers one state to another.<sup class=\"fn\" data-fn=\"2\"></sup> Efficiency here means satisfying people's preferences as fully as possible, not producing more output from each unit of input or any other technical notion.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Because most real policies hurt some people while helping others, the Pareto principle on its own is usually silent about them.<sup class=\"fn\" data-fn=\"4\"></sup> Nor is it a single target, for a game or a market can have several Pareto-efficient outcomes and the criterion gives no way of ranking them against one another.<sup class=\"fn\" data-fn=\"1\"></sup> It still carries great theoretical weight, because the first fundamental theorem of welfare economics shows that an equilibrium in perfectly competitive markets is Pareto efficient.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A weak form of the principle, that society should prefer one option to another whenever every individual does, is also one of the five conditions of Arrow's impossibility theorem.<sup class=\"fn\" data-fn=\"7\"></sup> None of this makes a Pareto-efficient outcome good, since an allocation that leaves one person with almost everything can satisfy the criterion, which tests for waste rather than for fairness.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>","sources":["CORE Econ, <i>The Economy 1.0</i>, Unit 5, “Property and Power: Mutual Gains and Conflict,” sections 5.2–5.3, https://www.core-econ.org/the-economy/book/text/05.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","“Vilfredo Pareto,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Pareto.html. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","“Kenneth Arrow,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Arrow.html. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1972,” press release, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1972/press-release/. [Open access]","Christian List, “Social Choice Theory,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 14 October 2022, https://plato.stanford.edu/entries/social-choice/. [Open access]"],"why":[{"q":"Why do economists value a criterion that needs no interpersonal comparisons?","a":"Because it lets them say that preferences are better satisfied in one state than another simply because some people prefer it and nobody prefers the alternative.<sup class=\"fn\" data-fn=\"2\"></sup> No judgement about whose satisfaction matters more is needed, which is why the criterion became central once comparisons of welfare between people were abandoned.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is the Pareto criterion often silent about real policies?","a":"Because almost every policy hurts some group for the benefit of another, and the criterion approves a change only if nobody loses.<sup class=\"fn\" data-fn=\"4\"></sup> Where there are losers it simply cannot say whether the change is better or worse, which is why compensation tests were proposed to extend it.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why can there be more than one Pareto-efficient allocation?","a":"Because any allocation that wastes nothing qualifies, however it shares out the gains.<sup class=\"fn\" data-fn=\"1\"></sup> In one two-person game three of the four possible outcomes are Pareto efficient, and every split of a sum of money between two people is efficient in this sense, including one that gives one person nothing.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Pareto efficiency"},
    "ec-073": {"questions":["A world where millions starve but no food is wasted is Pareto efficient, because the criterion ignores the <span class=\"blank\">_____</span> of food between people and asks only whether more could be had.","UK appraisal guidance puts the <span class=\"blank\">_____</span> of costs and benefits back into the sums by weighting gains to lower-income households more heavily than equal gains to richer ones."],"abstract":"<b>Distribution</b>, in economics, is the way income, wealth or the gains from an economic interaction are divided between the people involved, as distinct from how large the total is.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> Pareto efficiency, the test that no one can be made better off without someone being made worse off, is silent about it, because the criterion asks whether anything is wasted and not who gets what.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Any split of a sum of money between two people is Pareto efficient, including one that gives one of them nothing at all, and some such splits would seem very unfair.<sup class=\"fn\" data-fn=\"1\"></sup> The same holds for food, since a very unequal distribution can be Pareto efficient as long as all of it is eaten by someone who enjoys it even a little.<sup class=\"fn\" data-fn=\"1\"></sup> A world in which millions starve but no food is wasted passes the test, while one in which nobody starves but some food is wasted fails it.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Measures built on willingness to pay share the blind spot, because what a person is willing to pay depends on what they are able to pay, which tilts them towards the preferences of the rich.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Critics of money-based efficiency make the point with a wealthy woman who outbids the mother of a hungry infant for milk to wash her diamonds, an example its defenders call strained.<sup class=\"fn\" data-fn=\"3\"></sup> A policy that passes a benefit-cost test has shown only that the gainers could in principle compensate the losers, and the test does not consider how benefits and costs are spread among the people affected.<sup class=\"fn\" data-fn=\"5\"></sup> An older tradition in welfare economics put distribution at the centre, holding that more real income in the hands of the poor raises economic welfare provided the national income does not shrink.<sup class=\"fn\" data-fn=\"7\"></sup> Some official appraisal now brings distribution back in by weighting benefits to lower-income households more heavily, and UK guidance requires such weighted estimates to be shown alongside unweighted ones.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["CORE Econ, <i>The Economy 1.0</i>, Unit 5, “Property and Power: Mutual Gains and Conflict,” sections 5.2–5.3, https://www.core-econ.org/the-economy/book/text/05.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Paul Heyne, “Efficiency,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/Efficiency.html. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","US Environmental Protection Agency, National Center for Environmental Economics, “Mortality Risk Valuation,” last updated 26 January 2026, https://www.epa.gov/environmental-economics/mortality-risk-valuation. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","Arthur C. Pigou, <i>The Economics of Welfare</i>, 4th ed. (London: Macmillan, 1932), part I, chap. 8, Econlib, https://www.econlib.org/library/NPDBooks/Pigou/pgEW8.html. [Open access]"],"why":[{"q":"Why is a very unequal allocation still Pareto efficient?","a":"Because the criterion asks only whether someone could be made better off without anyone being made worse off.<sup class=\"fn\" data-fn=\"1\"></sup> Once every unit is used by someone who values it even a little, taking from the well-off to help the badly-off makes someone worse off, so the criterion cannot recommend it.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does willingness to pay favour the rich?","a":"Because the amount a person is willing to pay depends on their wealth as well as on how much they care.<sup class=\"fn\" data-fn=\"2\"></sup> Money valuations count only the preferences of those willing and able to back them with money, so compensation tests and cost-benefit sums give more weight to the rich unless they are adjusted.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does UK appraisal weight benefits by income?","a":"Because additional income is worth more to a low-income household than to a high-income one, a principle known as the diminishing marginal utility of income.<sup class=\"fn\" data-fn=\"6\"></sup> Analysts may therefore give a higher social value to benefits for lower-income households, and must show these weighted estimates alongside unweighted ones so that decision makers see the difference.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Distribution (economics)"},
    "ec-074": {"questions":["Because it asks only whether winners could pay losers, the <span class=\"blank\">_____</span> can approve a change that leaves the losers worse off, a possibility critics call small comfort to them.","Known also as the test for a potential Pareto improvement, the <span class=\"blank\">_____</span> lies behind cost-benefit analysis, where benefits exceeding costs mean gainers could in principle compensate losers."],"abstract":"The <b>compensation principle</b> holds that a change can count as an improvement for society if those who gain from it could compensate those who lose and still be better off, whether or not the compensation is ever paid.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Two economists proposed it in 1939 as a way past the Pareto principle, which approves a change only when nobody loses, and one of them was later cited for these criteria when he shared the 1972 Nobel prize.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> In one version a change passes if the gainers could compensate the losers after it, and in the other it passes if the losers could not have paid the gainers enough beforehand to give it up.<sup class=\"fn\" data-fn=\"1\"></sup> A change that passes is often called a potential Pareto improvement, meaning that what the winners would pay for it exceeds what the losers would need to be paid to accept it.<sup class=\"fn\" data-fn=\"2\"></sup> A standard illustration is free trade in cars, which helps millions of consumers at the expense of thousands of workers and shareholders in the domestic industry and passes the test if the consumers' gains outweigh those losses.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The principle underlies cost-benefit analysis, in which a policy whose total benefits exceed its total costs is said to pass because the winners could in principle compensate the losers.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Its first weakness is logical, since the same test can declare a move from one situation to another an improvement and the move back an improvement too, and combining the two versions does not remove every inconsistency.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Its second is ethical, for if the compensation is actually paid the ordinary Pareto principle already suffices, and if it is not paid the losers remain losers and the bare possibility is small comfort to them.<sup class=\"fn\" data-fn=\"1\"></sup> Because willingness to pay rises with wealth, tests of this kind also tend to favour changes that benefit the rich.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Practical appraisal has answered partly by reporting who gains and who loses, and UK guidance asks for income-weighted estimates to be presented beside the unweighted totals.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","“John R. Hicks,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Hicks.html. [Open access]","US Environmental Protection Agency, National Center for Environmental Economics, “Mortality Risk Valuation,” last updated 26 January 2026, https://www.epa.gov/environmental-economics/mortality-risk-valuation. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1972,” press release, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1972/press-release/. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]"],"why":[{"q":"Why was a test beyond the Pareto principle needed?","a":"Because most changes due to public policy hurt some groups for the benefit of others, and the Pareto principle approves a change only if nobody loses.<sup class=\"fn\" data-fn=\"1\"></sup> Without some way of weighing gains against losses it was silent about nearly every real decision, so compensation tests were proposed as a less restrictive criterion.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why can the test give contradictory answers?","a":"Because for plausible ways of computing the compensation, the same criterion may declare one situation better than a second and the second better than the first.<sup class=\"fn\" data-fn=\"1\"></sup> A change can be a potential Pareto improvement and its reversal one too, which means passing the test does not prove that the economic pie has grown.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does it matter whether the compensation is actually paid?","a":"Because if it is paid everybody gains, and the ordinary Pareto principle would have approved the change anyway.<sup class=\"fn\" data-fn=\"1\"></sup> If it is not paid, the losers remain losers, and the justice or injustice of that outcome is irrelevant to the calculation itself.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Compensation principle"},
    "ec-075": {"questions":["Whether a <span class=\"blank\">_____</span> simply adds up everyone's utility or looks only at the worst-off person is a value judgement, and each choice assumes a different kind of comparison between people.","Written as W of each person's utility in a given state, the <span class=\"blank\">_____</span> aimed to give the complete, consistent rankings that the Pareto principle and compensation tests could not provide."],"abstract":"A <b>social welfare function</b> is a rule that ranks the possible states of a society from better to worse according to how well off the individuals in each of them are.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Its classic form, written W of the utilities of each person in a given state, was set out from 1938 and is often named the Bergson–Samuelson social welfare function after the two economists who developed it.<sup class=\"fn\" data-fn=\"1\"></sup> The aim was to make complete and consistent judgements about social states, which the Pareto principle and the compensation tests could not do on their own.<sup class=\"fn\" data-fn=\"1\"></sup> In social choice theory the name is used for any method of aggregating individual preference orderings into a social ordering, which is how the best-known impossibility result about such methods was framed.<sup class=\"fn\" data-fn=\"2\"></sup> A variant that takes numerical measures of each person's welfare as its inputs, rather than rankings alone, is called a social welfare functional.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> Which function is used is a value judgement, and indexes of inequality are closely linked to welfare functions representing the values of a society.<sup class=\"fn\" data-fn=\"3\"></sup> A utilitarian function adds up everyone's utility, which assumes that differences in utility can be compared across individuals.<sup class=\"fn\" data-fn=\"3\"></sup> A function in the spirit of John Rawls judges a state only by its worst-off member, which assumes that each person's level of utility can be compared with everyone else's.<sup class=\"fn\" data-fn=\"3\"></sup> Between the two lies a continuum of functions that give growing weight to the worse-off, and an older argument for moving income from rich to poor rested on the utilitarian end, the aggregate sum of satisfaction.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Few economists now defend maximising total welfare outright, yet appraisal can still weight gains by income, as UK guidance does with a weight that rises as a group's median income falls below the national median.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Christian List, “Social Choice Theory,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 14 October 2022, https://plato.stanford.edu/entries/social-choice/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1998,” press release, 14 October 1998, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1998/press-release/. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","Arthur C. Pigou, <i>The Economics of Welfare</i>, 4th ed. (London: Macmillan, 1932), part I, chap. 8, Econlib, https://www.econlib.org/library/NPDBooks/Pigou/pgEW8.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]"],"why":[{"q":"Why did economists want a social welfare function at all?","a":"Because the Pareto principle and the compensation tests leave many pairs of social states unranked, or ranked inconsistently.<sup class=\"fn\" data-fn=\"1\"></sup> A well-defined function promised complete and consistent judgements, though building one needs some way of comparing people's welfare that ordinal preferences alone do not obviously supply.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does each social welfare function need interpersonal comparisons?","a":"Because each one weighs some people's gains against other people's losses.<sup class=\"fn\" data-fn=\"3\"></sup> Adding utilities assumes that differences in utility can be compared across individuals, and judging by the worst-off person assumes that each person's level of utility can be compared with everyone else's.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"How do social welfare functions show up in real appraisal?","a":"Through weights on gains and losses.<sup class=\"fn\" data-fn=\"1\"></sup> More sophisticated cost-benefit analysis relies on weighted sums of willingness to pay or on consistent social welfare functions instead of plain totals.<sup class=\"fn\" data-fn=\"1\"></sup> UK guidance, for example, gives a higher social value to benefits for lower-income households, using a formula built on the diminishing marginal utility of income.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Social welfare function"},
    "ec-076": {"questions":["Independence of irrelevant alternatives, unanimity and the absence of a dictator are three of the five conditions that <span class=\"blank\">_____</span> proves no aggregation rule can satisfy together for every profile of preferences.","Long read as a barrier to normative economics, <span class=\"blank\">_____</span> can be escaped when preferences lie along a single left-to-right dimension or when welfare can be compared between people."],"abstract":"<b>Arrow's impossibility theorem</b> states that no method of combining the preference rankings of two or more people over three or more alternatives into a social ranking can satisfy a short list of conditions that each look reasonable on their own.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The conditions are that the method works for any possible set of individual rankings, always yields a complete and consistent social ranking, respects unanimous preferences and has no dictator whose preferences always prevail.<sup class=\"fn\" data-fn=\"1\"></sup> The fifth, independence of irrelevant alternatives, requires the social ranking of any two options to depend only on how individuals rank those two, not on their views of anything else.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Kenneth Arrow proved the result as a graduate student, publishing it in <i>Social Choice and Individual Values</i> in 1951, and it was cited when he shared the 1972 Nobel prize in economics.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Its simplest ancestor is the paradox of voting described by Condorcet in 1785, in which three voters' rankings produce majorities for A over B, B over C and C over A, so that majority rule goes round in a cycle.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The theorem extended the framework of welfare economics to every collective decision, from elections and committees to the allocation of goods by markets.<sup class=\"fn\" data-fn=\"3\"></sup> For a long time it seemed an insurmountable obstacle to the normative branch of economics, since it suggested that individual preferences could not be aggregated into judgements about society in a theoretically satisfactory way.<sup class=\"fn\" data-fn=\"5\"></sup> One reading took it as a proof that populist democracy is impossible, while another held that it shows rankings alone carry too little information for good social choices.<sup class=\"fn\" data-fn=\"1\"></sup> There are ways out, for when preferences differ along a single dimension such as a left-to-right spectrum majority rule gives a consistent ranking, and allowing welfare to be compared between people also removes the impossibility.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Most social choice theorists now treat the result less as a dead end than as a map of trade-offs between desirable conditions, and its axiomatic method has perhaps been more influential than the theorem itself.<sup class=\"fn\" data-fn=\"1\"></sup>","sources":["Christian List, “Social Choice Theory,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 14 October 2022, https://plato.stanford.edu/entries/social-choice/. [Open access]","Michael Morreau, “Arrow’s Theorem,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 7 December 2025, https://plato.stanford.edu/entries/arrows-theorem/. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1972,” press release, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1972/press-release/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1998,” press release, 14 October 1998, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1998/press-release/. [Open access]","“Kenneth Arrow,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Arrow.html. [Open access]","“Amartya Sen,” in <i>The Concise Encyclopedia of Economics</i>, ed. David R. Henderson (Indianapolis: Liberty Fund, 2008), Econlib, https://www.econlib.org/library/Enc/bios/Sen.html. [Open access]"],"why":[{"q":"Why does majority voting fail to give a consistent social ranking?","a":"Because rankings that are each consistent can combine into a cycle.<sup class=\"fn\" data-fn=\"2\"></sup> If one voter ranks A, B, C, a second B, C, A and a third C, A, B, majorities prefer A to B, B to C and C to A, so no option beats every other and there is no social best.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why did the theorem seem so damaging to welfare economics?","a":"Because it suggested that individual preferences could not be aggregated into judgements about social states in a theoretically satisfactory way.<sup class=\"fn\" data-fn=\"5\"></sup> Constructing a social welfare function out of individual preferences, a central aim of welfare theory, appeared impossible under conditions that each looked harmless.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do comparisons of welfare between people offer a way out?","a":"Because the theorem assumes that only each person's ranking of the options is known, with no way of saying whose gain is larger.<sup class=\"fn\" data-fn=\"1\"></sup> Once welfare can be measured and compared between individuals, consistent rules without a dictator become possible, which is how later work turned the impossibility into a study of the information social choices need.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Arrow's impossibility theorem"},
    "ec-077": {"questions":["Adding up everyone's utility and ranking societies by their worst-off member both depend on <span class=\"blank\">_____</span>, which the ordinal tradition behind the best-known impossibility theorem held to be meaningless.","Because asking two people cannot show whose satisfaction is greater, <span class=\"blank\">_____</span> were set aside by the new welfare economics, which fell back on the Pareto principle and compensation tests."],"abstract":"<b>Interpersonal comparisons of utility</b> are judgements that one person gains more satisfaction or well-being from something than another does, or is better or worse off than another person.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> The older welfare economics relied on them, reasoning that income moved from a relatively rich person to a relatively poor one of similar temperament must raise the aggregate sum of satisfaction.<sup class=\"fn\" data-fn=\"2\"></sup> An influential essay of 1932 replied that there is no means of testing the magnitude of one person's satisfaction against another's, so that such comparisons fall outside the scope of any positive science.<sup class=\"fn\" data-fn=\"1\"></sup> Asking the two people would settle nothing, the argument ran, since each could insist that he had more satisfaction at the margin, and testing their blood would measure blood rather than satisfaction.<sup class=\"fn\" data-fn=\"1\"></sup> Daily life constantly assumes that the comparison can be made, but the essay took the diversity of the assumptions made at different times and places as evidence that they are conventional.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Economists who accepted the argument built a new welfare economics on the Pareto principle and compensation tests, abandoning interpersonal comparisons altogether.<sup class=\"fn\" data-fn=\"3\"></sup> The same ordinal outlook lies behind Kenneth Arrow's view that interpersonal comparison of utilities has no meaning, an assumption built into his impossibility theorem.<sup class=\"fn\" data-fn=\"4\"></sup> Many questions cannot be answered without such comparisons, since an egalitarian assessment must first establish who the worst-off are, and both adding utilities and judging by the worst-off assume some kind of comparability.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> From 1970 work in social choice showed how different assumptions about comparability, whether of levels of welfare or of gains and losses, change which collective decision rules are possible.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Most economists still equate welfare with the satisfaction of preferences and few defend maximising total welfare, while the essay's author later explained that he had meant only to show that the comparisons are normative, not useless.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>","sources":["Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 121–25, Mises Institute, https://cdn.mises.org/Essay%20on%20the%20Nature%20and%20Significance%20of%20Economic%20Science_2.pdf. [Open access]","Arthur C. Pigou, <i>The Economics of Welfare</i>, 4th ed. (London: Macmillan, 1932), part I, chap. 8, Econlib, https://www.econlib.org/library/NPDBooks/Pigou/pgEW8.html. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Christian List, “Social Choice Theory,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 14 October 2022, https://plato.stanford.edu/entries/social-choice/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1998,” press release, 14 October 1998, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1998/press-release/. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]"],"why":[{"q":"Why did the 1932 argument reject such comparisons?","a":"Because no observation can settle them.<sup class=\"fn\" data-fn=\"1\"></sup> A disagreement about one person's preferences can be resolved by asking him or watching his choices, but a disagreement about whether one person gets more satisfaction from an income than another cannot, since each could claim more and introspection does not reach another mind.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do egalitarian judgements need interpersonal comparisons?","a":"Because they must first establish who is worst off, which is itself a comparison of well-being between people.<sup class=\"fn\" data-fn=\"3\"></sup> Utilitarian sums assume that differences in utility can be compared across individuals, and the rule of judging by the worst-off assumes that levels of utility can be compared, so neither works without them.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why did abandoning the comparisons leave welfare economics so limited?","a":"Because without them the only principle left was the Pareto principle, which counts a change as an improvement only if it is one for every member of the population.<sup class=\"fn\" data-fn=\"3\"></sup> Since most policies hurt some groups to benefit others, that principle is generally silent, which led to compensation tests and later to renewed efforts to make comparisons explicitly.<sup class=\"fn\" data-fn=\"3\"></sup>"}]},
    "ec-078": {"questions":["Because willingness to pay rises with wealth, an unweighted <span class=\"blank\">_____</span> counts the preferences of the rich more heavily, which is why UK guidance now allows distributional weights.","Discounted to a net present value, the future gains and losses in a <span class=\"blank\">_____</span> of climate policy can swing on the discount rate chosen, as reviews of one influential study showed."],"abstract":"<b>Cost-benefit analysis</b> is a method of appraising a policy or project by expressing its benefits and costs in money and comparing the totals, so that a proposal whose benefits exceed its costs is said to pass the test.<sup class=\"fn\" data-fn=\"1\"></sup> Benefits are usually measured by what the people affected would be willing to pay for them, a measure that draws on a revised concept of consumer surplus, and costs by the money value of the resources used.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Benefits and costs that fall in different years are first adjusted for inflation and then discounted, so that the result can be expressed as a single net present value.<sup class=\"fn\" data-fn=\"3\"></sup> Some benefits are easy to value, such as gains to farming or tourism from cleaner water, while others, such as the satisfaction of knowing the air is clear over a place one may never visit, need special techniques to estimate.<sup class=\"fn\" data-fn=\"2\"></sup> In the United States presidential orders have encouraged its use since the early 1980s and require it for major regulations, and it is one of the main methods of British central government appraisal.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> <br><br> The method rests on the compensation principle, for passing the test means only that the gainers could in principle compensate the losers, not that anyone is actually compensated.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Because willingness to pay depends on wealth, an unadjusted analysis weights the preferences of the rich more than those of the poor, and it ignores how benefits and costs are distributed unless that is added.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> More careful versions weight willingness to pay by income or rest on an explicit social welfare function, and UK appraisal may now apply such distributional weights.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Results can turn on contested inputs, and an influential review's case for sharp, immediate cuts in greenhouse gas emissions was found to depend decisively on a near-zero discount rate.<sup class=\"fn\" data-fn=\"7\"></sup> Totals can also hide variation, since a body of environmental law whose overall benefits far exceed its costs may contain individual rules whose costs match or exceed their benefits.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["US Environmental Protection Agency, National Center for Environmental Economics, “Mortality Risk Valuation,” last updated 26 January 2026, https://www.epa.gov/environmental-economics/mortality-risk-valuation. [Open access]","<i>Principles of Economics 3e</i>, “12.4 The Benefits and Costs of U.S. Environmental Laws,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/12-4-the-benefits-and-costs-of-u-s-environmental-laws. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]","Royal Swedish Academy of Sciences, “The Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel 1972,” press release, NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/1972/press-release/. [Open access]","William D. Nordhaus, “A Review of the <i>Stern Review on the Economics of Climate Change</i>,” <i>Journal of Economic Literature</i> 45, no. 3 (2007): 686–702, https://www.aeaweb.org/articles?id=10.1257/jel.45.3.686. [Paywalled]"],"why":[{"q":"Why does passing the test not mean that everyone gains?","a":"Because where total benefits exceed total costs, some individuals usually still lose.<sup class=\"fn\" data-fn=\"1\"></sup> The test asks only whether the gainers could in principle compensate the losers, and that compensation is entirely hypothetical, so the justice of the result is irrelevant to the calculation.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why do some analysts weight benefits by income?","a":"Because an unadjusted analysis weights the preferences of the rich more than those of the poor, since willingness to pay depends on wealth.<sup class=\"fn\" data-fn=\"4\"></sup> More sophisticated versions use weighted sums of willingness to pay or consistent social welfare functions, and UK guidance gives a higher value to benefits for lower-income households.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why can the discount rate decide a climate appraisal?","a":"Because most of the benefits of cutting emissions arrive far in the future, and discounting gives later benefits less weight than earlier ones.<sup class=\"fn\" data-fn=\"3\"></sup> One review found that an influential case for immediate sharp cuts depended decisively on a near-zero discount rate and would not survive rates consistent with market interest rates.<sup class=\"fn\" data-fn=\"7\"></sup>"}],"wiki":"Cost–benefit analysis"},
    "ec-079": {"questions":["Wage premiums for dangerous jobs and spending on smoke detectors supply estimates of the <span class=\"blank\">_____</span>, which rises with income and is not the price of saving any named person.","Called the value of a prevented fatality in British appraisal, the <span class=\"blank\">_____</span> measures a small change in the risk of dying, not the worth of one individual's life."],"abstract":"The <b>value of a statistical life</b> is the total amount a large group of people would be willing to pay for small reductions in their individual risks of dying that together would be expected to prevent one death.<sup class=\"fn\" data-fn=\"1\"></sup> If each of 100,000 people would pay a given sum to cut their risk of dying this year by 1 in 100,000, one death is expected to be avoided and the value is that sum times 100,000.<sup class=\"fn\" data-fn=\"1\"></sup> It is not the amount anyone would pay to prevent the certain death of a particular person, and the agencies that use it stress that they do not place a value on individual lives.<sup class=\"fn\" data-fn=\"1\"></sup> Estimates come chiefly from the extra wages paid for riskier jobs and from purchases such as smoke detectors and car safety features, which reveal how people trade money against small risks.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> One review of more than 60 studies of such risk premiums from ten countries found that the value rises with income, with an income elasticity of about 0.5 to 0.6.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> Agencies use the figure to set the health benefits of a regulation against its costs, and the US Environmental Protection Agency recommends a central estimate of $7.4 million in 2006 dollars, updated to the year of the analysis.<sup class=\"fn\" data-fn=\"1\"></sup> British appraisal calls the same idea the value of a prevented fatality, and its guidance insists that this values a small change in the risk of death, not a life.<sup class=\"fn\" data-fn=\"3\"></sup> Leaving such risks unvalued, the guidance argues, would effectively treat human safety as having zero value.<sup class=\"fn\" data-fn=\"3\"></sup> The name invites the misreading it is meant to avoid, and the agency has proposed calling it the value of mortality risk reduction instead, since it can suggest a price on individual lives.<sup class=\"fn\" data-fn=\"1\"></sup> Because willingness to pay depends on wealth, an unadjusted measure would value risk reductions for richer people more highly, and US guidance instead applies one central estimate regardless of the income or age of the people affected.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>","sources":["US Environmental Protection Agency, National Center for Environmental Economics, “Mortality Risk Valuation,” last updated 26 January 2026, https://www.epa.gov/environmental-economics/mortality-risk-valuation. [Open access]","<i>Principles of Economics 3e</i>, “12.4 The Benefits and Costs of U.S. Environmental Laws,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/12-4-the-benefits-and-costs-of-u-s-environmental-laws. [Open access]","HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","W. Kip Viscusi and Joseph E. Aldy, “The Value of a Statistical Life: A Critical Review of Market Estimates throughout the World,” <i>Journal of Risk and Uncertainty</i> 27, no. 1 (2003): 5–76, NBER Working Paper 9487, https://www.nber.org/papers/w9487. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Marc Fleurbaey, “Normative Economics and Economic Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 6 May 2026, https://plato.stanford.edu/entries/economic-justice/. [Open access]"],"why":[{"q":"Why is it called a statistical life?","a":"Because it counts a death that is expected to be avoided on average across a large group, not a particular person who is saved.<sup class=\"fn\" data-fn=\"1\"></sup> When many people each face a slightly lower risk of dying in a year, one fewer death is expected among them, and that expected death is the statistical life.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"How do economists estimate it from behaviour?","a":"By studying how people trade money against small risks.<sup class=\"fn\" data-fn=\"1\"></sup> Riskier jobs such as ocean fishing usually pay more than safer ones to compensate for the danger, and buying smoke detectors or car safety options reveals what people will pay to lower their risk of dying.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> One review pooled more than 60 such wage-risk studies from ten countries.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why put a money value on safety at all?","a":"Because regulators must weigh the benefits of saving lives against the costs of doing so when they decide which rules are reasonable.<sup class=\"fn\" data-fn=\"2\"></sup> British guidance argues that not valuing changes in the risk of death would effectively treat human safety as having zero value in appraisal.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Value of a statistical life"},
    "ec-080": {"questions":["Pure time preference plus consumption growth weighted by how fast extra consumption loses value gives the <span class=\"blank\">_____</span> that decides how much a distant benefit counts today.","Whether climate policy demands sharp immediate cuts in emissions turned, critics argued, on the near-zero <span class=\"blank\">_____</span> that one influential review used to weigh the well-being of future generations."],"abstract":"The <b>social discount rate</b> is the rate at which a public appraisal reduces the weight given to costs and benefits the further in the future they fall, so that they can be expressed as present values.<sup class=\"fn\" data-fn=\"1\"></sup> It rests on social time preference, the principle that people generally prefer to receive benefits sooner and to bear costs later.<sup class=\"fn\" data-fn=\"1\"></sup> It is a real rate, applied only after the effects of general inflation have been removed, and it is never simply added to an inflation rate.<sup class=\"fn\" data-fn=\"1\"></sup> The standard derivation, the Ramsey rule after a 1928 model of saving, adds a rate of pure time preference to the expected growth of consumption multiplied by a parameter for how fast the value of extra consumption falls as people grow richer.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> In 2026 UK guidance cut its rate from 3.50 to 3.00 per cent for the first 30 years of a proposal, with lower rates beyond, using 0.5 per cent pure time preference and 1.5 per cent growth in consumption per head.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"1\"></sup> <br><br> Even modest rates shrink distant values sharply, and at that rate a benefit received five years from now is worth only about 86 per cent of the same benefit today.<sup class=\"fn\" data-fn=\"1\"></sup> Pure time preference is the contested part, since several philosophers and economists have rejected counting future people's well-being for less merely because it comes later, and the author of the 1928 model called such discounting “ethically indefensible”.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> An influential review of the economics of climate change used a pure time preference of 0.1 per cent a year and called for sharp, immediate cuts in greenhouse gas emissions.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Critics replied that its conclusions depended decisively on that near-zero rate and would not survive assumptions consistent with market real interest rates and savings rates.<sup class=\"fn\" data-fn=\"5\"></sup> Others argued that economists are much less sure of the right rate than is usually admitted, and that climate spending may be better seen as insurance against a small chance of ruinous catastrophe.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["HM Treasury, <i>The Green Book: Appraisal and Evaluation in Central Government</i> (London: HM Treasury, 2026), https://www.gov.uk/government/publications/the-green-book--2/the-green-book-2026. [Open access]","HM Treasury, “Green Book Discount Rate Review: HM Treasury Response” (London: HM Treasury, 2026), https://www.gov.uk/government/publications/green-book-discount-rate-review-2026/green-book-discount-rate-review-hm-treasury-response. [Open access]","Partha Dasgupta, “Ramsey and Intergenerational Welfare Economics,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 2 June 2023, https://plato.stanford.edu/entries/ramsey-economics/. [Open access]","Lukas Meyer, “Intergenerational Justice,” <i>The Stanford Encyclopedia of Philosophy</i>, substantive revision 17 July 2026, https://plato.stanford.edu/entries/justice-intergenerational/. [Open access]","William D. Nordhaus, “A Review of the <i>Stern Review on the Economics of Climate Change</i>,” <i>Journal of Economic Literature</i> 45, no. 3 (2007): 686–702, https://www.aeaweb.org/articles?id=10.1257/jel.45.3.686. [Paywalled]","Martin L. Weitzman, “A Review of the <i>Stern Review on the Economics of Climate Change</i>,” <i>Journal of Economic Literature</i> 45, no. 3 (2007): 703–24, https://www.aeaweb.org/articles?id=10.1257/jel.45.3.703. [Paywalled]"],"why":[{"q":"Why should a future benefit count for less than a present one?","a":"Partly because people generally prefer to receive benefits sooner and bear costs later, the principle of social time preference.<sup class=\"fn\" data-fn=\"1\"></sup> The rate also reflects expected growth, since if future people are richer an extra unit of consumption will matter less to them, which is the growth term of the Ramsey rule.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is pure time preference so controversial?","a":"Because it discounts future people's well-being merely because it comes later.<sup class=\"fn\" data-fn=\"4\"></sup> The author of the 1928 saving model called this ethically indefensible, yet in one stylised model setting it close to zero produces an optimal saving rate of 98 per cent, a figure described as outlandish.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did critics doubt the climate review's conclusions?","a":"Because one found that its case for extreme immediate action depended decisively on a near-zero discount rate and would not survive rates consistent with market interest and savings rates.<sup class=\"fn\" data-fn=\"5\"></sup> Another was sceptical of the low rate but argued that the right rate is far less certain than usually admitted, and that climate spending is better seen as insurance against catastrophe.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Social discount rate"},
    "ec-081": {"questions":["Textbooks keep testable positive statements apart from value-laden normative ones, yet the field of <span class=\"blank\">_____</span> exists because judging economic outcomes as fair or unfair cannot be avoided.","Whether a fair outcome is judged by its inequality or by the procedure that produced it is a question for <span class=\"blank\">_____</span>, which no science settles but economics can clarify."],"abstract":"<b>Economic ethics</b> is the study of the moral questions raised by economic life and by economics itself, where the appraisal of outcomes, institutions and processes meets the analysis of how they work.<sup class=\"fn\" data-fn=\"1\"></sup> The questions are far older than the discipline, and Aristotle held that usury was most reasonably hated, because its gain comes from money itself and not from the exchange for which money was invented.<sup class=\"fn\" data-fn=\"2\"></sup> Medieval scholastics asked when a price was just, and Aquinas judged it sinful to use deceit to sell above the just price, while allowing that such a price rested on an estimate rather than on mathematical precision.<sup class=\"fn\" data-fn=\"3\"></sup> Modern textbooks separate positive statements, which describe the world as it is and can be tested, from normative statements about how it should be, which rest on values.<sup class=\"fn\" data-fn=\"4\"></sup> An influential statement of 1932 drew the line sharply, holding that economics deals with ascertainable facts and ethics with valuations and obligations, with a logical gulf between them.<sup class=\"fn\" data-fn=\"5\"></sup> <br><br> In practice the line is hard to hold, since economists also advise on how to fix the economy and normative economics is a whole field, standardly called welfare economics.<sup class=\"fn\" data-fn=\"1\"></sup> Economists typically judge outcomes by welfare, understood as the satisfaction of preferences, partly in the hope that welfare can be kept apart from questions of equality, freedom and justice.<sup class=\"fn\" data-fn=\"1\"></sup> A judgement of fairness may concern the outcome itself, such as how unequal it is, or the procedure that produced it, such as whether exchange was voluntary and opportunities were equal.<sup class=\"fn\" data-fn=\"6\"></sup> A further question is whether some goods, from votes to body parts, should be kept out of markets altogether, and whether banning such markets merely drives the trade into black markets.<sup class=\"fn\" data-fn=\"7\"></sup> Neither philosophy nor economics can eliminate disagreements about values, one introductory course concludes, but economics can clarify how kinds of unfairness are connected and what trade-offs a policy involves.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Aristotle, <i>Politics</i> 1.1258b, trans. H. Rackham, Aristotle in 23 Volumes, vol. 21 (Cambridge, MA: Harvard University Press; London: William Heinemann, 1944), Perseus Digital Library, https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0058%3Abook%3D1%3Asection%3D1258b. [Open access]","Thomas Aquinas, <i>Summa Theologiae</i> II-II, q. 77, a. 1, trans. Fathers of the English Dominican Province, 2nd rev. ed. (1920), New Advent, https://www.newadvent.org/summa/3077.htm. [Open access]","<i>Principles of Economics 3e</i>, “2.3 Confronting Objections to the Economic Approach,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","Lionel Robbins, <i>An Essay on the Nature and Significance of Economic Science</i> (London: Macmillan, 1932), 132, https://archive.org/details/1932RobbinsEssayOnTheNatureAndSignificanceOfEconomicScienceOCRe. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i>, “5.3 Evaluating Institutions and Outcomes: Fairness,” 2023, https://www.core-econ.org/the-economy/microeconomics/05-the-rules-of-the-game-03-evaluating-institutions-outcomes.html. [Open access]","Lisa Herzog, “Markets,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 27 August 2025, https://plato.stanford.edu/entries/markets/. [Open access]"],"why":[{"q":"Why does economic ethics predate economics as a discipline?","a":"Because moral questions about money and prices were asked long before the subject existed. Aristotle held usury most reasonably hated because its gain comes from money itself,<sup class=\"fn\" data-fn=\"2\"></sup> and Aquinas judged it sinful to sell above the just price by deceit.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why is the line between positive and normative economics hard to hold?","a":"Because economists who describe the consequences of policy also advise on how to fix the economy, and normative economics is a field of its own.<sup class=\"fn\" data-fn=\"1\"></sup> It judges outcomes chiefly by welfare understood as preference satisfaction, hoping to set aside equality, freedom and justice.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why can economics clarify a question of fairness without settling it?","a":"Because no science can remove disagreements about values, but economics can show how kinds of unfairness are connected and what trade-offs a policy involves.<sup class=\"fn\" data-fn=\"6\"></sup> Fairness itself may be judged by the outcome or by the procedure that produced it.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Economic ethics"},
    "ec-082": {"questions":["When a union faces a single dominant employer, economic models cannot pin down the wage, which settles closer to whichever side has the greater <span class=\"blank\">_____</span> at the negotiating table.","A worker's poor next best option and an employer's power to dismiss give the employer the <span class=\"blank\">_____</span> that, in a contested exchange, lets it set wages and demand hard work."],"abstract":"<b>Bargaining power</b> is the ability of a party to an exchange or negotiation to secure a larger share of what the deal creates, within the limits of what each side would accept.<sup class=\"fn\" data-fn=\"1\"></sup> Those limits are set by structural power, the value of each side's next best alternative, since nobody agrees to terms worse than walking away.<sup class=\"fn\" data-fn=\"1\"></sup> Between the limits, the share goes to whoever can set the terms, for instance by making a take-it-or-leave-it offer, or can threaten to impose heavy costs on the other side.<sup class=\"fn\" data-fn=\"1\"></sup> In laboratory ultimatum games the proposer's power to make such an offer usually wins it more than half the pie, though the responder's power to refuse limits how much it can take.<sup class=\"fn\" data-fn=\"1\"></sup> When a union meets a single dominant employer, a case called bilateral monopoly, the wage is indeterminate in the model and settles nearer to whichever side has more power.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> A union exists to change the balance of power by making employers deal with workers collectively, and import competition has weakened the bargaining power of unions where they were once strong.<sup class=\"fn\" data-fn=\"3\"></sup> The standard competitive model leaves little room for power, because it assumes that agreed terms are enforced at no cost, a world, as one critique put it, in which a handshake is a handshake.<sup class=\"fn\" data-fn=\"4\"></sup> Where some valuable part of a deal cannot be enforced by a third party, as with how hard an employee works, exchange becomes contested and each side must enforce its own claims.<sup class=\"fn\" data-fn=\"4\"></sup> An employer can then hold power over workers by paying more than their next best option and threatening to take that rent away by dismissal.<sup class=\"fn\" data-fn=\"5\"></sup> A 2021 review found considerable monopsony power among employers even in online labour markets, and one account of the falling labour share in the United States blames declining worker power, which its authors judge more convincing than rising market power among firms.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"7\"></sup>","sources":["The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i>, “5.2 Institutions and Power,” 2023, https://www.core-econ.org/the-economy/microeconomics/05-the-rules-of-the-game-02-institutions-and-power.html. [Open access]","<i>Principles of Economics 3e</i>, “14.4 Bilateral Monopoly,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/14-4-bilateral-monopoly. [Open access]","<i>Principles of Economics 3e</i>, “14.3 Market Power on the Supply Side of Labor Markets: Unions,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/14-3-market-power-on-the-supply-side-of-labor-markets-unions. [Open access]","Samuel Bowles and Herbert Gintis, “The Revenge of Homo Economicus: Contested Exchange and the Revival of Political Economy,” <i>Journal of Economic Perspectives</i> 7, no. 1 (1993): 83–102, https://doi.org/10.1257/jep.7.1.83. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i>, “6.12 How Employers Exercise Power,” 2023, https://www.core-econ.org/the-economy/microeconomics/06-firm-and-employees-12-employers-exercise-power.html. [Open access]","Alan Manning, “Monopsony in Labor Markets: A Review,” <i>ILR Review</i> 74, no. 1 (2021): 3–26, https://doi.org/10.1177/0019793920922499. [Paywalled]","Anna Stansbury and Lawrence H. Summers, “The Declining Worker Power Hypothesis: An Explanation for the Recent Evolution of the American Economy,” <i>Brookings Papers on Economic Activity</i> 2020, no. 1: 1–96, https://doi.org/10.1353/eca.2020.0000. [Paywalled]"],"why":[{"q":"Why does a better outside option raise a negotiator's share?","a":"Because nobody accepts a deal worse than walking away, so the value of each side's next best alternative sets the least it will take.<sup class=\"fn\" data-fn=\"1\"></sup> When a responder's fallback improves, the proposer must offer more to be accepted.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why is the wage indeterminate when a union meets a monopsony?","a":"Because both sides want lower employment than a competitive market would give, but they pull the wage in opposite directions.<sup class=\"fn\" data-fn=\"2\"></sup> The model fixes only a range, and the outcome lies nearer the union's wage or the employer's according to their relative bargaining power.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why does contested exchange give employers power over workers?","a":"Because effort cannot be enforced by a third party, so the employer enforces it,<sup class=\"fn\" data-fn=\"4\"></sup> paying a wage above the worker's next best option and threatening dismissal to withdraw that rent.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Bargaining power"},
    "ec-083": {"questions":["Calling the market a democracy in which every penny casts a ballot, defenders of <span class=\"blank\">_____</span> argued that entrepreneurs only seem to rule while consumers are really in command.","If markets shape people's wants rather than simply serving them, the principle of <span class=\"blank\">_____</span> loses force, since preferences would be an outcome of the economy rather than its starting point."],"abstract":"<b>Consumer sovereignty</b> is the idea that consumers, through what they choose to buy, ultimately decide what a market economy produces, in what quality and in what quantity.<sup class=\"fn\" data-fn=\"2\"></sup> A leading defender of the market wrote in 1949 that entrepreneurs only seem to be in charge, because the captain who gives their orders is the consumer, and described the market as a democracy in which every penny casts a ballot.<sup class=\"fn\" data-fn=\"2\"></sup> Firms that fail to supply what buyers want at the lowest price make losses and are replaced, so on this view profit and loss are the devices through which consumers exercise their supremacy.<sup class=\"fn\" data-fn=\"2\"></sup> Behind the idea lies an assumption about people, that they are well informed, self-interested and good judges of their own interests, so that what they prefer is what is good for them.<sup class=\"fn\" data-fn=\"1\"></sup> Textbooks add a value to the description, presenting the ability to make personal choices about buying, working and saving as an important personal freedom.<sup class=\"fn\" data-fn=\"4\"></sup> <br><br> The assumption suits normative economics, because if choices reveal what is good for people, steering their choices can never make them better off, and questions of paternalism cannot even arise.<sup class=\"fn\" data-fn=\"1\"></sup> Critics note that preferences may rest on mistaken beliefs or past manipulation, and that if satisfying them is the standard, policy could raise welfare simply by moulding people's wants.<sup class=\"fn\" data-fn=\"1\"></sup> Some argue that markets themselves shape preferences, pushing people towards material rather than immaterial goods, which would make preferences partly an outcome of the economy rather than its starting point.<sup class=\"fn\" data-fn=\"3\"></sup> Experiments in 15 small-scale societies found that behaviour in economic games varied with how far markets were integrated into daily life, a sign that preferences differ with economic organisation.<sup class=\"fn\" data-fn=\"5\"></sup> Research on the flaws of human decision-making reopened the question, and a proposal of 2003 to nudge people towards their own goals by arranging their choices, without forbidding any, became known as libertarian paternalism.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Daniel M. Hausman, “Philosophy of Economics,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 4 September 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Ludwig von Mises, <i>Human Action: A Treatise on Economics</i> (1949), 4th rev. ed., chap. 15, sec. 4, Library of Economics and Liberty, https://www.econlib.org/library/Mises/HmA/msHmA15.html. [Open access]","Lisa Herzog, “Markets,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 27 August 2025, https://plato.stanford.edu/entries/markets/. [Open access]","<i>Principles of Economics 3e</i>, “2.3 Confronting Objections to the Economic Approach,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/2-3-confronting-objections-to-the-economic-approach. [Open access]","Joseph Henrich, Robert Boyd, Samuel Bowles, Colin Camerer, Ernst Fehr, Herbert Gintis and Richard McElreath, “In Search of Homo Economicus: Behavioral Experiments in 15 Small-Scale Societies,” <i>American Economic Review</i> 91, no. 2 (2001): 73–78, https://doi.org/10.1257/aer.91.2.73. [Paywalled]","Gerald Dworkin, “Paternalism,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 9 September 2020, https://plato.stanford.edu/entries/paternalism/. [Open access]"],"why":[{"q":"Why does consumer sovereignty make paternalism hard to justify?","a":"Because if what people choose reveals their preferences, and those preferences show what is good for them, then government action to steer someone's choices can never make that person better off.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do profits matter to the idea?","a":"Because firms that fail to supply what buyers want at the cheapest price make losses and are replaced, so on this view profit and loss are how consumers exercise their supremacy over producers.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why might preferences not be a fixed starting point?","a":"Because preferences may reflect past manipulation,<sup class=\"fn\" data-fn=\"1\"></sup> markets may push people towards material goods,<sup class=\"fn\" data-fn=\"3\"></sup> and behaviour in experimental games varied with how far markets shaped daily life.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Consumer sovereignty"},
    "ec-084": {"questions":["Borrowed from the study of utterances such as 'I promise', which do what they say, the term <span class=\"blank\">_____</span> describes economic theories that help to create the behaviour they predict.","If teaching the self-interest model makes students act more selfishly, economics shows <span class=\"blank\">_____</span>, shaping through its own lessons the very conduct that it claims merely to describe."],"abstract":"<b>Performativity</b>, in economics, is the claim that economic theories can help to shape the economy they describe, so that a theory may come to fit the world partly because the world was changed to fit it.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> The word comes from the philosophy of language, where a performative utterance such as 'I promise' does something rather than reporting something, and the philosopher who named such utterances denied that they were statements at all.<sup class=\"fn\" data-fn=\"1\"></sup> The best-known case is option pricing theory, which succeeded empirically not because it found pre-existing price patterns but because markets changed in ways that made its assumptions more accurate and because traders used it in arbitrage.<sup class=\"fn\" data-fn=\"2\"></sup> Economics also helped to restore the legitimacy of financial derivatives, which had suffered a drastic loss of standing in the first half of the 20th century, and so to create the exchanges on which they were traded.<sup class=\"fn\" data-fn=\"2\"></sup> Almost no financial derivatives were traded in 1970, yet by June 2004 contracts totalling $273 trillion, in US dollars of that year, were outstanding worldwide.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> A broader version holds that social-science theories can fulfil themselves by shaping institutions, management practices and norms of behaviour, so creating the behaviour they predict.<sup class=\"fn\" data-fn=\"4\"></sup> On that view a theory can win in the marketplace for ideas regardless of its empirical validity, once its language and assumptions are taken for granted and valued.<sup class=\"fn\" data-fn=\"4\"></sup> Several studies have found that economists behave in more self-interested ways than others, although that alone cannot show whether the training caused it or self-interested people chose the subject.<sup class=\"fn\" data-fn=\"5\"></sup> The same work offered preliminary evidence that exposure to the self-interest model does encourage self-interested behaviour, so that teaching the model may help to produce the conduct it assumes.<sup class=\"fn\" data-fn=\"5\"></sup> Critics reply that not every theory can be performative, that social institutions restrict the effect, and that the idea must not slide into treating any theory that shapes the world as thereby true.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Mitchell Green, “Speech Acts,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 24 September 2020, https://plato.stanford.edu/entries/speech-acts/. [Open access]","Donald MacKenzie and Yuval Millo, “Constructing a Market, Performing Theory: The Historical Sociology of a Financial Derivatives Exchange,” <i>American Journal of Sociology</i> 109, no. 1 (2003): 107–45, https://doi.org/10.1086/374404. [Paywalled]","Donald MacKenzie, <i>An Engine, Not a Camera</i> (Cambridge, MA: MIT Press, 2006), https://doi.org/10.7551/mitpress/9780262134606.001.0001. [Paywalled]","Fabrizio Ferraro, Jeffrey Pfeffer and Robert I. Sutton, “Economics Language and Assumptions: How Theories Can Become Self-Fulfilling,” <i>Academy of Management Review</i> 30, no. 1 (2005): 8–24, https://doi.org/10.5465/amr.2005.15281412. [Paywalled]","Robert H. Frank, Thomas Gilovich and Dennis T. Regan, “Does Studying Economics Inhibit Cooperation?,” <i>Journal of Economic Perspectives</i> 7, no. 2 (1993): 159–71, https://doi.org/10.1257/jep.7.2.159. [Open access]","Nicolas Brisset, “Economics Is Not Always Performative: Some Limits for Performativity,” <i>Journal of Economic Methodology</i> 23, no. 2 (2016): 160–84, https://doi.org/10.1080/1350178X.2016.1172805. [Paywalled]"],"why":[{"q":"Why did option pricing theory come to fit market prices?","a":"Because markets changed in ways that made the theory's assumptions more accurate, and traders used the theory itself in arbitrage, rather than because it had discovered price patterns that already existed.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why can a theory spread whether or not it is true?","a":"Because a theory can shape institutions, management practices and norms, creating the behaviour it predicts, and can win in the marketplace for ideas once its language and assumptions are taken for granted and valued.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why is the evidence on economics students hard to interpret?","a":"Because finding that economists behave more self-interestedly cannot show whether the training caused it or self-interested people chose the subject, though the same work offered preliminary evidence that exposure to the model encourages such behaviour.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Performativity"},
    "ec-085": {"questions":["Because a wealth total valued in money tests only the weak form, the stricter standard of <span class=\"blank\">_____</span> asks whether critical ecosystem services themselves are being kept intact over time.","Plastic trees that absorbed carbon might satisfy the weak standard but never <span class=\"blank\">_____</span>, which denies that human-made capital can in general substitute for the functions of nature."],"abstract":"<b>Strong sustainability</b> is the view that a critical stock of natural things and processes must be preserved, because natural capital cannot in general be replaced by human-made capital.<sup class=\"fn\" data-fn=\"1\"></sup> It is defined against weak sustainability, which accepts the replacement of natural capital by produced capital of equivalent function, so long as the total productive stock is maintained.<sup class=\"fn\" data-fn=\"1\"></sup> On the weak view, artificial trees that produced oxygen, absorbed carbon and supported animal and insect life would serve as well, economically, as real ones.<sup class=\"fn\" data-fn=\"1\"></sup> The strong view is made practical through critical natural capital, the part of nature whose maintenance is essential for environmental sustainability, and through the sustainability gap between present conditions and the standards it requires.<sup class=\"fn\" data-fn=\"2\"></sup> Its defenders argue that keeping rivers, forests and biodiverse systems preserves the widest range of options for the people of the future.<sup class=\"fn\" data-fn=\"1\"></sup> <br><br> The question matters for economics because the textbook treatment frames environmental protection as one good to be traded against economic output along a production possibility frontier.<sup class=\"fn\" data-fn=\"3\"></sup> A national wealth measure that adds produced, human and natural capital together in money assumes a high degree of substitutability, and its compilers say that it measures only weak sustainability.<sup class=\"fn\" data-fn=\"4\"></sup> They add that biodiversity loss, climate change and ocean pollution are a wake-up call about the limits to replacing critical ecosystem services with human-made substitutes.<sup class=\"fn\" data-fn=\"4\"></sup> A 2021 review for the UK Treasury argued that economies are embedded within nature, and estimated that between 1992 and 2014 natural capital per person fell by nearly 40% while produced capital per person doubled.<sup class=\"fn\" data-fn=\"5\"></sup> It also noted that formal growth models assume substitution between produced capital and technical progress can sustain growth indefinitely, an assumption that strong sustainability rejects.<sup class=\"fn\" data-fn=\"6\"></sup><sup class=\"fn\" data-fn=\"1\"></sup>","sources":["Andrew Brennan and Norva Y. S. Lo, “Environmental Ethics,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 3 December 2021, https://plato.stanford.edu/entries/ethics-environmental/. [Open access]","Paul Ekins, Sandrine Simon, Lisa Deutsch, Carl Folke and Rudolf De Groot, “A Framework for the Practical Application of the Concepts of Critical Natural Capital and Strong Sustainability,” <i>Ecological Economics</i> 44, no. 2–3 (2003): 165–85, https://doi.org/10.1016/S0921-8009(02)00272-0. [Paywalled]","<i>Principles of Economics 3e</i>, “12.6 The Tradeoff between Economic Output and Environmental Protection,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/12-6-the-tradeoff-between-economic-output-and-environmental-protection. [Open access]","Glenn-Marie Lange, James Cust, Diego Herrera, Esther Naikal and Grzegorz Peszko, “The Wealth of Nations,” chap. 1 in World Bank, <i>The Changing Wealth of Nations 2021: Managing Assets for the Future</i> (Washington, DC: World Bank, 2021), box 1.1, https://openknowledge.worldbank.org/handle/10986/36400. [Open access]","Partha Dasgupta, <i>The Economics of Biodiversity: The Dasgupta Review – Headline Messages</i> (London: HM Treasury, 2021), https://assets.publishing.service.gov.uk/media/60182857d3bf7f70c2afe5bb/Dasgupta_Review_-_Headline_Messages.pdf. [Open access]","Partha Dasgupta, <i>The Economics of Biodiversity: The Dasgupta Review – Abridged Version</i> (London: HM Treasury, 2021), chap. 12.2, https://assets.publishing.service.gov.uk/media/6014329ce90e076265e4d9ba/Dasgupta_Review_-_Abridged_Version.pdf. [Open access]"],"why":[{"q":"Why does strong sustainability reject plastic trees as a substitute?","a":"Because it holds that natural capital cannot in general be replaced by human-made capital and insists on preserving a critical stock of natural things and processes, whereas the weak view accepts any replacement of equivalent function.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does a national wealth measure test only weak sustainability?","a":"Because it adds produced, human and natural capital in one monetary unit, which assumes a high degree of substitutability and hides limits, thresholds and irreversibilities in natural capital.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does the question matter for models of growth?","a":"Because formal growth models assume that substitution between produced capital and technical progress can sustain growth indefinitely,<sup class=\"fn\" data-fn=\"6\"></sup> while natural capital per person fell by nearly 40% between 1992 and 2014 as produced capital per person doubled.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Weak and strong sustainability"},
    "ec-086": {"questions":["Without careful <span class=\"blank\">_____</span>, a price index for a fixed basket overstates the rising cost of living and so understates the growth of real incomes and living standards over time.","A study finding that price indexes vastly overstated the cost of light over two centuries shows how much measured growth depends on <span class=\"blank\">_____</span> for new and improved goods."],"abstract":"<b>Quality adjustment</b> is the part of price measurement that tries to separate how much of a higher price reflects a better or different product from how much is simply inflation.<sup class=\"fn\" data-fn=\"1\"></sup> It matters because a price index for a fixed basket otherwise tends to overstate the rise in the cost of living, failing to count how better goods and new inventions improve the standard of living.<sup class=\"fn\" data-fn=\"1\"></sup> A new product can be thought of as an extreme improvement in quality, from something that did not exist to something that does, and official baskets take in new products only gradually.<sup class=\"fn\" data-fn=\"1\"></sup> Under-estimating quality improvement is equivalent to over-estimating inflation and so under-estimating real income, while over-stating quality has the opposite effect.<sup class=\"fn\" data-fn=\"3\"></sup> The problem is hardest in services such as health and education, whose output has traditionally been measured by inputs, such as the number of doctors, rather than by what is actually produced.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> A study of lighting over two centuries concluded that traditional price indexes vastly overstated the rise in the price of light and so vastly understated the rise in living standards.<sup class=\"fn\" data-fn=\"2\"></sup> It argued that price indexes miss much of the action in technological revolutions, because they miss quality changes, changes in the efficiency of goods and the efficiency gains that new products bring.<sup class=\"fn\" data-fn=\"2\"></sup> By the early 2000s improved methods meant that the US consumer price index probably overstated inflation by only about 0.5% a year.<sup class=\"fn\" data-fn=\"1\"></sup> When measured productivity growth in the United States slowed after 2004, some argued that the slowdown was partly illusory because output data missed new digital products, but tests across dozens of countries and industries found that the case faced real hurdles.<sup class=\"fn\" data-fn=\"5\"></sup> Statisticians who had worked on the figures agreed that quality change and new goods have likely caused real output growth to be understated, but judged that this old problem could not explain the recent slowdown, while official statistics are still usually published as point estimates with no measure of error.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>","sources":["<i>Principles of Economics 3e</i>, “22.2 How to Measure Changes in the Cost of Living,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/22-2-how-to-measure-changes-in-the-cost-of-living. [Open access]","William D. Nordhaus, “Do Real-Output and Real-Wage Measures Capture Reality? The History of Lighting Suggests Not,” in <i>The Economics of New Goods</i> (Chicago: University of Chicago Press, 1996), chap. 1, https://www.nber.org/books-and-chapters/economics-new-goods/do-real-output-and-real-wage-measures-capture-reality-history-lighting-suggests-not. [Open access]","Joseph E. Stiglitz, Amartya Sen and Jean-Paul Fitoussi, <i>Report by the Commission on the Measurement of Economic Performance and Social Progress</i> (Paris, 2009), recommendation 5, https://ec.europa.eu/eurostat/documents/8131721/8131772/Stiglitz-Sen-Fitoussi-Commission-report.pdf. [Open access]","Erica L. Groshen, Brian C. Moyer, Ana M. Aizcorbe, Ralph Bradley and David M. Friedman, “How Government Statistics Adjust for Potential Biases from Quality Change and New Goods in an Age of Digital Technologies: A View from the Trenches,” <i>Journal of Economic Perspectives</i> 31, no. 2 (2017): 187–210, https://doi.org/10.1257/jep.31.2.187. [Open access]","Chad Syverson, “Challenges to Mismeasurement Explanations for the US Productivity Slowdown,” <i>Journal of Economic Perspectives</i> 31, no. 2 (2017): 165–86, https://doi.org/10.1257/jep.31.2.165. [Open access]","Charles F. Manski, “Communicating Uncertainty in Official Economic Statistics: An Appraisal Fifty Years after Morgenstern,” <i>Journal of Economic Literature</i> 53, no. 3 (2015): 631–53, https://doi.org/10.1257/jel.53.3.631. [Paywalled]"],"why":[{"q":"Why does ignoring quality change exaggerate inflation?","a":"Because a higher price for a better product is then counted entirely as inflation, so the index overstates the rise in the cost of living and understates the growth of real income.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why are public services especially hard to measure?","a":"Because their output has traditionally been measured by inputs such as the number of doctors, so quality change is missed, and without a measure of quality it is impossible to tell whether growth is understated or overstated.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did mismeasurement fail to explain the US productivity slowdown?","a":"Because the slowdown occurred in dozens of countries whatever their use of digital technology,<sup class=\"fn\" data-fn=\"5\"></sup> and statisticians judged the familiar quality and new-goods biases too small and badly timed to account for it.<sup class=\"fn\" data-fn=\"4\"></sup>"}]},
    "ec-087": {"questions":["Statisticians defend where they place the <span class=\"blank\">_____</span> partly by noting that counting household services would make every homemaker self-employed and unemployment virtually impossible by definition.","Moving the <span class=\"blank\">_____</span> to take in unpaid household services would add roughly a third to conventionally measured GDP in France, Finland and the United States, by one illustrative estimate."],"abstract":"The <b>production boundary</b> is the line national accountants draw between the activities counted as production, and so as part of output and gross domestic product, and the activities left out.<sup class=\"fn\" data-fn=\"1\"></sup> In the 2008 System of National Accounts, the international standard, it includes all production destined for the market, for sale or barter, and the goods and services that governments and non-profit bodies provide free.<sup class=\"fn\" data-fn=\"1\"></sup> It also includes all goods that households produce for their own use, such as food grown for the family's table, and the housing services that owner-occupiers are treated as providing for themselves.<sup class=\"fn\" data-fn=\"1\"></sup> It excludes the services households produce for their own consumption, such as preparing meals, caring for children and cleaning, unless paid domestic staff are employed to do them.<sup class=\"fn\" data-fn=\"1\"></sup> A wider general production boundary takes in everything that one unit could provide for another, and labour statisticians align their definition of work with that wider line.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> <br><br> The standard calls the location of its own line a compromise, but a deliberate one, made so that large non-monetary values do not swamp the flows used to analyse markets, inflation and disequilibria.<sup class=\"fn\" data-fn=\"1\"></sup> It adds that counting household services would make everyone doing them self-employed, making unemployment virtually impossible by definition.<sup class=\"fn\" data-fn=\"1\"></sup> The result is that GDP captures production bought and sold in markets and misses unpaid work and leisure, which textbooks list among its limits as a measure of the standard of living.<sup class=\"fn\" data-fn=\"2\"></sup> An experimental measure of economic welfare built in 1972 added imputations for leisure and non-market work, on the ground that omitting them made economists look blindly materialistic.<sup class=\"fn\" data-fn=\"3\"></sup> One illustrative calculation put household production at about 35% of conventionally measured GDP in France, 40% in Finland and 30% in the United States over 1995 to 2006, and a United States estimate found that it would have raised nominal GDP by 39% in 1965 and 26% in 2010.<sup class=\"fn\" data-fn=\"4\"></sup><sup class=\"fn\" data-fn=\"5\"></sup>","sources":["European Commission, International Monetary Fund, Organisation for Economic Co-operation and Development, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), paras 1.40–1.42, 1.78, 6.26–6.27, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","<i>Principles of Economics 3e</i>, “19.5 How Well GDP Measures the Well-Being of Society,” OpenStax, Rice University, 2022, https://openstax.org/books/principles-economics-3e/pages/19-5-how-well-gdp-measures-the-well-being-of-society. [Open access]","William D. Nordhaus and James Tobin, “Is Growth Obsolete?,” in <i>Economic Research: Retrospect and Prospect</i>, vol. 5, <i>Economic Growth</i> (New York: National Bureau of Economic Research, 1972), chap. 1, https://www.nber.org/books-and-chapters/economic-research-retrospect-and-prospect-volume-5-economic-growth/growth-obsolete. [Open access]","Joseph E. Stiglitz, Amartya Sen and Jean-Paul Fitoussi, <i>Report by the Commission on the Measurement of Economic Performance and Social Progress</i> (Paris, 2009), recommendation 5, https://ec.europa.eu/eurostat/documents/8131721/8131772/Stiglitz-Sen-Fitoussi-Commission-report.pdf. [Open access]","Benjamin Bridgman, Andrew Dugan, Mikhael Lal, Matthew Osborne and Shaunda Villones, “Accounting for Household Production in the National Accounts, 1965–2010,” <i>Survey of Current Business</i>, May 2012, 23–36, https://apps.bea.gov/scb/pdf/2012/05%20May/0512_household.pdf. [Open access]","International Conference of Labour Statisticians, “Resolution to Amend the 19th ICLS Resolution concerning Statistics of Work, Employment and Labour Underutilization,” Resolution II, 21st ICLS (Geneva: International Labour Office, 2023), paras 6–7, https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@dgreports/@stat/documents/normativeinstrument/wcms_230304.pdf. [Open access]"],"why":[{"q":"Why are home-grown goods counted but home-made services not?","a":"Because the decision to sell or keep goods can be made after they are produced, whereas the decision to consume a household service is made before it is provided, so the standard counts goods for own use but not such services.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why does the line matter for trends in GDP?","a":"Because as households buy services they once produced for themselves, measured income rises even where living standards change less.<sup class=\"fn\" data-fn=\"4\"></sup> A United States estimate found that counting home production lowered measured nominal GDP growth over 1965 to 2010 from 6.9% to 6.7%.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why does leaving out household services not deny their value?","a":"Because the standard states that their exclusion is not a denial of their welfare properties but a judgement that including them would make the accounts less useful for economic analysis, decision-taking and policymaking.<sup class=\"fn\" data-fn=\"1\"></sup>"}]},
    "ec-088": {"questions":["Women perform about three-quarters of all <span class=\"blank\">_____</span>, more than three times as much time as men, and in no country do men and women share it equally.","Valued at the hourly minimum wage, the world's <span class=\"blank\">_____</span> would equal about nine per cent of global GDP, yet the national accounts leave nearly all of it out."],"abstract":"<b>Unpaid care work</b> is care provided without a monetary reward, covering direct personal care, such as feeding a baby or nursing a sick partner, and indirect care, such as cooking and cleaning.<sup class=\"fn\" data-fn=\"1\"></sup> International labour statistics count it as work, since they define work as any activity producing goods or services for use by others or for one's own use, with own-use production and volunteering as forms of work beside employment.<sup class=\"fn\" data-fn=\"2\"></sup> Time-use surveys in 64 countries put the total at 16.4 billion hours a day, the equivalent of two billion people working eight hours a day with no pay.<sup class=\"fn\" data-fn=\"1\"></sup> Women perform 76.2% of it, 3.2 times as much time as men, and in no country do men and women share it equally.<sup class=\"fn\" data-fn=\"1\"></sup> In countries with data, women spend between three and six hours a day on unpaid care work, while men spend between half an hour and three hours.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Most of it is missing from gross domestic product, because national accounts exclude the services households produce for their own use, apart from paid domestic staff and owner-occupiers' housing.<sup class=\"fn\" data-fn=\"4\"></sup> Valued at the hourly minimum wage, the International Labour Organization estimated it at 9% of global GDP, or US$11 trillion at 2011 purchasing power parity.<sup class=\"fn\" data-fn=\"1\"></sup> National estimates vary widely with method and coverage, and the UK's statistics office valued the country's unpaid household service work at £1.24 trillion in 2016, equivalent to 63.1% of GDP.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Models of working hours that treat all time outside paid work as free time miss it, because the value of that time depends on how much cooking, cleaning and childcare must be done within it.<sup class=\"fn\" data-fn=\"6\"></sup> In the United States, women's weekly hours of home production fell from 40 to 26 between 1965 and 2010 while men's rose from 14 to 17, and counting that shift lowers measured GDP growth.<sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Laura Addati, Umberto Cattaneo, Valeria Esquivel and Isabel Valarino, <i>Care Work and Care Jobs for the Future of Decent Work</i> (Geneva: International Labour Office, 2018), xxix, 49, https://www.ilo.org/sites/default/files/wcmsp5/groups/public/%40dgreports/%40dcomm/%40publ/documents/publication/wcms_633135.pdf. [Open access]","International Conference of Labour Statisticians, “Resolution to Amend the 19th ICLS Resolution concerning Statistics of Work, Employment and Labour Underutilization,” Resolution II, 21st ICLS (Geneva: International Labour Office, 2023), paras 6–7, https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@dgreports/@stat/documents/normativeinstrument/wcms_230304.pdf. [Open access]","Esteban Ortiz-Ospina, Bertha Rohenkohl, Pablo Arriagada, Sandra Tzvetkova and Max Roser, “Women’s Employment,” Our World in Data, first published March 2018, revised February 2026, https://ourworldindata.org/female-labor-supply. [Open access]","European Commission, International Monetary Fund, Organisation for Economic Co-operation and Development, United Nations and World Bank, <i>System of National Accounts 2008</i> (New York: United Nations, 2009), paras 1.40–1.42, 1.78, 6.26–6.27, https://unstats.un.org/unsd/nationalaccount/docs/SNA2008.pdf. [Open access]","Office for National Statistics, “Household Satellite Accounts, UK: 2015 and 2016 Estimates,” 2 October 2018, https://www.ons.gov.uk/economy/nationalaccounts/satelliteaccounts/articles/householdsatelliteaccounts/2015and2016estimates. [Open access]","The CORE Econ Team, <i>The Economy 2.0: Microeconomics</i>, “3.11 Explaining Our Working Hours: Gender and Working Time,” 2023, https://www.core-econ.org/the-economy/microeconomics/03-scarcity-wellbeing-11-gender-working-time.html. [Open access]","Benjamin Bridgman, Andrew Dugan, Mikhael Lal, Matthew Osborne and Shaunda Villones, “Accounting for Household Production in the National Accounts, 1965–2010,” <i>Survey of Current Business</i>, May 2012, 23–36, https://apps.bea.gov/scb/pdf/2012/05%20May/0512_household.pdf. [Open access]"],"why":[{"q":"Why is unpaid care left out of GDP?","a":"Because national accounts exclude the services households produce for their own consumption, except paid domestic staff and owner-occupiers' housing, partly so that large non-monetary values do not swamp the flows used to analyse markets.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why do estimates of its value differ so much?","a":"Because they depend on method and coverage: valued at the hourly minimum wage it comes to 9% of global GDP, national figures range from 2.1% of GDP in Kyrgyzstan to 41.3% in Australia,<sup class=\"fn\" data-fn=\"1\"></sup> and a UK estimate for 2016 reached 63.1% of GDP.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why does unpaid care matter for models of working hours?","a":"Because such models treat time outside paid work as free time, but its value depends on how much unpaid cooking, cleaning and childcare it must hold, and time-use studies find women doing more unpaid work than men in every country with data.<sup class=\"fn\" data-fn=\"6\"></sup>"}]},
    "ec-089": {"questions":["Rational maximising agents, strict equilibrium and a focus on efficiency are the ingredients said to drive <span class=\"blank\">_____</span>, the spread of economic method into territory beyond the discipline's old borders.","Warnings against <span class=\"blank\">_____</span> ask for humility before carrying market tools into other fields, a caution sharpened by bibliometric evidence that economics is relatively insular among the social sciences."],"abstract":"<b>Economics imperialism</b> is the extension of economic analysis into subjects such as crime, the family, discrimination and education, which had previously been dealt with, if at all, by sociology, demography and criminology.<sup class=\"fn\" data-fn=\"1\"></sup> Its method carries over the core of economic theory, assuming that individuals behave purposefully, as if maximising an objective such as utility or wealth.<sup class=\"fn\" data-fn=\"1\"></sup> An influential account of 2000 named three ingredients that let economics invade territory once outside its realm, namely rational maximising individuals, a strict commitment to equilibrium and a focus on efficiency.<sup class=\"fn\" data-fn=\"2\"></sup> Its best-known practitioner insisted that the approach is a method rather than an assumption of selfishness, since people may maximise welfare as they conceive it, whether selfish, altruistic, loyal or spiteful.<sup class=\"fn\" data-fn=\"3\"></sup> Applied to the family it reads marriage, divorce and fertility through utility-maximising, forward-looking behaviour, and applied to crime it treats illegal acts as rational choices.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Some of its exports have lasted, and the human capital approach, which treats education and training as investments, became one of the most empirically applied theories in economics.<sup class=\"fn\" data-fn=\"1\"></sup> Critics argue that the expansion carries blind spots with it, and one philosophical assessment accepts unification across disciplines only where it captures how the new subject really works, demanding strong fallibilism and no over-confident arrogance.<sup class=\"fn\" data-fn=\"4\"></sup> Economics is also relatively insular among the social sciences on bibliometric evidence, hierarchical in structure and confident in its own ability to fix the world's problems.<sup class=\"fn\" data-fn=\"5\"></sup> That confidence has brought economists influence, but it has also exposed them more to conflicts of interest, political critique and even derision.<sup class=\"fn\" data-fn=\"5\"></sup> In the wider social sciences the expansion was called rational choice imperialism, and much of the furore over it rested on a failure, by defenders and critics alike, to appreciate the limits of the model.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Royal Swedish Academy of Sciences, “The Prize in Economics 1992,” press release, 13 October 1992, https://www.nobelprize.org/prizes/economic-sciences/1992/press-release/. [Open access]","Edward P. Lazear, “Economic Imperialism,” <i>Quarterly Journal of Economics</i> 115, no. 1 (2000): 99–146, https://doi.org/10.1162/003355300554683. [Paywalled]","Gary S. Becker, “The Economic Way of Looking at Life,” Nobel Lecture, 9 December 1992, https://www.nobelprize.org/uploads/2018/06/becker-lecture.pdf. [Open access]","Uskali Mäki, “Economics Imperialism,” <i>Philosophy of the Social Sciences</i> 39, no. 3 (2009): 351–80, https://doi.org/10.1177/0048393108319023. [Paywalled]","Marion Fourcade, Etienne Ollion and Yann Algan, “The Superiority of Economists,” <i>Journal of Economic Perspectives</i> 29, no. 1 (2015): 89–114, https://doi.org/10.1257/jep.29.1.89. [Open access]","Joseph Heath, “Methodological Individualism,” <i>Stanford Encyclopedia of Philosophy</i>, substantive revision 12 June 2024, https://plato.stanford.edu/entries/methodological-individualism/. [Open access]"],"why":[{"q":"Why could economics move into subjects such as crime and the family?","a":"Because its explanatory model, individuals behaving as if they maximised utility or wealth, was held to apply to many kinds of behaviour,<sup class=\"fn\" data-fn=\"1\"></sup> and it was applied in turn to crime, the family, discrimination and human capital.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why is the approach not simply an assumption of selfishness?","a":"Because it assumes that people maximise welfare as they conceive it, whether selfish, altruistic, loyal or spiteful, which makes it a method of analysis rather than an assumption about particular motives.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do critics link the expansion to blind spots?","a":"Because unification across disciplines is defensible only where it captures how the new subject works and admits severe uncertainty,<sup class=\"fn\" data-fn=\"4\"></sup> while economics itself is relatively insular among the social sciences.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Economics imperialism"},
    "ec-090": {"questions":["With a deep central band holding a ten per cent chance and paler pairs added out to ninety per cent, the <span class=\"blank\">_____</span> was designed to avoid any spurious appearance of precision in forecasts.","A 2024 review urged the Bank of England to drop its <span class=\"blank\">_____</span>, judging that the probability bands around its forecasts added little and drew scant public attention, though uncertainty still needed conveying."],"abstract":"A <b>fan chart</b> presents a forecast as a range of probabilities rather than a single line, with bands that widen and fade as the horizon lengthens and the uncertainty grows.<sup class=\"fn\" data-fn=\"1\"></sup> The Bank of England introduced it for its inflation forecast in February 1996, after an earlier chart had encouraged readers to fix on an apparently precise central projection.<sup class=\"fn\" data-fn=\"1\"></sup> In the original design the deepest central band held a 10% chance of the outcome, and pairs of paler bands were added in steps of ten percentage points until 90% of the distribution was covered.<sup class=\"fn\" data-fn=\"1\"></sup> Its stated aim was to convey the forecasters' real assessment without suggesting a degree of precision that would be spurious.<sup class=\"fn\" data-fn=\"1\"></sup> The US Federal Reserve also publishes a fan chart, with a 70% confidence interval around its policymakers' median projections based on the errors of forecasts over the previous 20 years.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The device answers a wider problem, which is that official statistics are commonly reported as point estimates with no measure of error, so that users may treat them as error free or guess the error wrongly.<sup class=\"fn\" data-fn=\"3\"></sup> Even a figure as basic as GDP is periodically revised, and the uncertainty in such statistics may be transitory, permanent or conceptual.<sup class=\"fn\" data-fn=\"3\"></sup> Policy analysis is likewise often presented with a certitude that is not credible, because its predictions rest on critical assumptions that have not been supported.<sup class=\"fn\" data-fn=\"4\"></sup> Whether fan charts solve the problem is disputed, and a 2024 review for the Bank of England judged that its charts had weak conceptual foundations, added little and drew little public attention, and should be eliminated.<sup class=\"fn\" data-fn=\"5\"></sup> The Bank agreed that in practice they had not communicated risks effectively to the public, while noting that whether scenarios could substitute for them would need careful consideration.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Erik Britton, Paul Fisher and John Whitley, “The Inflation Report Projections: Understanding the Fan Chart,” <i>Bank of England Quarterly Bulletin</i>, February 1998, 30–37, https://www.bankofengland.co.uk/quarterly-bulletin/1998/q1/the-inflation-report-projections-understanding-the-fan-chart. [Open access]","Board of Governors of the Federal Reserve System, “Summary of Economic Projections,” 18 September 2024, figure 4.A, https://www.federalreserve.gov/monetarypolicy/files/fomcprojtabl20240918.pdf. [Open access]","Charles F. Manski, “Communicating Uncertainty in Official Economic Statistics: An Appraisal Fifty Years after Morgenstern,” <i>Journal of Economic Literature</i> 53, no. 3 (2015): 631–53, https://doi.org/10.1257/jel.53.3.631. [Paywalled]","Charles F. Manski, “Policy Analysis with Incredible Certitude,” <i>Economic Journal</i> 121, no. 554 (2011): F261–89, https://doi.org/10.1111/j.1468-0297.2011.02457.x. [Paywalled]","Ben S. Bernanke, “Forecasting for Monetary Policy Making and Communication at the Bank of England: A Review,” Bank of England, 12 April 2024, recommendation 11, https://www.bankofengland.co.uk/independent-evaluation-office/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review. [Open access]","Bank of England, “Response of the Bank of England to the Bernanke Review of Forecasting for Monetary Policy Making and Communication at the Bank of England,” 12 April 2024, https://www.bankofengland.co.uk/independent-evaluation-office/forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review/response-forecasting-for-monetary-policy-making-and-communication-at-the-bank-of-england-a-review. [Open access]"],"why":[{"q":"Why did the Bank of England replace its single shaded band?","a":"Because the earlier chart encouraged readers to concentrate on an apparently precise central projection, gave no weight to the risks, and its band was often misread as upper and lower bounds rather than as probabilities.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Why do official statistics need measures of error?","a":"Because they are commonly reported as point estimates, so users may treat them as error free or guess the error wrongly, and even GDP is periodically revised.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did a 2024 review recommend dropping fan charts?","a":"Because it found that they had weak conceptual foundations, conveyed little beyond what could be said more directly, and received little public attention, though uncertainty and the balance of risks still had to be communicated.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Fan chart (time series)"},
    "ec-091": {"questions":["A poor man may wish for a coach and six, but a wish without the money to pay is not the <span class=\"blank\">_____</span> that an economist counts when studying a market.","Income, tastes, population and the prices of related goods all alter the <span class=\"blank\">_____</span> for a good, while a change in its own price only moves buyers along it."],"abstract":"<b>Demand</b>, in economics, is the amount of a good or service that buyers are willing and able to purchase at each possible price over a given period.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> It rests on both wanting a thing and being able to pay for it, so a desire that cannot be backed by money is not counted as demand at all.<sup class=\"fn\" data-fn=\"1\"></sup> Adam Smith drew the same line in 1776, setting the 'effectual demand' of people willing to pay the price at which a good can be brought to market against the wish of a very poor man for a coach and six.<sup class=\"fn\" data-fn=\"5\"></sup> Economists therefore mean by demand not a single quantity but the whole relationship between price and quantity demanded, which can be set out as a table called a demand schedule or drawn as a demand curve.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> The quantity demanded is one point on that relationship, the amount buyers would take at one particular price.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> <br><br> Price is not the only influence, and in setting out demand economists hold everything else constant, an assumption called ceteris paribus, Latin for ‘other things being equal’.<sup class=\"fn\" data-fn=\"2\"></sup> Income, tastes and preferences, the size and make-up of the population, the prices of related goods and expectations about the future all change how much buyers want at a given price.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> The standard 19th-century account put the point plainly: a person's demand increases when he will buy more at the same price, and as much as before at a higher one.<sup class=\"fn\" data-fn=\"4\"></sup> A market's demand is the sum of the demands of all its buyers, and in a large market the quirks of individuals tend to cancel out into a comparatively regular pattern.<sup class=\"fn\" data-fn=\"4\"></sup> Demand is still only half of the picture, since the price paid in a market is set by demand and supply together, which is why the two words are so often paired.<sup class=\"fn\" data-fn=\"8\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.2, “Shifts in Demand and Supply for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-2-shifts-in-demand-and-supply-for-goods-and-services. [Open access]","David R. Henderson, “Demand,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Demand.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 3, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=12. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan (London: Methuen, 1904), bk. 1, ch. 7, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=10. [Open access]","Augustin Cournot, <i>Researches into the Mathematical Principles of the Theory of Wealth</i>, trans. Nathaniel T. Bacon (New York: Macmillan, 1897), ch. 4, 46–47, https://archive.org/details/bub_gb_AGoGpyJY_SAC. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.1, “Demand,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-01-demand.html. [Open access]","Irena Asmundson, “Back to Basics: Supply and Demand,” <i>Finance &amp; Development</i> 47, no. 2 (June 2010), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2010/06/basics.htm. [Open access]"],"why":[{"q":"Why does an economist not count every want as demand?","a":"Because demand is based on the ability to pay as well as on needs and wants: someone who cannot pay has no effective demand.<sup class=\"fn\" data-fn=\"1\"></sup> Smith made the same point in 1776 with a very poor man who might like a coach and six, but whose wish could never bring one to market.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why is demand described as a list rather than as one number?","a":"Because the amount buyers want depends on the price asked, so a quantity means little without its price.<sup class=\"fn\" data-fn=\"3\"></sup> Cournot in 1838 treated the sales or demand for an article as a function of its price,<sup class=\"fn\" data-fn=\"6\"></sup> and Marshall represented a person's demand by the list of prices at which he would buy different amounts.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does a rise in income not just move buyers along the demand curve?","a":"Because income is one of the things held constant when demand is set out, so a change in it alters the quantity wanted at every price and moves the whole relationship, not one point on it.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup>"}],"wiki":"Demand"},
    "ec-092": {"questions":["Line up every would-be buyer from the highest willingness to pay to the lowest, and the steps they make trace a <span class=\"blank\">_____</span> that slopes down from left to right.","A fall in the price of coffee moves buyers down along the <span class=\"blank\">_____</span> to a larger quantity, but a rise in their incomes shifts the whole line to the right."],"abstract":"A <b>demand curve</b> is a graph of the quantity of a good that buyers are willing and able to purchase at each price, drawn from a table of prices and quantities called a demand schedule.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> By convention price runs up the vertical axis and quantity along the horizontal one, so the curve can be read both ways: how much will be bought at a price, or the price at which a given amount will find buyers.<sup class=\"fn\" data-fn=\"8\"></sup><sup class=\"fn\" data-fn=\"4\"></sup> Nearly all demand curves slope down from left to right, since a higher price means a smaller quantity demanded, although they may be steep or flat, straight or curved.<sup class=\"fn\" data-fn=\"1\"></sup> One way to build one is to line up the buyers in order of their willingness to pay, highest first, so that at any price the curve counts everyone whose valuation is at or above it.<sup class=\"fn\" data-fn=\"5\"></sup> The curve holds everything except the good's own price constant, so a change in that price is a movement along it, while a change in anything else shifts the whole curve.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> <br><br> The diagram is older than the textbooks that made it famous, since the French mathematician Antoine-Augustin Cournot drew the first market demand curve in 1838.<sup class=\"fn\" data-fn=\"3\"></sup> Cournot wrote demand as a function of price and measured price along the horizontal axis, the reverse of the custom that later took hold.<sup class=\"fn\" data-fn=\"3\"></sup> In 1841 the German economist Karl Heinrich Rau, apparently unaware of Cournot, put price on the vertical axis and used the diagram to show how a price below equilibrium creates excess demand that pushes the price back up.<sup class=\"fn\" data-fn=\"3\"></sup> Textbook demand curves are often drawn as straight lines for simplicity, but real ones are more likely to bend, their exact shape depending on how buyers' valuations are spread.<sup class=\"fn\" data-fn=\"5\"></sup> Economists use the word demand for the whole curve, keeping the phrase quantity demanded for a single point on it, the amount bought at one particular price.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.1, “Demand,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-01-demand.html. [Open access]","Thomas M. Humphrey, “Marshallian Cross Diagrams and Their Uses before Alfred Marshall: The Origins of Supply and Demand Geometry,” <i>Economic Review</i>, Federal Reserve Bank of Richmond (March/April 1992): 3–23, https://www.richmondfed.org/-/media/richmondfedorg/publications/research/economic_review/1992/pdf/er780201.pdf. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 3, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=12. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","David R. Henderson, “Demand,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Demand.html. [Open access]","David F. Perkis, “The Science of Supply and Demand,” <i>Page One Economics</i>, Federal Reserve Bank of St. Louis, March 2021, https://www.stlouisfed.org/publications/page-one-economics/2021/03/01/the-science-of-supply-and-demand. [Open access]","Irena Asmundson, “Back to Basics: Supply and Demand,” <i>Finance &amp; Development</i> 47, no. 2 (June 2010), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2010/06/basics.htm. [Open access]"],"why":[{"q":"Why does price go on the vertical axis?","a":"By convention: economists graph price on the vertical axis and quantity on the horizontal one.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> The first market demand curve, drawn in 1838, did the reverse, and price was first put on the vertical axis in a diagram of 1841.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why does a demand curve slope downwards?","a":"Because buyers differ in what they are willing to pay, so a lower price brings in more of them: line them up by willingness to pay and the curve counts everyone at or above each price.<sup class=\"fn\" data-fn=\"5\"></sup> For one buyer too, a higher price for a favourite snack means buying less.<sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why is the textbook demand curve often a straight line?","a":"For simplicity only: in practice demand is more likely to be a curve, its shape depending on how valuations vary among buyers.<sup class=\"fn\" data-fn=\"5\"></sup> What nearly all demand curves share is the downward slope from left to right.<sup class=\"fn\" data-fn=\"1\"></sup>"}],"wiki":"Demand curve"},
    "ec-093": {"questions":["Subsidised rice led some of the poorest households in Hunan to buy less of it, a rare documented breach of the <span class=\"blank\">_____</span> that economists had long sought in real markets.","Read as a causal claim, the <span class=\"blank\">_____</span> says that a rise in a good's own price lowers the quantity demanded, not merely that prices and quantities tend to move apart."],"abstract":"The <b>law of demand</b> states that, other things being equal, a rise in the price of a good lowers the quantity of it that buyers demand, and a fall in its price raises it.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> On a graph it is the downward slope of the demand curve, the inverse relationship between price and quantity demanded.<sup class=\"fn\" data-fn=\"1\"></sup> It is called a law because the results of countless studies are consistent with it, and it is part of everyday experience too, since a shop with surplus stock holds a sale rather than raising its prices.<sup class=\"fn\" data-fn=\"7\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> The standard 19th-century statement of it is that the amount demanded increases with a fall in price and diminishes with a rise in price.<sup class=\"fn\" data-fn=\"3\"></sup> The law says nothing about how large the response will be, since a fall of one-tenth in price might raise sales by a twentieth, by a quarter, or might double them.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Read carefully, it is a causal claim about the effect of a change in a good's own price, holding everything else constant, rather than a mere observation that prices and quantities move in opposite directions.<sup class=\"fn\" data-fn=\"6\"></sup> When demand rises for some other reason, such as a change in tastes, price and quantity can rise together without breaking the law at all.<sup class=\"fn\" data-fn=\"6\"></sup> Possible exceptions were noticed as early as 1838, when objects of whim and luxury, wanted only because they are rare and dear, were named as goods whose demand might collapse if they became cheap.<sup class=\"fn\" data-fn=\"4\"></sup> Other apparent exceptions, such as a new car wax that sold better after its price was raised, usually turn out to involve something besides price, in that case buyers who could not judge its quality before buying.<sup class=\"fn\" data-fn=\"2\"></sup> The first real-world evidence of upward-sloping demand came from a 2008 study in China, where subsidising rice for extremely poor households in Hunan led them to buy less of it, behaviour traced to the pressure of subsistence on the very poor.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","David R. Henderson, “Demand,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Demand.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 3, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=12. [Open access]","Augustin Cournot, <i>Researches into the Mathematical Principles of the Theory of Wealth</i>, trans. Nathaniel T. Bacon (New York: Macmillan, 1897), ch. 4, 46–47, https://archive.org/details/bub_gb_AGoGpyJY_SAC. [Open access]","Robert T. Jensen and Nolan H. Miller, “Giffen Behavior and Subsistence Consumption,” <i>American Economic Review</i> 98, no. 4 (2008): 1553–77, https://www.aeaweb.org/articles?id=10.1257/aer.98.4.1553. [Paywalled]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, rev. September 4, 2018, https://plato.stanford.edu/entries/economics/. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.1, “Demand,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-01-demand.html. [Open access]"],"why":[{"q":"Why do economists trust the law of demand so much?","a":"Because it is consistent with countless studies<sup class=\"fn\" data-fn=\"7\"></sup> and with ordinary behaviour, such as shoppers buying more strawberries in season, when they are cheap.<sup class=\"fn\" data-fn=\"2\"></sup> One economist joked that anyone who found a true counterexample would be assured of professional immortality and rapid promotion.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is a price rise with rising sales not a counterexample?","a":"Because the law holds other things equal: when demand increases for some other reason, such as a change in tastes, the price rises along with the quantity.<sup class=\"fn\" data-fn=\"6\"></sup> The standard account also set aside the special case of speculators, who may buy openly to raise a price before selling quietly.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why did cheaper rice reduce rice buying in Hunan?","a":"Because the poorest households behaved as though maximising utility subject to subsistence concerns, so their responses to price depended strongly, and not in a straight line, on how severe their poverty was.<sup class=\"fn\" data-fn=\"5\"></sup> The evidence was strong for rice in Hunan and weaker for wheat in Gansu.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Law of demand"},
    "ec-094": {"questions":["A failed coffee harvest raises the price of coffee, and the resulting <span class=\"blank\">_____</span> for tea, its substitute, pushes tea prices up although nothing about tea itself has altered.","Textbooks insist that a fall in a good's own price causes a change in quantity demanded, never a <span class=\"blank\">_____</span>, which comes from income, tastes, population, related prices or expectations."],"abstract":"A <b>change in demand</b> is a shift of the whole demand curve, in which buyers want a different quantity at every price and not just at the current one.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It is distinguished from a change in quantity demanded, which is a movement along an unchanged curve caused by a change in the good's own price.<sup class=\"fn\" data-fn=\"2\"></sup> The standard causes, often called demand shifters, are income, tastes and preferences, the size and make-up of the population, the prices of related goods and buyers' expectations.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> An increase in demand moves the curve to the right, towards higher quantities, and a decrease moves it to the left.<sup class=\"fn\" data-fn=\"6\"></sup> The idea predates the modern diagram, since the standard 19th-century account said a person's demand rises when he will buy more at the same price, which geometrically means moving his demand curve to the right.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Related goods work in two directions: a dearer substitute raises demand, as a higher price for one family car raises demand for its rival, while a dearer complement lowers it, as costlier petrol lowers demand for cars.<sup class=\"fn\" data-fn=\"7\"></sup> The same account noted that a failure of the coffee harvest would raise the prices people paid for tea.<sup class=\"fn\" data-fn=\"3\"></sup> Income usually raises demand, but not for every good, since urban mass transit and railway travel are classic inferior goods whose use fell as rising post-war incomes put more people in cars.<sup class=\"fn\" data-fn=\"7\"></sup> Keeping the two kinds of change apart matters because a rise in demand from some cause other than price pushes price and quantity up together, which can look like a breach of the law of demand but is not.<sup class=\"fn\" data-fn=\"5\"></sup> In a worked example of a second-hand textbook market, a jump in enrolments shifts demand to the right, leaving excess demand at the old price until sellers raise prices to a new equilibrium with more books sold.<sup class=\"fn\" data-fn=\"4\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.2, “Shifts in Demand and Supply for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-2-shifts-in-demand-and-supply-for-goods-and-services. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.1, “Demand,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-01-demand.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 3, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=12. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, rev. September 4, 2018, https://plato.stanford.edu/entries/economics/. [Open access]","David F. Perkis, “The Science of Supply and Demand,” <i>Page One Economics</i>, Federal Reserve Bank of St. Louis, March 2021, https://www.stlouisfed.org/publications/page-one-economics/2021/03/01/the-science-of-supply-and-demand. [Open access]","David R. Henderson, “Demand,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Demand.html. [Open access]"],"why":[{"q":"Why is a fall in price not a change in demand?","a":"Because the demand curve already shows what buyers do at every price, so a change in price is only a movement along it, a change in quantity demanded.<sup class=\"fn\" data-fn=\"2\"></sup> The curve shifts only when something other than price changes, such as income.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why can more income reduce demand for a good?","a":"Because some goods are inferior: as real income rises, people buy less of them.<sup class=\"fn\" data-fn=\"7\"></sup> Urban mass transit and railway travel are classic examples, since their use declined as post-war incomes rose and more people could afford cars.<sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why does a shift in demand change the price as well as the quantity?","a":"Because at the old price buyers now want more than sellers offer, so there is excess demand and sellers raise prices until a new equilibrium is reached, with more sold at a higher price.<sup class=\"fn\" data-fn=\"4\"></sup> A price rise driven in this way is consistent with the law of demand.<sup class=\"fn\" data-fn=\"5\"></sup>"}]},
    "ec-095": {"questions":["Wages, materials, technology, weather and taxes all enter the cost of production, which is why each of them can raise or lower the <span class=\"blank\">_____</span> of a good at any price.","Land on a busy Manhattan street corner cannot be multiplied however high its price climbs, a standard case of <span class=\"blank\">_____</span> that does not respond to price at all."],"abstract":"<b>Supply</b>, in economics, is the amount of a good or service that producers are willing to produce and bring to market at each possible price.<sup class=\"fn\" data-fn=\"1\"></sup> Like demand, it means the whole relationship between price and quantity, set out as a supply schedule or a supply curve, while the quantity supplied is one point on it.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> A higher price almost always draws out a larger quantity, a positive relationship known as the law of supply, which holds the other influences on supply constant.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> One common reason is cost, since a firm that expands output often has to turn to dearer materials or labour and will produce more only at a higher price.<sup class=\"fn\" data-fn=\"3\"></sup> Seen from the sellers' side, a supply curve can be built by lining up potential sellers by the lowest price each would accept, so that a higher price brings more of them into the market.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> Anything that changes the cost of production shifts supply, including the prices of inputs, the weather and other natural conditions, new technology, and government taxes, regulations and subsidies.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Economists do not really have a law of supply as firm as the law of demand, although they talk and write as though they do, and there are recognised exceptions.<sup class=\"fn\" data-fn=\"3\"></sup> Some things cannot be produced at all, such as more land on one Manhattan street corner, so a higher price calls forth no extra quantity.<sup class=\"fn\" data-fn=\"6\"></sup> The best-known possible exception, the backward-bending supply of labour, describes workers who choose more leisure once wages are high, though recent evidence suggests higher wages still bring more hours worked.<sup class=\"fn\" data-fn=\"3\"></sup> The idea that supply answers to price is old, since in 1776 Adam Smith argued that the quantity of any commodity brought to market naturally suits itself to the effectual demand as owners move land, labour and stock in and out.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.2, “Shifts in Demand and Supply for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-2-shifts-in-demand-and-supply-for-goods-and-services. [Open access]","Al Ehrbar, “Supply,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Supply.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=31. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan (London: Methuen, 1904), bk. 1, ch. 7, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=10. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.2, “Supply,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-02-supply.html. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","David F. Perkis, “The Science of Supply and Demand,” <i>Page One Economics</i>, Federal Reserve Bank of St. Louis, March 2021, https://www.stlouisfed.org/publications/page-one-economics/2021/03/01/the-science-of-supply-and-demand. [Open access]"],"why":[{"q":"Why does a higher price usually bring more goods to market?","a":"Because it makes production more profitable: when the price of petrol rises, firms explore and drill for more oil, build refineries and keep stations open longer.<sup class=\"fn\" data-fn=\"1\"></sup> Expanding output often means buying dearer inputs, so firms need the higher price to cover their rising unit costs.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"Why do economists look behind supply to the cost of production?","a":"Because the price sellers need for a quantity reflects what it costs to make: the sum of the prices of the factors of production needed for an amount was called its supply price.<sup class=\"fn\" data-fn=\"4\"></sup> Changes in input costs, technology, weather or taxes therefore move supply.<sup class=\"fn\" data-fn=\"2\"></sup>"},{"q":"Why is the law of supply weaker than the law of demand?","a":"Because some goods cannot be produced at any price, such as land at one city corner,<sup class=\"fn\" data-fn=\"6\"></sup> and labour may be an exception if high wages lead people to buy more leisure, although recent evidence suggests that higher wages still bring more hours.<sup class=\"fn\" data-fn=\"3\"></sup>"}],"wiki":"Supply (economics)"},
    "ec-096": {"questions":["Ranking would-be sellers from the lowest acceptable price to the highest gives a <span class=\"blank\">_____</span> that rises from left to right, since each higher price tempts more owners to sell.","Even with a fixed number of flats in one building, the <span class=\"blank\">_____</span> of flats for sale slopes upward, since higher offers persuade more owners to put theirs on the market."],"abstract":"A <b>supply curve</b> is a graph of the quantity of a good that sellers would offer at each price, drawn from a supply schedule, a table of the same figures.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> With price on the vertical axis and quantity on the horizontal one, nearly all supply curves slope up from left to right, though they may be steep or flat, straight or curved.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> For a whole market, the curve shows the total quantity that all firms together would produce at each price.<sup class=\"fn\" data-fn=\"3\"></sup> One way to build it is to rank potential sellers by the lowest price each would accept, so that every rise in price brings in sellers who would not have sold before.<sup class=\"fn\" data-fn=\"3\"></sup> A change in the good's own price is a movement along the curve, called a change in quantity supplied, and does not move the curve itself.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> <br><br> For competitive firms that take the market price as given, the supply curve represents marginal cost, the cost of producing one more unit, so its upward slope reflects costs that rise as output grows.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> Even a good whose total stock is fixed in the short run, such as the flats in one building, has an upward-sloping supply for sale, since higher offers persuade more owners to sell.<sup class=\"fn\" data-fn=\"6\"></sup> The curve was first drawn in 1838, when the French mathematician Antoine-Augustin Cournot combined market demand and supply curves in a single diagram.<sup class=\"fn\" data-fn=\"4\"></sup> Three years later the German economist Karl Heinrich Rau drew a vertical supply line against a falling demand curve to show how a shortage pushes the price up to equilibrium.<sup class=\"fn\" data-fn=\"4\"></sup> Later accounts treated the curve as a list of supply prices, the price needed to call forth each amount, and its meeting with demand as a stable equilibrium to which a disturbed price returns.<sup class=\"fn\" data-fn=\"5\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.2, “Supply,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-02-supply.html. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","Thomas M. Humphrey, “Marshallian Cross Diagrams and Their Uses before Alfred Marshall: The Origins of Supply and Demand Geometry,” <i>Economic Review</i>, Federal Reserve Bank of Richmond (March/April 1992): 3–23, https://www.richmondfed.org/-/media/richmondfedorg/publications/research/economic_review/1992/pdf/er780201.pdf. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=31. [Open access]","Al Ehrbar, “Supply,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Supply.html. [Open access]","Irena Asmundson, “Back to Basics: Supply and Demand,” <i>Finance &amp; Development</i> 47, no. 2 (June 2010), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2010/06/basics.htm. [Open access]","David F. Perkis, “The Science of Supply and Demand,” <i>Page One Economics</i>, Federal Reserve Bank of St. Louis, March 2021, https://www.stlouisfed.org/publications/page-one-economics/2021/03/01/the-science-of-supply-and-demand. [Open access]"],"why":[{"q":"Why does a market supply curve slope upward?","a":"Because sellers differ in the lowest price they will accept, so a higher price draws in more of them,<sup class=\"fn\" data-fn=\"3\"></sup> and firms that expand output face rising costs as they buy dearer materials or labour.<sup class=\"fn\" data-fn=\"6\"></sup>"},{"q":"Why is a change in price a movement along the curve?","a":"Because the curve already shows the quantity offered at every price, so a new price only picks out a different point on it.<sup class=\"fn\" data-fn=\"2\"></sup> A shift of the curve needs a change in something else, such as costs.<sup class=\"fn\" data-fn=\"8\"></sup>"},{"q":"What did one of the earliest supply-and-demand diagrams show?","a":"It drew a falling demand curve against a vertical supply line and showed that a price below equilibrium creates excess demand, which sellers exploit by raising the price until the shortage disappears.<sup class=\"fn\" data-fn=\"4\"></sup> An above-equilibrium price, in the same diagram, creates excess supply that pushes the price down.<sup class=\"fn\" data-fn=\"4\"></sup>"}],"wiki":"Supply (economics)"},
    "ec-097": {"questions":["Production cuts by Arab oil exporters in 1973 caused a sharp <span class=\"blank\">_____</span> which, with American producers lacking spare capacity, nearly quadrupled the price of a barrel within months.","Textbooks keep a rise in a good's own price, which only moves sellers along the curve, apart from a <span class=\"blank\">_____</span>, which comes from costs, technology, weather or the number of sellers."],"abstract":"A <b>change in supply</b> is a shift of the whole supply curve, in which sellers will offer a different quantity at every price and not just at the current one.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> It is distinguished from a change in quantity supplied, which is a movement along an unchanged curve caused by a change in the good's own price.<sup class=\"fn\" data-fn=\"2\"></sup> The usual supply shifters are the prices of inputs, the returns from other activities, technology, sellers' expectations, natural events and the number of sellers.<sup class=\"fn\" data-fn=\"2\"></sup> Most work through the cost of production, so dearer steel shifts the supply of cars to the left, and government taxes, regulations and subsidies can move supply in the same way.<sup class=\"fn\" data-fn=\"1\"></sup> An increase in supply moves the curve to the right, leaving excess supply at the old price, so the price falls and more is sold.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Technology and entry both work in this way, since a quicker baking technique lowers the marginal cost of a loaf, and new bakeries entering a market add to the bread supplied at each price.<sup class=\"fn\" data-fn=\"3\"></sup> Harvests are a long-noted example, since the same labour on the land yields very different quantities of corn or wine from one year to the next.<sup class=\"fn\" data-fn=\"7\"></sup> From the 1960s the improved seeds of the Green Revolution shifted grain supply to the right, and by the early 1990s the wheat and rice harvest from land sown with them was twice as high.<sup class=\"fn\" data-fn=\"1\"></sup> A decrease is just as instructive, since when Arab oil exporters cut production in 1973 American producers had no spare capacity, and the price rose from $2.90 a barrel before the embargo to $11.65 in January 1974.<sup class=\"fn\" data-fn=\"4\"></sup> A supply shift also shows why prices carry information, since users of a scarce material need to know only that its price has risen, not whether the cause was a new use or a lost source.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.2, “Shifts in Demand and Supply for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-2-shifts-in-demand-and-supply-for-goods-and-services. [Open access]","<i>Principles of Economics</i>, v. 2.0 (Saylor Academy, 2012), §3.2, “Supply,” https://saylordotorg.github.io/text_principles-of-economics-v2.0/s06-02-supply.html. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","Michael Corbett, “Oil Shock of 1973–74,” Federal Reserve History, November 22, 2013, https://www.federalreservehistory.org/essays/oil-shock-of-1973-74. [Open access]","David F. Perkis, “The Science of Supply and Demand,” <i>Page One Economics</i>, Federal Reserve Bank of St. Louis, March 2021, https://www.stlouisfed.org/publications/page-one-economics/2021/03/01/the-science-of-supply-and-demand. [Open access]","Friedrich A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan (London: Methuen, 1904), bk. 1, ch. 7, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=10. [Open access]"],"why":[{"q":"Why does a hurricane tend to raise petrol prices?","a":"Because it shifts supply to the left: after Hurricane Sandy in 2012, only 40 per cent of the New Jersey petrol stations tracked by one motoring group had power and were operating.<sup class=\"fn\" data-fn=\"5\"></sup> With demand unchanged, quantity falls and price rises, and where prices were held down, queues formed and stations sold out instead.<sup class=\"fn\" data-fn=\"5\"></sup>"},{"q":"Why could American oil producers not offset the cuts of 1973?","a":"Because the American oil industry lacked spare production capacity, so when Arab exporters cut output it could not bring more oil to market, and prices had to rise.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why does a cost-cutting technology lower the price?","a":"Because it shifts supply to the right, so at the old price there is more for sale than buyers want and firms cut their prices.<sup class=\"fn\" data-fn=\"3\"></sup> The new equilibrium has more sold at a lower price, a movement along the unchanged demand curve.<sup class=\"fn\" data-fn=\"3\"></sup>"}]},
    "ec-098": {"questions":["In laboratory trading sessions, traders who knew only their own valuations still drove prices close to the predicted <span class=\"blank\">_____</span> within a few rounds, to the surprise of the experimenter.","Haggling on a country corn exchange may toss the price about like a shuttlecock, yet it rarely strays far from the <span class=\"blank\">_____</span> at which the amounts offered and wanted match."],"abstract":"<b>Market equilibrium</b> is the state of a market at the price where the quantity buyers want equals the quantity sellers want to sell, the point where the demand and supply curves cross.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"6\"></sup> That price is called the equilibrium or market-clearing price, and the common quantity is the equilibrium quantity.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> The word means balance, since at that point no one can gain by offering or asking a different price, so the market has no reason to move unless something outside it changes.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> At any other price the plans of buyers and sellers do not match, and the resulting excess supply or excess demand creates pressure for the price to move back towards equilibrium.<sup class=\"fn\" data-fn=\"1\"></sup> When everyone trades at that price, a competitive equilibrium is also a Nash equilibrium, since no buyer or seller can do better by acting differently.<sup class=\"fn\" data-fn=\"2\"></sup> <br><br> The classic illustration is a country corn exchange, where bargaining may toss the price about like a shuttlecock but rarely leaves it far from the level at which supply and demand are equal.<sup class=\"fn\" data-fn=\"3\"></sup> Such an equilibrium is called stable when a displaced price tends to return, as a pendulum swings back towards its lowest point.<sup class=\"fn\" data-fn=\"4\"></sup> In real markets the demand and supply schedules keep changing, so equilibrium is better read as a point that prices tend towards than as a place where they settle for long.<sup class=\"fn\" data-fn=\"4\"></sup> Laboratory markets from 1962 onwards found that traders who knew only their own valuations still reached prices very close to the theoretical equilibrium.<sup class=\"fn\" data-fn=\"5\"></sup> The model is still an idealisation, and evidence of perfect competition is hard to find, with studies of credit card lending and a New York fish market showing prices that did not behave as it predicts.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, ch. 2, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=30. [Open access]","Alfred Marshall, <i>Principles of Economics</i>, 8th ed. (London: Macmillan, 1920), bk. 5, ch. 3, Library of Economics and Liberty, https://www.econlib.org/library/Marshall/marP.html?chapter_num=31. [Open access]","Royal Swedish Academy of Sciences, “Information for the Public: The Prize in Economic Sciences 2002,” NobelPrize.org, https://www.nobelprize.org/prizes/economic-sciences/2002/popular-information/. [Open access]","Irena Asmundson, “Back to Basics: Supply and Demand,” <i>Finance &amp; Development</i> 47, no. 2 (June 2010), International Monetary Fund, https://www.imf.org/external/pubs/ft/fandd/2010/06/basics.htm. [Open access]","Daniel M. Hausman, “Philosophy of Economics,” in <i>The Stanford Encyclopedia of Philosophy</i>, rev. September 4, 2018, https://plato.stanford.edu/entries/economics/. [Open access]","Al Ehrbar, “Supply,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Supply.html. [Open access]"],"why":[{"q":"Why does a market tend to move back to equilibrium?","a":"Because at any other price someone can gain by changing it: with excess supply sellers cut prices to sell, and with excess demand they raise them.<sup class=\"fn\" data-fn=\"1\"></sup> Markets in which prices can move freely are always in equilibrium or moving towards it.<sup class=\"fn\" data-fn=\"8\"></sup>"},{"q":"Why is market equilibrium a model rather than a description?","a":"Because it assumes price-taking buyers and sellers of identical goods, which real markets rarely match, although it remains a useful approximation where individuals have little influence on prices.<sup class=\"fn\" data-fn=\"2\"></sup> Economists idealise in this way knowingly, supposing that firms and individuals in competitive markets cannot influence prices.<sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why did the first laboratory markets surprise the man who ran them?","a":"Because prices came very close to the theoretical equilibrium even though the subjects lacked the information needed to calculate it.<sup class=\"fn\" data-fn=\"5\"></sup> Later experiments by others largely confirmed the result, while finding that outcomes depended on the exact design of the market.<sup class=\"fn\" data-fn=\"5\"></sup>"}],"wiki":"Economic equilibrium"},
    "ec-099": {"questions":["A hat-seller who sees disappointed customers leave each day raises her price, and through many such small moves the <span class=\"blank\">_____</span> carries the whole market to a new balance.","When rents are frozen below the market level, the <span class=\"blank\">_____</span> can no longer ration flats, so queues, side payments, black markets or ration coupons decide who gets one instead."],"abstract":"The <b>price mechanism</b> is the way changes in prices coordinate what buyers and sellers do, so that a market moves towards the price at which the quantity demanded equals the quantity supplied.<sup class=\"fn\" data-fn=\"2\"></sup><sup class=\"fn\" data-fn=\"7\"></sup> When there is excess demand some buyers will pay more and sellers can raise their prices, and when there is excess supply sellers cut prices to sell what they have.<sup class=\"fn\" data-fn=\"3\"></sup><sup class=\"fn\" data-fn=\"2\"></sup> Someone has to make the first move, since in the competitive model everyone takes the price as given, so a seller who sees customers go home disappointed raises her price and others follow until the market clears again.<sup class=\"fn\" data-fn=\"2\"></sup> Prices also act as signals, encouraging producers to bring forth more supply in future and others to devise substitutes for a good that has grown dear.<sup class=\"fn\" data-fn=\"6\"></sup> In 1776 Adam Smith described market prices as continually gravitating towards a natural price, though accidents, natural causes and regulations could hold them above it for long periods.<sup class=\"fn\" data-fn=\"3\"></sup> <br><br> Its strongest defence concerns knowledge: in 1945 Friedrich Hayek argued that the price system is a way of communicating information dispersed among a great many people.<sup class=\"fn\" data-fn=\"1\"></sup> If tin grows scarcer, its users need not know whether a new use or a lost source is the cause, only that its price has risen, and tens of thousands then use it more sparingly without any order being issued.<sup class=\"fn\" data-fn=\"1\"></sup> The mechanism works less perfectly as prices grow more rigid, and real prices change in steps, since in United States consumer prices from 1995 to 1997 half lasted less than 4.3 months before changing.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"5\"></sup> Where prices are not allowed to move, other devices do the rationing, such as queues, black markets and coupons, as with petrol in the United States when its price was capped in 1973 and 1979.<sup class=\"fn\" data-fn=\"4\"></sup> Some sellers choose not to use it, holding prices for concert and Olympic tickets below the market-clearing level, and in the Olympic case allocating them by lottery so that buyers with less to spend also got a chance.<sup class=\"fn\" data-fn=\"2\"></sup>","sources":["Friedrich A. Hayek, “The Use of Knowledge in Society,” <i>American Economic Review</i> 35, no. 4 (1945): 519–30, Library of Economics and Liberty, https://www.econlib.org/library/Essays/hykKnw.html. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 11, “Rent-Seeking, Price-Setting, and Market Dynamics,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/11.html. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan (London: Methuen, 1904), bk. 1, ch. 7, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=10. [Open access]","Hugh Rockoff, “Price Controls,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/PriceControls.html. [Open access]","Mark Bils and Peter J. Klenow, “Some Evidence on the Importance of Sticky Prices,” <i>Journal of Political Economy</i> 112, no. 5 (2004): 947–85, NBER Working Paper 9069 version, https://www.nber.org/papers/w9069. [Open access]","Al Ehrbar, “Supply,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/Supply.html. [Open access]","Thomas M. Humphrey, “Marshallian Cross Diagrams and Their Uses before Alfred Marshall: The Origins of Supply and Demand Geometry,” <i>Economic Review</i>, Federal Reserve Bank of Richmond (March/April 1992): 3–23, https://www.richmondfed.org/-/media/richmondfedorg/publications/research/economic_review/1992/pdf/er780201.pdf. [Open access]"],"why":[{"q":"Why does a price rise tell users to economise?","a":"Because it passes on, in one figure, the news that a material is more valuable elsewhere, so people adjust without knowing the cause.<sup class=\"fn\" data-fn=\"1\"></sup> Hayek called the economy of knowledge with which the system operates its most significant fact.<sup class=\"fn\" data-fn=\"1\"></sup>"},{"q":"Who actually changes the price when a market is out of equilibrium?","a":"Buyers and sellers themselves: when demand shifts, some stop taking the going price and become price-makers, earning a temporary rent, until a new equilibrium is reached.<sup class=\"fn\" data-fn=\"2\"></sup> Smith described buyers competing by offering more when the quantity brought to market falls short.<sup class=\"fn\" data-fn=\"3\"></sup>"},{"q":"What happens when a price is not allowed to clear the market?","a":"Some other device must ration the supply, such as a queue: American drivers waited in long lines when petrol prices were capped in 1973 and 1979.<sup class=\"fn\" data-fn=\"4\"></sup> Economists generally expect a fixed price to reduce both the quantity and the quality of the good.<sup class=\"fn\" data-fn=\"6\"></sup>"}],"wiki":"Price mechanism"},
    "ec-100": {"questions":["Support prices far above world levels and an unlimited promise to buy produced a growing <span class=\"blank\">_____</span> of farm goods in the European Community before the reform of 1992.","A legal minimum price set above equilibrium leaves buyers on the short side of the market, so the <span class=\"blank\">_____</span> it creates means trade is limited to what they will take."],"abstract":"<b>Excess supply</b>, also called a surplus, is the situation in which the quantity of a good supplied is greater than the quantity demanded at the current price.<sup class=\"fn\" data-fn=\"1\"></sup><sup class=\"fn\" data-fn=\"3\"></sup> Its mirror image is excess demand, or a shortage, in which buyers want more than sellers offer, as happens at any price below equilibrium.<sup class=\"fn\" data-fn=\"1\"></sup> Excess supply arises at any price above the market-clearing level, where the higher price both discourages buyers and encourages sellers to offer more.<sup class=\"fn\" data-fn=\"1\"></sup> In a free market it tends to be temporary, since unsold goods pile up, sellers would rather sell at a lower price than not at all, and once some cut prices others follow.<sup class=\"fn\" data-fn=\"1\"></sup> In 1776 Adam Smith described the same process, observing that when more is brought to market than buyers will take at the natural price, some must be sold to those willing to pay less, which lowers the price of the whole.<sup class=\"fn\" data-fn=\"7\"></sup> <br><br> Excess supply lasts when the price is held above equilibrium by law, which is why price floors are associated with surpluses and price ceilings with shortages.<sup class=\"fn\" data-fn=\"5\"></sup><sup class=\"fn\" data-fn=\"8\"></sup> With the price above the clearing level, buyers are on the short side of the market, so the quantity actually traded is the smaller of the two quantities and the rest of the supply goes unsold.<sup class=\"fn\" data-fn=\"4\"></sup> Farm price supports are the standard case, in which governments hold prices up by buying the surplus, so that farmers gain while taxpayers and food buyers bear the cost.<sup class=\"fn\" data-fn=\"2\"></sup> The European Community's common agricultural policy combined support prices well above world market prices with an unlimited buying guarantee, and it produced more and more food surpluses.<sup class=\"fn\" data-fn=\"6\"></sup> In 1992 the Council replaced protection through prices with compensatory income support for farmers, to close the widening gap between supply and demand and bring farm spending under control.<sup class=\"fn\" data-fn=\"6\"></sup>","sources":["Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.1, “Demand, Supply, and Equilibrium in Markets for Goods and Services,” https://openstax.org/books/principles-economics-3e/pages/3-1-demand-supply-and-equilibrium-in-markets-for-goods-and-services. [Open access]","Steven A. Greenlaw, David Shapiro and Daniel MacDonald, <i>Principles of Economics</i>, 3rd ed. (Houston, TX: OpenStax, 2022), §3.4, “Price Ceilings and Price Floors,” https://openstax.org/books/principles-economics-3e/pages/3-4-price-ceilings-and-price-floors. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 8, “Supply and Demand: Price-Taking and Competitive Markets,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/08.html. [Open access]","The CORE Team, <i>The Economy 1.0</i>, Unit 11, “Rent-Seeking, Price-Setting, and Market Dynamics,” CORE Econ, https://books.core-econ.org/the-economy-v1/book/text/11.html. [Open access]","Hugh Rockoff, “Price Controls,” in <i>The Concise Encyclopedia of Economics</i>, Library of Economics and Liberty, https://www.econlib.org/library/Enc/PriceControls.html. [Open access]","European Parliament, “The Common Agricultural Policy – Instruments and Reforms,” Fact Sheets on the European Union, https://www.europarl.europa.eu/factsheets/en/sheet/107/the-common-agricultural-policy-instruments-and-reforms. [Open access]","Adam Smith, <i>An Inquiry into the Nature and Causes of the Wealth of Nations</i>, ed. Edwin Cannan (London: Methuen, 1904), bk. 1, ch. 7, Library of Economics and Liberty, https://www.econlib.org/library/Smith/smWN.html?chapter_num=10. [Open access]","Thomas M. Humphrey, “Marshallian Cross Diagrams and Their Uses before Alfred Marshall: The Origins of Supply and Demand Geometry,” <i>Economic Review</i>, Federal Reserve Bank of Richmond (March/April 1992): 3–23, https://www.richmondfed.org/-/media/richmondfedorg/publications/research/economic_review/1992/pdf/er780201.pdf. [Open access]"],"why":[{"q":"Why does a surplus usually push the price down?","a":"Because unsold stock leaves firms without the cash to pay workers and cover costs, so some cut prices, preferring a lower price to no sale, and others follow to avoid losing sales.<sup class=\"fn\" data-fn=\"1\"></sup> Smith noted that the fall is sharper for perishable goods.<sup class=\"fn\" data-fn=\"7\"></sup>"},{"q":"Why do price floors leave goods unsold?","a":"Because a legal minimum above equilibrium raises the quantity supplied and lowers the quantity demanded, so a surplus appears, at least for a time.<sup class=\"fn\" data-fn=\"5\"></sup> The quantity actually traded is then set by buyers, who are on the short side of the market.<sup class=\"fn\" data-fn=\"4\"></sup>"},{"q":"Why did the European Community reform its farm policy in 1992?","a":"Because high support prices and an unlimited buying guarantee had produced growing surpluses and rising spending, so the Council replaced price support with compensatory income support.<sup class=\"fn\" data-fn=\"6\"></sup> Under price supports, governments buy up the excess and taxpayers and consumers pay the costs.<sup class=\"fn\" data-fn=\"2\"></sup>"}],"wiki":"Excess supply"}
  };
  (window.CARD_EXTRA_IN = window.CARD_EXTRA_IN || []).push({ CARD_EXTRA: CARD_EXTRA });
})();
